function act(obs, mem) {
    function nrm(a) {
        while (a > 180) a -= 360;
        while (a < -180) a += 360;
        return a;
    }
    function cl(v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; }
    function dist(x1, y1, x2, y2) {
        var dx = x2 - x1, dy = y2 - y1;
        return Math.sqrt(dx * dx + dy * dy);
    }

    function nav(tx, ty) {
        var dx = tx - obs.x, dy = ty - obs.y;
        var d = Math.sqrt(dx * dx + dy * dy);
        var th = Math.atan2(dy, dx) * 180 / Math.PI;
        var he = nrm(th - obs.heading);
        var av = 0, mr = 15;
        for (var i = 0; i < 9; i++) {
            var a = (i - 4) * 20, r = obs.rays[i];
            if (r < mr) mr = r;
            if (r < 7) av += -(a / 80) * (7 - r) / 7;
        }
        if (obs.rays[4] < 6) {
            var lO = (obs.rays[5] + obs.rays[6] + obs.rays[7]) / 3;
            var rO = (obs.rays[0] + obs.rays[1] + obs.rays[2]) / 3;
            av += (lO > rO ? 0.4 : -0.4) * (6 - obs.rays[4]) / 6;
        }
        if (obs.rays[4] < 1.5) {
            return { left: -0.15, right: -0.15, drill: false };
        }
        if (Math.abs(he) > 55) {
            var dir = he > 0 ? 1 : -1;
            return { left: cl(-0.35 * dir, -1, 1), right: cl(0.35 * dir, -1, 1), drill: false };
        }
        var sp = 0.7;
        if (d < 25) sp = cl(d / 25 * 0.7, 0.1, 0.7);
        if (mr < 4) sp = Math.min(sp, 0.3);
        if (mr < 2) sp = Math.min(sp, 0.12);
        var st = cl(0.015 * he + av * 0.4, -1, 1);
        return { left: cl(sp - st, -1, 1), right: cl(sp + st, -1, 1), drill: false };
    }

    if (!mem._i) {
        mem._i = 1;
        mem.tk = 0;
        mem.bx = 200;
        mem.by = 200;
        mem.cap = 5;
        mem.sites = [];
        mem.trips = [];
        mem.tripIdx = 0;
        mem.siteIdx = 0;
        mem.state = 'drive';
        mem.tgt = null;
        mem.srT = 0;
        mem.srC = null;
        mem.srP = [];
        mem.srI = 0;
        mem.stk = 0;
        mem.rec = 0;
        mem.lx = obs.x;
        mem.ly = obs.y;
        mem.lb = obs.battery;
        mem.er = 0;
        mem.oppDrill = false;
        mem.done = false;

        if (obs.mission) {
            mem.bx = obs.mission.base.x;
            mem.by = obs.mission.base.y;
            mem.cap = obs.mission.capacity || 5;
            var hints = obs.mission.hints || [];
            for (var i = 0; i < hints.length; i++) {
                if (hints[i].estimate > 0) {
                    mem.sites.push({ x: hints[i].x, y: hints[i].y, v: hints[i].estimate, done: false });
                }
            }
            var rem = [];
            for (var i = 0; i < mem.sites.length; i++) {
                rem.push({ x: mem.sites[i].x, y: mem.sites[i].y, v: mem.sites[i].v, idx: i });
            }
            var used = {};
            while (rem.length > 0 && mem.trips.length < 15) {
                var anchor = null;
                for (var i = 0; i < rem.length; i++) {
                    if (!used[rem[i].idx] && (!anchor || rem[i].v > anchor.v)) {
                        anchor = rem[i];
                    }
                }
                if (!anchor) break;
                used[anchor.idx] = 1;
                var trip = [{ x: anchor.x, y: anchor.y, v: anchor.v, idx: anchor.idx }];
                for (var j = 1; j < mem.cap; j++) {
                    var bi = -1, bs = -1e9;
                    for (var k = 0; k < rem.length; k++) {
                        if (used[rem[k].idx]) continue;
                        var dd = dist(trip[trip.length - 1].x, trip[trip.length - 1].y, rem[k].x, rem[k].y);
                        var sc = rem[k].v / (dd + 15);
                        if (sc > bs) { bs = sc; bi = k; }
                    }
                    if (bi < 0) break;
                    used[rem[bi].idx] = 1;
                    trip.push({ x: rem[bi].x, y: rem[bi].y, v: rem[bi].v, idx: rem[bi].idx });
                }
                var ordered = [];
                var rrem = trip.slice();
                var cx = mem.bx, cy = mem.by;
                while (rrem.length > 0) {
                    var bi2 = 0, bd2 = 1e9;
                    for (var k = 0; k < rrem.length; k++) {
                        var dd = dist(cx, cy, rrem[k].x, rrem[k].y);
                        if (dd < bd2) { bd2 = dd; bi2 = k; }
                    }
                    var n = rrem.splice(bi2, 1)[0];
                    ordered.push(n);
                    cx = n.x; cy = n.y;
                }
                mem.trips.push(ordered);
            }
        }
    }

    mem.tk++;

    var bD = mem.lb - obs.battery;
    if (bD > 0) {
        if (mem.er === 0) mem.er = bD;
        else if (bD > mem.er * 3) mem.er = mem.er * 0.5 + bD * 0.5;
        else mem.er = mem.er * 0.99 + bD * 0.01;
    }
    mem.lb = obs.battery;

    var mdx = obs.x - mem.lx, mdy = obs.y - mem.ly;
    var moved = Math.sqrt(mdx * mdx + mdy * mdy);
    var cmdA = Math.abs(obs.wheelLeft) > 0.08 || Math.abs(obs.wheelRight) > 0.08;
    if (cmdA && moved < 0.002) mem.stk++;
    else if (moved > 0.015) mem.stk = 0;
    mem.lx = obs.x;
    mem.ly = obs.y;

    if (obs.bumped) mem.rec = Math.max(mem.rec, 18);

    if ((mem.rec > 0 || mem.stk > 25) && mem.state !== 'drill') {
        mem.rec = Math.max(mem.rec - 1, 0);
        mem.stk = 0;
        if (mem.rec > 12) return { left: -0.35, right: -0.25, drill: false };
        if (mem.rec > 5) {
            var td = (mem.tk >> 1) & 1 ? 1 : -1;
            return { left: 0.25 * td, right: -0.25 * td, drill: false };
        }
        return { left: -0.08, right: -0.08, drill: false };
    }

    var dBase = dist(obs.x, obs.y, mem.bx, mem.by);
    var dToTgt = mem.tgt ? dist(obs.x, obs.y, mem.tgt.x, mem.tgt.y) : 0;
    var dFromTgt = mem.tgt ? dist(mem.tgt.x, mem.tgt.y, mem.bx, mem.by) : dBase;
    var returnTicks = Math.max(dToTgt + dFromTgt, dBase) * 10 / 1.5 + 400;
    var tToEmpty = mem.er > 1e-8 ? obs.battery / mem.er : 1e9;
    var needRet = obs.carried >= mem.cap ||
        (tToEmpty < returnTicks * 1.5 && obs.battery < 0.5) ||
        obs.battery < 0.12 ||
        (obs.timeLeft < 30 && obs.carried > 0);

    if (needRet && mem.state !== 'drill' && !mem.done) {
        if (dBase < 3.5) {
            mem.state = 'dock';
            mem.tgt = null;
        } else {
            if (obs.beacon && obs.beacon.distance < 20) {
                var bh = obs.heading + obs.beacon.bearing;
                return nav(obs.x + obs.beacon.distance * Math.cos(bh * Math.PI / 180),
                    obs.y + obs.beacon.distance * Math.sin(bh * Math.PI / 180));
            }
            return nav(mem.bx, mem.by);
        }
    }

    if (mem.done) return { left: 0, right: 0, drill: false };

    if (mem.state === 'drive') {
        if (obs.site && obs.site.distance < 2 && !mem.oppDrill) {
            mem.state = 'drill';
            mem.oppDrill = true;
            return { left: 0, right: 0, drill: true };
        }

        if (!mem.tgt) {
            var trip = mem.trips[mem.tripIdx];
            if (trip && mem.siteIdx < trip.length) {
                var s = trip[mem.siteIdx];
                if (s.done) {
                    mem.siteIdx++;
                    return { left: 0, right: 0, drill: false };
                }
                mem.tgt = { x: s.x, y: s.y, type: 'site' };
            } else {
                if (mem.tripIdx >= mem.trips.length && dBase < 3.5 && obs.docked) {
                    mem.done = true;
                    return { left: 0, right: 0, drill: false };
                }
                mem.tgt = { x: mem.bx, y: mem.by, type: 'base' };
            }
        }

        var t = mem.tgt;
        var dd = dist(obs.x, obs.y, t.x, t.y);

        if (t.type === 'site' && dd < 12) {
            mem.state = 'search';
            mem.srT = 0;
            mem.srC = { x: t.x, y: t.y };
            mem.srI = 0;
            var pts = [];
            for (var si = -1; si <= 1; si++)
                for (var sj = -1; sj <= 1; sj++)
                    pts.push({ x: t.x + si * 10, y: t.y + sj * 10 });
            pts.push({ x: t.x + 20, y: t.y });
            pts.push({ x: t.x - 20, y: t.y });
            pts.push({ x: t.x, y: t.y + 20 });
            pts.push({ x: t.x, y: t.y - 20 });
            pts.sort(function (a, b) {
                return dist(t.x, t.y, a.x, a.y) - dist(t.x, t.y, b.x, b.y);
            });
            mem.srP = pts;
            return nav(t.x, t.y);
        }

        if (t.type === 'base' && dd < 3.5) {
            mem.state = 'dock';
            mem.tgt = null;
            return { left: 0, right: 0, drill: false };
        }

        return nav(t.x, t.y);
    }

    if (mem.state === 'search') {
        mem.srT++;

        if (obs.site && obs.site.distance < 8) {
            var sh = obs.heading + obs.site.bearing;
            var sx = obs.x + obs.site.distance * Math.cos(sh * Math.PI / 180);
            var sy = obs.y + obs.site.distance * Math.sin(sh * Math.PI / 180);
            if (obs.site.distance < 1.3) {
                mem.state = 'drill';
                return { left: 0, right: 0, drill: true };
            }
            return nav(sx, sy);
        }

        if (mem.srI < mem.srP.length && mem.srT < 600) {
            var pt = mem.srP[mem.srI];
            var pd = dist(obs.x, obs.y, pt.x, pt.y);
            if (pd < 3) {
                mem.srI++;
                return { left: 0, right: 0, drill: false };
            }
            return nav(pt.x, pt.y);
        }

        if (mem.trips[mem.tripIdx] && mem.trips[mem.tripIdx][mem.siteIdx])
            mem.trips[mem.tripIdx][mem.siteIdx].done = true;
        mem.siteIdx++;
        mem.state = 'drive';
        mem.tgt = null;
        return { left: 0, right: 0, drill: false };
    }

    if (mem.state === 'drill') {
        if (obs.drilling !== undefined && obs.drilling >= 6) {
            if (mem.oppDrill) {
                mem.oppDrill = false;
                for (var ti = 0; ti < mem.trips.length; ti++) {
                    for (var si2 = 0; si2 < mem.trips[ti].length; si2++) {
                        if (!mem.trips[ti][si2].done && dist(obs.x, obs.y, mem.trips[ti][si2].x, mem.trips[ti][si2].y) < 15) {
                            mem.trips[ti][si2].done = true;
                        }
                    }
                }
            } else {
                if (mem.trips[mem.tripIdx] && mem.trips[mem.tripIdx][mem.siteIdx])
                    mem.trips[mem.tripIdx][mem.siteIdx].done = true;
                mem.siteIdx++;
            }
            mem.state = 'drive';
            mem.tgt = null;
            return { left: 0, right: 0, drill: false };
        }

        if (obs.timeLeft < 12 + dBase * 5 && obs.carried > 0) {
            mem.oppDrill = false;
            mem.state = 'drive';
            mem.tgt = null;
            return { left: 0, right: 0, drill: false };
        }

        var v = (obs.wheelLeft + obs.wheelRight) / 2;
        if (Math.abs(v) > 0.05) {
            var br = -v * 0.4;
            return { left: cl(br, -0.3, 0.3), right: cl(br, -0.3, 0.3), drill: true };
        }
        var hold = obs.pitch > 1 ? Math.min(0.15, obs.pitch * 0.012) : (obs.pitch < -1 ? Math.max(-0.15, obs.pitch * 0.012) : 0);
        return { left: hold, right: hold, drill: true };
    }

    if (mem.state === 'dock') {
        if (obs.docked) {
            if (obs.battery > 0.8 || obs.timeLeft < 300) {
                mem.tripIdx++;
                mem.siteIdx = 0;
                mem.state = 'drive';
                mem.tgt = null;
                if (mem.tripIdx >= mem.trips.length) {
                    mem.done = true;
                }
                return { left: 0, right: 0, drill: false };
            }
            return { left: 0, right: 0, drill: false };
        }
        if (obs.beacon) {
            var bh2 = obs.heading + obs.beacon.bearing;
            return nav(obs.x + obs.beacon.distance * Math.cos(bh2 * Math.PI / 180),
                obs.y + obs.beacon.distance * Math.sin(bh2 * Math.PI / 180));
        }
        return nav(mem.bx, mem.by);
    }

    return { left: 0, right: 0, drill: false };
}

function act(obs, mem) {
    function clamp(v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; }
    function norm180(a) {
        while (a > 180) a -= 360;
        while (a < -180) a += 360;
        return a;
    }
    function dist(x1, y1, x2, y2) {
        var dx = x2 - x1, dy = y2 - y1;
        return Math.sqrt(dx * dx + dy * dy);
    }

    function nav(hdg, tx, ty) {
        var dx = tx - obs.x, dy = ty - obs.y;
        var d = Math.sqrt(dx * dx + dy * dy);
        var th = Math.atan2(dy, dx) * 180 / Math.PI;
        var err = norm180(th - hdg);
        var fwd = obs.rays[4]; if (!(fwd > 0)) fwd = 15; if (fwd > 15) fwd = 15;
        var rMin = 15;
        for (var i = 0; i < 9; i++) {
            var r = obs.rays[i]; if (!(r > 0)) r = 15; if (r > 15) r = 15;
            if (r < rMin) rMin = r;
        }
        var lC = 0, rC = 0;
        for (var i = 5; i <= 8; i++) { var r = obs.rays[i]; if (!(r > 0)) r = 15; if (r > 15) r = 15; lC += r; }
        lC /= 4;
        for (var i = 0; i <= 3; i++) { var r = obs.rays[i]; if (!(r > 0)) r = 15; if (r > 15) r = 15; rC += r; }
        rC /= 4;

        if (rMin < 1.0) return { left: -0.4, right: -0.4, drill: false };

        if (fwd < 4) {
            var diff = lC - rC;
            var turnDir;
            if (diff > 1.0) turnDir = 1;
            else if (diff < -1.0) turnDir = -1;
            else turnDir = mem.lastTurn || 1;
            mem.lastTurn = turnDir;
            var amt = clamp((4 - fwd) / 4 * 0.5, 0.2, 0.5);
            return { left: clamp(-amt * turnDir, -1, 1), right: clamp(amt * turnDir, -1, 1), drill: false };
        }

        if (Math.abs(err) > 50) {
            var turn = clamp(err / 50 * 0.35, -0.4, 0.4);
            return { left: -turn, right: turn, drill: false };
        }

        var speed = 0.85;
        if (d < 15) speed = clamp(d / 15 * 0.85, 0.15, 0.85);
        if (fwd < 8) speed = Math.min(speed, 0.45);
        if (fwd < 6) speed = Math.min(speed, 0.25);

        var steer = clamp(err * 0.025, -0.4, 0.4);
        if (lC < 3) steer -= (3 - lC) * 0.08;
        if (rC < 3) steer += (3 - rC) * 0.08;
        steer = clamp(steer, mem.prevSteer - 0.1, mem.prevSteer + 0.1);
        mem.prevSteer = steer;

        return { left: clamp(speed - steer, -0.7, 1), right: clamp(speed + steer, -0.7, 1), drill: false };
    }

    function navBase(hdg) {
        if (obs.beacon && obs.beacon.distance < 20) {
            var b = obs.beacon.bearing, bd = obs.beacon.distance;
            if (bd < 2) return { left: 0, right: 0, drill: false };
            if (Math.abs(b) > 30) {
                var t = clamp(b / 30 * 0.3, -0.4, 0.4);
                return { left: -t, right: t, drill: false };
            }
            var sp = clamp(bd / 5 * 0.3, 0.05, 0.3);
            var st = clamp(b * 0.05, -0.4, 0.4);
            return { left: clamp(sp - st, -0.5, 1), right: clamp(sp + st, -0.5, 1), drill: false };
        }
        return nav(hdg, mem.bx, mem.by);
    }

    function genSearch(cx, cy) {
        var pts = [{ x: cx, y: cy }];
        for (var i = -2; i <= 2; i++) for (var j = -2; j <= 2; j++) {
            if (i || j) pts.push({ x: clamp(cx + i * 10, 5, 395), y: clamp(cy + j * 10, 5, 395) });
        }
        pts.sort(function (a, b) { return dist(cx, cy, a.x, a.y) - dist(cx, cy, b.x, b.y); });
        return pts;
    }

    if (!mem.init) {
        mem.init = true;
        mem.tick = 0;
        mem.bx = 200; mem.by = 200; mem.cap = 5;
        if (obs.mission) {
            mem.bx = obs.mission.base.x; mem.by = obs.mission.base.y;
            mem.cap = obs.mission.capacity || 5;
        }
        mem.hints = [];
        if (obs.mission && obs.mission.hints) {
            for (var i = 0; i < obs.mission.hints.length; i++) {
                var h = obs.mission.hints[i];
                if (h.estimate > 0) {
                    var d = dist(h.x, h.y, mem.bx, mem.by);
                    mem.hints.push({ x: h.x, y: h.y, est: h.estimate, done: false });
                }
            }
        }
        mem.state = 'goto';
        mem.target = null;
        mem.sPts = []; mem.sIdx = 0;
        mem.stuck = 0; mem.sPhase = 0; mem.sDir = 1;
        mem.prevX = obs.x; mem.prevY = obs.y; mem.prevHdg = obs.heading;
        mem.prevSteer = 0; mem.lastTurn = 1;
        mem.found = []; mem.drillHold = 0; mem.drillTicks = 0;
    }
    mem.tick++;

    var hdg = obs.heading;
    if (mem.tick > 1 && Math.abs(norm180(hdg - mem.prevHdg)) > 30) hdg = mem.prevHdg;
    mem.prevHdg = hdg;

    var mdx = obs.x - mem.prevX, mdy = obs.y - mem.prevY;
    if (mem.state !== 'drill') {
        if (Math.sqrt(mdx * mdx + mdy * mdy) > 0.05) { mem.stuck = 0; mem.sPhase = 0; }
        else mem.stuck++;
