    if (obs.bumped && mem.state !== 'drill') mem.stuck = Math.max(mem.stuck, 25);
    mem.prevX = obs.x; mem.prevY = obs.y;

    if (mem.stuck > 20 && mem.state !== 'drill') {
        if (mem.sPhase === 0) {
            if (mem.stuck < 40) return { left: -0.5, right: -0.5, drill: false };
            mem.sPhase = 1; mem.stuck = 20;
        }
        if (mem.sPhase === 1) {
            if (mem.stuck < 45) return { left: 0.4 * mem.sDir, right: -0.4 * mem.sDir, drill: false };
            mem.sPhase = 2; mem.stuck = 20;
        }
        if (mem.sPhase === 2) {
            if (mem.stuck < 35) return { left: 0.5, right: 0.5, drill: false };
            mem.sPhase = 0; mem.stuck = 0; mem.sDir = -mem.sDir;
        }
    }

    if (obs.site && obs.site.distance < 8) {
        var sh = hdg + obs.site.bearing;
        var sx = obs.x + obs.site.distance * Math.cos(sh * Math.PI / 180);
        var sy = obs.y + obs.site.distance * Math.sin(sh * Math.PI / 180);
        var f = false;
        for (var i = 0; i < mem.found.length; i++) {
            if (dist(sx, sy, mem.found[i].x, mem.found[i].y) < 8) {
                mem.found[i].x = sx; mem.found[i].y = sy;
                mem.found[i].val = obs.site.value; f = true; break;
            }
        }
        if (!f) mem.found.push({ x: sx, y: sy, val: obs.site.value, done: false });
    }

    var dBase = dist(obs.x, obs.y, mem.bx, mem.by);
    var ticksLeft = obs.timeLeft * 10;
    var retTicks = Math.max(dBase / 2.5 * 10 + 100, 100);
    var needReturn = obs.carried >= mem.cap || obs.battery < 0.12 ||
        (obs.carried > 0 && ticksLeft < retTicks * 1.5);

    var canDrill = obs.carried < mem.cap && obs.battery > 0.05 && ticksLeft > retTicks + 70;

    if (obs.site && obs.site.distance < 1.5 && mem.state !== 'drill' && canDrill) {
        mem.state = 'drill'; mem.drillHold = 0; mem.drillTicks = 0;
    }

    if (mem.state === 'drill') {
        if (obs.drilling >= 6) {
            if (mem.target && mem.target.ref) mem.target.ref.done = true;
            for (var i = 0; i < mem.found.length; i++)
                if (!mem.found[i].done && dist(obs.x, obs.y, mem.found[i].x, mem.found[i].y) < 10)
                    mem.found[i].done = true;
            mem.target = null; mem.sPts = []; mem.sIdx = 0;
            mem.drillHold = 0; mem.drillTicks = 0; mem.state = 'goto';
            return { left: 0, right: 0, drill: false };
        }

        mem.drillTicks++;
        if (mem.drillTicks > 600 || obs.battery < 0.05 || ticksLeft < 100) {
            mem.state = 'return'; mem.target = null;
            mem.sPts = []; mem.sIdx = 0; mem.drillTicks = 0;
            return { left: 0, right: 0, drill: false };
        }

        var v = (obs.wheelLeft + obs.wheelRight) / 2;
        if (Math.abs(v) > 0.03) {
            mem.drillHold = clamp(mem.drillHold - v * 0.15, -0.35, 0.35);
        } else {
            mem.drillHold = clamp(mem.drillHold + obs.pitch * 0.005, -0.35, 0.35);
        }
        return { left: mem.drillHold, right: mem.drillHold, drill: true };
    }

    if (mem.state === 'dock') {
        if (obs.docked) {
            if (obs.battery > 0.5 || ticksLeft < 300) {
                mem.state = 'goto'; mem.target = null; mem.sPts = [];
