            var sh = hdg + obs.site.bearing;
            var sx = obs.x + obs.site.distance * Math.cos(sh * Math.PI / 180);
            var sy = obs.y + obs.site.distance * Math.sin(sh * Math.PI / 180);
            if (obs.site.distance < 1.5 && canDrill) {
                mem.state = 'drill'; mem.drillHold = 0; mem.drillTicks = 0;
                return { left: 0, right: 0, drill: true };
