      wheelL * mem.lastOutL > 0.02) {
    var ratioL = Math.abs(wheelL / mem.lastOutL);
    if (ratioL > 0.12 && ratioL < 5.5) {
      var aL = ratioL < mem.scaleL * 0.7 ? 0.10 : 0.025;
      mem.scaleL = clamp(mem.scaleL * (1 - aL) + ratioL * aL, 0.5, 5.2);
    }
  }
  if (mem.lastOutR !== undefined &&
      Math.abs(mem.lastOutR - mem.prevOutR) < 0.035 &&
      Math.abs(mem.lastOutR) > 0.16 &&
      wheelR * mem.lastOutR > 0.02) {
    var ratioR = Math.abs(wheelR / mem.lastOutR);
    if (ratioR > 0.12 && ratioR < 5.5) {
      var aR = ratioR < mem.scaleR * 0.7 ? 0.10 : 0.025;
      mem.scaleR = clamp(mem.scaleR * (1 - aR) + ratioR * aR, 0.5, 5.2);
    }
  }

  var rawDeltaH = wrap(rawH - mem.lastRawH);
  var compassJump = Math.abs(rawDeltaH - dpsi) > 0.9 && Math.abs(rawDeltaH) > 0.65;
  if (compassJump) mem.compassBad = 25;
  else if (mem.compassBad > 0) mem.compassBad--;

  var yawPred = mem.yaw + dpsi;
  var compassErr = wrap(rawH - mem.bias - yawPred);
  if (!compassJump && mem.compassBad <= 0 && Math.abs(compassErr) < 1.2) {
    mem.yaw = yawPred + 0.22 * compassErr;
  } else {
