  }
  mem.yaw = wrap(mem.yaw);

  mem.gpsWinPath += Math.abs(wheelV) * dt;
  mem.gpsWinTurn += Math.abs(dpsi);
  if (tick % 40 === 0) {
    var gpsWindowMove = dist(rawX, rawY, mem.gpsWinX, mem.gpsWinY);
    if (mem.gpsWinPath > 2.8 && mem.gpsWinTurn < 0.9 && gpsWindowMove < 0.5) {
