    var cdy = rawY - mem.calY;
    var cdist = Math.sqrt(cdx * cdx + cdy * cdy);
    if (!mem.gpsFrozen && !compassJump && mem.calPath > 4.5 &&
        cdist > 3.5 && mem.calTurn < 0.42) {
      var course = Math.atan2(cdy, cdx);
      var avgCompass = Math.atan2(mem.calSin, mem.calCos);
      var biasErr = wrap(avgCompass - course - mem.bias);
      if (Math.abs(biasErr) < 0.85) {
