  var oldPX = mem.poseX;
  var oldPY = mem.poseY;
  var midYaw = mem.yaw - dpsi * 0.5;
  var predX = oldPX + wheelV * dt * Math.cos(midYaw);
  var predY = oldPY + wheelV * dt * Math.sin(midYaw);

  if (!mem.gpsFrozen) {
    var gpsInnovation = dist(predX, predY, rawX, rawY);
    if (gpsInnovation < 25) {
      var gpsAlpha = gpsInnovation > 8 ? 0.06 : (gpsInnovation > 3 ? 0.18 : 0.38);
      if (mem.gpsRecover > 0) {
