  var prevSolar = n(mem.prevSolar, solar);
  var batteryDrop = prevBattery - battery;
  var energyUse = batteryDrop + 0.5 * (prevSolar + solar) * dt;
  if (!docked && !mem.lastDrill && Math.abs(wheelV) > 0.12 &&
      (batteryDrop > 0.00005 || solar < 0.004 || battery < 0.95)) {
    if (energyUse > 0) mem.energyAcc += energyUse;
    mem.energyDist += Math.max(stepDist, Math.abs(wheelV) * dt * 0.5);
    if (mem.energyDist >= 12) {
      var measuredRate = mem.energyAcc / Math.max(1, mem.energyDist);
      if (measuredRate > 0.00012 && measuredRate < 0.03) {
        var erAlpha = measuredRate > mem.energyRate ? 0.24 : 0.10;
        mem.energyRate = clamp(mem.energyRate * (1 - erAlpha) +
                               measuredRate * erAlpha, 0.0003, 0.02);
