  mem.prevSolar = solar;
  mem.lastRawH = rawH;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;

  var rays = [];
  var sourceRays = Array.isArray(obs.rays) ? obs.rays : [];
  for (var ri = 0; ri < 9; ri++) {
    var rv = n(sourceRays[ri], 15);
    rays[ri] = clamp(rv < 0 ? 15 : rv, 0, 15);
