  function rayAt(angleDeg) {
    var a = clamp(angleDeg, -80, 80);
    var p = (a + 80) / 20;
    var i = Math.floor(p);
    if (i >= 8) i = 8;
    var j = Math.min(8, i + 1);
    var f = p - i;
    if (i === j) return rays[i];
    return rays[i] * (1 - f) + rays[j] * f;
