  var bumped = !!obs.bumped;
  if (bumped && !mem.wasBumped) {
    var openLeft = rayAt(20) + rayAt(40) + rayAt(60);
    var openRight = rayAt(-20) + rayAt(-40) + rayAt(-60);
    if (Math.abs(openLeft - openRight) < 0.1) mem.bumpSide = (tick % 2) ? 1 : -1;
    else mem.bumpSide = openLeft > openRight ? 1 : -1;
