  mem.wasBumped = bumped;

  function output(left, right, drill) {
    left = clamp(left, -1, 1);
    right = clamp(right, -1, 1);
    mem.prevOutL = n(mem.lastOutL, 0);
    mem.prevOutR = n(mem.lastOutR, 0);
    mem.lastOutL = left;
    mem.lastOutR = right;
    mem.lastDrill = !!drill;
    return { left: left, right: right, drill: !!drill };
