  function motorCommand(target, actual, side) {
    var scale = side === 0 ? mem.scaleL : mem.scaleR;
    var integ = side === 0 ? mem.iL : mem.iR;
    var err = target - actual;

    if (Math.abs(target) < 0.045) {
