    }

    if (d <= stop) return moveOutput(0, 0, false);

    var relDeg = wrap(targetRel * Math.PI / 180) * 180 / Math.PI;
    var steerDeg = relDeg;
    var clearance = rayAt(clamp(relDeg, -80, 80));
    var speedCap = cruise;

    if (Math.abs(relDeg) < 78 && clearance < 2.7) {
      var leftOpen = rayAt(relDeg + 40) + rayAt(relDeg + 60);
      var rightOpen = rayAt(relDeg - 40) + rayAt(relDeg - 60);
