    if (clearance < 1.4) speedCap = Math.min(speedCap, 0.14);
    else if (clearance < 2.1) speedCap = Math.min(speedCap, 0.22);
    else if (clearance < 3.2) speedCap = Math.min(speedCap, 0.38);
    else if (clearance < 5.0) speedCap = Math.min(speedCap, 0.56);

