    y = p.y;

    var dx = x - mem.poseX;
    var dy = y - mem.poseY;
    var d = Math.sqrt(dx * dx + dy * dy);

    if (mem.trackKey !== key) {
      mem.trackKey = key;
      mem.trackBest = d;
      mem.trackLast = tick;
      mem.detour = null;
      mem.detourCount = 0;
    } else if (d < n(mem.trackBest, d) - 0.55) {
      mem.trackBest = d;
      mem.trackLast = tick;
    }

    if (mem.detour && mem.detour.key === key) {
      var detDist = dist(mem.poseX, mem.poseY, mem.detour.x, mem.detour.y);
      if (detDist < 1.6 || tick > mem.detour.until) {
