      var rel = wrap(goalAngle - mem.yaw) * 180 / Math.PI;
      var leftClear = rayAt(rel + 45) + rayAt(rel + 65);
      var rightClear = rayAt(rel - 45) + rayAt(rel - 65);
      var side;
      if (Math.abs(leftClear - rightClear) < 0.1) side = (tick % 2) ? 1 : -1;
      else side = leftClear > rightClear ? 1 : -1;

      var detAngle = goalAngle + side * 0.85;
      var detPoint = clampPoint(mem.poseX + 6 * Math.cos(detAngle),
