      mem.trackLast = tick;
    }

    var tx = x, ty = y;
    if (mem.detour && mem.detour.key === key) {
      tx = mem.detour.x;
      ty = mem.detour.y;
    }

    dx = tx - mem.poseX;
    dy = ty - mem.poseY;
    var targetDist = Math.sqrt(dx * dx + dy * dy);
    var targetRel = wrap(Math.atan2(dy, dx) - mem.yaw) * 180 / Math.PI;
