  function chooseHint() {
    var best = -1;
    var bestScore = -1;
    for (var i = 0; i < mem.hints.length; i++) {
      var hh = mem.hints[i];
      if (!hh || hh.status !== 0) continue;

      var outDist = dist(mem.poseX, mem.poseY, hh.x, hh.y);
      var homeDist = dist(mem.baseX, mem.baseY, hh.x, hh.y);
      var route = outDist + homeDist;

      var need = energyNeed(route, carried + 1, 1.75, 50);
      var timeNeed = (route + 45) * 1.20 / 0.68 + 90;
      if (battery < need + 0.035 || timeLeft < timeNeed) continue;

      var score = hh.value / (45 + route + 0.35 * outDist);
