    var active = Math.floor(n(mem.activeHint, -1));
    var resume = mem.siteResume || "SELECT";
    var sx = mem.siteGX;
    var sy = mem.siteGY;

    if (assoc >= 0 && assoc < mem.hints.length) {
      mem.hints[assoc].status = 1;
    }

    if (sx !== null && sy !== null) {
      mem.lastSampleX = sx;
      mem.lastSampleY = sy;
      mem.lastSampleTick = tick;
      if (mem.signalPeakVal > 0 &&
