      mem.activeHint = -1;
      mem.mode = "SELECT";
      mem.searchQueue = [];
      mem.searchWaitStart = 0;
    } else {
      if (resume === "RETURN" || resume === "SITE") resume = "SELECT";
      mem.mode = resume;
    }

    mem.siteActive = false;
    mem.drillStarted = false;
    mem.drillFullTicks = 0;
    mem.siteAssoc = -1;
    mem.siteResume = null;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.lastDrill = false;
  }

  function siteControl() {
    var s = obs.site && typeof obs.site === "object" ? obs.site : null;
    var d, bearing;

    if (s) {
      updateSiteGoal(s);
      d = Math.max(0, n(s.distance, 0));
      bearing = n(s.bearing, 0);
    } else if (mem.siteGX !== null && mem.siteGY !== null) {
      var dx = mem.siteGX - mem.poseX;
      var dy = mem.siteGY - mem.poseY;
      d = Math.sqrt(dx * dx + dy * dy);
      bearing = wrap(Math.atan2(dy, dx) - mem.yaw) * 180 / Math.PI;
    } else {
      mem.siteActive = false;
      mem.mode = mem.siteResume || "SELECT";
      return idleOutput();
    }

    if (d > 1.15) {
      return driveRel(bearing, d, 0.88, 0.48);
    }

    var pitch = n(obs.pitch, 0) * Math.PI / 180;
    var proj = Math.cos(bearing * Math.PI / 180);
    var correction = clamp((d - 0.65) * 0.18 * proj, -0.06, 0.06);
    var slopeHold = clamp(Math.sin(pitch) * 0.22, -0.045, 0.045);
    var holdV = clamp(correction + slopeHold, -0.105, 0.105);
    var c = wheelCommands(holdV, 0);

    var still = Math.max(Math.abs(wheelL), Math.abs(wheelR)) < 0.135;
    var drillOn = (d <= 1.25 && still) ||
                  (mem.lastDrill && d <= 1.42) ||
