  }

  function beginSearch(cx, cy, value, hintIndex) {
    var p = clampPoint(cx, cy);
    mem.searchCenterX = p.x;
    mem.searchCenterY = p.y;
    mem.searchCenterVal = Math.max(0, n(value, 0));
    mem.searchRound = -1;
    mem.searchStep = 12;
    mem.searchStage = "center";
    mem.searchQueue = [{ x: p.x, y: p.y }];
    mem.searchIndex = 0;
    mem.searchWaitStart = 0;
    mem.searchPointPeak = 0;
    mem.searchRoundBestVal = 0;
    mem.searchRoundBestX = p.x;
    mem.searchRoundBestY = p.y;
    if (hintIndex >= 0 && hintIndex < mem.hints.length) {
      mem.activeHint = hintIndex;
    } else {
      mem.activeHint = -1;
    }
    mem.mode = "SEARCH";
    mem.trackKey = null;
    mem.detour = null;
  }

  function setSearchQueue(points, stage) {
    var clean = [];
    var seen = {};
    for (var i = 0; i < points.length; i++) {
      var p = clampPoint(points[i].x, points[i].y);
      var key = Math.round(p.x * 10) + ":" + Math.round(p.y * 10);
      if (!seen[key]) {
        seen[key] = true;
        clean.push(p);
      }
    }

    var ordered = [];
    var px = mem.poseX, py = mem.poseY;
    while (clean.length) {
      var bi = 0, bd = 1e30;
      for (var j = 0; j < clean.length; j++) {
        var dd = dist(px, py, clean[j].x, clean[j].y);
        if (dd < bd) {
          bd = dd;
          bi = j;
        }
      }
      var chosen = clean.splice(bi, 1)[0];
      ordered.push(chosen);
      px = chosen.x;
      py = chosen.y;
    }

    mem.searchQueue = ordered;
    mem.searchIndex = 0;
    mem.searchWaitStart = 0;
    mem.searchPointPeak = 0;
    mem.searchStage = stage;
    mem.searchRoundBestVal = Math.max(0, n(mem.searchCenterVal, 0));
    mem.searchRoundBestX = mem.searchCenterX;
    mem.searchRoundBestY = mem.searchCenterY;
  }

  function startSearchCross(step) {
    var cx = mem.searchCenterX;
    var cy = mem.searchCenterY;
    setSearchQueue([
      { x: cx + step, y: cy },
      { x: cx - step, y: cy },
      { x: cx, y: cy + step },
      { x: cx, y: cy - step }
    ], "cross");
  }

  function finishSearch() {
    var ai = Math.floor(n(mem.activeHint, -1));
    if (ai >= 0 && ai < mem.hints.length &&
        mem.hints[ai].status === 0) {
      mem.hints[ai].status = 2;
    }

    if (mem.signalPeakVal > 0 &&
        dist(mem.signalPeakX, mem.signalPeakY,
             mem.searchCenterX, mem.searchCenterY) < 25) {
      mem.signalPeakVal = 0;
      mem.signalPeakTick = 0;
    }

    mem.activeHint = -1;
    mem.mode = "SELECT";
    mem.searchQueue = [];
    mem.searchIndex = 0;
    mem.searchWaitStart = 0;
    mem.genericCooldown = tick + 420;
    mem.trackKey = null;
    mem.detour = null;
  }

  function finishSearchQueue() {
    if (mem.searchStage === "center") {
      mem.searchCenterVal = Math.max(0, n(mem.searchRoundBestVal, 0));
      mem.searchRound = 0;
      mem.searchStep = 12;
      startSearchCross(mem.searchStep);
      return;
    }

    if (mem.searchStage === "cross") {
      var bestVal = Math.max(0, n(mem.searchRoundBestVal, 0));
      if (bestVal > mem.searchCenterVal) {
        mem.searchCenterVal = bestVal;
        mem.searchCenterX = mem.searchRoundBestX;
        mem.searchCenterY = mem.searchRoundBestY;
      }

      if (mem.searchCenterVal <= 0.0001) {
        finishSearch();
        return;
      }

      if (mem.searchRound < 2) {
        mem.searchRound++;
        mem.searchStep = Math.max(4.5, mem.searchStep * 0.68);
        startSearchCross(mem.searchStep);
        return;
      }

      var fineStep = 5.0;
      var fx = mem.searchCenterX;
      var fy = mem.searchCenterY;
      setSearchQueue([
        { x: fx + fineStep, y: fy },
        { x: fx - fineStep, y: fy },
        { x: fx, y: fy + fineStep },
        { x: fx, y: fy - fineStep },
        { x: fx + fineStep, y: fy + fineStep },
        { x: fx + fineStep, y: fy - fineStep },
        { x: fx - fineStep, y: fy + fineStep },
        { x: fx - fineStep, y: fy - fineStep }
      ], "fine");
      return;
    }

    finishSearch();
  }

