  }

  function wheelCommands(v, omega, extra) {
    var targetL = clamp(v - 0.3 * omega, -0.65, 0.65);
    var targetR = clamp(v + 0.3 * omega, -0.65, 0.65);
    return [
      motorCommand(targetL, wheelL, 0, extra),
      motorCommand(targetR, wheelR, 1, extra)
    ];
  }

  function moveOutput(v, omega, drill, extra) {
    var c = wheelCommands(v, omega, num(extra, 0));
    return output(c[0], c[1], drill);
  }

  function stationaryOutput(extra) {
    return moveOutput(0, 0, false, num(extra, 0));
  }

  function driveRelative(targetRel, d, stop, cruise) {
    if (tick <= num(mem.bumpUntil, 0)) {
      return moveOutput(-0.18, num(mem.bumpSide, 1) * 0.65, false,
                        0.12 * Math.sin(num(obs.pitch, 0) / DEG));
    }

    if (d <= stop) {
      return stationaryOutput(0.10 * Math.sin(num(obs.pitch, 0) / DEG));
    }

    var rel = wrap(targetRel * PI / 180) * DEG;
    var aim = rel;
    var clearance = 15;

    if (Math.abs(rel) < 80) {
      clearance = rayAt(rel);
      if (clearance < 4.2) {
        var bestScore = -1e30;
        var bestAngle = rel;
        for (var ca = -80; ca <= 80; ca += 20) {
          var cr = rayAt(ca);
          var diff = Math.abs(wrap((ca - rel) / DEG)) * DEG;
          var score = -0.015 * diff +
                      0.10 * Math.min(cr, 10) -
                      0.22 * Math.pow(Math.max(0, 3.8 - cr), 2);

          var worldA = mem.yaw + ca / DEG;
          var wx = Math.cos(worldA);
          var wy = Math.sin(worldA);
          if (mem.poseX < mem.minX + 6 && wx < 0) score -= 1.5;
          if (mem.poseX > mem.maxX - 6 && wx > 0) score -= 1.5;
          if (mem.poseY < mem.minY + 6 && wy < 0) score -= 1.5;
          if (mem.poseY > mem.maxY - 6 && wy > 0) score -= 1.5;

          if (score > bestScore) {
            bestScore = score;
            bestAngle = ca;
          }
        }
        aim = bestAngle;
        clearance = rayAt(aim);
      }
    }

    var cap = Math.min(0.55, Math.max(0.1, cruise));
    if (badRayCount >= 6) cap = Math.min(cap, 0.38);
    if (clearance < 1.3) cap = Math.min(cap, 0.08);
    else if (clearance < 2.0) cap = Math.min(cap, 0.18);
    else if (clearance < 3.4) cap = Math.min(cap, 0.34);
    else if (clearance < 5.0) cap = Math.min(cap, 0.46);

    var remaining = Math.max(0, d - stop);
    var v = Math.min(cap, Math.sqrt(0.42 * remaining));
    if (remaining > 0.16) v = Math.max(v, Math.min(cap, 0.14));

    var err = aim / DEG;
    var absErr = Math.abs(err);
    if (absErr > 1.18) {
      v = 0;
    } else {
      v *= Math.max(0, Math.cos(err));
      if (absErr > 0.8) v = Math.min(v, 0.20);
      else if (absErr > 0.52) v = Math.min(v, 0.38);
    }

    if (clearance < 1.3) v = 0;
    var omega = clamp(1.55 * err, -0.95, 0.95);
    return moveOutput(v, omega, false,
                      0.12 * Math.sin(num(obs.pitch, 0) / DEG));
  }

  function clampPoint(x, y) {
    return {
      x: clamp(x, mem.minX + 3, mem.maxX - 3),
      y: clamp(y, mem.minY + 3, mem.maxY - 3)
    };
  }

  function navTo(x, y, stop, key, cruise) {
    var p = clampPoint(x, y);
    x = p.x;
    y = p.y;

    var mainDist = dist(mem.poseX, mem.poseY, x, y);
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = mainDist;
      mem.navStuck = 0;
      mem.detour = null;
      mem.detourCount = 0;
    } else if (mainDist < num(mem.navBest, mainDist) - 0.65) {
      mem.navBest = mainDist;
      mem.navStuck = 0;
    } else if (mainDist > stop + 3 && Math.abs(wheelV) > 0.22) {
      mem.navStuck = num(mem.navStuck, 0) + dt;
    } else {
      mem.navStuck = Math.max(0, num(mem.navStuck, 0) - dt);
    }

    if (mem.detour && mem.detour.key === key) {
      var detD = dist(mem.poseX, mem.poseY, mem.detour.x, mem.detour.y);
      if (detD < 1.6 || tick > mem.detour.until) {
        mem.detour = null;
        mem.navBest = mainDist;
        mem.navStuck = 0;
      }
    }

    if (!mem.detour && mem.navStuck > 14 &&
        num(mem.detourCount, 0) < 3 && mainDist > stop + 4) {
      var leftOpen = rayAt(20) + rayAt(40) + rayAt(60);
      var rightOpen = rayAt(-20) + rayAt(-40) + rayAt(-60);
      var side = leftOpen >= rightOpen ? 1 : -1;
      if (Math.abs(leftOpen - rightOpen) < 0.1) side = (tick % 2) ? 1 : -1;

      var goalAngle = Math.atan2(y - mem.poseY, x - mem.poseX);
      var detAngle = goalAngle + side * 0.9;
      var detPoint = clampPoint(mem.poseX + 7 * Math.cos(detAngle),
                                mem.poseY + 7 * Math.sin(detAngle));
      mem.detour = {
        x: detPoint.x,
        y: detPoint.y,
        key: key,
        until: tick + 110
      };
      mem.detourCount = num(mem.detourCount, 0) + 1;
      mem.navStuck = 0;
    }

    var tx = x, ty = y;
    if (mem.detour && mem.detour.key === key) {
      tx = mem.detour.x;
      ty = mem.detour.y;
    }

    var dx = tx - mem.poseX;
    var dy = ty - mem.poseY;
    var d = Math.sqrt(dx * dx + dy * dy);
    var rel = wrap(Math.atan2(dy, dx) - mem.yaw) * DEG;
    return driveRelative(rel, d, stop, cruise);
  }

  function energyNeed(distanceMeters, samples, margin, extraMeters) {
    var effective = Math.max(0, distanceMeters) * 1.30 +
                    Math.max(0, extraMeters || 0);
    var load = 1 + 0.13 * Math.max(0, samples);
    return 0.055 + effective * mem.energyRate * load * margin;
  }

  function baseDistance() {
    return dist(mem.poseX, mem.poseY, mem.baseX, mem.baseY);
  }

  function homeTime() {
    return baseDistance() * 1.55 / 0.48 + 22;
  }

  function canSampleHere() {
    if (carried >= capacity) return false;
    var home = baseDistance();
    if (home < 3) return timeLeft > 8;
    var need = energyNeed(home + 5, carried + 1, 2.0, 8);
    var tNeed = home * 1.5 / 0.46 + 24;
    return battery > need + 0.05 && timeLeft > tNeed + 7;
  }

  function chooseHint() {
    if (carried >= capacity) return -1;
    var best = -1;
    var bestScore = -1;

    for (var i = 0; i < mem.hints.length; i++) {
      var hh = mem.hints[i];
      if (!hh || hh.status !== 0) continue;

      var outDist = dist(mem.poseX, mem.poseY, hh.x, hh.y);
      var homeDist = dist(mem.baseX, mem.baseY, hh.x, hh.y);
      var route = outDist + homeDist;
      var need = energyNeed(route, carried + 1, 1.9, 40);
      var tNeed = (route * 1.40 + 50) / 0.50 + 25;

      if (battery < need + 0.05 || timeLeft < tNeed) continue;

      var score = hh.value / (48 + route * 1.15 + outDist * 0.25);
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }
    return best;
  }

  function siteEstimate(s) {
    var d = Math.max(0, num(s.distance, 0));
    var b = num(s.bearing, 0) / DEG;
    var a = mem.yaw + b;
    return {
      x: mem.poseX + d * Math.cos(a),
      y: mem.poseY + d * Math.sin(a)
    };
  }

  function updateSiteGoal(s) {
    if (!s) return;
    var p = siteEstimate(s);
    if (!isFinite(mem.siteGX) || !isFinite(mem.siteGY)) {
      mem.siteGX = p.x;
      mem.siteGY = p.y;
    } else {
      mem.siteGX = 0.60 * mem.siteGX + 0.40 * p.x;
      mem.siteGY = 0.60 * mem.siteGY + 0.40 * p.y;
    }
    mem.siteValue = num(s.value, mem.siteValue || 0);
  }

  function activateSite(s) {
    var resume = mem.mode || "SELECT";
    if (resume === "RETURN") resume = "SELECT";

    mem.siteResume = resume;
    mem.siteActive = true;
    mem.drillStarted = drilling > 0.01;
    mem.sampleStartCarried = carried;
    mem.siteAssoc = -1;
    updateSiteGoal(s);

    var p = siteEstimate(s);
    var best = -1;
    var bestD = 1e30;

    for (var i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].status !== 0) continue;
      var hd = dist(p.x, p.y, mem.hints[i].x, mem.hints[i].y);
      if (hd < bestD) {
        bestD = hd;
        best = i;
      }
    }
    if (best >= 0 && bestD <= 30) mem.siteAssoc = best;

    var ai = Math.floor(num(mem.activeHint, -1));
    if (ai >= 0 && ai < mem.hints.length &&
        mem.hints[ai].status === 0 &&
        dist(p.x, p.y, mem.hints[ai].x, mem.hints[ai].y) <= 36) {
      mem.siteAssoc = ai;
    }

    mem.mode = "SITE";
  }

  function finishSite() {
    var assoc = Math.floor(num(mem.siteAssoc, -1));
    var active = Math.floor(num(mem.activeHint, -1));
    var resume = mem.siteResume || "SELECT";
    var sx = isFinite(mem.siteGX) ? mem.siteGX : mem.poseX;
    var sy = isFinite(mem.siteGY) ? mem.siteGY : mem.poseY;

    if (assoc >= 0 && assoc < mem.hints.length) {
      mem.hints[assoc].status = 1;
      if (mem.siteValue > 0) mem.hints[assoc].value = mem.siteValue;
    }

    mem.lastSampleX = mem.poseX;
    mem.lastSampleY = mem.poseY;
    mem.lastSampleTick = tick;
    mem.finishedSiteTick = tick;

    if (mem.signalPeakVal > 0 &&
        dist(mem.signalPeakX, mem.signalPeakY, sx, sy) < 22) {
      mem.signalPeakVal = 0;
      mem.signalPeakTick = 0;
    }

    if (assoc >= 0 && assoc === active) {
      mem.activeHint = -1;
      mem.mode = "SELECT";
      mem.searchQueue = [];
      mem.searchIndex = 0;
    } else {
      if (resume === "RETURN" || resume === "SITE") resume = "SELECT";
      mem.mode = resume;
    }

    mem.siteActive = false;
    mem.drillStarted = false;
    mem.siteAssoc = -1;
    mem.siteResume = null;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.lastDrill = false;
  }

  function siteControl() {
    var s = obs.site && typeof obs.site === "object" ? obs.site : null;
    var d, bearing;

    if (s) {
      updateSiteGoal(s);
      d = Math.max(0, num(s.distance, 0));
      bearing = num(s.bearing, 0);
    } else if (isFinite(mem.siteGX) && isFinite(mem.siteGY)) {
      var dx = mem.siteGX - mem.poseX;
      var dy = mem.siteGY - mem.poseY;
      d = Math.sqrt(dx * dx + dy * dy);
      bearing = wrap(Math.atan2(dy, dx) - mem.yaw) * DEG;
    } else {
      mem.siteActive = false;
      mem.mode = mem.siteResume || "SELECT";
      return stationaryOutput(0);
    }

    if (drilling > 0.01) mem.drillStarted = true;

    if (d > 1.30) {
      return driveRelative(bearing, d, 1.02, 0.38);
    }

    var pitch = num(obs.pitch, 0) / DEG;
    var radial = 0;
    if (!mem.drillStarted) {
      radial = clamp((d - 0.92) * 0.16 *
                     Math.cos(bearing / DEG), -0.07, 0.07);
    }
    var holdV = clamp(radial + 0.42 * Math.sin(pitch), -0.12, 0.12);
    var c = wheelCommands(holdV, 0, 0.18 * Math.sin(pitch));

    var still = Math.abs(wheelV) < 0.12 &&
                Math.abs(wheelL) < 0.15 &&
                Math.abs(wheelR) < 0.15;
    var drillOn = d <= 1.42 && still;
    if (drilling > 0.01 && d <= 1.5 && still) drillOn = true;
    if (drillOn) mem.drillStarted = true;

    return output(c[0], c[1], drillOn);
  }

  function setSearchQueue(points, stage) {
    var clean = [];
    var seen = {};

    for (var i = 0; i < points.length; i++) {
      var p = clampPoint(points[i].x, points[i].y);
      var key = Math.round(p.x * 10) + ":" + Math.round(p.y * 10);
      if (!seen[key]) {
        seen[key] = true;
        clean.push(p);
      }
    }

    var ordered = [];
    var px = mem.poseX, py = mem.poseY;
    while (clean.length) {
      var bi = 0, bd = 1e30;
      for (var j = 0; j < clean.length; j++) {
        var dd = dist(px, py, clean[j].x, clean[j].y);
        if (dd < bd) {
          bd = dd;
          bi = j;
        }
      }
      var chosen = clean.splice(bi, 1)[0];
      ordered.push(chosen);
      px = chosen.x;
      py = chosen.y;
    }

    mem.searchQueue = ordered;
    mem.searchIndex = 0;
    mem.searchWaitStart = 0;
    mem.searchPointPeak = 0;
    mem.searchStage = stage;
    mem.searchRoundBestVal = Math.max(0, num(mem.searchCenterVal, 0));
    mem.searchRoundBestX = mem.searchCenterX;
    mem.searchRoundBestY = mem.searchCenterY;
  }

  function startSearchCross(step) {
    var cx = mem.searchCenterX;
    var cy = mem.searchCenterY;
    setSearchQueue([
      { x: cx + step, y: cy },
      { x: cx - step, y: cy },
      { x: cx, y: cy + step },
      { x: cx, y: cy - step }
    ], "cross");
  }

  function beginSearch(cx, cy, value, hintIndex) {
    var p = clampPoint(cx, cy);
    mem.searchCenterX = p.x;
    mem.searchCenterY = p.y;
    mem.searchCenterVal = Math.max(0, num(value, 0));
    mem.searchRound = 0;
    mem.searchStep = 10;
    mem.searchPointPeak = 0;

    if (hintIndex >= 0 && hintIndex < mem.hints.length) {
      mem.activeHint = hintIndex;
    } else {
      mem.activeHint = -1;
    }

    mem.mode = "SEARCH";
    mem.navKey = null;
    mem.detour = null;

    if (dist(mem.poseX, mem.poseY, p.x, p.y) > 2.5) {
      mem.searchQueue = [{ x: p.x, y: p.y }];
      mem.searchIndex = 0;
      mem.searchWaitStart = 0;
      mem.searchStage = "center";
      mem.searchRoundBestVal = mem.searchCenterVal;
      mem.searchRoundBestX = p.x;
      mem.searchRoundBestY = p.y;
    } else {
      startSearchCross(mem.searchStep);
    }
  }

  function finishSearch() {
    var ai = Math.floor(num(mem.activeHint, -1));
    if (ai >= 0 && ai < mem.hints.length &&
        mem.hints[ai].status === 0) {
      mem.hints[ai].status = 2;
    }

    if (mem.signalPeakVal > 0 &&
        dist(mem.signalPeakX, mem.signalPeakY,
             mem.searchCenterX, mem.searchCenterY) < 25) {
      mem.signalPeakVal = 0;
      mem.signalPeakTick = 0;
    }

    mem.activeHint = -1;
    mem.mode = "SELECT";
    mem.searchQueue = [];
    mem.searchIndex = 0;
    mem.searchWaitStart = 0;
    mem.genericCooldown = tick + 300;
    mem.navKey = null;
    mem.detour = null;
  }

  function finishSearchQueue() {
    if (mem.searchStage === "center") {
      mem.searchCenterVal = Math.max(mem.searchCenterVal,
                                     num(mem.searchRoundBestVal, 0));
      mem.searchRound = 0;
      mem.searchStep = 10;
      startSearchCross(mem.searchStep);
      return;
    }

    var bestVal = Math.max(0, num(mem.searchRoundBestVal, 0));
    var threshold = Math.max(0.0005, mem.searchCenterVal * 0.03);

    if (bestVal > mem.searchCenterVal + threshold &&
        mem.searchRound < 2) {
      mem.searchCenterVal = bestVal;
      mem.searchCenterX = mem.searchRoundBestX;
      mem.searchCenterY = mem.searchRoundBestY;
      mem.searchRound++;
      mem.searchStep = Math.max(3, mem.searchStep * 0.55);
      startSearchCross(mem.searchStep);
      return;
    }

    finishSearch();
  }

  function projectedTaskDistance() {
    if (mem.mode === "TRAVEL") {
      var ti = Math.floor(num(mem.activeHint, -1));
      if (ti >= 0 && ti < mem.hints.length) {
        var hnt = mem.hints[ti];
        return dist(mem.poseX, mem.poseY, hnt.x, hnt.y) +
               dist(hnt.x, hnt.y, mem.baseX, mem.baseY) + 40;
      }
    }

    if (mem.mode === "SEARCH" && Array.isArray(mem.searchQueue)) {
      var total = 0;
      var px = mem.poseX, py = mem.poseY;
      for (var i = mem.searchIndex; i < mem.searchQueue.length; i++) {
        total += dist(px, py, mem.searchQueue[i].x, mem.searchQueue[i].y);
        px = mem.searchQueue[i].x;
        py = mem.searchQueue[i].y;
      }
      total += dist(px, py, mem.baseX, mem.baseY) + 15;
      return total;
    }

    if (mem.mode === "SITE" && mem.siteActive) return baseDistance() + 8;
    return 0;
  }

  function shouldReturn() {
    if (docked || mem.mode === "RETURN") return false;
    if (carried >= capacity && carried > 0) return true;

    var home = baseDistance();
    var homeNeed = energyNeed(home, carried, 2.15, 10);
    if (home > 3 && battery < homeNeed + 0.055) return true;

    if ((carried > 0 || home > 4) && timeLeft < homeTime() + 10) return true;

    var projected = projectedTaskDistance();
    if (projected > 0) {
      var taskNeed = energyNeed(projected, carried + 1, 1.9, 10);
      if (battery < taskNeed + 0.04) return true;

      var taskTime = projected * 1.43 / 0.48 + 35;
      if (timeLeft < taskTime && (carried > 0 || home > 4)) return true;
    }

    return false;
  }

  function enterReturn() {
    mem.mode = "RETURN";
    mem.activeHint = -1;
    mem.siteActive = false;
    mem.drillStarted = false;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.siteAssoc = -1;
    mem.siteResume = null;
    mem.searchQueue = [];
    mem.searchIndex = 0;
    mem.searchWaitStart = 0;
    mem.detour = null;
    mem.navKey = null;
  }

  function returnControl() {
    var b = obs.beacon && typeof obs.beacon === "object" ? obs.beacon : null;
    if (b) {
      var bd = Math.max(0, num(b.distance, 20));
      if (bd <= 1.65) {
        return stationaryOutput(0.10 * Math.sin(num(obs.pitch, 0) / DEG));
      }
      return driveRelative(num(b.bearing, 0), bd, 1.25, 0.48);
    }
    return navTo(mem.baseX, mem.baseY, 2.0, "home", 0.48);
  }

  var siteObs = obs.site && typeof obs.site === "object" ? obs.site : null;

  if (mem.siteActive && drilling > 0.01) mem.drillStarted = true;
  if (mem.siteActive && carried > num(mem.sampleStartCarried, carried)) {
    finishSite();
  }

  if (mem.mode === "RETURN") {
    if (docked && carried <= 0) {
      mem.mode = "SELECT";
      mem.activeHint = -1;
      mem.navKey = null;
      mem.detour = null;
    } else if (docked) {
      return stationaryOutput(0);
    } else {
      return returnControl();
    }
  }

  if (docked && carried > 0) return stationaryOutput(0);

  if (mem.siteActive) {
    if (!mem.drillStarted && !canSampleHere()) {
      enterReturn();
      return returnControl();
    }
    return siteControl();
  }

  if (siteObs && carried < capacity &&
      tick - num(mem.finishedSiteTick, -10000) > 3) {
    var sitePoint = siteEstimate(siteObs);
    var recentSame = mem.lastSampleX !== null &&
                     tick - num(mem.lastSampleTick, -10000) < 5 &&
                     dist(sitePoint.x, sitePoint.y,
                          mem.lastSampleX, mem.lastSampleY) < 1.2;
    if (!recentSame && canSampleHere()) {
      activateSite(siteObs);
      return siteControl();
    }
  }

  if (shouldReturn()) {
    enterReturn();
    return returnControl();
  }

  for (var loop = 0; loop < 8; loop++) {
    if (mem.mode === "SELECT" || !mem.mode) {
      var nextHint = chooseHint();
      if (nextHint >= 0) {
        mem.activeHint = nextHint;
        mem.mode = "TRAVEL";
        mem.navKey = null;
        mem.detour = null;
        continue;
      }

      if (carried < capacity &&
          tick >= num(mem.genericCooldown, 0) &&
          timeLeft > 35) {
        var gx = mem.poseX, gy = mem.poseY, gval = science;
        if (mem.signalPeakVal > gval * 1.20 &&
            tick - num(mem.signalPeakTick, 0) < 500 &&
            dist(mem.poseX, mem.poseY,
                 mem.signalPeakX, mem.signalPeakY) < 45) {
          gx = mem.signalPeakX;
          gy = mem.signalPeakY;
          gval = mem.signalPeakVal;
        }

        var genericRoute = dist(mem.poseX, mem.poseY, gx, gy) +
                           baseDistance() + 40;
        var genericNeed = energyNeed(genericRoute, carried + 1, 1.85, 10);
        var genericTime = genericRoute * 1.4 / 0.48 + 35;

        if (gval > 0.0001 &&
            battery > genericNeed + 0.05 &&
            timeLeft > genericTime) {
          beginSearch(gx, gy, gval, -1);
          continue;
        }
      }

      if (carried > 0 || baseDistance() > 3) {
        enterReturn();
        return returnControl();
      }
      return stationaryOutput(0);
    }

    if (mem.mode === "TRAVEL") {
      var ti = Math.floor(num(mem.activeHint, -1));
      if (ti < 0 || ti >= mem.hints.length ||
          mem.hints[ti].status !== 0) {
        mem.activeHint = -1;
        mem.mode = "SELECT";
        continue;
      }

      var targetHint = mem.hints[ti];
      var hd = dist(mem.poseX, mem.poseY, targetHint.x, targetHint.y);

      if (hd <= 3.2) {
        if (science > 0.0001) {
          beginSearch(mem.poseX, mem.poseY, science, ti);
        } else {
          targetHint.status = 2;
          mem.activeHint = -1;
          mem.mode = "SELECT";
        }
        continue;
      }

      return navTo(targetHint.x, targetHint.y, 1.8,
                   "hint:" + ti, 0.52);
    }

    if (mem.mode === "SEARCH") {
      if (!Array.isArray(mem.searchQueue) ||
          mem.searchIndex >= mem.searchQueue.length) {
        finishSearchQueue();
        continue;
      }

      var node = mem.searchQueue[mem.searchIndex];
      var nd = dist(mem.poseX, mem.poseY, node.x, node.y);

      if (nd <= 1.7) {
        if (Math.max(Math.abs(wheelL), Math.abs(wheelR)) > 0.13) {
          mem.searchWaitStart = 0;
          return stationaryOutput(0.10 * Math.sin(num(obs.pitch, 0) / DEG));
        }

        if (!mem.searchWaitStart) {
          mem.searchWaitStart = tick;
          mem.searchPointPeak = science;
        } else if (science > mem.searchPointPeak) {
          mem.searchPointPeak = science;
        }

        if (tick - mem.searchWaitStart >= 6) {
          if (mem.searchStage === "center") {
            mem.searchCenterVal = Math.max(mem.searchCenterVal,
                                           mem.searchPointPeak);
            mem.searchRound = 0;
            mem.searchStep = 10;
            startSearchCross(mem.searchStep);
          } else {
            var val = Math.max(0, num(mem.searchPointPeak, 0));
            if (val > mem.searchRoundBestVal) {
