function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  var dt = 0.1;
  var PI = Math.PI;

  function num(v, d) {
    if (v === null || v === undefined) return d;
    var q = Number(v);
    return isFinite(q) ? q : d;
  }

  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }

  function wrap(a) {
    while (a > PI) a -= 2 * PI;
    while (a < -PI) a += 2 * PI;
