    var y0 = num(obs.y, by);
    var h0 = num(obs.heading, 0) * PI / 180;

    mem.poseX = x0;
    mem.poseY = y0;
    mem.yaw = h0;
    mem.bias = 0;
    mem.lastRawX = x0;
    mem.lastRawY = y0;
    mem.lastRawH = h0;

    mem.gpsFrozen = false;
    mem.gpsRecover = 0;
    mem.gpsWinX = x0;
    mem.gpsWinY = y0;
    mem.gpsWinPath = 0;
    mem.gpsWinTurn = 0;

    mem.calX = x0;
    mem.calY = y0;
    mem.calPath = 0;
    mem.calTurn = 0;
    mem.calSin = 0;
    mem.calCos = 0;

    mem.energyRate = 0.0016;
    mem.energyAcc = 0;
    mem.energyDist = 0;
    mem.prevBattery = num(obs.battery, 1);
    mem.prevSolar = num(obs.solar, 0);
    mem.batteryMax = num(obs.battery, 1);

    mem.scaleL = 2.8;
    mem.scaleR = 2.8;
    mem.iL = 0;
    mem.iR = 0;
    mem.lastCmdL = 0;
    mem.lastCmdR = 0;
    mem.prevCmdL = 0;
    mem.prevCmdR = 0;
    mem.lastTargetL = 0;
    mem.lastTargetR = 0;
    mem.prevTargetL = 0;
    mem.prevTargetR = 0;
    mem.lastDrill = false;

    mem.lastRays = [];
    mem.rayRepeat = [];
    mem.rayBad = [];
    mem.rayMoved = 0;
