  learnGain(wheelR, 1);

  var rawDeltaH = wrap(rawH - mem.lastRawH);
  var compassJump = Math.abs(rawDeltaH - dpsi) > 0.9 &&
                    Math.abs(rawDeltaH) > 0.65;
  if (compassJump) mem.compassBad = 25;
  else if (mem.compassBad > 0) mem.compassBad--;

  var yawPred = mem.yaw + dpsi;
  var compassErr = wrap(rawH - mem.bias - yawPred);
  if (!compassJump && mem.compassBad <= 0 && Math.abs(compassErr) < 0.9) {
