      if (innovation > 8) gpsAlpha *= 0.4;
      if (mem.gpsRecover > 0) {
        gpsAlpha *= 0.55;
        mem.gpsRecover--;
      }
      var gx = clamp((rawX - predX) * gpsAlpha, -1.2, 1.2);
      var gy = clamp((rawY - predY) * gpsAlpha, -1.2, 1.2);
