    else mem.iR = integ;
    return clamp(u, -0.68, 0.68);
  }

  function moveOutput(v, omega, drill) {
    var targetL = clamp(v - 0.3 * omega, -0.85, 0.85);
    var targetR = clamp(v + 0.3 * omega, -0.85, 0.85);
    var left = motorCommand(targetL, wheelL, 0);
    var right = motorCommand(targetR, wheelR, 1);
    return output(left, right, drill, targetL, targetR);
  }

  function idleOutput() {
    return moveOutput(0, 0, false);
  }

  function driveRelative(targetRel, d, stop, cruise) {
    if (tick <= num(mem.bumpUntil, 0)) {
      return moveOutput(-0.17, num(mem.bumpSide, 1) * 0.62, false);
    }

    if (d <= stop) return idleOutput();

    var rel = wrap(targetRel * PI / 180) * 180 / PI;
    var aim = rel;
    var clearance = Math.abs(rel) <= 80 ? rayAt(rel) : 15;

    if (Math.abs(rel) < 78 && clearance < 3.3) {
      var bestScore = -1e30;
      var bestAngle = rel;
      for (var ca = -80; ca <= 80; ca += 20) {
        var cr = rayAt(ca);
        var diff = Math.abs(wrap((ca - rel) * PI / 180)) * 180 / PI;
        var score = 0.12 * Math.min(cr, 8) -
                    0.009 * diff -
                    0.45 * Math.max(0, 2.5 - cr);
        if (score > bestScore) {
          bestScore = score;
          bestAngle = ca;
        }
      }
      aim = bestAngle;
      clearance = rayAt(aim);
    }

    var speedCap = clamp(cruise, 0.10, 0.55);
    if (clearance < 1.35) speedCap = Math.min(speedCap, 0.06);
    else if (clearance < 2.0) speedCap = Math.min(speedCap, 0.16);
    else if (clearance < 3.0) speedCap = Math.min(speedCap, 0.25);
    else if (clearance < 4.5) speedCap = Math.min(speedCap, 0.36);

    var remaining = Math.max(0, d - stop);
    var v = Math.min(speedCap, Math.sqrt(0.55 * remaining));
    if (remaining > 0.20 && speedCap > 0.14 && v < 0.12) v = 0.12;

    var aimRad = aim * PI / 180;
    var absAim = Math.abs(aimRad);
    if (absAim > 1.23) {
      v = 0;
    } else {
      v *= Math.max(0, Math.cos(aimRad));
      if (absAim > 0.82) v = Math.min(v, 0.18);
    }

    if (clearance < 1.35) v = 0;
    var omega = clamp(1.55 * aimRad, -0.95, 0.95);
    return moveOutput(v, omega, false);
  }

  function clampPoint(x, y) {
    return {
      x: clamp(x, mem.minX + 3, mem.maxX - 3),
      y: clamp(y, mem.minY + 3, mem.maxY - 3)
    };
  }

  function navTo(x, y, stop, key, cruise) {
    var p = clampPoint(x, y);
    x = p.x;
    y = p.y;

    var mainDist = dist(mem.poseX, mem.poseY, x, y);
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = mainDist;
      mem.navStuck = 0;
      mem.detour = null;
      mem.detourCount = 0;
    } else if (mainDist < num(mem.navBest, mainDist) - 0.55) {
      mem.navBest = mainDist;
      mem.navStuck = 0;
    } else if (mainDist > stop + 2.5 &&
               (Math.abs(wheelV) > 0.16 || Math.abs(dpsi) > 0.05)) {
      mem.navStuck = num(mem.navStuck, 0) + dt;
    } else {
      mem.navStuck = Math.max(0, num(mem.navStuck, 0) - dt);
    }

    if (mem.detour && mem.detour.key === key) {
      var detD = dist(mem.poseX, mem.poseY, mem.detour.x, mem.detour.y);
      if (detD < 1.8 || tick > mem.detour.until) {
        mem.detour = null;
        mem.navBest = mainDist;
        mem.navStuck = 0;
      }
    }

    if (!mem.detour &&
        mem.navStuck > 13 &&
        mem.detourCount < 3 &&
        mainDist > stop + 4) {
      var leftClear = rayAt(20) + rayAt(40) + rayAt(60);
      var rightClear = rayAt(-20) + rayAt(-40) + rayAt(-60);
      var side;
      if (Math.abs(leftClear - rightClear) < 0.1) {
        side = (tick % 2) ? 1 : -1;
      } else {
        side = leftClear > rightClear ? 1 : -1;
      }

      var goalAngle = Math.atan2(y - mem.poseY, x - mem.poseX);
      var detAngle = goalAngle + side * 0.90;
      var dp = clampPoint(
        mem.poseX + 6.5 * Math.cos(detAngle),
        mem.poseY + 6.5 * Math.sin(detAngle)
      );

      if (dist(mem.poseX, mem.poseY, dp.x, dp.y) > 1.2) {
        mem.detour = {
          x: dp.x,
          y: dp.y,
          key: key,
          until: tick + 110
        };
        mem.detourCount++;
        mem.navStuck = 0;
      }
    }

    var tx = x;
    var ty = y;
    if (mem.detour && mem.detour.key === key) {
      tx = mem.detour.x;
      ty = mem.detour.y;
    }

    var dx = tx - mem.poseX;
    var dy = ty - mem.poseY;
    var d = Math.sqrt(dx * dx + dy * dy);
    var rel = wrap(Math.atan2(dy, dx) - mem.yaw) * 180 / PI;
    return driveRelative(rel, d, stop, cruise);
  }

  function baseDistance() {
    return dist(mem.poseX, mem.poseY, mem.baseX, mem.baseY);
  }

  function homeDistance() {
    var b = obs.beacon && typeof obs.beacon === "object" ? obs.beacon : null;
    if (b) return Math.max(0, num(b.distance, baseDistance()));
    return baseDistance();
  }

  function travelSeconds(d) {
    return Math.max(0, d) * 2.65 + 16;
  }

  function energyNeed(distanceMeters, samples, margin, extraMeters) {
    var d = Math.max(0, distanceMeters) * 1.12 +
            Math.max(0, extraMeters || 0);
    var load = 1 + 0.16 * Math.max(0, samples);
    return 0.085 + d * mem.energyRate * load * margin;
  }

  function canInvestigate(x, y) {
    var route = dist(mem.poseX, mem.poseY, x, y) +
                dist(x, y, mem.baseX, mem.baseY) + 25;
    return battery > energyNeed(route, carried + 1, 1.95, 4) + 0.05 &&
           timeLeft > route * 2.65 + 45;
  }

  function chooseHint() {
    if (carried >= capacity) return -1;

    var best = -1;
    var bestScore = -1;

    for (var i = 0; i < mem.hints.length; i++) {
      var hh = mem.hints[i];
      if (!hh || hh.status !== 0) continue;

      var outDist = dist(mem.poseX, mem.poseY, hh.x, hh.y);
      var homeDist = dist(mem.baseX, mem.baseY, hh.x, hh.y);
      var route = outDist + homeDist + 28;
      var need = energyNeed(route, carried + 1, 2.05, 8);
      var timeNeed = travelSeconds(outDist) +
                     travelSeconds(homeDist) + 82;

      if (battery < need + 0.06 || timeLeft < timeNeed) continue;

      var score = hh.value / (40 + route + 0.20 * outDist);
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }

    return best;
  }

  function siteEstimate(s) {
    var d = Math.max(0, num(s.distance, 0));
    var b = num(s.bearing, 0) * PI / 180;
    var a = mem.yaw + b;
    return {
      x: mem.poseX + d * Math.cos(a),
      y: mem.poseY + d * Math.sin(a)
    };
  }

  function updateSiteGoal(s) {
    if (!s) return;
    var p = siteEstimate(s);
    if (mem.siteGX === null ||
        mem.siteGY === null ||
        !isFinite(mem.siteGX) ||
        !isFinite(mem.siteGY)) {
      mem.siteGX = p.x;
      mem.siteGY = p.y;
    } else {
      mem.siteGX = 0.70 * mem.siteGX + 0.30 * p.x;
      mem.siteGY = 0.70 * mem.siteGY + 0.30 * p.y;
    }
    mem.siteValue = num(s.value, mem.siteValue || 0);
  }

  function activateSite(s) {
    var resume = mem.mode || "SELECT";
    if (resume === "RETURN") resume = "SELECT";

    mem.siteResume = resume;
    mem.siteActive = true;
    mem.drillStarted = drilling > 0.01;
    mem.drillStallTicks = 0;
    mem.prevDrilling = drilling;
    mem.sampleStartCarried = carried;
    mem.siteAssoc = -1;
    updateSiteGoal(s);

    var p = siteEstimate(s);
    var best = -1;
    var bestD = 1e30;

    for (var i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].status !== 0) continue;
      var hd = dist(p.x, p.y, mem.hints[i].x, mem.hints[i].y);
      if (hd < bestD) {
        bestD = hd;
        best = i;
      }
    }
    if (best >= 0 && bestD <= 32) mem.siteAssoc = best;

    var ai = Math.floor(num(mem.activeHint, -1));
    if (ai >= 0 &&
        ai < mem.hints.length &&
        mem.hints[ai].status === 0 &&
        dist(p.x, p.y, mem.hints[ai].x, mem.hints[ai].y) <= 35) {
      if (mem.siteAssoc < 0 || bestD > 20) mem.siteAssoc = ai;
    }

    mem.mode = "SITE";
  }

  function finishSite() {
    var assoc = Math.floor(num(mem.siteAssoc, -1));
    var active = Math.floor(num(mem.activeHint, -1));
    var resume = mem.siteResume || "SELECT";

    if (assoc >= 0 && assoc < mem.hints.length) {
      mem.hints[assoc].status = 1;
      if (mem.siteValue > 0) mem.hints[assoc].value = mem.siteValue;
    }

    mem.lastSampleX = mem.poseX;
    mem.lastSampleY = mem.poseY;
    mem.lastSampleTick = tick;
    mem.finishedSiteTick = tick;

    if (mem.signalPeakVal > 0 &&
        dist(mem.signalPeakX, mem.signalPeakY, mem.poseX, mem.poseY) < 25) {
      mem.signalPeakVal = 0;
      mem.signalPeakTick = 0;
    }

    if (assoc >= 0 && assoc === active) {
      mem.activeHint = -1;
      mem.mode = "SELECT";
      mem.searchQueue = [];
      mem.searchIndex = 0;
      mem.searchWaitStart = 0;
    } else {
      if (resume === "RETURN" || resume === "SITE") resume = "SELECT";
      mem.mode = resume;
    }

    mem.siteActive = false;
    mem.drillStarted = false;
    mem.drillStallTicks = 0;
    mem.siteAssoc = -1;
    mem.siteResume = null;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.lastDrill = false;
  }

  function siteControl() {
    var s = obs.site && typeof obs.site === "object" ? obs.site : null;
    var d;
    var bearing;

    if (s) {
      updateSiteGoal(s);
      d = Math.max(0, num(s.distance, 0));
      bearing = num(s.bearing, 0);
    } else if (mem.siteGX !== null && mem.siteGY !== null) {
      var dx = mem.siteGX - mem.poseX;
      var dy = mem.siteGY - mem.poseY;
      d = Math.sqrt(dx * dx + dy * dy);
      bearing = wrap(Math.atan2(dy, dx) - mem.yaw) * 180 / PI;
    } else {
      mem.siteActive = false;
      mem.mode = mem.siteResume || "SELECT";
      return idleOutput();
    }

    if (d > 0.90) {
      return driveRelative(bearing, d, 0.72, 0.31);
    }

    var still = Math.abs(wheelL) < 0.13 && Math.abs(wheelR) < 0.13;
    var drillOn = d <= 1.38 && still;
    if (drilling > 0.01 && d <= 1.48 && still) drillOn = true;

    if (drillOn || drilling > 0.01) mem.drillStarted = true;
    return moveOutput(0, 0, drillOn);
  }

  function setSearchQueue(points, stage) {
    var clean = [];
    var seen = {};

    for (var i = 0; i < points.length; i++) {
      var p = clampPoint(points[i].x, points[i].y);
      var key = Math.round(p.x * 10) + ":" + Math.round(p.y * 10);
      if (!seen[key]) {
        seen[key] = true;
        clean.push(p);
      }
    }

    var ordered = [];
    var px = mem.poseX;
    var py = mem.poseY;

    while (clean.length) {
      var bi = 0;
      var bd = 1e30;
      for (var j = 0; j < clean.length; j++) {
        var dd = dist(px, py, clean[j].x, clean[j].y);
        if (dd < bd) {
          bd = dd;
          bi = j;
        }
      }
      var chosen = clean.splice(bi, 1)[0];
      ordered.push(chosen);
      px = chosen.x;
      py = chosen.y;
    }

    mem.searchQueue = ordered;
    mem.searchIndex = 0;
    mem.searchWaitStart = 0;
    mem.searchPointPeak = 0;
    mem.searchStage = stage;
    mem.searchRoundBestVal = Math.max(0, num(mem.searchCenterVal, 0));
    mem.searchRoundBestX = mem.searchCenterX;
    mem.searchRoundBestY = mem.searchCenterY;
    mem.navKey = null;
    mem.detour = null;
  }

  function startSearchCross(step, stage) {
    var cx = mem.searchCenterX;
    var cy = mem.searchCenterY;
    setSearchQueue([
      { x: cx + step, y: cy },
      { x: cx - step, y: cy },
      { x: cx, y: cy + step },
      { x: cx, y: cy - step }
    ], stage);
  }

  function beginSearch(cx, cy, value, hintIndex, resume) {
    var p = clampPoint(cx, cy);
    mem.searchCenterX = p.x;
    mem.searchCenterY = p.y;
    mem.searchCenterVal = Math.max(0, num(value, 0));
    mem.searchRound = 0;
    mem.searchStep = 8;
    mem.searchWideTried = false;
    mem.searchPointPeak = 0;
    mem.searchResume = resume || "SELECT";

    if (hintIndex >= 0 && hintIndex < mem.hints.length) {
      mem.activeHint = hintIndex;
    } else {
      mem.activeHint = -1;
    }

    mem.mode = "SEARCH";
    mem.navKey = null;
    mem.detour = null;

    if (dist(mem.poseX, mem.poseY, p.x, p.y) > 2.8) {
      mem.searchQueue = [{ x: p.x, y: p.y }];
      mem.searchIndex = 0;
      mem.searchWaitStart = 0;
      mem.searchStage = "center";
      mem.searchRoundBestVal = mem.searchCenterVal;
      mem.searchRoundBestX = p.x;
      mem.searchRoundBestY = p.y;
    } else {
      startSearchCross(8, "cross");
    }
  }

  function finishSearch() {
    var ai = Math.floor(num(mem.activeHint, -1));
    if (ai >= 0 &&
        ai < mem.hints.length &&
        mem.hints[ai].status === 0) {
      mem.hints[ai].status = 2;
    }

    if (mem.signalPeakVal > 0 &&
        dist(mem.signalPeakX, mem.signalPeakY,
             mem.searchCenterX, mem.searchCenterY) < 25) {
      mem.signalPeakVal = 0;
      mem.signalPeakTick = 0;
    }

    var resume = mem.searchResume || "SELECT";
    if (ai >= 0) resume = "SELECT";
    if (resume === "SEARCH" || resume === "SITE" || resume === "RETURN") {
      resume = "SELECT";
    }

    mem.activeHint = -1;
    mem.mode = resume;
    mem.searchQueue = [];
    mem.searchIndex = 0;
    mem.searchWaitStart = 0;
    mem.genericCooldown = tick + 300;
    mem.navKey = null;
    mem.detour = null;
  }

  function finishSearchQueue() {
    if (mem.searchStage === "center") {
      mem.searchCenterVal = Math.max(
        mem.searchCenterVal,
        num(mem.searchRoundBestVal, 0)
      );
      mem.searchRound = 0;
      if (mem.searchCenterVal > 0.0001) {
        startSearchCross(8, "cross");
      } else {
        finishSearch();
      }
      return;
    }

    var bestVal = Math.max(0, num(mem.searchRoundBestVal, 0));
    var tolerance = Math.max(0.0001, mem.searchCenterVal * 0.025);

    if (bestVal > mem.searchCenterVal + tolerance) {
      mem.searchCenterVal = bestVal;
      mem.searchCenterX = mem.searchRoundBestX;
      mem.searchCenterY = mem.searchRoundBestY;
      mem.searchRound++;

      if (mem.searchRound < 4) {
        startSearchCross(8, "cross");
      } else {
        finishSearch();
      }
      return;
    }

    if (mem.searchStage === "cross" &&
        mem.searchRound === 0 &&
        !mem.searchWideTried &&
        mem.searchCenterVal > 0.0001) {
      mem.searchWideTried = true;
      startSearchCross(14, "wide");
      return;
    }

    finishSearch();
  }

  function projectedTaskDistance() {
    var home = baseDistance();

    if (mem.mode === "TRAVEL") {
      var ti = Math.floor(num(mem.activeHint, -1));
      if (ti >= 0 && ti < mem.hints.length) {
        var hnt = mem.hints[ti];
        return dist(mem.poseX, mem.poseY, hnt.x, hnt.y) +
               dist(hnt.x, hnt.y, mem.baseX, mem.baseY) + 32;
      }
    }

    if (mem.mode === "SEARCH" &&
        Array.isArray(mem.searchQueue) &&
        mem.searchQueue.length > 0) {
      var total = 0;
      var px = mem.poseX;
      var py = mem.poseY;
      for (var i = mem.searchIndex; i < mem.searchQueue.length; i++) {
        total += dist(px, py, mem.searchQueue[i].x, mem.searchQueue[i].y);
        px = mem.searchQueue[i].x;
        py = mem.searchQueue[i].y;
      }
      total += dist(px, py, mem.baseX, mem.baseY) + 22;
      return total;
    }

    if (mem.mode === "SITE" && mem.siteActive) return home + 9;

    if (mem.mode === "WANDER" && mem.wanderTarget) {
      return dist(mem.poseX, mem.poseY,
                  mem.wanderTarget.x, mem.wanderTarget.y) +
             dist(mem.wanderTarget.x, mem.wanderTarget.y,
                  mem.baseX, mem.baseY) + 24;
    }

    return 0;
  }

  function canSampleHere() {
    if (carried >= capacity) return false;

    var home = homeDistance();
    if (home < 3) return battery > 0.12 && timeLeft > 8;

    var need = energyNeed(home + 10, carried + 1, 1.9, 5);
    return battery > need + 0.06 &&
           timeLeft > travelSeconds(home) + 18;
  }

  function shouldReturn() {
    if (docked || mem.mode === "RETURN") return false;

    var committed = mem.siteActive && mem.drillStarted;
    if (committed) return false;

    if (carried >= capacity && carried > 0) return true;

    var home = homeDistance();
    var homeNeed = energyNeed(home + 10, carried, 2.0, 0);
    if (home > 3 && battery < homeNeed + 0.075) return true;

    if (carried > 0 && timeLeft < travelSeconds(home) + 12) return true;

    var projected = projectedTaskDistance();
    if (projected > 0) {
      var taskNeed = energyNeed(projected, carried + 1, 2.0, 5);
      if (battery < taskNeed + 0.05) return true;
      if (timeLeft < projected * 2.65 + 42) return true;
    }

    if (timeLeft < travelSeconds(home) + 10 &&
        (carried > 0 || home > 3)) {
      return true;
    }

    return false;
  }

  function enterReturn() {
    mem.mode = "RETURN";
    mem.activeHint = -1;
    mem.siteActive = false;
    mem.drillStarted = false;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.siteAssoc = -1;
    mem.siteResume = null;
    mem.searchQueue = [];
    mem.searchIndex = 0;
    mem.searchWaitStart = 0;
    mem.detour = null;
    mem.navKey = null;
  }

  function returnControl() {
    var b = obs.beacon && typeof obs.beacon === "object" ? obs.beacon : null;
    if (b) {
      var bd = Math.max(0, num(b.distance, 20));
      if (bd <= 2.0) return idleOutput();
      return driveRelative(num(b.bearing, 0), bd, 1.85, 0.48);
    }
    return navTo(mem.baseX, mem.baseY, 1.85, "home", 0.48);
  }

  function wanderPoint(index) {
    var ring = Math.floor(index / 8);
    var spoke = index % 8;
    var radius = 35 + 40 * ring;
    var angle = spoke * PI / 4 + ring * 0.23;
    return clampPoint(
      mem.baseX + radius * Math.cos(angle),
      mem.baseY + radius * Math.sin(angle)
    );
  }

  function genericSearchAllowed(x, y) {
    return canInvestigate(x, y);
  }

  var siteObs = obs.site && typeof obs.site === "object" ? obs.site : null;

  if (mem.siteActive) {
    if (drilling > 0.01) mem.drillStarted = true;

    if (mem.lastDrill) {
      if (drilling > mem.prevDrilling + 0.001) {
        mem.drillStallTicks = 0;
      } else {
        mem.drillStallTicks++;
      }
    }

    if (drilling + 0.08 < mem.prevDrilling) {
      mem.drillStarted = false;
      mem.drillStallTicks = 0;
    }
    if (mem.drillStallTicks > 100) {
      mem.drillStarted = false;
      mem.drillStallTicks = 0;
    }
    mem.prevDrilling = drilling;

    if (carried > num(mem.sampleStartCarried, carried)) {
      finishSite();
    }
  }

  if (mem.mode === "RETURN") {
    if (docked) {
      if (carried > 0) return idleOutput();
      if (battery < 0.72 && timeLeft > 35) return idleOutput();
      if (timeLeft < 35) return idleOutput();

      mem.mode = "SELECT";
      mem.activeHint = -1;
      mem.navKey = null;
      mem.detour = null;
    } else {
      return returnControl();
    }
  }

  if (mem.siteActive) {
    if (shouldReturn()) {
      enterReturn();
      return returnControl();
    }
    return siteControl();
  }

  if (siteObs && carried < capacity) {
    var sitePoint = siteEstimate(siteObs);
    var repeatedSample = mem.lastSampleX !== null &&
                         tick - num(mem.lastSampleTick, -10000) < 20 &&
                         dist(sitePoint.x, sitePoint.y,
                              mem.lastSampleX, mem.lastSampleY) < 2.5;

    if (!repeatedSample && canSampleHere()) {
      activateSite(siteObs);
      return siteControl();
    }
  }

  if (shouldReturn()) {
    enterReturn();
    return returnControl();
  }

  for (var loop = 0; loop < 10; loop++) {
    if (mem.mode === "SELECT" || !mem.mode) {
      var nextHint = chooseHint();

      if (nextHint >= 0) {
        mem.activeHint = nextHint;
        mem.activePeakVal = 0;
        mem.activePeakX = mem.poseX;
        mem.activePeakY = mem.poseY;
        mem.mode = "TRAVEL";
        mem.navKey = null;
        mem.detour = null;
        continue;
      }

      if (carried > 0) {
        enterReturn();
        return returnControl();
      }

      if (tick >= num(mem.genericCooldown, 0) && science > 0.0001) {
        var gx = mem.poseX;
        var gy = mem.poseY;
        var gval = science;

        if (mem.signalPeakVal > gval * 1.05 &&
            tick - num(mem.signalPeakTick, 0) < 600 &&
            dist(mem.poseX, mem.poseY,
                 mem.signalPeakX, mem.signalPeakY) < 45) {
          gx = mem.signalPeakX;
          gy = mem.signalPeakY;
          gval = mem.signalPeakVal;
        }

        if (gval > 0.0001 && genericSearchAllowed(gx, gy)) {
          beginSearch(gx, gy, gval, -1, "SELECT");
          continue;
        }
      }

      if (docked && battery < 0.66) return idleOutput();
      if (timeLeft < 55) return idleOutput();

      mem.mode = "WANDER";
      continue;
    }

    if (mem.mode === "TRAVEL") {
      var ti = Math.floor(num(mem.activeHint, -1));
      if (ti < 0 ||
          ti >= mem.hints.length ||
          mem.hints[ti].status !== 0) {
        mem.activeHint = -1;
        mem.mode = "SELECT";
        continue;
      }

      var targetHint = mem.hints[ti];
      var hd = dist(mem.poseX, mem.poseY, targetHint.x, targetHint.y);

      if (hd <= 2.8) {
        var cx = targetHint.x;
        var cy = targetHint.y;
        var cv = science;

        if (mem.activePeakVal > 0.0001 &&
            dist(mem.activePeakX, mem.activePeakY,
                 targetHint.x, targetHint.y) < 28) {
          cx = mem.activePeakX;
          cy = mem.activePeakY;
          cv = Math.max(cv, mem.activePeakVal);
        }

        beginSearch(cx, cy, cv, ti, "SELECT");
        continue;
      }

      return navTo(targetHint.x, targetHint.y, 1.8,
                   "hint:" + ti, 0.46);
    }

    if (mem.mode === "SEARCH") {
      if (!Array.isArray(mem.searchQueue) ||
          mem.searchIndex >= mem.searchQueue.length) {
        finishSearchQueue();
        continue;
      }

      var node = mem.searchQueue[mem.searchIndex];
      var nd = dist(mem.poseX, mem.poseY, node.x, node.y);

      if (nd <= 1.45) {
        if (Math.max(Math.abs(wheelL), Math.abs(wheelR)) > 0.14) {
          mem.searchWaitStart = 0;
          return idleOutput();
        }

        if (!mem.searchWaitStart) {
          mem.searchWaitStart = tick;
          mem.searchPointPeak = science;
        } else if (science > mem.searchPointPeak) {
          mem.searchPointPeak = science;
        }

        if (tick - mem.searchWaitStart >= 8) {
          var val = Math.max(0, num(mem.searchPointPeak, 0));
          if (val > mem.searchRoundBestVal) {
            mem.searchRoundBestVal = val;
            mem.searchRoundBestX = node.x;
            mem.searchRoundBestY = node.y;
          }

          if (mem.searchStage === "center") {
            mem.searchCenterVal = Math.max(mem.searchCenterVal, val);
            mem.searchRound = 0;
            if (mem.searchCenterVal > 0.0001) {
              startSearchCross(8, "cross");
            } else {
              finishSearch();
            }
          } else {
            mem.searchIndex++;
            mem.searchWaitStart = 0;
            mem.searchPointPeak = 0;
            if (mem.searchIndex >= mem.searchQueue.length) {
              finishSearchQueue();
            }
          }
          continue;
        }

        return idleOutput();
      }

      mem.searchWaitStart = 0;
      return navTo(node.x, node.y, 1.10,
                   "search:" + mem.searchStage + ":" +
                   mem.searchRound + ":" + mem.searchIndex, 0.43);
    }

    if (mem.mode === "WANDER") {
      if (tick >= num(mem.genericCooldown, 0) && science > 0.0001) {
        var wx = mem.poseX;
        var wy = mem.poseY;
        var wv = science;

        if (mem.signalPeakVal > wv * 1.08 &&
            tick - num(mem.signalPeakTick, 0) < 500 &&
            dist(mem.poseX, mem.poseY,
                 mem.signalPeakX, mem.signalPeakY) < 35) {
          wx = mem.signalPeakX;
          wy = mem.signalPeakY;
          wv = mem.signalPeakVal;
        }

        if (genericSearchAllowed(wx, wy)) {
          beginSearch(wx, wy, wv, -1, "WANDER");
          continue;
        }
      }

      if (!mem.wanderTarget) {
        var wp = wanderPoint(mem.wanderIndex);
        mem.wanderTarget = { x: wp.x, y: wp.y, index: mem.wanderIndex };
      }

      var target = mem.wanderTarget;
      var wanderRoute = dist(mem.poseX, mem.poseY, target.x, target.y) +
                        dist(target.x, target.y, mem.baseX, mem.baseY) + 20;

      if (battery < energyNeed(wanderRoute, carried + 1, 1.95, 4) + 0.05 ||
          timeLeft < wanderRoute * 2.65 + 38) {
        if (baseDistance() > 3 || carried > 0) {
          enterReturn();
          return returnControl();
        }
        if (docked) return idleOutput();
        return idleOutput();
      }

      var wd = dist(mem.poseX, mem.poseY, target.x, target.y);
      if (wd <= 2.0) {
        mem.wanderIndex++;
        mem.wanderTarget = null;
        mem.mode = "SELECT";
        continue;
      }

      return navTo(target.x, target.y, 1.65,
                   "wander:" + target.index, 0.46);
    }

    if (mem.mode === "SITE" && mem.siteActive) {
      return siteControl();
    }

    if (mem.mode === "RETURN") return returnControl();

    mem.mode = "SELECT";
  }

  return idleOutput();
}

function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  var PI = Math.PI;
  var DT = 0.1;

  function num(v, d) {
    if (v === null || v === undefined) return d;
    var q = Number(v);
    return isFinite(q) ? q : d;
  }

  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }

  function wrap(a) {
    while (a > PI) a -= 2 * PI;
    while (a < -PI) a += 2 * PI;
    return a;
  }

  function dist(x1, y1, x2, y2) {
    var dx = x2 - x1;
    var dy = y2 - y1;
    return Math.sqrt(dx * dx + dy * dy);
  }

  var mission = obs.mission || {};

  if (!mem.initialized) {
    var size = mission.size;
    var w = 400;
    var h = 400;

    if (typeof size === "number") {
      w = size;
      h = size;
    } else if (size && typeof size === "object") {
      w = num(size.width, num(size.x, 400));
      h = num(size.height, num(size.y, 400));
    }

    var base = mission.base || {};
    var bx = num(base.x, num(obs.x, w * 0.5));
    var by = num(base.y, num(obs.y, h * 0.5));
    var sourceHints = Array.isArray(mission.hints) ? mission.hints : [];

    var centered = bx < 0 || by < 0;
    for (var ci = 0; ci < sourceHints.length; ci++) {
      var ch = sourceHints[ci] || {};
      if (num(ch.x, 0) < 0 || num(ch.y, 0) < 0) centered = true;
    }

    mem.mapW = w;
    mem.mapH = h;
    mem.minX = size && typeof size === "object"
      ? num(size.minX, centered ? -w * 0.5 : 0)
      : (centered ? -w * 0.5 : 0);
    mem.maxX = size && typeof size === "object"
      ? num(size.maxX, mem.minX + w)
      : (centered ? w * 0.5 : w);
    mem.minY = size && typeof size === "object"
      ? num(size.minY, centered ? -h * 0.5 : 0)
      : (centered ? -h * 0.5 : 0);
    mem.maxY = size && typeof size === "object"
      ? num(size.maxY, mem.minY + h)
      : (centered ? h * 0.5 : h);

    mem.baseX = bx;
    mem.baseY = by;
    mem.capacity = Math.max(
      1,
      Math.floor(num(mission.capacity, num(obs.capacity, 5)))
    );
    mem.seconds = num(mission.seconds, 1200);

    mem.hints = [];
    for (var hi = 0; hi < sourceHints.length; hi++) {
      var hint = sourceHints[hi] || {};
      mem.hints.push({
        x: clamp(num(hint.x, bx), mem.minX + 5, mem.maxX - 5),
        y: clamp(num(hint.y, by), mem.minY + 5, mem.maxY - 5),
        value: Math.max(0.1, num(hint.estimate, num(hint.value, 1))),
        status: 0
      });
    }

    var x0 = num(obs.x, bx);
    var y0 = num(obs.y, by);
    var h0 = num(obs.heading, 0) * PI / 180;

    mem.poseX = x0;
    mem.poseY = y0;
    mem.yaw = h0;
    mem.bias = 0;
    mem.lastRawX = x0;
    mem.lastRawY = y0;
    mem.lastRawH = h0;

    mem.gpsFrozen = false;
    mem.gpsRecover = 0;
    mem.gpsWinX = x0;
    mem.gpsWinY = y0;
    mem.gpsWinPath = 0;
    mem.gpsWinTurn = 0;

    mem.calX = x0;
    mem.calY = y0;
    mem.calPath = 0;
    mem.calTurn = 0;
    mem.calSin = 0;
    mem.calCos = 0;

    mem.energyRate = 0.0015;
    mem.energyAcc = 0;
    mem.energyDist = 0;
    mem.prevBattery = num(obs.battery, 1);
    mem.prevSolar = num(obs.solar, 0);
    mem.batteryMax = num(obs.battery, 1);

    mem.gainL = 2.8;
    mem.gainR = 2.8;
    mem.deadL = 0.17;
    mem.deadR = 0.17;
    mem.iL = 0;
    mem.iR = 0;
    mem.lastCmdL = 0;
    mem.lastCmdR = 0;
    mem.prevCmdL = 0;
    mem.prevCmdR = 0;
    mem.lastTargetL = 0;
    mem.lastTargetR = 0;
    mem.prevTargetL = 0;
    mem.prevTargetR = 0;
    mem.lastDrill = false;

    mem.rays = [];
    mem.lastRays = [];
    mem.rayRepeat = [];
    mem.rayBad = [];
    mem.rayMoved = 0;
    for (var ri = 0; ri < 9; ri++) {
      mem.rays[ri] = 15;
      mem.lastRays[ri] = -1;
      mem.rayRepeat[ri] = 0;
      mem.rayBad[ri] = false;
    }

    mem.mode = "SELECT";
    mem.activeHint = -1;
    mem.activePeakVal = 0;
    mem.activePeakX = x0;
    mem.activePeakY = y0;

    mem.siteActive = false;
    mem.siteDrillStarted = false;
    mem.siteResume = null;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.siteValue = 0;
    mem.siteAssoc = -1;
    mem.sampleStartCarried = 0;
    mem.lastSampleX = null;
    mem.lastSampleY = null;
    mem.lastSampleTick = -10000;
    mem.finishedSiteTick = -10000;

    mem.searchQueue = [];
    mem.searchIndex = 0;
    mem.searchWaitStart = 0;
    mem.searchPointPeak = 0;
    mem.searchStage = "";
    mem.searchRound = 0;
    mem.searchStep = 8;
    mem.searchWideTried = false;
    mem.searchHint = -1;
    mem.searchResume = "SELECT";
    mem.searchCenterX = x0;
    mem.searchCenterY = y0;
    mem.searchCenterVal = 0;
    mem.searchRoundBestVal = 0;
    mem.searchRoundBestX = x0;
    mem.searchRoundBestY = y0;

    mem.signalPeakVal = 0;
    mem.signalPeakX = x0;
    mem.signalPeakY = y0;
    mem.signalPeakTick = 0;
    mem.lastGenericX = null;
    mem.lastGenericY = null;
    mem.lastGenericVal = 0;
    mem.lastGenericTick = -10000;
    mem.genericCooldown = 0;

    mem.navKey = null;
    mem.navBest = 0;
    mem.navStuck = 0;
    mem.detour = null;
    mem.detourCount = 0;
    mem.bumpUntil = 0;
    mem.bumpSide = 1;
    mem.bumpedPrev = false;

    mem.explorePts = [];
    for (var ey = mem.minY + 18; ey <= mem.maxY - 18; ey += 55) {
      for (var ex = mem.minX + 18; ex <= mem.maxX - 18; ex += 55) {
        mem.explorePts.push({ x: ex, y: ey, done: false });
      }
    }
    mem.exploreTarget = -1;
    mem.exploreAlt = false;

    mem.tick = 0;
    mem.initialized = true;
  }

  mem.tick = (mem.tick || 0) + 1;
  var tick = mem.tick;

  var rawX = num(obs.x, mem.lastRawX);
  var rawY = num(obs.y, mem.lastRawY);
  var rawH = num(obs.heading, mem.lastRawH * 180 / PI) * PI / 180;
  var wheelL = num(obs.wheelLeft, 0);
  var wheelR = num(obs.wheelRight, 0);
  var wheelV = (wheelL + wheelR) * 0.5;
  var dpsi = clamp((wheelR - wheelL) / 0.6 * DT, -1, 1);
  var battery = Math.max(0, num(obs.battery, 0));
  var solar = Math.max(0, num(obs.solar, 0));
  var carried = Math.max(0, Math.floor(num(obs.carried, 0)));
  var capacity = Math.max(1, Math.floor(num(obs.capacity, mem.capacity)));
  var timeLeft = num(obs.timeLeft, mem.seconds - tick * DT);
  var science = Math.max(0, num(obs.science, 0));
  var drilling = Math.max(0, num(obs.drilling, 0));
  var docked = !!obs.docked;

  if (battery > mem.batteryMax) mem.batteryMax = battery;

  var rawDeltaH = wrap(rawH - mem.lastRawH);
  var compassJump = Math.abs(rawDeltaH) > 0.72 &&
                    Math.abs(rawDeltaH - dpsi) > 0.82;

  if (compassJump) {
    mem.compassBad = 30;
  } else if (mem.compassBad > 0) {
    mem.compassBad--;
  }

  var yawPred = mem.yaw + dpsi;
  if (!compassJump && mem.compassBad <= 0) {
    var compassErr = wrap(rawH - mem.bias - yawPred);
    if (Math.abs(compassErr) < 1.0) {
      yawPred += clamp(0.10 * compassErr, -0.06, 0.06);
    }
  }
  mem.yaw = wrap(yawPred);

  mem.gpsWinPath += Math.abs(wheelV) * DT;
  mem.gpsWinTurn += Math.abs(dpsi);
  if (tick % 50 === 0) {
    var gpsWindowMove = dist(rawX, rawY, mem.gpsWinX, mem.gpsWinY);
    if (mem.gpsWinPath > 3.0 &&
        mem.gpsWinTurn < 1.1 &&
        gpsWindowMove < 0.45) {
      if (!mem.gpsFrozen) mem.gpsRecover = 20;
      mem.gpsFrozen = true;
    } else if (mem.gpsWinPath > 1.0 &&
               gpsWindowMove > Math.max(0.8, mem.gpsWinPath * 0.17)) {
      if (mem.gpsFrozen) mem.gpsRecover = 20;
      mem.gpsFrozen = false;
    }
    mem.gpsWinX = rawX;
    mem.gpsWinY = rawY;
    mem.gpsWinPath = 0;
    mem.gpsWinTurn = 0;
  }

  mem.calPath += Math.max(0, wheelV) * DT;
  mem.calTurn += Math.abs(dpsi);
  if (!compassJump && mem.compassBad <= 0) {
    mem.calSin += Math.sin(rawH);
    mem.calCos += Math.cos(rawH);
  }

  if (mem.calPath >= 9.5 || tick % 220 === 0) {
    var calDx = rawX - mem.calX;
    var calDy = rawY - mem.calY;
    var calDist = Math.sqrt(calDx * calDx + calDy * calDy);
    if (!mem.gpsFrozen &&
        mem.calPath > 7 &&
        calDist > 5.5 &&
        mem.calTurn < 0.45 &&
        Math.abs(mem.calSin) + Math.abs(mem.calCos) > 0.1) {
      var course = Math.atan2(calDy, calDx);
      var avgCompass = Math.atan2(mem.calSin, mem.calCos);
      var measuredBias = wrap(avgCompass - course);
      var biasErr = wrap(measuredBias - mem.bias);
      if (Math.abs(biasErr) < 0.9) {
        var biasStep = clamp(0.14 * biasErr, -0.05, 0.05);
        mem.bias = wrap(mem.bias + biasStep);
        mem.yaw = wrap(mem.yaw - biasStep);
      }
    }
    mem.calX = rawX;
    mem.calY = rawY;
    mem.calPath = 0;
    mem.calTurn = 0;
    mem.calSin = 0;
    mem.calCos = 0;
  }

  var oldPX = mem.poseX;
  var oldPY = mem.poseY;
  var moveV = Math.abs(wheelV) < 0.015 ? 0 : wheelV;
  var midYaw = mem.yaw - dpsi * 0.5;
  var predX = oldPX + moveV * DT * Math.cos(midYaw);
  var predY = oldPY + moveV * DT * Math.sin(midYaw);

  if (!mem.gpsFrozen) {
    var innovation = dist(predX, predY, rawX, rawY);
    if (innovation < 30) {
      var gpsAlpha = Math.abs(wheelV) > 0.08 ? 0.10 : 0.14;
      if (innovation > 6) gpsAlpha *= 0.4;
      if (mem.gpsRecover > 0) {
        gpsAlpha *= 0.55;
        mem.gpsRecover--;
      }
      predX += gpsAlpha * (rawX - predX);
      predY += gpsAlpha * (rawY - predY);
    }
  }

  mem.poseX = predX;
  mem.poseY = predY;

  var prevBattery = num(mem.prevBattery, battery);
  var prevSolar = num(mem.prevSolar, solar);
  var acceptedSolar = battery < mem.batteryMax - 0.035
    ? 0.5 * (prevSolar + solar) * DT
    : 0;
  var energyUse = prevBattery - battery + acceptedSolar;

  if (!docked && !mem.lastDrill &&
      (Math.abs(wheelV) > 0.06 || Math.abs(dpsi) > 0.03)) {
    if (energyUse > 0) mem.energyAcc += energyUse;
    mem.energyDist += Math.max(
      Math.abs(wheelV) * DT,
      Math.abs(dpsi) * 0.10
    );
    if (mem.energyDist >= 15) {
      var measuredRate = mem.energyAcc / Math.max(1, mem.energyDist);
      if (measuredRate > 0.00012 && measuredRate < 0.06) {
        var erAlpha = measuredRate > mem.energyRate ? 0.22 : 0.08;
        mem.energyRate = clamp(
          mem.energyRate * (1 - erAlpha) + measuredRate * erAlpha,
          0.0003,
          0.04
        );
      }
      mem.energyAcc = 0;
      mem.energyDist = 0;
    }
  }

  mem.prevBattery = battery;
  mem.prevSolar = solar;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;
  mem.lastRawH = rawH;

  var sourceRays = Array.isArray(obs.rays) ? obs.rays : [];
  mem.rayMoved += Math.abs(wheelV) * DT + 0.12 * Math.abs(dpsi);
  var badRayCount = 0;

  for (var r = 0; r < 9; r++) {
    var rv = num(sourceRays[r], 15);
    rv = clamp(rv < 0 ? 15 : rv, 0, 15);
    mem.rays[r] = rv;

    if (mem.lastRays[r] >= 0 &&
        Math.abs(rv - mem.lastRays[r]) < 0.002) {
      mem.rayRepeat[r] = (mem.rayRepeat[r] || 0) + 1;
    } else {
      mem.rayRepeat[r] = 0;
      mem.rayBad[r] = false;
    }

    if (mem.rayRepeat[r] > 90 && rv < 14.8 && mem.rayMoved > 2.5) {
      mem.rayBad[r] = true;
    }
    if (mem.rayBad[r]) badRayCount++;
    mem.lastRays[r] = rv;
  }
  if (tick % 50 === 0) mem.rayMoved = 0;

  function rayAt(angleDeg) {
    var a = clamp(angleDeg, -80, 80);
    var p = (a + 80) / 20;
    var i = Math.floor(p);
    if (i >= 8) i = 8;
    var j = Math.min(8, i + 1);
    var f = p - i;
    var v1 = mem.rayBad[i] ? 15 : mem.rays[i];
    var v2 = mem.rayBad[j] ? 15 : mem.rays[j];
    if (i === j) return v1;
    return v1 * (1 - f) + v2 * f;
  }

  var bumped = !!obs.bumped;
  if (bumped && !mem.bumpedPrev) {
    var openLeft = rayAt(20) + rayAt(40) + rayAt(60);
    var openRight = rayAt(-20) + rayAt(-40) + rayAt(-60);
    if (Math.abs(openLeft - openRight) < 0.1) {
      mem.bumpSide = (tick % 2) ? 1 : -1;
    } else {
      mem.bumpSide = openLeft > openRight ? 1 : -1;
    }
    mem.bumpUntil = tick + 10;
  }
  mem.bumpedPrev = bumped;

  if (science > mem.signalPeakVal + 0.000001) {
    mem.signalPeakVal = science;
    mem.signalPeakX = mem.poseX;
    mem.signalPeakY = mem.poseY;
    mem.signalPeakTick = tick;
  }

  if (mem.mode === "TRAVEL" &&
      mem.activeHint >= 0 &&
      mem.activeHint < mem.hints.length) {
    var activeTargetForPeak = mem.hints[mem.activeHint];
    if (dist(mem.poseX, mem.poseY,
             activeTargetForPeak.x, activeTargetForPeak.y) < 50 &&
        science > mem.activePeakVal + 0.000001) {
      mem.activePeakVal = science;
      mem.activePeakX = mem.poseX;
      mem.activePeakY = mem.poseY;
    }
  }

  if (mem.mode === "SEARCH" && science > mem.searchRoundBestVal) {
    mem.searchRoundBestVal = science;
    mem.searchRoundBestX = mem.poseX;
    mem.searchRoundBestY = mem.poseY;
  }

  function output(left, right, drill, targetL, targetR) {
    left = clamp(left, -1, 1);
    right = clamp(right, -1, 1);
    mem.prevCmdL = num(mem.lastCmdL, 0);
    mem.prevCmdR = num(mem.lastCmdR, 0);
    mem.prevTargetL = num(mem.lastTargetL, 0);
    mem.prevTargetR = num(mem.lastTargetR, 0);
    mem.lastCmdL = left;
    mem.lastCmdR = right;
    mem.lastTargetL = num(targetL, 0);
    mem.lastTargetR = num(targetR, 0);
    mem.lastDrill = !!drill;
    return { left: left, right: right, drill: !!drill };
  }

  function motorCommand(target, actual, side, pitchTerm) {
    var scale = side === 0 ? mem.gainL : mem.gainR;
    var dead = side === 0 ? mem.deadL : mem.deadR;
    var integ = side === 0 ? mem.iL : mem.iR;
    var lastCmd = side === 0 ? mem.lastCmdL : mem.lastCmdR;
    var prevCmd = side === 0 ? mem.prevCmdL : mem.prevCmdR;
    var lastTarget = side === 0 ? mem.lastTargetL : mem.lastTargetR;
    var prevTarget = side === 0 ? mem.prevTargetL : mem.prevTargetR;

    if (Math.abs(lastTarget) > 0.12 &&
        lastTarget * actual > 0.02 &&
        Math.abs(lastTarget - prevTarget) < 0.05 &&
        Math.abs(lastCmd - prevCmd) < 0.045 &&
        Math.abs(lastCmd) > dead + 0.08) {
      var den = Math.max(0.07, Math.abs(lastCmd) - dead);
      var est = Math.abs(actual) / den;
      if (est > 0.65 && est < 6) {
        scale = clamp(0.99 * scale + 0.01 * est, 0.8, 5.8);
        if (side === 0) mem.gainL = scale;
        else mem.gainR = scale;
      }
    }

    var err = target - actual;
    var u;

    if (Math.abs(target) < 0.035) {
      integ = clamp(integ + err * 0.50 * DT, -0.24, 0.24);
      if (Math.abs(actual) > 0.15) {
        u = -Math.sign(actual) *
            (dead + Math.min(0.20, 0.38 * Math.abs(actual))) +
            pitchTerm;
        integ *= 0.55;
      } else {
        if (Math.abs(actual) < 0.06) integ *= 0.85;
        u = integ + pitchTerm;
      }
    } else {
      if (lastTarget * target < -0.01) integ *= 0.45;
      integ = clamp(integ + err * 0.45 * DT, -0.24, 0.24);
      var ff = (target > 0 ? 1 : -1) *
               (dead + Math.abs(target) / Math.max(0.8, scale));
      u = ff + 0.20 * err + integ + pitchTerm;
    }

    if (side === 0) mem.iL = integ;
    else mem.iR = integ;
    return clamp(u, -0.78, 0.78);
  }

  function moveOutput(v, omega, drill) {
    var targetL = clamp(v - 0.3 * omega, -0.72, 0.72);
    var targetR = clamp(v + 0.3 * omega, -0.72, 0.72);
    var pitchRad = num(obs.pitch, 0) * PI / 180;
    var pitchTerm = 0.35 * Math.sin(pitchRad);
    var left = motorCommand(targetL, wheelL, 0, pitchTerm);
    var right = motorCommand(targetR, wheelR, 1, pitchTerm);
    return output(left, right, drill, targetL, targetR);
  }

  function idleOutput() {
    return moveOutput(0, 0, false);
  }

  function driveRelative(targetRel, d, stop, cruise) {
    if (tick <= num(mem.bumpUntil, 0)) {
      return moveOutput(-0.16, num(mem.bumpSide, 1) * 0.75, false);
    }

    if (d <= stop) return idleOutput();

    var rel = wrap(targetRel);
    var aim = rel;
    var relDeg = rel * 180 / PI;
    var clearance = Math.abs(relDeg) <= 80 ? rayAt(relDeg) : 15;

    if (Math.abs(relDeg) < 82 && clearance < 3.5) {
      var bestScore = -1e30;
      var bestAngle = relDeg;
      for (var ca = -80; ca <= 80; ca += 20) {
        var cr = rayAt(ca);
        var diff = Math.abs(wrap((ca - relDeg) * PI / 180)) * 180 / PI;
        var score = 0.70 * Math.min(cr, 8) - 0.018 * diff;
        var worldA = mem.yaw + ca * PI / 180;
        if (mem.poseX < mem.minX + 7 && Math.cos(worldA) < 0) score -= 1.5;
        if (mem.poseX > mem.maxX - 7 && Math.cos(worldA) > 0) score -= 1.5;
        if (mem.poseY < mem.minY + 7 && Math.sin(worldA) < 0) score -= 1.5;
        if (mem.poseY > mem.maxY - 7 && Math.sin(worldA) > 0) score -= 1.5;
        if (score > bestScore) {
          bestScore = score;
          bestAngle = ca;
        }
      }
      aim = bestAngle * PI / 180;
      clearance = rayAt(bestAngle);
    }

    var cap = clamp(cruise, 0.08, 0.50);
    if (badRayCount >= 7) cap = Math.min(cap, 0.34);
    if (clearance < 1.0) cap = Math.min(cap, 0.06);
    else if (clearance < 1.6) cap = Math.min(cap, 0.13);
    else if (clearance < 2.4) cap = Math.min(cap, 0.22);
    else if (clearance < 3.5) cap = Math.min(cap, 0.32);

    var front = rayAt(0);
    if (front < 0.9 && Math.abs(aim) < 0.45) cap = 0;
    else if (front < 1.4 && Math.abs(aim) < 0.30) {
      cap = Math.min(cap, 0.10);
    }

    var remaining = Math.max(0, d - stop);
    var v = Math.min(cap, Math.sqrt(0.45 * remaining));
    if (remaining > 0.45 && cap > 0.14 && v < 0.14) {
      v = 0.14;
    }

    var absAim = Math.abs(aim);
    if (absAim > 1.15) {
      v = 0;
    } else {
      v *= Math.max(0, Math.cos(aim));
      if (absAim > 0.82) v = Math.min(v, 0.17);
      else if (absAim > 0.58) v = Math.min(v, 0.28);
    }

    var omega = clamp(1.65 * aim, -1.30, 1.30);
    return moveOutput(v, omega, false);
  }

  function clampPoint(x, y) {
    return {
      x: clamp(x, mem.minX + 5, mem.maxX - 5),
      y: clamp(y, mem.minY + 5, mem.maxY - 5)
    };
  }

  function navTo(x, y, stop, key, cruise) {
    var p = clampPoint(x, y);
    x = p.x;
    y = p.y;

    var mainDist = dist(mem.poseX, mem.poseY, x, y);

    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = mainDist;
      mem.navStuck = 0;
      mem.detour = null;
      mem.detourCount = 0;
    } else if (mainDist < num(mem.navBest, mainDist) - 0.60) {
      mem.navBest = mainDist;
      mem.navStuck = 0;
      if (mem.detourCount > 0 && mainDist < mem.navBest - 2) {
        mem.detourCount = 0;
      }
    } else if (mainDist > stop + 3) {
      mem.navStuck = num(mem.navStuck, 0) + DT;
    } else {
      mem.navStuck = Math.max(0, num(mem.navStuck, 0) - DT);
    }

    if (mem.detour && mem.detour.key === key) {
      var detD = dist(mem.poseX, mem.poseY, mem.detour.x, mem.detour.y);
      if (detD < 1.7 || tick > mem.detour.until) {
        mem.detour = null;
        mem.navBest = mainDist;
        mem.navStuck = 0;
      } else if (detD < num(mem.detour.best, detD) - 0.5) {
        mem.detour.best = detD;
        mem.navStuck = 0;
      }
    }

    if (!mem.detour && mem.navStuck > 12 &&
        mem.detourCount < 5 && mainDist > stop + 4) {
      var leftOpen = rayAt(20) + rayAt(40) + rayAt(60);
      var rightOpen = rayAt(-20) + rayAt(-40) + rayAt(-60);
      var side;
      if (Math.abs(leftOpen - rightOpen) < 0.1) {
        side = (tick % 2) ? 1 : -1;
      } else {
        side = leftOpen > rightOpen ? 1 : -1;
      }

      var goalAngle = Math.atan2(y - mem.poseY, x - mem.poseX);
      var detAngle = goalAngle + side * 0.90;
      var dp = clampPoint(
        mem.poseX + 7 * Math.cos(detAngle),
        mem.poseY + 7 * Math.sin(detAngle)
      );

      if (dist(mem.poseX, mem.poseY, dp.x, dp.y) > 1.2) {
        mem.detour = {
          x: dp.x,
          y: dp.y,
          key: key,
          until: tick + 130,
          best: dist(mem.poseX, mem.poseY, dp.x, dp.y)
        };
        mem.detourCount++;
        mem.navStuck = 0;
      }
    }

    var tx = x;
    var ty = y;
    if (mem.detour && mem.detour.key === key) {
      tx = mem.detour.x;
      ty = mem.detour.y;
    }

    var dx = tx - mem.poseX;
    var dy = ty - mem.poseY;
    var d = Math.sqrt(dx * dx + dy * dy);
    var rel = wrap(Math.atan2(dy, dx) - mem.yaw);
    return driveRelative(rel, d, stop, cruise);
  }

  function baseDistance() {
    return dist(mem.poseX, mem.poseY, mem.baseX, mem.baseY);
  }

  function homeDistance() {
    var b = obs.beacon && typeof obs.beacon === "object" ? obs.beacon : null;
    if (b) return Math.max(0, num(b.distance, baseDistance()));
    return baseDistance();
  }

  function energyNeed(distanceMeters, samples, margin) {
    var d = Math.max(0, distanceMeters);
    var load = 1 + 0.16 * Math.max(0, samples);
    return 0.09 + d * mem.energyRate * load * margin;
  }

  function travelTime(d) {
    return Math.max(0, d) / 0.34 + 20;
  }

  function canSampleHere() {
    if (carried >= capacity) return false;
    var home = homeDistance();
    if (home < 3) return battery > 0.12 && timeLeft > 9;
    var need = energyNeed(home + 8, carried + 1, 1.65);
    return battery > need + 0.05 &&
           timeLeft > travelTime(home) + 8;
  }

  function chooseHint() {
    if (carried >= capacity) return -1;

    var best = -1;
    var bestScore = -1e30;

    for (var i = 0; i < mem.hints.length; i++) {
      var hh = mem.hints[i];
      if (!hh || hh.status !== 0) continue;

      var outDist = dist(mem.poseX, mem.poseY, hh.x, hh.y);
      var homeDist = dist(mem.baseX, mem.baseY, hh.x, hh.y);
      var route = outDist + homeDist + 30;
      var need = energyNeed(route, carried + 1, 1.75);

      if (battery < need + 0.05) continue;
      if (timeLeft < route / 0.35 + 75) continue;

      var score = hh.value / (40 + route * 0.9 + outDist * 0.15);
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }
    return best;
  }

  function siteEstimate(s) {
    var d = Math.max(0, num(s.distance, 0));
    var b = num(s.bearing, 0) * PI / 180;
    var a = mem.yaw + b;
    return {
      x: mem.poseX + d * Math.cos(a),
      y: mem.poseY + d * Math.sin(a)
    };
  }

  function updateSiteGoal(s) {
    if (!s) return;
    var p = siteEstimate(s);
    if (mem.siteGX === null ||
        mem.siteGY === null ||
        !isFinite(mem.siteGX) ||
        !isFinite(mem.siteGY)) {
      mem.siteGX = p.x;
      mem.siteGY = p.y;
    } else {
      mem.siteGX = 0.65 * mem.siteGX + 0.35 * p.x;
      mem.siteGY = 0.65 * mem.siteGY + 0.35 * p.y;
    }
    mem.siteValue = num(s.value, mem.siteValue || 0);
  }

  function activateSite(s) {
    var resume = mem.mode || "SELECT";
    if (resume === "RETURN" || resume === "SITE") resume = "SELECT";

    mem.siteResume = resume;
    mem.siteActive = true;
    mem.siteDrillStarted = drilling > 0.01;
    mem.sampleStartCarried = carried;
    mem.siteAssoc = -1;
    updateSiteGoal(s);

    var p = siteEstimate(s);
    var best = -1;
    var bestD = 1e30;

    for (var i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].status === 1) continue;
      var hd = dist(p.x, p.y, mem.hints[i].x, mem.hints[i].y);
      if (hd < bestD) {
        bestD = hd;
        best = i;
      }
    }

    if (best >= 0 && bestD <= 32) mem.siteAssoc = best;

    var ai = Math.floor(num(mem.activeHint, -1));
    if (ai < 0) ai = Math.floor(num(mem.searchHint, -1));
    if (ai >= 0 && ai < mem.hints.length &&
        mem.hints[ai].status !== 1 &&
        dist(p.x, p.y, mem.hints[ai].x, mem.hints[ai].y) <= 38 &&
        (mem.siteAssoc < 0 || bestD > 18)) {
      mem.siteAssoc = ai;
    }

    mem.mode = "SITE";
    mem.navKey = null;
  }

  function finishSite() {
    var assoc = Math.floor(num(mem.siteAssoc, -1));
    var active = Math.floor(num(mem.activeHint, -1));
    var searchHint = Math.floor(num(mem.searchHint, -1));
    var resume = mem.siteResume || "SELECT";
    var sx = mem.siteGX !== null && isFinite(mem.siteGX) ? mem.siteGX : mem.poseX;
    var sy = mem.siteGY !== null && isFinite(mem.siteGY) ? mem.siteGY : mem.poseY;

    if (assoc >= 0 && assoc < mem.hints.length) {
      mem.hints[assoc].status = 1;
      if (mem.siteValue > 0) mem.hints[assoc].value = mem.siteValue;
    }

    mem.lastSampleX = sx;
    mem.lastSampleY = sy;
    mem.lastSampleTick = tick;
    mem.finishedSiteTick = tick;

    if (mem.signalPeakVal > 0 &&
        dist(mem.signalPeakX, mem.signalPeakY, sx, sy) < 24) {
      mem.signalPeakVal = 0;
      mem.signalPeakTick = 0;
    }

    if (assoc >= 0 && assoc === active) {
      mem.activeHint = -1;
    }

    if (resume === "TRAVEL" && assoc >= 0 && assoc === active) {
      mem.mode = "SELECT";
    } else if (resume === "SITE" || resume === "RETURN") {
      mem.mode = "SELECT";
    } else {
      mem.mode = resume;
    }

    if (assoc >= 0 && assoc === searchHint && mem.mode !== "SEARCH") {
      mem.searchHint = -1;
    }

    mem.siteActive = false;
    mem.siteDrillStarted = false;
    mem.siteAssoc = -1;
    mem.siteResume = null;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.navKey = null;
    mem.lastDrill = false;
  }

  function siteControl() {
    var s = obs.site && typeof obs.site === "object" ? obs.site : null;
    var d;
    var bearing;

    if (s) {
      updateSiteGoal(s);
      d = Math.max(0, num(s.distance, 0));
      bearing = num(s.bearing, 0);
    } else if (mem.siteGX !== null && mem.siteGY !== null) {
      var dx = mem.siteGX - mem.poseX;
      var dy = mem.siteGY - mem.poseY;
      d = Math.sqrt(dx * dx + dy * dy);
      bearing = wrap(Math.atan2(dy, dx) - mem.yaw) * 180 / PI;
    } else {
      mem.siteActive = false;
      mem.mode = mem.siteResume || "SELECT";
      return idleOutput();
    }

    if (drilling > 0.01 || mem.lastDrill) {
      mem.siteDrillStarted = true;
    }

    if (!mem.siteDrillStarted && d > 0.92) {
      return driveRelative(bearing * PI / 180, d, 0.70, 0.27);
    }

    if (mem.siteDrillStarted && d > 1.50) {
      return driveRelative(bearing * PI / 180, d, 1.12, 0.16);
    }

    var still = Math.abs(wheelL) < 0.10 && Math.abs(wheelR) < 0.10;
    var drillOn = false;
    if (d <= 1.38 && still) drillOn = true;
    if (mem.siteDrillStarted && d <= 1.50 && still) drillOn = true;
    if (drillOn) mem.siteDrillStarted = true;

    return moveOutput(0, 0, drillOn);
  }

  function clampPointForSearch(x, y) {
    return clampPoint(x, y);
  }

  function setSearchQueue(points, stage) {
    var clean = [];
    var seen = {};

    for (var i = 0; i < points.length; i++) {
      var p = clampPointForSearch(points[i].x, points[i].y);
      var key = Math.round(p.x * 10) + ":" + Math.round(p.y * 10);
      if (!seen[key]) {
        seen[key] = true;
        clean.push(p);
      }
    }

    var ordered = [];
    var px = mem.poseX;
    var py = mem.poseY;

    while (clean.length) {
      var bi = 0;
      var bd = 1e30;
      for (var j = 0; j < clean.length; j++) {
        var dd = dist(px, py, clean[j].x, clean[j].y);
        if (dd < bd) {
          bd = dd;
          bi = j;
        }
      }
      var chosen = clean.splice(bi, 1)[0];
      ordered.push(chosen);
      px = chosen.x;
      py = chosen.y;
    }

    mem.searchQueue = ordered;
    mem.searchIndex = 0;
    mem.searchWaitStart = 0;
    mem.searchPointPeak = 0;
    mem.searchStage = stage;
    mem.searchRoundBestVal = Math.max(0, num(mem.searchCenterVal, 0));
    mem.searchRoundBestX = mem.searchCenterX;
    mem.searchRoundBestY = mem.searchCenterY;
    mem.navKey = null;
    mem.detour = null;
  }

  function startSearchCross(step, stage) {
    var cx = mem.searchCenterX;
    var cy = mem.searchCenterY;
    setSearchQueue([
      { x: cx + step, y: cy },
      { x: cx - step, y: cy },
      { x: cx, y: cy + step },
      { x: cx, y: cy - step }
    ], stage);
  }

  function beginSearch(cx, cy, value, hintIndex, resume) {
    var p = clampPoint(cx, cy);
    mem.searchCenterX = p.x;
    mem.searchCenterY = p.y;
    mem.searchCenterVal = Math.max(0, num(value, 0));
    mem.searchRound = 0;
    mem.searchStep = 8;
    mem.searchWideTried = false;
    mem.searchHint = hintIndex >= 0 ? hintIndex : -1;
    mem.searchResume = resume || "SELECT";
    mem.searchQueue = [];
    mem.searchIndex = 0;
    mem.searchWaitStart = 0;
    mem.searchPointPeak = 0;

    mem.activeHint = hintIndex >= 0 ? hintIndex : -1;
    mem.mode = "SEARCH";
    mem.navKey = null;
    mem.detour = null;

    if (dist(mem.poseX, mem.poseY, p.x, p.y) > 2.5) {
      mem.searchQueue = [{ x: p.x, y: p.y }];
      mem.searchStage = "center";
      mem.searchRoundBestVal = mem.searchCenterVal;
      mem.searchRoundBestX = p.x;
      mem.searchRoundBestY = p.y;
    } else {
      startSearchCross(8, "cross");
    }
  }

  function finishSearch() {
    var hi = Math.floor(num(mem.searchHint, -1));
    if (hi >= 0 && hi < mem.hints.length &&
        mem.hints[hi].status === 0) {
      mem.hints[hi].status = 2;
    }
    if (mem.activeHint === hi) mem.activeHint = -1;

    if (mem.signalPeakVal > 0 &&
        dist(mem.signalPeakX, mem.signalPeakY,
             mem.searchCenterX, mem.searchCenterY) < 24) {
      mem.signalPeakVal = 0;
      mem.signalPeakTick = 0;
    }

    var resume = mem.searchResume || "SELECT";
    if (resume === "SEARCH" || resume === "SITE" || resume === "RETURN") {
      resume = "SELECT";
    }

    mem.mode = resume;
    mem.searchQueue = [];
    mem.searchIndex = 0;
    mem.searchWaitStart = 0;
    mem.searchHint = -1;
    mem.activeHint = -1;
    mem.genericCooldown = tick + 180;
    mem.navKey = null;
    mem.detour = null;
  }

  function finishSearchQueue() {
    if (mem.searchStage === "center") {
      mem.searchCenterVal = Math.max(
        mem.searchCenterVal,
        num(mem.searchRoundBestVal, 0)
      );
      mem.searchRound = 0;
      startSearchCross(8, "cross");
      return;
    }

    var bestVal = Math.max(0, num(mem.searchRoundBestVal, 0));
    var tolerance = Math.max(0.00001, mem.searchCenterVal * 0.025);
    var improved = bestVal > mem.searchCenterVal + tolerance;

    if (improved && mem.searchRound < 2) {
      mem.searchCenterVal = bestVal;
      mem.searchCenterX = mem.searchRoundBestX;
      mem.searchCenterY = mem.searchRoundBestY;
      mem.searchRound++;
      var refineStep = mem.searchStage === "wide" ? 6 :
                       Math.max(4, 8 - 2 * mem.searchRound);
      startSearchCross(refineStep, "refine");
      return;
    }

    if (!mem.searchWideTried && mem.searchCenterVal > 0.00005) {
      mem.searchWideTried = true;
      startSearchCross(14, "wide");
      return;
    }

    finishSearch();
  }

  function sitePointFromObservation(s) {
    return siteEstimate(s);
  }

  function projectedTaskDistance() {
    if (mem.mode === "TRAVEL") {
      var ti = Math.floor(num(mem.activeHint, -1));
      if (ti >= 0 && ti < mem.hints.length) {
        var hnt = mem.hints[ti];
        return dist(mem.poseX, mem.poseY, hnt.x, hnt.y) +
               dist(hnt.x, hnt.y, mem.baseX, mem.baseY) + 30;
      }
    }

    if (mem.mode === "SEARCH" && Array.isArray(mem.searchQueue)) {
      var total = 0;
      var px = mem.poseX;
      var py = mem.poseY;
      for (var i = mem.searchIndex; i < mem.searchQueue.length; i++) {
        total += dist(px, py, mem.searchQueue[i].x, mem.searchQueue[i].y);
        px = mem.searchQueue[i].x;
        py = mem.searchQueue[i].y;
      }
      return total + dist(px, py, mem.baseX, mem.baseY) + 15;
    }

    if (mem.mode === "EXPLORE" &&
        mem.exploreTarget >= 0 &&
        mem.exploreTarget < mem.explorePts.length) {
      var ep = mem.explorePts[mem.exploreTarget];
      return dist(mem.poseX, mem.poseY, ep.x, ep.y) +
             dist(ep.x, ep.y, mem.baseX, mem.baseY) + 15;
    }

    if (mem.mode === "SITE" && mem.siteActive) {
      return baseDistance() + 8;
    }
    return 0;
  }

  function shouldReturn() {
    if (docked || mem.mode === "RETURN") return false;
    if (carried >= capacity && carried > 0) return true;

    var home = homeDistance();
    var homeNeed = energyNeed(home + 6, carried, 1.85);
    if (home > 3 && battery < homeNeed + 0.045) return true;

    if (carried > 0 && timeLeft < travelTime(home) + 10) return true;

    var projected = projectedTaskDistance();
    if (carried > 0 && projected > 0) {
      if (battery < energyNeed(projected, carried + 1, 1.65) + 0.04) {
        return true;
      }
      if (timeLeft < projected / 0.34 + 40) return true;
    }

    if (carried === 0 && home > 5 &&
        battery < energyNeed(home + 5, 0, 1.8) + 0.03) {
      return true;
    }
    return false;
  }

  function tryGenericSearch(resume) {
    if (tick < num(mem.genericCooldown, 0) || science <= 0.00005) {
      return false;
    }

    var gx = mem.poseX;
    var gy = mem.poseY;
    var gval = science;

    if (mem.signalPeakVal > gval * 1.12 &&
        tick - num(mem.signalPeakTick, 0) < 300 &&
        dist(mem.poseX, mem.poseY, mem.signalPeakX, mem.signalPeakY) < 30) {
      gx = mem.signalPeakX;
      gy = mem.signalPeakY;
      gval = mem.signalPeakVal;
    }

    if (mem.lastGenericX !== null &&
        tick - num(mem.lastGenericTick, -10000) < 500 &&
        dist(gx, gy, mem.lastGenericX, mem.lastGenericY) < 14 &&
        gval < num(mem.lastGenericVal, 0) * 1.5) {
      return false;
    }

    var route = dist(mem.poseX, mem.poseY, gx, gy) +
                dist(gx, gy, mem.baseX, mem.baseY) + 30;
    if (battery < energyNeed(route, carried + 1, 1.65) + 0.04) {
      return false;
    }
    if (timeLeft < route / 0.34 + 45) return false;

    mem.lastGenericX = gx;
    mem.lastGenericY = gy;
    mem.lastGenericVal = gval;
    mem.lastGenericTick = tick;
    beginSearch(gx, gy, gval, -1, resume);
    return true;
  }

  function enterReturn() {
    mem.mode = "RETURN";
    mem.activeHint = -1;
    mem.siteActive = false;
    mem.siteDrillStarted = false;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.siteAssoc = -1;
    mem.siteResume = null;
    mem.searchQueue = [];
    mem.searchIndex = 0;
    mem.searchWaitStart = 0;
    mem.searchHint = -1;
    mem.detour = null;
    mem.navKey = null;
  }

  function returnControl() {
    var b = obs.beacon && typeof obs.beacon === "object" ? obs.beacon : null;
    if (b) {
      var bd = Math.max(0, num(b.distance, 20));
      if (bd <= 2.05) return idleOutput();
      return driveRelative(num(b.bearing, 0) * PI / 180, bd, 1.65, 0.42);
    }
    var d = baseDistance();
    if (d <= 1.8) return idleOutput();
    return navTo(mem.baseX, mem.baseY, 1.65, "home", 0.42);
  }

  function chooseExploreTarget() {
    var best = -1;
    var bestD = 1e30;
    for (var i = 0; i < mem.explorePts.length; i++) {
      var p = mem.explorePts[i];
      if (p.done) continue;
      var d = dist(mem.poseX, mem.poseY, p.x, p.y);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    return best;
  }

  var siteObs = obs.site && typeof obs.site === "object" ? obs.site : null;

  if (mem.siteActive) {
    if (drilling > 0.01 || mem.lastDrill) mem.siteDrillStarted = true;
    if (carried > num(mem.sampleStartCarried, carried)) {
      finishSite();
    }
  }

  if (mem.mode === "RETURN") {
    if (docked) {
      if (carried > 0) return idleOutput();
      var chargeTarget = clamp(mem.batteryMax * 0.82, 0.55, 0.94);
      if (battery < chargeTarget && timeLeft > 55) return idleOutput();
      if (timeLeft < 25) return idleOutput();

      mem.mode = "SELECT";
      mem.activeHint = -1;
      mem.navKey = null;
      mem.detour = null;
    } else {
      return returnControl();
    }
  }

  if (mem.siteActive) {
    if (!mem.siteDrillStarted && !canSampleHere()) {
      enterReturn();
      return returnControl();
    }
    return siteControl();
  }

  if (siteObs && carried < capacity &&
      tick - num(mem.finishedSiteTick, -10000) > 3) {
    var sitePoint = sitePointFromObservation(siteObs);
    var recentSame = mem.lastSampleX !== null &&
                     tick - num(mem.lastSampleTick, -10000) < 25 &&
                     dist(sitePoint.x, sitePoint.y,
                          mem.lastSampleX, mem.lastSampleY) < 2.5;
    if (!recentSame && canSampleHere()) {
      activateSite(siteObs);
      return siteControl();
    }
  }

  if (shouldReturn()) {
    enterReturn();
    return returnControl();
  }

  for (var loop = 0; loop < 10; loop++) {
    if (mem.mode === "SELECT" || !mem.mode) {
      if (tryGenericSearch("SELECT")) continue;

      var nextHint = chooseHint();
      if (nextHint >= 0) {
        mem.activeHint = nextHint;
        mem.activePeakVal = 0;
        mem.activePeakX = mem.poseX;
        mem.activePeakY = mem.poseY;
        mem.mode = "TRAVEL";
        mem.navKey = null;
        mem.detour = null;
        continue;
      }

      if (carried > 0) {
        enterReturn();
        return returnControl();
      }

      var targetCharge = clamp(mem.batteryMax * 0.82, 0.55, 0.94);
      if (docked && battery < targetCharge && timeLeft > 55) {
        return idleOutput();
      }
      if (timeLeft < 35) return idleOutput();

      mem.mode = "EXPLORE";
      continue;
    }

    if (mem.mode === "TRAVEL") {
      var ti = Math.floor(num(mem.activeHint, -1));
      if (ti < 0 || ti >= mem.hints.length ||
          mem.hints[ti].status !== 0) {
        mem.activeHint = -1;
        mem.mode = "SELECT";
        continue;
      }

      var targetHint = mem.hints[ti];
      var hd = dist(mem.poseX, mem.poseY, targetHint.x, targetHint.y);

      if (hd <= 4.0) {
        var cx = targetHint.x;
        var cy = targetHint.y;
        var cv = science;

        if (mem.activePeakVal > 0.00005 &&
            dist(mem.activePeakX, mem.activePeakY,
                 targetHint.x, targetHint.y) < 36 &&
            (mem.activePeakVal > cv * 1.05 || cv <= 0.00005)) {
          cx = mem.activePeakX;
          cy = mem.activePeakY;
          cv = Math.max(cv, mem.activePeakVal);
        }

        beginSearch(cx, cy, cv, ti, "SELECT");
        continue;
      }

      return navTo(targetHint.x, targetHint.y, 1.9,
                   "hint:" + ti, 0.43);
    }

    if (mem.mode === "SEARCH") {
      if (!Array.isArray(mem.searchQueue) ||
          mem.searchIndex >= mem.searchQueue.length) {
        finishSearchQueue();
        continue;
      }

      var node = mem.searchQueue[mem.searchIndex];
      var nd = dist(mem.poseX, mem.poseY, node.x, node.y);

      if (nd <= 1.45) {
        if (Math.max(Math.abs(wheelL), Math.abs(wheelR)) > 0.14) {
          mem.searchWaitStart = 0;
          return idleOutput();
        }

        if (!mem.searchWaitStart) {
          mem.searchWaitStart = tick;
          mem.searchPointPeak = science;
        } else if (science > mem.searchPointPeak) {
          mem.searchPointPeak = science;
        }

        if (tick - mem.searchWaitStart >= 7) {
          var val = Math.max(0, num(mem.searchPointPeak, 0));

          if (mem.searchStage === "center") {
            mem.searchCenterVal = Math.max(mem.searchCenterVal, val);
            mem.searchRound = 0;
            startSearchCross(8, "cross");
          } else {
            if (val > mem.searchRoundBestVal) {
              mem.searchRoundBestVal = val;
              mem.searchRoundBestX = node.x;
              mem.searchRoundBestY = node.y;
            }
            mem.searchIndex++;
            mem.searchWaitStart = 0;
            mem.searchPointPeak = 0;
            if (mem.searchIndex >= mem.searchQueue.length) {
              finishSearchQueue();
            }
          }
          continue;
        }

        return idleOutput();
      }

      mem.searchWaitStart = 0;
      return navTo(node.x, node.y, 1.15,
                   "search:" + mem.searchStage + ":" +
                   mem.searchRound + ":" + mem.searchIndex, 0.40);
    }

    if (mem.mode === "EXPLORE") {
      if (tryGenericSearch("EXPLORE")) continue;

      if (mem.exploreTarget < 0 ||
          mem.exploreTarget >= mem.explorePts.length ||
          mem.explorePts[mem.exploreTarget].done) {
        mem.exploreTarget = chooseExploreTarget();
      }

      if (mem.exploreTarget < 0) {
        if (!mem.exploreAlt) {
          mem.exploreAlt = true;
          mem.explorePts = [];
          for (var ay = mem.minY + 43; ay <= mem.maxY - 18; ay += 55) {
            for (var ax = mem.minX + 43; ax <= mem.maxX - 18; ax += 55) {
              mem.explorePts.push({ x: ax, y: ay, done: false });
            }
          }
          mem.exploreTarget = -1;
          continue;
        }
        if (carried > 0) {
          enterReturn();
          return returnControl();
        }
        return idleOutput();
      }

      var ep = mem.explorePts[mem.exploreTarget];
      var ed = dist(mem.poseX, mem.poseY, ep.x, ep.y);

      if (ed <= 2.0) {
        ep.done = true;
        mem.exploreTarget = -1;
