    if (d <= stop) return idleOutput();

    var rel = wrap(targetRel);
    var aim = rel;
    var relDeg = rel * 180 / PI;
    var clearance = Math.abs(relDeg) <= 80 ? rayAt(relDeg) : 15;

    if (Math.abs(relDeg) < 82 && clearance < 3.3) {
