    else if (clearance < 1.35) cap = Math.min(cap, 0.10);
    else if (clearance < 2.0) cap = Math.min(cap, 0.18);
    else if (clearance < 3.0) cap = Math.min(cap, 0.27);
    else if (clearance < 4.2) cap = Math.min(cap, 0.34);

    var front = rayAt(0);
    if (front < 0.85 && Math.abs(aim) < 0.45) cap = 0;
    else if (front < 1.30 && Math.abs(aim) < 0.30) {
