    var v = Math.min(cap, Math.sqrt(0.65 * remaining));
    var absAim = Math.abs(aim);
    if (absAim > 1.18) {
      v = 0;
    } else {
      v *= Math.max(0, Math.cos(aim));
      if (absAim > 0.82) v = Math.min(v, 0.15);
      else if (absAim > 0.58) v = Math.min(v, 0.27);
