    return moveOutput(v, omega, false);
  }

  function navTo(x, y, stop, key, cruise) {
    var p = clampPoint(x, y);
    x = p.x;
    y = p.y;

    var mainDist = dist(mem.poseX, mem.poseY, x, y);
    key = String(key);

    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = mainDist;
      mem.navProgressTick = tick;
      mem.navDetour = null;
      mem.navDetourCount = 0;
    } else if (mainDist < num(mem.navBest, mainDist) - 0.45) {
      if (mainDist < num(mem.navBest, mainDist) - 1.5) {
        mem.navDetourCount = 0;
      }
      mem.navBest = mainDist;
      mem.navProgressTick = tick;
    }

    if (mem.navDetour && mem.navDetour.key === key) {
      var detD = dist(mem.poseX, mem.poseY,
                      mem.navDetour.x, mem.navDetour.y);
      if (detD < 1.8 || tick > mem.navDetour.until) {
        mem.navDetour = null;
        mem.navBest = mainDist;
        mem.navProgressTick = tick;
      }
    }

    if (!mem.navDetour &&
        mainDist > stop + 4 &&
        tick - num(mem.navProgressTick, tick) > 100 &&
        mem.navDetourCount < 3) {
      var leftClear = rayAt(20) + rayAt(40) + rayAt(60);
      var rightClear = rayAt(-20) + rayAt(-40) + rayAt(-60);
      var side;
      if (Math.abs(leftClear - rightClear) < 0.1) {
        side = (tick % 2) ? 1 : -1;
      } else {
        side = leftClear > rightClear ? 1 : -1;
      }

      var goalAngle = Math.atan2(y - mem.poseY, x - mem.poseX);
      var detAngle = goalAngle + side * 0.95;
      var dp = clampPoint(
        mem.poseX + 6.5 * Math.cos(detAngle),
        mem.poseY + 6.5 * Math.sin(detAngle)
      );

      if (dist(mem.poseX, mem.poseY, dp.x, dp.y) > 1.4) {
        mem.navDetour = {
          x: dp.x,
          y: dp.y,
          key: key,
          until: tick + 150
        };
        mem.navDetourCount++;
      }
      mem.navProgressTick = tick;
    }

    var tx = x;
    var ty = y;
    if (mem.navDetour && mem.navDetour.key === key) {
      tx = mem.navDetour.x;
      ty = mem.navDetour.y;
    }

    var dx = tx - mem.poseX;
    var dy = ty - mem.poseY;
    var d = Math.sqrt(dx * dx + dy * dy);
    var rel = wrap(Math.atan2(dy, dx) - mem.yaw);
    return driveRelative(rel, d, stop, cruise);
  }

  function baseDistance() {
    return dist(mem.poseX, mem.poseY, mem.baseX, mem.baseY);
  }

  function homeDistance() {
    var b = obs.beacon && typeof obs.beacon === "object" ? obs.beacon : null;
    if (b) return Math.max(0, num(b.distance, baseDistance()));
    return baseDistance();
  }

  function energyNeed(distanceMeters, samples, margin) {
    var d = Math.max(0, distanceMeters) * 1.12;
    var load = 1 + 0.18 * Math.max(0, samples);
    return 0.12 + d * mem.energyRate * load * margin;
  }

  function travelTime(d) {
    return Math.max(0, d) / 0.32 + 22;
  }

  function canSampleHere() {
    if (carried >= capacity) return false;
    var home = homeDistance();
    if (home < 3) return battery > 0.12 && timeLeft > 9;
    var need = energyNeed(home + 9, carried + 1, 2.15);
    return battery > need + 0.045 &&
           timeLeft > travelTime(home) + 12;
  }

  function projectedTaskDistance() {
    if (mem.mode === "TRAVEL") {
      var ti = Math.floor(num(mem.activeHint, -1));
      if (ti >= 0 && ti < mem.hints.length) {
        var hnt = mem.hints[ti];
        return dist(mem.poseX, mem.poseY, hnt.x, hnt.y) +
               num(mem.scanCost, 164) +
               dist(hnt.x, hnt.y, mem.baseX, mem.baseY) + 15;
      }
    }

    if (mem.mode === "SCAN" &&
        Array.isArray(mem.scanPoints) &&
        mem.scanPoints.length > 0) {
      var total = 0;
      var px = mem.poseX;
      var py = mem.poseY;
      for (var si = mem.scanIndex; si < mem.scanPoints.length; si++) {
        total += dist(px, py,
                      mem.scanPoints[si].x,
                      mem.scanPoints[si].y);
        px = mem.scanPoints[si].x;
        py = mem.scanPoints[si].y;
      }
      return total + dist(px, py, mem.baseX, mem.baseY) + 15;
    }

    if (mem.mode === "EXPLORE" &&
        mem.exploreTarget >= 0 &&
        mem.exploreTarget < mem.explorePts.length) {
      var ep = mem.explorePts[mem.exploreTarget];
      return dist(mem.poseX, mem.poseY, ep.x, ep.y) +
             dist(ep.x, ep.y, mem.baseX, mem.baseY) + 20;
    }

    if (mem.mode === "SITE" && mem.siteActive) {
      return homeDistance() + 10;
    }
    return 0;
  }

  function shouldReturn() {
    if (docked || mem.mode === "RETURN") return false;
    if (carried >= capacity && carried > 0) return true;

    var home = homeDistance();
    var homeNeed = energyNeed(home + 9, carried, 2.15);
    if (home > 3 && battery < homeNeed + 0.055) return true;

    if (carried > 0 && timeLeft < travelTime(home) + 15) return true;

    var projected = projectedTaskDistance();
    if (projected > 0) {
      var taskNeed = energyNeed(projected,
                                Math.min(capacity, carried + 1),
                                1.95);
      if (battery < taskNeed + 0.035) return true;
      if (carried > 0 && timeLeft < projected / 0.34 + 35) return true;
    }

    if (carried > 0 && timeLeft < travelTime(home) + 18) return true;
    return false;
  }

  function siteEstimate(s) {
    var d = Math.max(0, num(s.distance, 0));
    var b = num(s.bearing, 0) * PI / 180;
    var a = mem.yaw + b;
    return {
      x: mem.poseX + d * Math.cos(a),
      y: mem.poseY + d * Math.sin(a)
    };
  }

  function updateSiteGoal(s) {
    if (!s) return;
    var p = siteEstimate(s);
    if (mem.siteGX === null ||
        mem.siteGY === null ||
        !isFinite(mem.siteGX) ||
        !isFinite(mem.siteGY)) {
      mem.siteGX = p.x;
      mem.siteGY = p.y;
    } else {
      mem.siteGX = 0.65 * mem.siteGX + 0.35 * p.x;
      mem.siteGY = 0.65 * mem.siteGY + 0.35 * p.y;
    }
    mem.siteValue = num(s.value, mem.siteValue || 0);
  }

  function activateSite(s) {
    var resume = mem.mode || "SELECT";
    if (resume === "RETURN" || resume === "SITE") resume = "SELECT";

    mem.siteResume = resume;
    mem.siteActive = true;
    mem.siteDrillStarted = drilling > 0.01;
    mem.siteMiss = 0;
    mem.siteLastDistance = Math.max(0, num(s.distance, 8));
    mem.sampleStartCarried = carried;
    mem.siteAssoc = -1;
    updateSiteGoal(s);

    var p = siteEstimate(s);
    var best = -1;
    var bestD = 1e30;

    for (var i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].status >= 2) continue;
      var hd = dist(p.x, p.y, mem.hints[i].x, mem.hints[i].y);
      if (hd < bestD) {
        bestD = hd;
        best = i;
      }
    }

    var ai = Math.floor(num(mem.activeHint, -1));
    if (ai >= 0 &&
        ai < mem.hints.length &&
        mem.hints[ai].status < 2) {
      var ad = dist(p.x, p.y, mem.hints[ai].x, mem.hints[ai].y);
      if (ad <= 42 && (best < 0 || ad <= bestD + 5)) {
        best = ai;
        bestD = ad;
      }
    }
    if (best >= 0 && bestD <= 38) mem.siteAssoc = best;

    mem.mode = "SITE";
    mem.navKey = null;
  }

  function finishSite() {
    var assoc = Math.floor(num(mem.siteAssoc, -1));
    var resume = mem.siteResume || "SELECT";
    var sx = mem.siteGX !== null && isFinite(mem.siteGX)
      ? mem.siteGX : mem.poseX;
    var sy = mem.siteGY !== null && isFinite(mem.siteGY)
      ? mem.siteGY : mem.poseY;

    if (assoc >= 0 && assoc < mem.hints.length) {
      if (mem.hints[assoc].status < 2) mem.hints[assoc].status = 1;
      if (mem.siteValue > 0) mem.hints[assoc].value = mem.siteValue;
    }

    mem.lastSampleX = sx;
    mem.lastSampleY = sy;
    mem.lastSampleTick = tick;

    if (resume === "RETURN" || resume === "SITE") resume = "SELECT";
    mem.mode = resume;
    mem.siteActive = false;
    mem.siteDrillStarted = false;
    mem.siteResume = null;
    mem.siteAssoc = -1;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.siteMiss = 0;
    mem.lastDrill = false;
    mem.navKey = null;
  }

  function siteControl() {
    var s = obs.site && typeof obs.site === "object" ? obs.site : null;
    var d;
    var bearing;

    if (s) {
      updateSiteGoal(s);
      d = Math.max(0, num(s.distance, 0));
      bearing = num(s.bearing, 0);
      mem.siteLastDistance = d;
      mem.siteMiss = 0;
    } else {
      mem.siteMiss = num(mem.siteMiss, 0) + 1;
      if (mem.siteGX !== null && mem.siteGY !== null) {
        var dx = mem.siteGX - mem.poseX;
        var dy = mem.siteGY - mem.poseY;
        d = Math.sqrt(dx * dx + dy * dy);
        bearing = wrap(Math.atan2(dy, dx) - mem.yaw) * 180 / PI;
      } else {
        d = num(mem.siteLastDistance, 8);
        bearing = 0;
      }

      if (mem.siteMiss > 120 &&
          !mem.siteDrillStarted &&
          drilling <= 0.01) {
        mem.siteActive = false;
        mem.mode = mem.siteResume || "SELECT";
        mem.siteResume = null;
        mem.siteAssoc = -1;
        mem.siteGX = null;
        mem.siteGY = null;
        mem.navKey = null;
        return idleOutput();
      }
    }

    if (drilling > 0.01 || mem.lastDrill) {
      mem.siteDrillStarted = true;
    }

    if (d > 1.34) {
      return driveRelative(bearing * PI / 180, d, 1.02,
                           mem.siteDrillStarted ? 0.15 : 0.23);
    }

    var still = Math.abs(wheelL) < 0.12 && Math.abs(wheelR) < 0.12;
    var drillOn = d <= 1.38 && still;
    if (drilling > 0.01 && d <= 1.50 && still) drillOn = true;
    if (drillOn) mem.siteDrillStarted = true;
    return moveOutput(0, 0, drillOn);
  }

  function makeScanPoints(cx, cy, lanes) {
    var rows;
    if (lanes >= 4) rows = [-18, -6, 6, 18];
    else if (lanes === 3) rows = [-16, 0, 16];
    else rows = [-12, 12];

    var points = [];
    var startLeft = mem.poseX <= cx;
    var seen = {};

    for (var i = 0; i < rows.length; i++) {
      var leftFirst = (i % 2 === 0) ? startLeft : !startLeft;
      var x1 = cx + (leftFirst ? -18 : 18);
      var x2 = cx + (leftFirst ? 18 : -18);
      var y = cy + rows[i];
      var p1 = clampPoint(x1, y);
      var p2 = clampPoint(x2, y);
      var k1 = Math.round(p1.x * 10) + ":" + Math.round(p1.y * 10);
      var k2 = Math.round(p2.x * 10) + ":" + Math.round(p2.y * 10);
      if (!seen[k1]) {
        seen[k1] = true;
        points.push(p1);
      }
      if (!seen[k2]) {
        seen[k2] = true;
        points.push(p2);
      }
    }
    return points;
  }

  function laneCost(lanes) {
    if (lanes >= 4) return 205;
    if (lanes === 3) return 164;
    return 118;
  }

  function beginScan(cx, cy, source, hintIndex, lanes, resume) {
    var p = clampPoint(cx, cy);
    mem.scanCenterX = p.x;
    mem.scanCenterY = p.y;
    mem.scanSource = source;
    mem.scanResume = source === "hint" ? "SELECT" : (resume || "SELECT");
    mem.scanHintIndex = hintIndex;
    mem.scanLanes = lanes;
    mem.scanCost = laneCost(lanes);
    mem.scanPoints = makeScanPoints(p.x, p.y, lanes);
    mem.scanIndex = 0;
    mem.scanWaitStart = 0;
    mem.activeHint = source === "hint" ? hintIndex : -1;
    mem.mode = "SCAN";
    mem.navKey = null;
    mem.navDetour = null;
  }

  function finishScan() {
    if (mem.scanSource === "hint") {
      var hi = Math.floor(num(mem.scanHintIndex, -1));
      if (hi >= 0 && hi < mem.hints.length) {
        mem.hints[hi].status = 2;
      }
      mem.mode = "SELECT";
      mem.activeHint = -1;
    } else {
      if (!Array.isArray(mem.genericDone)) mem.genericDone = [];
      mem.genericDone.push({
        x: mem.scanCenterX,
        y: mem.scanCenterY
      });
      if (mem.genericDone.length > 20) mem.genericDone.shift();
      mem.mode = mem.scanResume || "SELECT";
      mem.genericCooldown = tick + 250;
      mem.signalPeakVal = 0;
      mem.signalPeakTick = 0;
    }

    mem.scanPoints = [];
    mem.scanIndex = 0;
    mem.scanSource = "";
    mem.scanHintIndex = -1;
    mem.navKey = null;
    mem.navDetour = null;
  }

  function chooseHint() {
    if (carried >= capacity) return null;

    var best = null;
    var bestScore = -1;

    for (var i = 0; i < mem.hints.length; i++) {
      var hh = mem.hints[i];
      if (!hh || hh.status !== 0) continue;

      var outDist = dist(mem.poseX, mem.poseY, hh.x, hh.y);
      var homeDist = dist(mem.baseX, mem.baseY, hh.x, hh.y);
      var chosenLanes = 0;

      for (var lanes = 4; lanes >= 2; lanes--) {
        var route = outDist + homeDist + laneCost(lanes) + 18;
        var need = energyNeed(route, carried + 1, 1.85);
        var timeNeed = route / 0.36 + 52;
        if (battery > need + 0.035 && timeLeft > timeNeed) {
          chosenLanes = lanes;
          break;
        }
      }

      if (chosenLanes === 0) continue;

      var cost = laneCost(chosenLanes);
      var score = hh.value /
        (52 + 0.72 * outDist + 0.86 * homeDist + 0.38 * cost);
      if (score > bestScore) {
        bestScore = score;
        best = { index: i, lanes: chosenLanes };
      }
    }

    return best;
  }

  function chooseExploreTarget() {
    var best = -1;
    var bestD = 1e30;
    for (var i = 0; i < mem.explorePts.length; i++) {
      var p = mem.explorePts[i];
      if (p.done) continue;
      var d = dist(mem.poseX, mem.poseY, p.x, p.y);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    return best;
  }

  function trySignalScan(resume) {
    if (tick < num(mem.genericCooldown, 0) ||
        carried >= capacity ||
        mem.signalPeakVal <= 0) {
      return false;
    }

    var threshold = Math.max(0.035, mem.scienceAvg * 1.18 + 0.015);
    if (mem.signalPeakVal < threshold ||
        tick - num(mem.signalPeakTick, 0) > 3000) {
      return false;
    }

    var gx = mem.signalPeakX;
    var gy = mem.signalPeakY;

    for (var i = 0; i < mem.hints.length; i++) {
      if (dist(gx, gy, mem.hints[i].x, mem.hints[i].y) < 34) {
        return false;
      }
    }

    for (var j = 0; j < mem.genericDone.length; j++) {
      if (dist(gx, gy, mem.genericDone[j].x, mem.genericDone[j].y) < 28) {
        return false;
      }
    }

    var route = dist(mem.poseX, mem.poseY, gx, gy) +
                laneCost(3) +
                dist(gx, gy, mem.baseX, mem.baseY) + 20;
    if (battery < energyNeed(route, carried + 1, 1.90) + 0.04) {
      return false;
    }
    if (timeLeft < route / 0.34 + 55) return false;

    beginScan(gx, gy, "signal", -1, 3, resume);
    return true;
  }

  function enterReturn() {
    var from = mem.mode;
    if (from === "SITE") from = mem.siteResume || "SELECT";
    if (from === "RETURN") from = "SELECT";

    if (carried > 0) {
      mem.returnFrom = from;
    } else {
      mem.returnFrom = "SELECT";
      if (from === "EXPLORE" &&
          mem.exploreTarget >= 0 &&
          mem.exploreTarget < mem.explorePts.length) {
        mem.explorePts[mem.exploreTarget].done = true;
        mem.exploreTarget = -1;
      }
      if (from === "SCAN" && mem.scanSource === "signal") {
        if (!Array.isArray(mem.genericDone)) mem.genericDone = [];
        mem.genericDone.push({
          x: mem.scanCenterX,
          y: mem.scanCenterY
        });
      }
      mem.activeHint = -1;
    }

    mem.mode = "RETURN";
    mem.siteActive = false;
    mem.siteDrillStarted = false;
    mem.siteResume = null;
    mem.siteAssoc = -1;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.navKey = null;
    mem.navDetour = null;
  }

  function returnControl() {
    var b = obs.beacon && typeof obs.beacon === "object" ? obs.beacon : null;
    if (b) {
      var bd = Math.max(0, num(b.distance, 20));
      if (bd <= 2.05) return idleOutput();
      return driveRelative(num(b.bearing, 0) * PI / 180,
                           bd, 1.90, 0.38);
    }

    var d = baseDistance();
    if (d <= 1.90) return idleOutput();
    return navTo(mem.baseX, mem.baseY, 1.75, "home", 0.38);
  }

  var siteObs = obs.site && typeof obs.site === "object" ? obs.site : null;

  if (mem.siteActive) {
    if (drilling > 0.01 || mem.lastDrill) {
      mem.siteDrillStarted = true;
    }
    if (carried > num(mem.sampleStartCarried, carried)) {
      finishSite();
    }
  }

  if (mem.mode === "RETURN") {
    if (docked) {
      if (carried > 0) return idleOutput();

      var chargeTarget = Math.max(0.70, mem.batteryMax * 0.90);
      if (battery < chargeTarget && timeLeft > 65) return idleOutput();
      if (timeLeft < 24) return idleOutput();

      mem.mode = mem.returnFrom || "SELECT";
      if (mem.mode === "RETURN" || mem.mode === "SITE") mem.mode = "SELECT";
      mem.returnFrom = "SELECT";
      mem.navKey = null;
      mem.navDetour = null;
    } else {
      return returnControl();
    }
  }

  if (mem.siteActive) {
    if (!mem.siteDrillStarted && shouldReturn()) {
      enterReturn();
      return returnControl();
    }
    return siteControl();
  }

  if (shouldReturn()) {
    enterReturn();
    return returnControl();
  }

  if (siteObs && carried < capacity) {
    var sitePoint = siteEstimate(siteObs);
    var repeatedSample = mem.lastSampleX !== null &&
                         tick - num(mem.lastSampleTick, -10000) < 25 &&
                         dist(sitePoint.x, sitePoint.y,
                              mem.lastSampleX, mem.lastSampleY) < 2.7;

    if (!repeatedSample && canSampleHere()) {
      activateSite(siteObs);
      return siteControl();
    }
  }

  for (var loop = 0; loop < 12; loop++) {
    if (mem.mode === "SELECT" || !mem.mode) {
      var nextHint = chooseHint();

      if (nextHint) {
        mem.activeHint = nextHint.index;
        mem.scanLanes = nextHint.lanes;
        mem.scanCost = laneCost(nextHint.lanes);
        mem.scanSource = "hint";
        mem.scanHintIndex = nextHint.index;
        mem.mode = "TRAVEL";
        mem.navKey = null;
        mem.navDetour = null;
        continue;
      }

      if (carried > 0) {
        enterReturn();
        return returnControl();
      }

      if (trySignalScan("SELECT")) continue;

      if (docked && battery < Math.max(0.70, mem.batteryMax * 0.90) &&
          timeLeft > 65) {
        return idleOutput();
      }
      if (timeLeft < 28) return idleOutput();

      mem.mode = "EXPLORE";
      continue;
    }

    if (mem.mode === "TRAVEL") {
      var ti = Math.floor(num(mem.activeHint, -1));
      if (ti < 0 || ti >= mem.hints.length ||
          mem.hints[ti].status >= 2) {
        mem.activeHint = -1;
        mem.mode = "SELECT";
        continue;
      }

      var targetHint = mem.hints[ti];
      var hd = dist(mem.poseX, mem.poseY, targetHint.x, targetHint.y);
      if (hd <= 2.7) {
        beginScan(targetHint.x, targetHint.y, "hint",
                  ti, mem.scanLanes, "SELECT");
        continue;
      }

      return navTo(targetHint.x, targetHint.y, 1.75,
                   "hint:" + ti, 0.40);
    }

    if (mem.mode === "SCAN") {
      if (!Array.isArray(mem.scanPoints) ||
          mem.scanIndex >= mem.scanPoints.length) {
        finishScan();
        continue;
      }

      var node = mem.scanPoints[mem.scanIndex];
      var nd = dist(mem.poseX, mem.poseY, node.x, node.y);
      if (nd <= 1.35) {
        mem.scanIndex++;
        mem.navKey = null;
        continue;
      }

      return navTo(node.x, node.y, 1.25,
                   "scan:" + mem.scanSource + ":" +
                   mem.scanIndex, 0.39);
    }

    if (mem.mode === "EXPLORE") {
      if (trySignalScan("EXPLORE")) continue;

      if (mem.exploreTarget < 0 ||
          mem.exploreTarget >= mem.explorePts.length ||
          mem.explorePts[mem.exploreTarget].done) {
        mem.exploreTarget = chooseExploreTarget();
      }

      if (mem.exploreTarget < 0) {
        if (carried > 0) {
          enterReturn();
          return returnControl();
        }
        return idleOutput();
      }

      var ep = mem.explorePts[mem.exploreTarget];
      var ed = dist(mem.poseX, mem.poseY, ep.x, ep.y);
      if (ed <= 1.9) {
        ep.done = true;
        mem.exploreTarget = -1;
        mem.navKey = null;
        mem.mode = "SELECT";
        continue;
      }

      return navTo(ep.x, ep.y, 1.65,
                   "explore:" + mem.exploreTarget, 0.39);
    }

    if (mem.mode === "SITE" && mem.siteActive) {
      return siteControl();
    }

    if (mem.mode === "RETURN") return returnControl();

    mem.mode = "SELECT";
  }

  return idleOutput();
}

function act(obs, mem) {
  if (!obs || typeof obs !== "object") obs = {};
  if (!mem || typeof mem !== "object") mem = {};

  var PI = Math.PI;
  var DT = 0.1;

  function num(v, d) {
    if (v === null || v === undefined) return d;
    var q = Number(v);
    return isFinite(q) ? q : d;
  }

  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }

  function wrap(a) {
    while (a > PI) a -= 2 * PI;
    while (a < -PI) a += 2 * PI;
    return a;
  }

  function dist(x1, y1, x2, y2) {
    var dx = x2 - x1;
    var dy = y2 - y1;
    return Math.sqrt(dx * dx + dy * dy);
  }

  var mission = obs.mission || {};

  if (!mem.initialized) {
    var size = mission.size;
    var w = 400;
    var h = 400;

    if (typeof size === "number") {
      w = size;
      h = size;
    } else if (size && typeof size === "object") {
      w = num(size.width, num(size.x, 400));
      h = num(size.height, num(size.y, 400));
    }

    var base = mission.base || {};
    var bx = num(base.x, num(obs.x, w * 0.5));
    var by = num(base.y, num(obs.y, h * 0.5));
    var sourceHints = Array.isArray(mission.hints) ? mission.hints : [];

    var centered = bx < 0 || by < 0;
    for (var ci = 0; ci < sourceHints.length; ci++) {
      var ch = sourceHints[ci] || {};
      if (num(ch.x, 0) < 0 || num(ch.y, 0) < 0) centered = true;
    }

    mem.mapW = w;
    mem.mapH = h;
    mem.minX = size && typeof size === "object"
      ? num(size.minX, centered ? -w * 0.5 : 0)
      : (centered ? -w * 0.5 : 0);
    mem.maxX = size && typeof size === "object"
      ? num(size.maxX, mem.minX + w)
      : (centered ? w * 0.5 : w);
    mem.minY = size && typeof size === "object"
      ? num(size.minY, centered ? -h * 0.5 : 0)
      : (centered ? -h * 0.5 : 0);
    mem.maxY = size && typeof size === "object"
      ? num(size.maxY, mem.minY + h)
      : (centered ? h * 0.5 : h);

    mem.baseX = bx;
    mem.baseY = by;
    mem.capacity = Math.max(
      1,
      Math.floor(num(mission.capacity, num(obs.capacity, 5)))
    );
    mem.seconds = num(mission.seconds, 1200);

    mem.hints = [];
    for (var hi = 0; hi < sourceHints.length; hi++) {
      var sh = sourceHints[hi] || {};
      mem.hints.push({
        x: clamp(num(sh.x, bx), mem.minX + 5, mem.maxX - 5),
        y: clamp(num(sh.y, by), mem.minY + 5, mem.maxY - 5),
        value: Math.max(0.1, num(sh.estimate, num(sh.value, 1))),
        status: 0
      });
    }

    var x0 = num(obs.x, bx);
    var y0 = num(obs.y, by);
    var h0 = num(obs.heading, 0) * PI / 180;

    mem.poseX = x0;
    mem.poseY = y0;
    mem.yaw = h0;
    mem.bias = 0;
    mem.lastRawX = x0;
    mem.lastRawY = y0;
    mem.lastRawH = h0;

    mem.gpsFrozen = false;
    mem.gpsRecover = 0;
    mem.gpsWinX = x0;
    mem.gpsWinY = y0;
    mem.gpsWinPath = 0;
    mem.gpsWinTurn = 0;
    mem.gpsSameCount = 0;

    mem.calX = x0;
    mem.calY = y0;
    mem.calPath = 0;
    mem.calTurn = 0;
    mem.calSin = 0;
    mem.calCos = 0;

    mem.energyRate = 0.0009;
    mem.energyAcc = 0;
    mem.energyDist = 0;
    mem.prevBattery = num(obs.battery, 1);
    mem.prevSolar = num(obs.solar, 0);
    mem.batteryMax = num(obs.battery, 1);

    mem.gainL = 3.0;
    mem.gainR = 3.0;
    mem.deadL = 0.12;
    mem.deadR = 0.12;
    mem.iL = 0;
    mem.iR = 0;
    mem.lastCmdL = 0;
    mem.lastCmdR = 0;
    mem.prevCmdL = 0;
    mem.prevCmdR = 0;
    mem.lastTargetL = 0;
    mem.lastTargetR = 0;
    mem.prevTargetL = 0;
    mem.prevTargetR = 0;
    mem.lastDrill = false;

    mem.rays = [];
    mem.lastRays = [];
    mem.rayRepeat = [];
    mem.rayBad = [];
    mem.rayMoved = 0;
    for (var ri = 0; ri < 9; ri++) {
      mem.rays[ri] = 15;
      mem.lastRays[ri] = -1;
      mem.rayRepeat[ri] = 0;
      mem.rayBad[ri] = false;
    }

    mem.mode = "SELECT";
    mem.activeHint = -1;
    mem.scanLanes = 4;
    mem.scanCost = 215;
    mem.scanSource = "";
    mem.scanResume = "SELECT";
    mem.scanHintIndex = -1;
    mem.scanSignalIndex = -1;
    mem.scanPoints = [];
    mem.scanIndex = 0;

    mem.siteActive = false;
    mem.siteDrillStarted = false;
    mem.siteResume = null;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.siteValue = 0;
    mem.siteAssoc = -1;
    mem.siteLastDistance = 8;
    mem.siteMiss = 0;
    mem.sampleStartCarried = 0;
    mem.lastSampleX = null;
    mem.lastSampleY = null;
    mem.lastSampleTick = -10000;

    mem.scienceBase = Math.max(0, num(obs.science, 0));
    mem.signalCandidates = [];
    mem.genericDone = [];
    mem.genericCooldown = 0;

    mem.navKey = null;
    mem.navBest = 0;
    mem.navProgressTick = 0;
    mem.navDetour = null;
    mem.navDetourCount = 0;
    mem.avoidUntil = 0;
    mem.avoidStart = 0;
    mem.avoidSide = 1;
    mem.bumpUntil = 0;
    mem.bumpSide = 1;
    mem.bumpedPrev = false;
    mem.bumpCount = 0;
    mem.compassBad = 0;
    mem.headingRepeat = 0;

    mem.explorePts = [];
    var seenExplore = {};
    for (var ey = mem.minY + 30; ey <= mem.maxY - 30; ey += 65) {
      for (var ex = mem.minX + 30; ex <= mem.maxX - 30; ex += 65) {
        var ek = Math.round(ex) + ":" + Math.round(ey);
        if (!seenExplore[ek]) {
          seenExplore[ek] = true;
          mem.explorePts.push({ x: ex, y: ey, done: false });
        }
      }
    }
    mem.exploreTarget = -1;
    mem.returnFrom = "SELECT";
    mem.tick = 0;
    mem.initialized = true;
  }

  function clampPoint(x, y, margin) {
    var m = num(margin, 4);
    return {
      x: clamp(x, mem.minX + m, mem.maxX - m),
      y: clamp(y, mem.minY + m, mem.maxY - m)
    };
  }

  mem.tick = (mem.tick || 0) + 1;
  var tick = mem.tick;

  var rawX = num(obs.x, mem.lastRawX);
  var rawY = num(obs.y, mem.lastRawY);
  var rawH = num(obs.heading, mem.lastRawH * 180 / PI) * PI / 180;
  var wheelL = num(obs.wheelLeft, 0);
  var wheelR = num(obs.wheelRight, 0);
  var wheelV = (wheelL + wheelR) * 0.5;
  var dpsi = clamp((wheelR - wheelL) / 0.6 * DT, -1.2, 1.2);
  var battery = Math.max(0, num(obs.battery, 0));
  var solar = Math.max(0, num(obs.solar, 0));
  var carried = Math.max(0, Math.floor(num(obs.carried, 0)));
  var capacity = Math.max(1, Math.floor(num(obs.capacity, mem.capacity)));
  var timeLeft = num(obs.timeLeft, mem.seconds - tick * DT);
  var science = Math.max(0, num(obs.science, 0));
  var drilling = Math.max(0, num(obs.drilling, 0));
  var docked = !!obs.docked;

  if (battery > mem.batteryMax) mem.batteryMax = battery;

  var rawDeltaH = wrap(rawH - mem.lastRawH);
  if (Math.abs(rawDeltaH) < 0.001 && Math.abs(dpsi) > 0.04) {
    mem.headingRepeat = (mem.headingRepeat || 0) + 1;
  } else {
    mem.headingRepeat = 0;
  }

  var mismatchH = Math.abs(wrap(rawDeltaH - dpsi));
  var compassJump =
    (Math.abs(rawDeltaH) > 0.35 && mismatchH > 0.42) ||
    mem.headingRepeat > 20;

  if (compassJump) {
    mem.compassBad = 50;
  } else if (mem.compassBad > 0) {
    mem.compassBad--;
  }

  mem.yaw = wrap(mem.yaw + dpsi);
  if (!compassJump && mem.compassBad <= 0) {
    var compassErr = wrap(rawH - mem.bias - mem.yaw);
    if (Math.abs(compassErr) < 1.2) {
      mem.yaw = wrap(mem.yaw + clamp(0.025 * compassErr, -0.018, 0.018));
    }
  }

  var rawStep = dist(rawX, rawY, mem.lastRawX, mem.lastRawY);
  if (rawStep < 0.003) mem.gpsSameCount = (mem.gpsSameCount || 0) + 1;
  else mem.gpsSameCount = 0;

  mem.gpsWinPath += Math.abs(wheelV) * DT;
  mem.gpsWinTurn += Math.abs(dpsi);
  if (tick % 50 === 0) {
    var gpsWindowMove = dist(rawX, rawY, mem.gpsWinX, mem.gpsWinY);
    if (mem.gpsWinPath > 3.0 &&
        mem.gpsWinTurn < 1.2 &&
        gpsWindowMove < 0.25 &&
        mem.gpsSameCount > 40) {
      if (!mem.gpsFrozen) mem.gpsRecover = 20;
      mem.gpsFrozen = true;
    } else if (mem.gpsWinPath > 1.0 &&
               gpsWindowMove > Math.max(0.65, mem.gpsWinPath * 0.14)) {
      if (mem.gpsFrozen) mem.gpsRecover = 20;
      mem.gpsFrozen = false;
    }
    mem.gpsWinX = rawX;
    mem.gpsWinY = rawY;
    mem.gpsWinPath = 0;
    mem.gpsWinTurn = 0;
  }

  var oldPX = mem.poseX;
  var oldPY = mem.poseY;
  var moveV = Math.abs(wheelV) < 0.018 ? 0 : wheelV;
  var midYaw = wrap(mem.yaw - dpsi * 0.5);
  var predX = oldPX + moveV * DT * Math.cos(midYaw);
  var predY = oldPY + moveV * DT * Math.sin(midYaw);

  if (!mem.gpsFrozen) {
    var innovation = dist(predX, predY, rawX, rawY);
    if (innovation < 22) {
      var gpsAlpha = Math.abs(wheelV) > 0.08 ? 0.30 : 0.38;
      if (innovation > 5) gpsAlpha *= 0.40;
      if (mem.gpsRecover > 0) {
        gpsAlpha *= 0.55;
        mem.gpsRecover--;
      }
      predX += clamp((rawX - predX) * gpsAlpha, -0.50, 0.50);
      predY += clamp((rawY - predY) * gpsAlpha, -0.50, 0.50);
    }
  }

  mem.poseX = predX;
  mem.poseY = predY;

  if (!mem.gpsFrozen &&
      !compassJump &&
      mem.compassBad <= 0 &&
      wheelV > 0.14 &&
      Math.abs(dpsi) < 0.055) {
    if (mem.calPath < 0.001) {
      mem.calX = rawX;
      mem.calY = rawY;
      mem.calTurn = 0;
      mem.calSin = 0;
      mem.calCos = 0;
    }
    mem.calPath += wheelV * DT;
    mem.calTurn += Math.abs(dpsi);
    mem.calSin += Math.sin(rawH);
    mem.calCos += Math.cos(rawH);
  } else if (mem.calPath > 0) {
    mem.calTurn += Math.abs(dpsi);
    if (mem.calTurn > 0.52) {
      mem.calPath = 0;
      mem.calTurn = 0;
      mem.calSin = 0;
      mem.calCos = 0;
    }
  }

  if (mem.calPath >= 7.5) {
    var calDx = rawX - mem.calX;
    var calDy = rawY - mem.calY;
    var calDist = Math.sqrt(calDx * calDx + calDy * calDy);
    if (!mem.gpsFrozen &&
        calDist > 4 &&
        calDist > mem.calPath * 0.52 &&
        Math.abs(mem.calSin) + Math.abs(mem.calCos) > 0.1) {
      var course = Math.atan2(calDy, calDx);
      var avgCompass = Math.atan2(mem.calSin, mem.calCos);
      var measuredBias = wrap(avgCompass - course);
      var biasErr = wrap(measuredBias - mem.bias);
      if (Math.abs(biasErr) < 1.1) {
        mem.bias = wrap(mem.bias + 0.25 * biasErr);
      }
      var courseErr = wrap(course - mem.yaw);
      if (Math.abs(courseErr) < 1.4) {
        mem.yaw = wrap(mem.yaw + 0.18 * courseErr);
      }
    }
    mem.calX = rawX;
    mem.calY = rawY;
    mem.calPath = 0;
    mem.calTurn = 0;
    mem.calSin = 0;
    mem.calCos = 0;
  }

  var prevBattery = num(mem.prevBattery, battery);
  var prevSolar = num(mem.prevSolar, solar);
  var acceptedSolar = battery < mem.batteryMax - 0.025
    ? 0.5 * (prevSolar + solar) * DT
    : 0;
  var energyUse = prevBattery - battery + acceptedSolar;

  if (!docked && !mem.lastDrill) {
    if (energyUse > 0) mem.energyAcc += energyUse;
    if (battery < prevBattery - 0.08 && Math.abs(wheelV) < 0.08) {
      mem.energyRate = Math.max(mem.energyRate, 0.0025);
    }
    if (Math.abs(wheelV) > 0.05 || Math.abs(dpsi) > 0.02) {
      var energyStep = Math.max(
        Math.abs(wheelV) * DT,
        Math.abs(dpsi) * 0.08,
        rawStep * 0.55
      );
      mem.energyDist += energyStep;
      if (mem.energyDist >= 20) {
        var measuredRate = mem.energyAcc / Math.max(1, mem.energyDist);
        if (measuredRate > 0.00012 && measuredRate < 0.08) {
          var erAlpha = measuredRate > mem.energyRate ? 0.25 : 0.08;
          mem.energyRate = clamp(
            mem.energyRate * (1 - erAlpha) + measuredRate * erAlpha,
            0.00035,
            0.04
          );
        }
        mem.energyAcc = 0;
        mem.energyDist = 0;
      }
    }
  }

  mem.prevBattery = battery;
  mem.prevSolar = solar;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;
  mem.lastRawH = rawH;

  var sourceRays = Array.isArray(obs.rays) ? obs.rays : [];
  mem.rayMoved += Math.abs(wheelV) * DT + 0.12 * Math.abs(dpsi);
  var badRayCount = 0;

  for (var r = 0; r < 9; r++) {
    var rv = num(sourceRays[r], 15);
    rv = clamp(rv < 0 ? 15 : rv, 0, 15);
    mem.rays[r] = rv;

    if (mem.lastRays[r] >= 0 &&
        Math.abs(rv - mem.lastRays[r]) < 0.001) {
      mem.rayRepeat[r] = (mem.rayRepeat[r] || 0) + 1;
    } else {
      mem.rayRepeat[r] = 0;
      mem.rayBad[r] = false;
    }

    if (mem.rayRepeat[r] > 100 &&
        rv < 14.8 &&
        mem.rayMoved > 3.0) {
      mem.rayBad[r] = true;
    }
    if (mem.rayBad[r]) badRayCount++;
    mem.lastRays[r] = rv;
  }
  if (tick % 50 === 0) mem.rayMoved = 0;

  function rayAt(angleDeg) {
    var a = clamp(angleDeg, -80, 80);
    var p = (a + 80) / 20;
    var i = Math.floor(p);
    if (i >= 8) i = 8;
    var j = Math.min(8, i + 1);
    var f = p - i;
    var v1 = mem.rayBad[i] ? 15 : mem.rays[i];
    var v2 = mem.rayBad[j] ? 15 : mem.rays[j];
    if (i === j) return v1;
    return v1 * (1 - f) + v2 * f;
  }

  function chooseSide() {
    var leftOpen = rayAt(20) + rayAt(40) + rayAt(60);
    var rightOpen = rayAt(-20) + rayAt(-40) + rayAt(-60);
    if (Math.abs(leftOpen - rightOpen) < 0.2) {
      return (tick % 2) ? 1 : -1;
    }
    return leftOpen > rightOpen ? 1 : -1;
  }

  var bumped = !!obs.bumped;
  if (bumped && (!mem.bumpedPrev || tick % 40 === 0)) {
    mem.bumpSide = chooseSide();
    mem.bumpUntil = tick + 12;
    mem.avoidSide = mem.bumpSide;
    mem.avoidStart = tick;
    mem.avoidUntil = tick + 85;
    mem.bumpCount = (mem.bumpCount || 0) + 1;
    mem.navProgressTick = tick - 55;
  }
  mem.bumpedPrev = bumped;

  var baseScience = Math.max(0, num(mem.scienceBase, science));
  if (science < baseScience * 1.45 + 0.05) {
    mem.scienceBase = baseScience + 0.003 * (science - baseScience);
  }
  var signalThreshold = Math.max(
    0.22,
    num(mem.scienceBase, 0) * 1.55 + 0.04
  );
  if (science > signalThreshold) {
    if (!Array.isArray(mem.signalCandidates)) mem.signalCandidates = [];
    var nearestCand = -1;
    var nearestCandD = 1e30;
    for (var sc = 0; sc < mem.signalCandidates.length; sc++) {
      var oldCand = mem.signalCandidates[sc];
      var cd = dist(mem.poseX, mem.poseY, oldCand.x, oldCand.y);
      if (cd < nearestCandD) {
        nearestCandD = cd;
        nearestCand = sc;
      }
    }

    if (nearestCand >= 0 && nearestCandD < 28) {
      var cnd = mem.signalCandidates[nearestCand];
      if (science > cnd.value) {
        cnd.value = science;
        cnd.x = mem.poseX;
        cnd.y = mem.poseY;
        cnd.tick = tick;
      }
    } else {
      if (mem.signalCandidates.length >= 10) {
        var weakest = 0;
        for (var wi = 1; wi < mem.signalCandidates.length; wi++) {
          if (mem.signalCandidates[wi].value <
              mem.signalCandidates[weakest].value) weakest = wi;
        }
        if (science > mem.signalCandidates[weakest].value) {
          mem.signalCandidates.splice(weakest, 1);
          mem.signalCandidates.push({
            x: mem.poseX,
            y: mem.poseY,
            value: science,
            tick: tick,
            done: false
          });
        }
      } else {
        mem.signalCandidates.push({
          x: mem.poseX,
          y: mem.poseY,
          value: science,
          tick: tick,
          done: false
        });
      }
    }
  }

  function output(left, right, drill, targetL, targetR) {
    left = clamp(left, -1, 1);
    right = clamp(right, -1, 1);
    mem.prevCmdL = num(mem.lastCmdL, 0);
    mem.prevCmdR = num(mem.lastCmdR, 0);
    mem.prevTargetL = num(mem.lastTargetL, 0);
    mem.prevTargetR = num(mem.lastTargetR, 0);
    mem.lastCmdL = left;
    mem.lastCmdR = right;
    mem.lastTargetL = num(targetL, 0);
    mem.lastTargetR = num(targetR, 0);
    mem.lastDrill = !!drill;
    return { left: left, right: right, drill: !!drill };
  }

  function motorCommand(target, actual, side, pitchTerm) {
    var gain = side === 0 ? mem.gainL : mem.gainR;
    var dead = side === 0 ? mem.deadL : mem.deadR;
    var integ = side === 0 ? mem.iL : mem.iR;
    var lastCmd = side === 0 ? mem.lastCmdL : mem.lastCmdR;
    var prevCmd = side === 0 ? mem.prevCmdL : mem.prevCmdR;
    var lastTarget = side === 0 ? mem.lastTargetL : mem.lastTargetR;
    var prevTarget = side === 0 ? mem.prevTargetL : mem.prevTargetR;

    if (Math.abs(lastTarget) > 0.10 &&
        lastTarget * actual > 0.015 &&
        Math.abs(lastTarget - prevTarget) < 0.06 &&
        Math.abs(lastCmd - prevCmd) < 0.06 &&
        Math.abs(lastCmd) > dead + 0.035) {
      var den = Math.max(0.04, Math.abs(lastCmd) - dead);
      var est = Math.abs(actual) / den;
      if (est > 0.55 && est < 7) {
        var aGain = est > gain ? 0.035 : 0.07;
        gain = clamp(gain * (1 - aGain) + est * aGain, 0.65, 6.5);
        if (side === 0) mem.gainL = gain;
        else mem.gainR = gain;
      }
    }

    var err = target - actual;
    var u;
    if (Math.abs(target) < 0.035) {
      integ *= 0.65;
      if (Math.abs(actual) > 0.07) {
        u = -Math.sign(actual) *
            (dead + Math.min(0.22, 0.38 * Math.abs(actual))) +
            pitchTerm;
      } else {
        u = pitchTerm;
      }
    } else {
      integ = clamp(integ + err * 0.10 * DT, -0.12, 0.12);
      var ff = (target > 0 ? 1 : -1) *
               (dead + Math.abs(target) / Math.max(0.75, gain));
      u = ff + 0.42 * err + integ + pitchTerm;
    }

    if (side === 0) mem.iL = integ;
    else mem.iR = integ;

    u = clamp(u, -0.42, 0.42);
    var slew = 0.085;
    u = clamp(u, lastCmd - slew, lastCmd + slew);
    return clamp(u, -0.42, 0.42);
  }

  function moveOutput(v, omega, drill) {
    var targetL = clamp(v - 0.3 * omega, -0.58, 0.58);
    var targetR = clamp(v + 0.3 * omega, -0.58, 0.58);
    var pitchRad = num(obs.pitch, 0) * PI / 180;
    var pitchTerm = clamp(0.78 * Math.sin(pitchRad), -0.22, 0.22);
    var left = motorCommand(targetL, wheelL, 0, pitchTerm);
    var right = motorCommand(targetR, wheelR, 1, pitchTerm);
    return output(left, right, drill, targetL, targetR);
  }

  function idleOutput() {
    return moveOutput(0, 0, false);
  }

  function driveRelative(targetRel, d, stop, cruise) {
    if (tick <= num(mem.bumpUntil, 0)) {
      return moveOutput(-0.13, num(mem.bumpSide, 1) * 0.58, false);
    }

    if (d <= stop) return idleOutput();

    var rel = wrap(targetRel);
    var relDeg = rel * 180 / PI;

    if (Math.abs(rel) > 1.82) {
      return moveOutput(0, clamp(1.15 * rel, -0.78, 0.78), false);
    }

    var directRay = Math.abs(relDeg) <= 80 ? rayAt(relDeg) : 15;
    var forceAvoid = tick < num(mem.avoidUntil, 0);

    if (forceAvoid &&
        tick - num(mem.avoidStart, tick) > 18 &&
        directRay > 4.8 &&
        Math.abs(rel) < 0.65) {
      mem.avoidUntil = 0;
      forceAvoid = false;
    }

    if (!forceAvoid &&
        Math.abs(relDeg) < 78 &&
        directRay < 3.0) {
      mem.avoidSide = chooseSide();
      mem.avoidStart = tick;
      mem.avoidUntil = tick + 70;
      forceAvoid = true;
    }

    var aim = rel;
    var clearance = directRay;

    if ((forceAvoid || directRay < 3.0) && Math.abs(relDeg) < 82) {
      var refDeg = relDeg;
      if (forceAvoid) {
        refDeg = clamp(
          relDeg + num(mem.avoidSide, 1) * 32,
          -78,
          78
        );
      }

      var bestScore = -1e30;
      var bestAngle = clamp(refDeg, -80, 80);
      for (var ca = -80; ca <= 80; ca += 20) {
        var cr = rayAt(ca);
        var diff = wrap((ca - refDeg) * PI / 180);
        var score = 2.0 * Math.cos(diff) +
                    0.22 * Math.min(cr, 8) -
                    0.34 * Math.max(0, 2.0 - cr);

        if (forceAvoid) {
          var change = wrap((ca - relDeg) * PI / 180);
          if (change * num(mem.avoidSide, 1) > 0.08) score += 0.25;
        }

        var worldA = mem.yaw + ca * PI / 180;
        var testX = mem.poseX + 7 * Math.cos(worldA);
        var testY = mem.poseY + 7 * Math.sin(worldA);
        if (testX < mem.minX + 3 || testX > mem.maxX - 3 ||
            testY < mem.minY + 3 || testY > mem.maxY - 3) {
          score -= 1.2;
        }

        if (cr < 0.85) score -= 2.2;
        else if (cr < 1.35) score -= 0.8;

        if (score > bestScore) {
          bestScore = score;
          bestAngle = ca;
        }
      }
      aim = bestAngle * PI / 180;
      clearance = rayAt(bestAngle);
    }

    var cap = clamp(cruise, 0.08, 0.44);
    if (badRayCount >= 6) cap = Math.min(cap, 0.27);
    if (clearance < 0.85) cap = 0;
    else if (clearance < 1.35) cap = Math.min(cap, 0.08);
    else if (clearance < 2.0) cap = Math.min(cap, 0.15);
    else if (clearance < 3.0) cap = Math.min(cap, 0.23);
    else if (clearance < 4.2) cap = Math.min(cap, 0.30);

    var allBlind = true;
    for (var bi = 0; bi < 9; bi++) {
      if (!mem.rayBad[bi] && mem.rays[bi] < 14.8) {
        allBlind = false;
        break;
      }
    }
    if (allBlind) cap = Math.min(cap, 0.28);

    var front = rayAt(0);
    if (front < 0.85 && Math.abs(aim) < 0.42) cap = 0;
    else if (front < 1.30 && Math.abs(aim) < 0.30) {
      cap = Math.min(cap, 0.10);
    }

    var remaining = Math.max(0, d - stop);
    var v = Math.min(cap, Math.sqrt(0.62 * remaining));
    var absAim = Math.abs(aim);

    if (absAim > 1.18) {
      v = 0;
    } else {
      v *= Math.max(0, Math.cos(aim));
      if (absAim > 0.82) v = Math.min(v, 0.13);
      else if (absAim > 0.58) v = Math.min(v, 0.25);
    }

    var omega = clamp(1.45 * aim, -0.85, 0.85);
    return moveOutput(v, omega, false);
  }

  function navTo(x, y, stop, key, cruise) {
    key = String(key);
    var margin = key === "home" ? 1.5 : 4;
    var p = clampPoint(x, y, margin);
    x = p.x;
    y = p.y;

    var mainDist = dist(mem.poseX, mem.poseY, x, y);

    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = mainDist;
      mem.navProgressTick = tick;
      mem.navDetour = null;
      mem.navDetourCount = 0;
    } else if (mainDist < num(mem.navBest, mainDist) - 0.40) {
      if (mainDist < num(mem.navBest, mainDist) - 1.8) {
        mem.navDetourCount = 0;
      }
      mem.navBest = mainDist;
      mem.navProgressTick = tick;
    }

    if (mem.navDetour && mem.navDetour.key === key) {
      var detD = dist(mem.poseX, mem.poseY,
                      mem.navDetour.x, mem.navDetour.y);
      if (detD < 2.1 || tick > mem.navDetour.until) {
        mem.navDetour = null;
        mem.navProgressTick = tick;
        mem.navBest = mainDist;
      } else if (detD < num(mem.navDetour.best, detD) - 0.40) {
        mem.navDetour.best = detD;
        mem.navProgressTick = tick;
      }
    }

    if (!mem.navDetour &&
        mainDist > stop + 4 &&
        tick - num(mem.navProgressTick, tick) > 85 &&
        num(mem.navDetourCount, 0) < 5) {
      var side = chooseSide();
      if (mem.navDetourCount % 2 === 1) side = -side;
      var goalAngle = Math.atan2(y - mem.poseY, x - mem.poseX);
      var detAngle = goalAngle + side * 0.95;
      var dp = clampPoint(
        mem.poseX + 7 * Math.cos(detAngle),
        mem.poseY + 7 * Math.sin(detAngle),
        5
      );

      if (dist(mem.poseX, mem.poseY, dp.x, dp.y) < 2.2) {
        detAngle = goalAngle - side * 1.05;
        dp = clampPoint(
          mem.poseX + 6 * Math.cos(detAngle),
          mem.poseY + 6 * Math.sin(detAngle),
          5
        );
        side = -side;
      }

      if (dist(mem.poseX, mem.poseY, dp.x, dp.y) > 2.0) {
        mem.navDetour = {
          x: dp.x,
          y: dp.y,
          key: key,
          until: tick + 145,
          best: dist(mem.poseX, mem.poseY, dp.x, dp.y)
        };
        mem.navDetourCount++;
        mem.avoidSide = side;
        mem.avoidStart = tick;
        mem.avoidUntil = tick + 65;
      }
      mem.navProgressTick = tick;
    }

    var tx = x;
    var ty = y;
    var localStop = stop;
    var localCruise = cruise;
    if (mem.navDetour && mem.navDetour.key === key) {
      tx = mem.navDetour.x;
      ty = mem.navDetour.y;
      localStop = 1.9;
      localCruise = Math.min(cruise, 0.33);
    }

    var dx = tx - mem.poseX;
    var dy = ty - mem.poseY;
    var d = Math.sqrt(dx * dx + dy * dy);
    var rel = wrap(Math.atan2(dy, dx) - mem.yaw);
    return driveRelative(rel, d, localStop, localCruise);
  }

  function baseDistance() {
    return dist(mem.poseX, mem.poseY, mem.baseX, mem.baseY);
  }

  function homeDistance() {
    var b = obs.beacon && typeof obs.beacon === "object" ? obs.beacon : null;
    if (b) return Math.max(0, num(b.distance, baseDistance()));
    return baseDistance();
  }

  function energyNeed(distanceMeters, samples, margin) {
    var d = Math.max(0, distanceMeters);
    var load = 1 + 0.22 * Math.max(0, samples);
    return 0.10 + d * mem.energyRate * load * margin +
           0.012 * Math.max(0, samples);
  }

  function travelTime(d) {
    return Math.max(0, d) * 1.35 / 0.38 + 22;
  }

  function patternCost(lanes) {
    if (lanes >= 4) return 215;
    if (lanes === 3) return 156;
    return 96;
  }

  function canSampleHere() {
    if (carried >= capacity) return false;
    var home = homeDistance();
    var need = energyNeed(home * 1.42 + 12, carried + 1, 1.32);
    return battery > need + 0.055 &&
           timeLeft > travelTime(home) + 10;
  }

  function projectedTaskDistance() {
    if (mem.mode === "TRAVEL") {
      var ti = Math.floor(num(mem.activeHint, -1));
      if (ti >= 0 && ti < mem.hints.length) {
        var hnt = mem.hints[ti];
        return dist(mem.poseX, mem.poseY, hnt.x, hnt.y) +
               patternCost(mem.scanLanes || 3) +
               dist(hnt.x, hnt.y, mem.baseX, mem.baseY) + 15;
      }
    }

    if (mem.mode === "SCAN" &&
        Array.isArray(mem.scanPoints) &&
        mem.scanPoints.length > 0) {
      var total = 0;
      var px = mem.poseX;
      var py = mem.poseY;
      for (var si = mem.scanIndex; si < mem.scanPoints.length; si++) {
        total += dist(px, py, mem.scanPoints[si].x, mem.scanPoints[si].y);
        px = mem.scanPoints[si].x;
        py = mem.scanPoints[si].y;
      }
      return total + dist(px, py, mem.baseX, mem.baseY) + 12;
    }

    if (mem.mode === "EXPLORE" &&
        mem.exploreTarget >= 0 &&
        mem.exploreTarget < mem.explorePts.length) {
      var ep = mem.explorePts[mem.exploreTarget];
      return dist(mem.poseX, mem.poseY, ep.x, ep.y) +
             dist(ep.x, ep.y, mem.baseX, mem.baseY) + 12;
    }

    if (mem.mode === "SITE" && mem.siteActive) {
      return homeDistance() + 12;
    }
    return 0;
  }

  function shouldReturn() {
    if (docked || mem.mode === "RETURN") return false;
    if (carried >= capacity && carried > 0) return true;

    var home = homeDistance();
    var homeNeed = energyNeed(home * 1.38 + 9, carried, 1.34);
    if (home > 2.5 && battery < homeNeed + 0.055) return true;

    if (carried > 0) {
      if (timeLeft < home * 1.42 / 0.38 + 24) return true;
      var projected = projectedTaskDistance();
      if (projected > 0) {
        if (battery <
            energyNeed(projected * 1.12, carried + 1, 1.22) + 0.045) {
          return true;
        }
        if (timeLeft < projected * 1.24 / 0.38 + 28) return true;
      }
    }

    if (carried === 0 && home > 5 &&
        battery < energyNeed(home * 1.42 + 10, 0, 1.35) + 0.045) {
      return true;
    }
    return false;
  }

  function siteEstimate(s) {
    var d = Math.max(0, num(s.distance, 0));
    var b = num(s.bearing, 0) * PI / 180;
    var a = mem.yaw + b;
    return {
      x: mem.poseX + d * Math.cos(a),
      y: mem.poseY + d * Math.sin(a)
    };
  }

  function updateSiteGoal(s) {
    if (!s) return;
    var p = siteEstimate(s);
    if (mem.siteGX === null ||
        mem.siteGY === null ||
        !isFinite(mem.siteGX) ||
        !isFinite(mem.siteGY)) {
      mem.siteGX = p.x;
      mem.siteGY = p.y;
    } else {
      mem.siteGX = 0.68 * mem.siteGX + 0.32 * p.x;
      mem.siteGY = 0.68 * mem.siteGY + 0.32 * p.y;
    }
    mem.siteValue = num(s.value, mem.siteValue || 0);
  }

  function activateSite(s) {
    var resume = mem.mode || "SELECT";
    if (resume === "RETURN" || resume === "SITE") resume = "SELECT";

    mem.siteResume = resume;
    mem.siteActive = true;
    mem.siteDrillStarted = drilling > 0.01;
    mem.siteMiss = 0;
    mem.siteLastDistance = Math.max(0, num(s.distance, 8));
    mem.sampleStartCarried = carried;
    mem.siteAssoc = -1;
    updateSiteGoal(s);

    var p = siteEstimate(s);
    var best = -1;
    var bestD = 1e30;

    for (var i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].status === 1) continue;
      var hd = dist(p.x, p.y, mem.hints[i].x, mem.hints[i].y);
      if (hd < bestD) {
        bestD = hd;
        best = i;
      }
    }

    var ai = Math.floor(num(mem.activeHint, -1));
    if (ai >= 0 && ai < mem.hints.length &&
        mem.hints[ai].status !== 1) {
      var ad = dist(p.x, p.y, mem.hints[ai].x, mem.hints[ai].y);
      if (ad <= 46 && (best < 0 || ad <= bestD + 8)) {
        best = ai;
        bestD = ad;
      }
    }
    if (best >= 0 && bestD <= 42) mem.siteAssoc = best;

    mem.mode = "SITE";
    mem.navKey = null;
  }

  function finishSite() {
    var assoc = Math.floor(num(mem.siteAssoc, -1));
    var active = Math.floor(num(mem.activeHint, -1));
    var resume = mem.siteResume || "SELECT";
    var sx = mem.siteGX !== null && isFinite(mem.siteGX)
      ? mem.siteGX : mem.poseX;
    var sy = mem.siteGY !== null && isFinite(mem.siteGY)
      ? mem.siteGY : mem.poseY;

    if (assoc >= 0 && assoc < mem.hints.length) {
      mem.hints[assoc].status = 1;
      if (mem.siteValue > 0) mem.hints[assoc].value = mem.siteValue;
    } else if (active >= 0 && active < mem.hints.length &&
               dist(sx, sy, mem.hints[active].x, mem.hints[active].y) < 42) {
      mem.hints[active].status = 1;
      if (mem.siteValue > 0) mem.hints[active].value = mem.siteValue;
    }

    mem.lastSampleX = sx;
    mem.lastSampleY = sy;
    mem.lastSampleTick = tick;

    for (var ci = 0; ci < mem.signalCandidates.length; ci++) {
      if (dist(sx, sy,
               mem.signalCandidates[ci].x,
               mem.signalCandidates[ci].y) < 32) {
        mem.signalCandidates[ci].done = true;
      }
    }

    if (resume === "RETURN" || resume === "SITE") resume = "SELECT";
    mem.mode = resume;
    mem.siteActive = false;
    mem.siteDrillStarted = false;
    mem.siteResume = null;
    mem.siteAssoc = -1;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.siteMiss = 0;
    mem.lastDrill = false;
    mem.navKey = null;
  }

  function siteControl() {
    var s = obs.site && typeof obs.site === "object" ? obs.site : null;
    var d;
    var bearing;

    if (s) {
      updateSiteGoal(s);
      d = Math.max(0, num(s.distance, 0));
      bearing = num(s.bearing, 0);
      mem.siteLastDistance = d;
      mem.siteMiss = 0;
    } else {
      mem.siteMiss = num(mem.siteMiss, 0) + 1;
      if (mem.siteGX !== null && mem.siteGY !== null) {
        var dx = mem.siteGX - mem.poseX;
        var dy = mem.siteGY - mem.poseY;
        d = Math.sqrt(dx * dx + dy * dy);
        bearing = wrap(Math.atan2(dy, dx) - mem.yaw) * 180 / PI;
      } else {
        d = num(mem.siteLastDistance, 8);
        bearing = 0;
      }

      if (mem.siteMiss > 180 &&
          !mem.siteDrillStarted &&
          drilling <= 0.01) {
        mem.siteActive = false;
        mem.mode = mem.siteResume || "SELECT";
        mem.siteResume = null;
        mem.siteAssoc = -1;
        mem.siteGX = null;
        mem.siteGY = null;
        mem.navKey = null;
        return idleOutput();
      }
    }

    if (drilling > 0.01 || mem.lastDrill) {
      mem.siteDrillStarted = true;
    }

    if ((!mem.siteDrillStarted && d > 1.37) ||
        (mem.siteDrillStarted && d > 1.50)) {
      return driveRelative(
        bearing * PI / 180,
        d,
        1.14,
        mem.siteDrillStarted ? 0.12 : 0.20
      );
    }

    var still = Math.max(Math.abs(wheelL), Math.abs(wheelR)) < 0.15;
    var drillOn = d <= 1.49 && still;
    if (drillOn) mem.siteDrillStarted = true;
    return moveOutput(0, 0, drillOn);
  }

  function makeScanPoints(cx, cy, lanes) {
    var rows;
    var halfX;
    if (lanes >= 4) {
      rows = [-20, -7, 7, 20];
      halfX = 22;
    } else if (lanes === 3) {
      rows = [-18, 0, 18];
      halfX = 20;
    } else {
      rows = [-12, 12];
      halfX = 18;
    }

    var points = [];
    var startLeft = mem.poseX <= cx;
    for (var i = 0; i < rows.length; i++) {
      var leftFirst = (i % 2 === 0) ? startLeft : !startLeft;
      var x1 = cx + (leftFirst ? -halfX : halfX);
      var x2 = cx + (leftFirst ? halfX : -halfX);
      var y = cy + rows[i];
      points.push(clampPoint(x1, y, 4));
      points.push(clampPoint(x2, y, 4));
    }
    return points;
  }

  function beginScan(cx, cy, source, hintIndex, signalIndex, lanes, resume) {
    var p = clampPoint(cx, cy, 4);
    mem.scanCenterX = p.x;
    mem.scanCenterY = p.y;
    mem.scanSource = source;
    mem.scanResume = source === "hint" ? "SELECT" : (resume || "SELECT");
    mem.scanHintIndex = hintIndex;
    mem.scanSignalIndex = signalIndex;
    mem.scanLanes = lanes;
    mem.scanCost = patternCost(lanes);
    mem.scanPoints = makeScanPoints(p.x, p.y, lanes);
    mem.scanIndex = 0;
    mem.activeHint = source === "hint" ? hintIndex : -1;
    mem.mode = "SCAN";
    mem.navKey = null;
    mem.navDetour = null;
  }

  function finishScan() {
    if (mem.scanSource === "hint") {
      var hi = Math.floor(num(mem.scanHintIndex, -1));
      if (hi >= 0 && hi < mem.hints.length &&
          mem.hints[hi].status === 0) {
        mem.hints[hi].status = 2;
      }
      mem.mode = "SELECT";
      mem.activeHint = -1;
    } else {
      if (!Array.isArray(mem.genericDone)) mem.genericDone = [];
      mem.genericDone.push({
        x: mem.scanCenterX,
        y: mem.scanCenterY
      });
      if (mem.genericDone.length > 24) mem.genericDone.shift();

      var si = Math.floor(num(mem.scanSignalIndex, -1));
      if (si >= 0 && si < mem.signalCandidates.length) {
        mem.signalCandidates[si].done = true;
      }
      mem.mode = mem.scanResume || "SELECT";
      if (mem.mode === "SCAN" || mem.mode === "SITE" ||
          mem.mode === "RETURN") mem.mode = "SELECT";
      mem.genericCooldown = tick + 180;
    }

    mem.scanPoints = [];
    mem.scanIndex = 0;
    mem.scanSource = "";
    mem.scanHintIndex = -1;
    mem.scanSignalIndex = -1;
    mem.navKey = null;
    mem.navDetour = null;
  }

  function chooseHint() {
    if (carried >= capacity) return null;

    var best = null;
    var bestScore = -1;

    for (var i = 0; i < mem.hints.length; i++) {
      var hh = mem.hints[i];
      if (!hh || hh.status !== 0) continue;

      var outDist = dist(mem.poseX, mem.poseY, hh.x, hh.y);
      var homeDist = dist(mem.baseX, mem.baseY, hh.x, hh.y);
      var chosenLanes = 0;
      var chosenRoute = 0;

      for (var lanes = 4; lanes >= 2; lanes--) {
        var route = outDist * 1.24 +
                    patternCost(lanes) * 1.12 +
                    homeDist * 1.34 + 20;
        var need = energyNeed(route, carried + 1, 1.30);
        var timeNeed = route * 1.15 / 0.42 + 38;
        if (battery > need + 0.07 && timeLeft > timeNeed) {
          chosenLanes = lanes;
          chosenRoute = route;
          break;
        }
      }

      if (chosenLanes === 0) continue;

      var score = hh.value /
        (40 + 0.76 * outDist + 0.78 * homeDist +
         0.34 * patternCost(chosenLanes));
      if (score > bestScore) {
        bestScore = score;
        best = {
          index: i,
          lanes: chosenLanes,
          route: chosenRoute
        };
      }
    }

    return best;
  }

  function trySignalSearch(resume, localOnly) {
    if (tick < num(mem.genericCooldown, 0) ||
        carried >= capacity ||
        !Array.isArray(mem.signalCandidates)) {
      return false;
    }

    var best = -1;
    var bestScore = -1e30;
    var threshold = Math.max(0.22, mem.scienceBase * 1.55 + 0.04);

    for (var i = 0; i < mem.signalCandidates.length; i++) {
      var c = mem.signalCandidates[i];
      if (!c || c.done || c.value < threshold) continue;
      if (localOnly && dist(mem.poseX, mem.poseY, c.x, c.y) > 45) continue;

      var alreadyDone = false;
      for (var gd = 0; gd < mem.genericDone.length; gd++) {
        if (dist(c.x, c.y, mem.genericDone[gd].x, mem.genericDone[gd].y) < 28) {
          alreadyDone = true;
          break;
        }
      }
      if (alreadyDone) continue;

      var nearPendingHint = false;
      for (var hi = 0; hi < mem.hints.length; hi++) {
        if (mem.hints[hi].status === 0 &&
            dist(c.x, c.y, mem.hints[hi].x, mem.hints[hi].y) < 30) {
          nearPendingHint = true;
          break;
        }
      }
      if (nearPendingHint) continue;

      var nearSample = mem.lastSampleX !== null &&
                       dist(c.x, c.y, mem.lastSampleX, mem.lastSampleY) < 24;
      if (nearSample) continue;

      var lanes = c.value > threshold * 4 ? 4 : 3;
      var scanLen = patternCost(lanes);
      var outDist = dist(mem.poseX, mem.poseY, c.x, c.y);
      var homeDist = dist(mem.baseX, mem.baseY, c.x, c.y);
      var route = outDist * 1.24 + scanLen * 1.12 +
                  homeDist * 1.34 + 20;

      if (battery < energyNeed(route, carried + 1, 1.30) + 0.07) continue;
      if (timeLeft < route * 1.15 / 0.42 + 38) continue;

      var score = c.value / (50 + outDist + homeDist + scanLen * 0.35);
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }

    if (best < 0) return false;
    var cand = mem.signalCandidates[best];
    var lanesBest = cand.value > threshold * 4 ? 4 : 3;
    beginScan(cand.x, cand.y, "signal", -1, best,
              lanesBest, resume || "SELECT");
    return true;
  }

  function chooseExploreTarget() {
    var best = -1;
    var bestD = 1e30;
    for (var i = 0; i < mem.explorePts.length; i++) {
      var p = mem.explorePts[i];
      if (p.done) continue;
      var d = dist(mem.poseX, mem.poseY, p.x, p.y);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    return best;
  }

  function enterReturn() {
    if (mem.mode === "RETURN") return;

    var from = mem.mode || "SELECT";
    if (from === "SITE") from = mem.siteResume || "SELECT";
    if (from === "RETURN") from = "SELECT";
    mem.returnFrom = from;

    mem.mode = "RETURN";
    mem.siteActive = false;
    mem.siteDrillStarted = false;
    mem.siteResume = null;
    mem.siteAssoc = -1;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.navKey = null;
    mem.navDetour = null;
    mem.avoidUntil = 0;
  }

  function returnControl() {
    var b = obs.beacon && typeof obs.beacon === "object" ? obs.beacon : null;
    if (b) {
      var bd = Math.max(0, num(b.distance, 20));
      if (bd <= 2.05) return idleOutput();
      return driveRelative(
        num(b.bearing, 0) * PI / 180,
        bd,
        1.90,
        0.36
      );
    }

    var d = baseDistance();
    if (d <= 1.85) return idleOutput();
    return navTo(mem.baseX, mem.baseY, 1.80, "home", 0.36);
  }

  var siteObs = obs.site && typeof obs.site === "object" ? obs.site : null;

  if (mem.siteActive) {
    if (drilling > 0.01 || mem.lastDrill) {
      mem.siteDrillStarted = true;
    }
    if (carried > num(mem.sampleStartCarried, carried)) {
      finishSite();
    }
  }

  if (mem.mode === "RETURN") {
    if (!docked) return returnControl();
    if (carried > 0) return idleOutput();

    var chargeTarget = Math.max(0.68, mem.batteryMax * 0.88);
    if (battery < chargeTarget && timeLeft > 55) return idleOutput();
    if (timeLeft < 24) return idleOutput();

    mem.mode = mem.returnFrom || "SELECT";
    if (mem.mode === "RETURN" || mem.mode === "SITE") mem.mode = "SELECT";
    mem.returnFrom = "SELECT";
    mem.navKey = null;
    mem.navDetour = null;
  }

  if (mem.siteActive) {
    if (!mem.siteDrillStarted && shouldReturn()) {
      enterReturn();
      return returnControl();
    }
    return siteControl();
  }

  if (siteObs && carried < capacity && mem.mode !== "RETURN") {
    var sitePoint = siteEstimate(siteObs);
    var recentSame = mem.lastSampleX !== null &&
                     tick - num(mem.lastSampleTick, -10000) < 40 &&
                     dist(sitePoint.x, sitePoint.y,
                          mem.lastSampleX, mem.lastSampleY) < 3.0;
    if (!recentSame) {
      if (canSampleHere()) {
        activateSite(siteObs);
        return siteControl();
      }
      enterReturn();
      return returnControl();
    }
  }

  if (shouldReturn()) {
    enterReturn();
    return returnControl();
  }

  for (var loop = 0; loop < 12; loop++) {
    if (mem.mode === "SELECT" || !mem.mode) {
      var localSignal = false;
      for (var lc = 0; lc < mem.signalCandidates.length; lc++) {
        var lcand = mem.signalCandidates[lc];
        if (lcand && !lcand.done &&
            lcand.value > Math.max(0.75, mem.scienceBase * 4.0) &&
            dist(mem.poseX, mem.poseY, lcand.x, lcand.y) < 45) {
          localSignal = true;
          break;
        }
      }
      if (localSignal && trySignalSearch("SELECT", true)) continue;

      var nextHint = chooseHint();
      if (nextHint) {
        mem.activeHint = nextHint.index;
        mem.scanLanes = nextHint.lanes;
        mem.scanCost = patternCost(nextHint.lanes);
        mem.scanSource = "hint";
        mem.scanHintIndex = nextHint.index;
        mem.mode = "TRAVEL";
        mem.navKey = null;
        mem.navDetour = null;
        continue;
      }

      if (trySignalSearch("SELECT", false)) continue;

      if (carried > 0) {
        enterReturn();
        return returnControl();
      }

      var targetCharge = Math.max(0.68, mem.batteryMax * 0.88);
      if (docked && battery < targetCharge && timeLeft > 55) {
        return idleOutput();
      }
      if (timeLeft < 28) return idleOutput();

      mem.mode = "EXPLORE";
      continue;
    }

    if (mem.mode === "TRAVEL") {
      var ti = Math.floor(num(mem.activeHint, -1));
      if (ti < 0 || ti >= mem.hints.length ||
          mem.hints[ti].status !== 0) {
        mem.activeHint = -1;
        mem.mode = "SELECT";
        continue;
      }

      var targetHint = mem.hints[ti];
      var hd = dist(mem.poseX, mem.poseY, targetHint.x, targetHint.y);
      if (hd <= 2.8) {
        beginScan(targetHint.x, targetHint.y, "hint",
                  ti, -1, mem.scanLanes || 3, "SELECT");
        continue;
      }

      return navTo(targetHint.x, targetHint.y, 1.70,
                   "hint:" + ti, 0.38);
    }

    if (mem.mode === "SCAN") {
      if (!Array.isArray(mem.scanPoints) ||
          mem.scanIndex >= mem.scanPoints.length) {
        finishScan();
        continue;
      }

      var node = mem.scanPoints[mem.scanIndex];
      var nd = dist(mem.poseX, mem.poseY, node.x, node.y);
      if (nd <= 1.55) {
        mem.scanIndex++;
        mem.navKey = null;
        continue;
      }

      return navTo(node.x, node.y, 1.35,
                   "scan:" + mem.scanSource + ":" + mem.scanIndex,
                   0.35);
    }

    if (mem.mode === "EXPLORE") {
      if (trySignalSearch("SELECT", false)) continue;

      if (mem.exploreTarget < 0 ||
          mem.exploreTarget >= mem.explorePts.length ||
          mem.explorePts[mem.exploreTarget].done) {
        mem.exploreTarget = chooseExploreTarget();
      }

      if (mem.exploreTarget < 0) {
        if (carried > 0) {
          enterReturn();
          return returnControl();
        }
        return idleOutput();
      }

      var ep = mem.explorePts[mem.exploreTarget];
      var ed = dist(mem.poseX, mem.poseY, ep.x, ep.y);
      if (ed <= 1.9) {
        ep.done = true;
        mem.exploreTarget = -1;
        mem.navKey = null;
        mem.mode = "SELECT";
        continue;
      }

      if (battery <
          energyNeed((ed + dist(ep.x, ep.y, mem.baseX, mem.baseY)) * 1.25 + 10,
                     0, 1.30) + 0.05) {
        enterReturn();
        return returnControl();
      }

      return navTo(ep.x, ep.y, 1.65,
                   "explore:" + mem.exploreTarget, 0.35);
    }

    if (mem.mode === "SITE" && mem.siteActive) {
      return siteControl();
    }

    if (mem.mode === "RETURN") return returnControl();

    mem.mode = "SELECT";
  }

  return idleOutput();
}

function act(obs, mem) {
  if (!obs || typeof obs !== "object") obs = {};
  if (!mem || typeof mem !== "object") mem = {};

  var PI = Math.PI;
  var DT = 0.1;

  function num(v, d) {
    if (v === null || v === undefined) return d;
    var q = Number(v);
    return isFinite(q) ? q : d;
  }

  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }

  function wrap(a) {
    while (a > PI) a -= 2 * PI;
    while (a < -PI) a += 2 * PI;
    return a;
  }

  function dist(x1, y1, x2, y2) {
    var dx = x2 - x1;
    var dy = y2 - y1;
    return Math.sqrt(dx * dx + dy * dy);
  }

  var mission = obs.mission || {};

  if (!mem.initialized) {
    var size = mission.size;
    var w = 400;
    var h = 400;

    if (typeof size === "number") {
      w = size;
      h = size;
    } else if (size && typeof size === "object") {
      w = num(size.width, num(size.x, 400));
      h = num(size.height, num(size.y, 400));
    }

    var base = mission.base || {};
    var bx = num(base.x, num(obs.x, w * 0.5));
    var by = num(base.y, num(obs.y, h * 0.5));
    var sourceHints = Array.isArray(mission.hints) ? mission.hints : [];

    var centered = bx < 0 || by < 0;
    for (var ci = 0; ci < sourceHints.length; ci++) {
      var ch = sourceHints[ci] || {};
      if (num(ch.x, 0) < 0 || num(ch.y, 0) < 0) centered = true;
    }

    mem.mapW = w;
    mem.mapH = h;
    mem.minX = size && typeof size === "object"
      ? num(size.minX, centered ? -w * 0.5 : 0)
      : (centered ? -w * 0.5 : 0);
    mem.maxX = size && typeof size === "object"
      ? num(size.maxX, mem.minX + w)
      : (centered ? w * 0.5 : w);
    mem.minY = size && typeof size === "object"
      ? num(size.minY, centered ? -h * 0.5 : 0)
      : (centered ? -h * 0.5 : 0);
    mem.maxY = size && typeof size === "object"
      ? num(size.maxY, mem.minY + h)
      : (centered ? h * 0.5 : h);

    mem.baseX = bx;
    mem.baseY = by;
    mem.capacity = Math.max(
      1,
      Math.floor(num(mission.capacity, num(obs.capacity, 5)))
    );
    mem.seconds = num(mission.seconds, 1200);

    mem.hints = [];
    for (var hi = 0; hi < sourceHints.length; hi++) {
      var sh = sourceHints[hi] || {};
      mem.hints.push({
        x: clamp(num(sh.x, bx), mem.minX + 4, mem.maxX - 4),
        y: clamp(num(sh.y, by), mem.minY + 4, mem.maxY - 4),
        value: Math.max(0.1, num(sh.estimate, num(sh.value, 1))),
        status: 0
      });
    }

    var x0 = num(obs.x, bx);
    var y0 = num(obs.y, by);
    var h0 = num(obs.heading, 0) * PI / 180;

    mem.poseX = x0;
    mem.poseY = y0;
    mem.yaw = h0;
    mem.bias = 0;
    mem.lastRawX = x0;
    mem.lastRawY = y0;
    mem.lastRawH = h0;

    mem.gpsFrozen = false;
    mem.gpsWinX = x0;
    mem.gpsWinY = y0;
    mem.gpsWinPath = 0;
    mem.gpsWinTurn = 0;
    mem.gpsSameCount = 0;

    mem.calX = x0;
    mem.calY = y0;
    mem.calPath = 0;
    mem.calTurn = 0;
    mem.calSin = 0;
    mem.calCos = 0;

    mem.energyRate = 0.0014;
    mem.energyAcc = 0;
    mem.energyDist = 0;
    mem.prevBattery = num(obs.battery, 1);
    mem.prevSolar = num(obs.solar, 0);
    mem.batteryMax = num(obs.battery, 1);

    mem.gainL = 3.0;
    mem.gainR = 3.0;
    mem.deadL = 0.12;
    mem.deadR = 0.12;
    mem.iL = 0;
    mem.iR = 0;
    mem.lastCmdL = 0;
    mem.lastCmdR = 0;
    mem.lastTargetL = 0;
    mem.lastTargetR = 0;
    mem.lastDrill = false;

    mem.rays = [];
    mem.lastRays = [];
    mem.rayRepeat = [];
    mem.rayBad = [];
    mem.rayMoved = 0;
    for (var ri = 0; ri < 9; ri++) {
      mem.rays[ri] = 15;
      mem.lastRays[ri] = -1;
      mem.rayRepeat[ri] = 0;
      mem.rayBad[ri] = false;
    }

    mem.mode = "SELECT";
    mem.activeHint = -1;
    mem.scanLanes = 3;
    mem.scanSource = "";
    mem.scanHintIndex = -1;
    mem.scanSignalIndex = -1;
    mem.scanPoints = [];
    mem.scanIndex = 0;
    mem.scanCenterX = x0;
    mem.scanCenterY = y0;

    mem.siteActive = false;
    mem.siteDrillStarted = false;
    mem.siteResume = null;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.siteValue = 0;
    mem.siteAssoc = -1;
    mem.siteLastDistance = 8;
    mem.siteMiss = 0;
    mem.sampleStartCarried = 0;
    mem.lastSampleX = null;
    mem.lastSampleY = null;
    mem.lastSampleTick = -10000;

    mem.scienceBase = Math.max(0, num(obs.science, 0));
    mem.signalCandidates = [];
    mem.bumpedPrev = false;
    mem.bumpUntil = 0;
    mem.bumpSide = 1;
    mem.bumpCount = 0;
    mem.headingRepeat = 0;
    mem.compassBad = 0;

    mem.navKey = null;
    mem.navBest = 0;
    mem.navProgressTick = 0;
    mem.navDetour = null;
    mem.navDetourCount = 0;

    mem.explorePts = [];
    var seenExplore = {};
    for (var ey = mem.minY + 25; ey <= mem.maxY - 25; ey += 55) {
      for (var ex = mem.minX + 25; ex <= mem.maxX - 25; ex += 55) {
        var gx = clamp(ex, mem.minX + 5, mem.maxX - 5);
        var gy = clamp(ey, mem.minY + 5, mem.maxY - 5);
        var ek = Math.round(gx) + ":" + Math.round(gy);
        if (!seenExplore[ek]) {
          seenExplore[ek] = true;
          mem.explorePts.push({ x: gx, y: gy, done: false });
        }
      }
    }

    mem.exploreTarget = -1;
    mem.returnFrom = "SELECT";
    mem.tick = 0;
    mem.initialized = true;
  }

  mem.tick = (mem.tick || 0) + 1;
  var tick = mem.tick;

  function clampPoint(x, y, margin) {
    var m = num(margin, 4);
    return {
      x: clamp(x, mem.minX + m, mem.maxX - m),
      y: clamp(y, mem.minY + m, mem.maxY - m)
    };
  }

  var rawX = num(obs.x, mem.lastRawX);
  var rawY = num(obs.y, mem.lastRawY);
  var rawH = wrap(num(obs.heading, mem.lastRawH * 180 / PI) * PI / 180);
  var wheelL = num(obs.wheelLeft, 0);
  var wheelR = num(obs.wheelRight, 0);
  var wheelV = (wheelL + wheelR) * 0.5;
  var dpsi = clamp((wheelR - wheelL) / 0.6 * DT, -0.6, 0.6);
  var battery = Math.max(0, num(obs.battery, 0));
  var solar = Math.max(0, num(obs.solar, 0));
  var carried = Math.max(0, Math.floor(num(obs.carried, 0)));
  var capacity = Math.max(1, Math.floor(num(obs.capacity, mem.capacity)));
  var timeLeft = num(obs.timeLeft, mem.seconds - tick * DT);
  var science = Math.max(0, num(obs.science, 0));
  var drilling = Math.max(0, num(obs.drilling, 0));
  var docked = !!obs.docked;
  var bumped = !!obs.bumped;

  if (battery > mem.batteryMax) mem.batteryMax = battery;

  var rawDeltaH = wrap(rawH - mem.lastRawH);
  if (Math.abs(rawDeltaH) < 0.001 && Math.abs(dpsi) > 0.04) {
    mem.headingRepeat = (mem.headingRepeat || 0) + 1;
  } else {
    mem.headingRepeat = 0;
  }

  var compassJump =
    (Math.abs(rawDeltaH) > 0.4 &&
     Math.abs(wrap(rawDeltaH - dpsi)) > 0.55) ||
    mem.headingRepeat > 18;

  if (compassJump) {
    mem.compassBad = 40;
  } else if (mem.compassBad > 0) {
    mem.compassBad--;
  }

  mem.yaw = wrap(mem.yaw + dpsi);
  if (!compassJump && mem.compassBad <= 0) {
    var compassErr = wrap(rawH - mem.bias - mem.yaw);
    if (Math.abs(compassErr) < 1.2) {
      mem.yaw = wrap(mem.yaw + clamp(0.055 * compassErr, -0.035, 0.035));
    }
  }

  var rawStep = dist(rawX, rawY, mem.lastRawX, mem.lastRawY);
  if (rawStep < 0.003) mem.gpsSameCount = (mem.gpsSameCount || 0) + 1;
  else mem.gpsSameCount = 0;

  mem.gpsWinPath += Math.abs(wheelV) * DT;
  mem.gpsWinTurn += Math.abs(dpsi);

  if (tick % 50 === 0) {
    var gpsWindowMove = dist(rawX, rawY, mem.gpsWinX, mem.gpsWinY);
