  var moveV = (Math.abs(wheelV) < 0.018 || bumped) ? 0 : wheelV;
  var midYaw = wrap(mem.yaw - dpsi * 0.5);
  var predX = mem.poseX + moveV * DT * Math.cos(midYaw);
  var predY = mem.poseY + moveV * DT * Math.sin(midYaw);

  if (!mem.gpsFrozen) {
    var innovation = dist(predX, predY, rawX, rawY);
    if (innovation < 30) {
      var gpsAlpha = Math.abs(wheelV) > 0.08 ? 0.30 : 0.38;
      if (innovation > 5) gpsAlpha *= 0.40;
      predX += clamp((rawX - predX) * gpsAlpha, -0.65, 0.65);
      predY += clamp((rawY - predY) * gpsAlpha, -0.65, 0.65);
    }
  }

  mem.poseX = predX;
  mem.poseY = predY;

  if (!mem.gpsFrozen &&
      !compassJump &&
      mem.compassBad <= 0 &&
      wheelV > 0.12 &&
      Math.abs(dpsi) < 0.045) {
    if (mem.calPath < 0.001) {
      mem.calX = rawX;
      mem.calY = rawY;
      mem.calTurn = 0;
      mem.calSin = 0;
      mem.calCos = 0;
