  mem.prevSolar = solar;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;
  mem.lastRawH = rawH;

  var sourceRays = Array.isArray(obs.rays) ? obs.rays : [];
  mem.rayMoved += Math.abs(wheelV) * DT + 0.12 * Math.abs(dpsi);
  var badRayCount = 0;

  for (var r = 0; r < 9; r++) {
    var rv = clamp(num(sourceRays[r], 15), 0, 15);
    mem.rays[r] = rv;

    if (mem.lastRays[r] >= 0 &&
        Math.abs(rv - mem.lastRays[r]) < 0.001) {
      mem.rayRepeat[r] = (mem.rayRepeat[r] || 0) + 1;
    } else {
      mem.rayRepeat[r] = 0;
      mem.rayBad[r] = false;
    }

    if (mem.rayRepeat[r] > 100 &&
        rv < 14.8 &&
        mem.rayMoved > 3) {
      mem.rayBad[r] = true;
