    mem.lastRays[r] = rv;
  }
  if (tick % 50 === 0) mem.rayMoved = 0;

  function rayAt(angleDeg) {
    var a = clamp(angleDeg, -80, 80);
    var p = (a + 80) / 20;
    var i = Math.floor(p);
    if (i >= 8) i = 8;
    var j = Math.min(8, i + 1);
    var f = p - i;
    var v1 = mem.rayBad[i] ? 15 : mem.rays[i];
    var v2 = mem.rayBad[j] ? 15 : mem.rays[j];
    if (i === j) return v1;
    return v1 * (1 - f) + v2 * f;
  }

  function chooseSide() {
    var leftOpen = rayAt(20) + rayAt(40) + rayAt(60);
    var rightOpen = rayAt(-20) + rayAt(-40) + rayAt(-60);
    if (Math.abs(leftOpen - rightOpen) < 0.2) {
      return (tick % 2) ? 1 : -1;
    }
    return leftOpen > rightOpen ? 1 : -1;
  }

  if (bumped && !mem.bumpedPrev) {
    mem.bumpSide = chooseSide();
    mem.bumpUntil = tick + 8;
    mem.bumpCount = (mem.bumpCount || 0) + 1;
    mem.navProgressTick = tick - 100;
    mem.navDetour = null;
  }
  mem.bumpedPrev = bumped;

  var scienceBase = Math.max(0, num(mem.scienceBase, science));
  if (science < scienceBase * 1.35 + 0.06) {
    scienceBase += 0.008 * (science - scienceBase);
  }
  mem.scienceBase = Math.max(0, scienceBase);
  var signalThreshold = Math.max(0.20, mem.scienceBase * 1.55 + 0.03);

  if (science > signalThreshold) {
    if (!Array.isArray(mem.signalCandidates)) mem.signalCandidates = [];
    var nearestCand = -1;
    var nearestCandD = 1e30;

    for (var sc = 0; sc < mem.signalCandidates.length; sc++) {
      var oldCand = mem.signalCandidates[sc];
      var cd = dist(mem.poseX, mem.poseY, oldCand.x, oldCand.y);
      if (cd < nearestCandD) {
        nearestCandD = cd;
        nearestCand = sc;
      }
    }

    if (nearestCand >= 0 &&
        nearestCandD < 22 &&
        !mem.signalCandidates[nearestCand].done) {
      var cnd = mem.signalCandidates[nearestCand];
      if (science > cnd.value) {
        cnd.value = science;
        cnd.x = mem.poseX;
        cnd.y = mem.poseY;
        cnd.tick = tick;
      }
    } else if (nearestCand < 0 ||
               nearestCandD >= 22 ||
               !mem.signalCandidates[nearestCand].done) {
      var newCand = {
        x: mem.poseX,
        y: mem.poseY,
        value: science,
        tick: tick,
        done: false
      };

      if (mem.signalCandidates.length < 14) {
        mem.signalCandidates.push(newCand);
      } else {
        var weakest = 0;
        for (var wi = 1; wi < mem.signalCandidates.length; wi++) {
          if (mem.signalCandidates[wi].value <
              mem.signalCandidates[weakest].value) weakest = wi;
        }
        if (science > mem.signalCandidates[weakest].value) {
          mem.signalCandidates.splice(weakest, 1);
          mem.signalCandidates.push(newCand);
        }
      }
    }
  }

  function output(left, right, drill, targetL, targetR) {
    left = clamp(left, -1, 1);
    right = clamp(right, -1, 1);
    mem.lastCmdL = left;
    mem.lastCmdR = right;
    mem.lastTargetL = num(targetL, 0);
    mem.lastTargetR = num(targetR, 0);
    mem.lastDrill = !!drill;
    return { left: left, right: right, drill: !!drill };
  }

  function motorCommand(target, actual, side, pitchTerm, holding) {
    var gain = side === 0 ? mem.gainL : mem.gainR;
    var dead = side === 0 ? mem.deadL : mem.deadR;
    var integ = side === 0 ? mem.iL : mem.iR;
    var lastCmd = side === 0 ? mem.lastCmdL : mem.lastCmdR;
    var lastTarget = side === 0 ? mem.lastTargetL : mem.lastTargetR;

    if (Math.abs(lastTarget) > 0.10 &&
        lastTarget * actual > 0.015 &&
        Math.abs(lastTarget - target) < 0.07 &&
        Math.abs(lastCmd) > dead + 0.035) {
      var den = Math.max(0.04, Math.abs(lastCmd) - dead);
      var est = Math.abs(actual) / den;
      if (est > 0.45 && est < 9) {
        var ag = est > gain ? 0.035 : 0.065;
        gain = clamp(gain * (1 - ag) + est * ag, 0.65, 8);
        if (side === 0) mem.gainL = gain;
        else mem.gainR = gain;
      }
    }

    var err = target - actual;
    var u;

    if (Math.abs(target) < 0.025) {
      integ *= 0.55;
      if (Math.abs(actual) > 0.04) {
        var brake = dead + Math.min(0.30, (holding ? 0.85 : 0.65) *
                                    Math.abs(actual));
        u = (actual > 0 ? -brake : brake) + pitchTerm;
      } else {
        u = pitchTerm;
      }
    } else {
      if (lastTarget * target < -0.01) integ *= 0.35;
      integ = clamp(integ + err * 0.12 * DT, -0.14, 0.14);
      var st = target > 0 ? 1 : -1;
      var ff = st * (dead + Math.abs(target) / Math.max(0.7, gain));
      u = ff + 0.27 * err + integ + pitchTerm;
    }

    if (side === 0) mem.iL = integ;
    else mem.iR = integ;

    u = clamp(u, -0.58, 0.58);
    var slew = 0.13;
    u = clamp(u, lastCmd - slew, lastCmd + slew);
    return clamp(u, -0.58, 0.58);
  }

  function moveOutput(v, omega, drill, holding) {
    var targetL = clamp(v - 0.3 * omega, -0.48, 0.48);
    var targetR = clamp(v + 0.3 * omega, -0.48, 0.48);
    var pitchRad = num(obs.pitch, 0) * PI / 180;
    var pitchTerm = clamp(0.78 * Math.sin(pitchRad), -0.20, 0.20);
    var left = motorCommand(targetL, wheelL, 0, pitchTerm, !!holding);
    var right = motorCommand(targetR, wheelR, 1, pitchTerm, !!holding);
    return output(left, right, drill, targetL, targetR);
  }

  function idleOutput() {
    return moveOutput(0, 0, false, false);
  }

  function driveRelative(targetRel, d, stop, cruise) {
    if (tick <= num(mem.bumpUntil, 0)) {
      return moveOutput(-0.15, num(mem.bumpSide, 1) * 0.56, false, false);
    }

    if (d <= stop) return idleOutput();

    var rel = wrap(targetRel);
    if (Math.abs(rel) > 1.9) {
      return moveOutput(0, clamp(1.15 * rel, -0.78, 0.78), false, false);
    }

    var relDeg = rel * 180 / PI;
    var directRay = Math.abs(relDeg) <= 80 ? rayAt(relDeg) : 15;
    var aim = rel;
    var clearance = directRay;

    if (Math.abs(relDeg) < 78 && directRay < 3.1) {
      var bestScore = -1e30;
      var bestAngle = relDeg;

      for (var ca = -80; ca <= 80; ca += 20) {
        var cr = rayAt(ca);
        var diff = wrap((ca - relDeg) * PI / 180);
        var score = 1.9 * Math.cos(diff) +
                    0.22 * Math.min(cr, 8) -
                    0.42 * Math.max(0, 1.8 - cr);

        var worldA = mem.yaw + ca * PI / 180;
        var testX = mem.poseX + 7 * Math.cos(worldA);
        var testY = mem.poseY + 7 * Math.sin(worldA);
        if (testX < mem.minX + 3 || testX > mem.maxX - 3 ||
            testY < mem.minY + 3 || testY > mem.maxY - 3) {
          score -= 1.4;
        }
        if (cr < 0.8) score -= 2.0;
        else if (cr < 1.3) score -= 0.7;

        if (score > bestScore) {
          bestScore = score;
          bestAngle = ca;
        }
      }

      aim = bestAngle * PI / 180;
      clearance = rayAt(bestAngle);
    }

    var cap = clamp(cruise, 0.08, 0.36);
    if (badRayCount >= 6) cap = Math.min(cap, 0.26);

    var allBlind = true;
    for (var bi = 0; bi < 9; bi++) {
      if (!mem.rayBad[bi] && mem.rays[bi] < 14.8) {
        allBlind = false;
        break;
      }
    }
    if (allBlind) cap = Math.min(cap, 0.27);

    if (clearance < 0.85) cap = 0;
    else if (clearance < 1.3) cap = Math.min(cap, 0.09);
    else if (clearance < 1.9) cap = Math.min(cap, 0.16);
    else if (clearance < 2.7) cap = Math.min(cap, 0.23);
    else if (clearance < 3.7) cap = Math.min(cap, 0.30);

    var front = rayAt(0);
    if (front < 0.85 && Math.abs(aim) < 0.38) cap = 0;
    else if (front < 1.25 && Math.abs(aim) < 0.28) {
      cap = Math.min(cap, 0.10);
    }

    var remaining = Math.max(0, d - stop);
    var v = Math.min(cap, Math.sqrt(0.46 * remaining));
    var absAim = Math.abs(aim);

    if (absAim > 1.35) {
      v = 0;
    } else {
      v *= Math.max(0, Math.cos(aim));
      if (absAim > 0.95) v = Math.min(v, 0.11);
      else if (absAim > 0.65) v = Math.min(v, 0.23);
    }

    var omega = clamp(1.30 * aim, -0.78, 0.78);
    return moveOutput(v, omega, false, false);
  }

  function navTo(x, y, stop, key, cruise) {
    key = String(key);
    var margin = key === "home" ? 1.5 : 4;
    var p = clampPoint(x, y, margin);
    x = p.x;
    y = p.y;

    var mainDist = dist(mem.poseX, mem.poseY, x, y);

    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = mainDist;
      mem.navProgressTick = tick;
      mem.navDetour = null;
      mem.navDetourCount = 0;
    } else if (mainDist < num(mem.navBest, mainDist) - 0.35) {
      if (mainDist < num(mem.navBest, mainDist) - 1.5) {
        mem.navDetourCount = 0;
      }
      mem.navBest = mainDist;
      mem.navProgressTick = tick;
    }

    if (mem.navDetour && mem.navDetour.key === key) {
      var detD = dist(mem.poseX, mem.poseY,
                      mem.navDetour.x, mem.navDetour.y);
      if (detD < 1.8 || tick > mem.navDetour.until) {
        mem.navDetour = null;
        mem.navProgressTick = tick;
        mem.navBest = mainDist;
      } else if (detD < num(mem.navDetour.best, detD) - 0.35) {
        mem.navDetour.best = detD;
        mem.navProgressTick = tick;
      }
    }

    if (!mem.navDetour &&
        mainDist > stop + 3.5 &&
        tick - num(mem.navProgressTick, tick) > 110 &&
        num(mem.navDetourCount, 0) < 5) {
      var side = chooseSide();
      if (mem.navDetourCount % 2 === 1) side = -side;
      var goalAngle = Math.atan2(y - mem.poseY, x - mem.poseX);
      var detAngle = goalAngle + side * 0.95;
      var dp = clampPoint(
        mem.poseX + 6 * Math.cos(detAngle),
        mem.poseY + 6 * Math.sin(detAngle),
        5
      );

      if (dist(mem.poseX, mem.poseY, dp.x, dp.y) < 2) {
        detAngle = goalAngle - side * 1.0;
        dp = clampPoint(
          mem.poseX + 6 * Math.cos(detAngle),
          mem.poseY + 6 * Math.sin(detAngle),
          5
        );
        side = -side;
      }

      if (dist(mem.poseX, mem.poseY, dp.x, dp.y) > 2) {
        mem.navDetour = {
          x: dp.x,
          y: dp.y,
          key: key,
          until: tick + 130,
          best: dist(mem.poseX, mem.poseY, dp.x, dp.y)
        };
        mem.navDetourCount++;
      }
      mem.navProgressTick = tick;
    }

    var tx = x;
    var ty = y;
    var localStop = stop;
    var localCruise = cruise;

    if (mem.navDetour && mem.navDetour.key === key) {
      tx = mem.navDetour.x;
      ty = mem.navDetour.y;
      localStop = 1.8;
      localCruise = Math.min(cruise, 0.30);
    }

    var dx = tx - mem.poseX;
    var dy = ty - mem.poseY;
    var d = Math.sqrt(dx * dx + dy * dy);
    var rel = wrap(Math.atan2(dy, dx) - mem.yaw);
    return driveRelative(rel, d, localStop, localCruise);
  }

  function baseDistance() {
    return dist(mem.poseX, mem.poseY, mem.baseX, mem.baseY);
  }

  function homeDistance() {
    var b = obs.beacon && typeof obs.beacon === "object" ? obs.beacon : null;
    if (b) return Math.max(0, num(b.distance, baseDistance()));
    return baseDistance();
  }

  function energyNeed(distanceMeters, samples) {
    var d = Math.max(0, distanceMeters);
    var n = Math.max(0, samples);
    var load = 1 + 0.18 * n;
    return 0.075 + d * mem.energyRate * load * 1.35 + 0.022 * n;
  }

  function patternLength(lanes, source) {
    if (source === "signal") return lanes >= 3 ? 90 : 60;
    return lanes >= 3 ? 138 : 84;
  }

  function patternPoints(cx, cy, source, lanes) {
    var rows;
    var halfX;

    if (source === "signal") {
      if (lanes >= 3) {
        rows = [-9, 0, 9];
        halfX = 12;
      } else {
        rows = [-8, 8];
        halfX = 11;
      }
    } else if (lanes >= 3) {
      rows = [-15, 0, 15];
      halfX = 18;
    } else {
      rows = [-10, 10];
      halfX = 16;
    }

    if (mem.poseY > cy + 5) rows.reverse();

    var points = [];
    var startLeft = mem.poseX <= cx;
    var seen = {};

    for (var i = 0; i < rows.length; i++) {
      var leftFirst = (i % 2 === 0) ? startLeft : !startLeft;
      var x1 = cx + (leftFirst ? -halfX : halfX);
      var x2 = cx + (leftFirst ? halfX : -halfX);
      var y = cy + rows[i];
      var p1 = clampPoint(x1, y, 4);
      var p2 = clampPoint(x2, y, 4);
      var k1 = Math.round(p1.x * 10) + ":" + Math.round(p1.y * 10);
      var k2 = Math.round(p2.x * 10) + ":" + Math.round(p2.y * 10);

      if (!seen[k1]) {
        seen[k1] = true;
        points.push(p1);
      }
      if (!seen[k2]) {
        seen[k2] = true;
        points.push(p2);
      }
    }
    return points;
  }

  function currentTaskRoute() {
    if (mem.mode === "TRAVEL") {
      var ti = Math.floor(num(mem.activeHint, -1));
      if (ti >= 0 && ti < mem.hints.length) {
        var hnt = mem.hints[ti];
        return dist(mem.poseX, mem.poseY, hnt.x, hnt.y) +
               patternLength(mem.scanLanes || 3, "hint") +
               dist(hnt.x, hnt.y, mem.baseX, mem.baseY) + 14;
      }
    }

    if (mem.mode === "SCAN" &&
        Array.isArray(mem.scanPoints) &&
        mem.scanPoints.length > 0) {
      var total = 0;
      var px = mem.poseX;
      var py = mem.poseY;
      for (var si = mem.scanIndex; si < mem.scanPoints.length; si++) {
        total += dist(px, py,
                      mem.scanPoints[si].x,
                      mem.scanPoints[si].y);
        px = mem.scanPoints[si].x;
        py = mem.scanPoints[si].y;
      }
      return total + dist(px, py, mem.baseX, mem.baseY) + 12;
    }

    if (mem.mode === "EXPLORE" &&
        mem.exploreTarget >= 0 &&
        mem.exploreTarget < mem.explorePts.length) {
      var ep = mem.explorePts[mem.exploreTarget];
      return dist(mem.poseX, mem.poseY, ep.x, ep.y) +
             dist(ep.x, ep.y, mem.baseX, mem.baseY) + 12;
    }

    if (mem.mode === "SITE" && mem.siteActive) {
      return homeDistance() + 10;
    }

    return 0;
  }

  function canSampleHere() {
    if (carried >= capacity) return false;
    var home = homeDistance();
    var need = energyNeed(home * 1.30 + 12, carried + 1) + 0.045;
    return battery > need &&
           timeLeft > home / 0.26 + 28;
  }

  function shouldReturn() {
    if (docked || mem.mode === "RETURN") return false;
    if (mem.siteActive && mem.siteDrillStarted) return false;
    if (carried >= capacity && carried > 0) return true;

    var home = homeDistance();
    var homeNeed = energyNeed(home * 1.30 + 10, carried) + 0.075;
    if (home > 2.4 && battery < homeNeed) return true;

    if (carried > 0 &&
        timeLeft < home / 0.26 + 34 + 6 * carried) return true;

    var projected = currentTaskRoute();
    if (projected > 0 &&
        battery < energyNeed(projected, carried + 1) + 0.07) {
      return true;
    }

    return false;
  }

  function siteEstimate(s) {
    var d = Math.max(0, num(s.distance, 0));
    var b = num(s.bearing, 0) * PI / 180;
    var a = mem.yaw + b;
    return {
      x: mem.poseX + d * Math.cos(a),
      y: mem.poseY + d * Math.sin(a)
    };
  }

  function updateSiteGoal(s) {
    if (!s) return;
    var p = siteEstimate(s);

    if (mem.siteGX === null ||
        mem.siteGY === null ||
        !isFinite(mem.siteGX) ||
        !isFinite(mem.siteGY)) {
      mem.siteGX = p.x;
      mem.siteGY = p.y;
    } else {
      mem.siteGX = 0.62 * mem.siteGX + 0.38 * p.x;
      mem.siteGY = 0.62 * mem.siteGY + 0.38 * p.y;
    }

    mem.siteValue = num(s.value, mem.siteValue || 0);
  }

  function activateSite(s) {
    var resume = mem.mode || "SELECT";
    if (resume === "RETURN" || resume === "SITE") resume = "SELECT";

    mem.siteResume = resume;
    mem.siteActive = true;
    mem.siteDrillStarted = drilling > 0.01;
    mem.siteMiss = 0;
    mem.siteLastDistance = Math.max(0, num(s.distance, 8));
    mem.sampleStartCarried = carried;
    mem.siteAssoc = -1;
    updateSiteGoal(s);

    var ai = Math.floor(num(mem.activeHint, -1));
    if (ai >= 0 &&
        ai < mem.hints.length &&
        mem.hints[ai].status !== 1 &&
        dist(mem.poseX, mem.poseY,
             mem.hints[ai].x, mem.hints[ai].y) < 36) {
      mem.siteAssoc = ai;
    } else {
      var best = -1;
      var bestD = 1e30;
      for (var i = 0; i < mem.hints.length; i++) {
        if (mem.hints[i].status === 1) continue;
        var hd = dist(mem.poseX, mem.poseY,
                      mem.hints[i].x, mem.hints[i].y);
        if (hd < bestD) {
          bestD = hd;
          best = i;
        }
      }
      if (best >= 0 && bestD < 31) mem.siteAssoc = best;
    }

    mem.mode = "SITE";
    mem.navKey = null;
  }

  function finishSite() {
    var assoc = Math.floor(num(mem.siteAssoc, -1));
    var active = Math.floor(num(mem.activeHint, -1));
    var resume = mem.siteResume || "SELECT";
    var wasActiveHint = assoc >= 0 && assoc === active;
    var sx = mem.poseX;
    var sy = mem.poseY;

    if (assoc >= 0 && assoc < mem.hints.length) {
      mem.hints[assoc].status = 1;
      if (mem.siteValue > 0) mem.hints[assoc].value = mem.siteValue;
    }

    mem.lastSampleX = sx;
    mem.lastSampleY = sy;
    mem.lastSampleTick = tick;

    for (var ci = 0; ci < mem.signalCandidates.length; ci++) {
      if (dist(sx, sy,
               mem.signalCandidates[ci].x,
               mem.signalCandidates[ci].y) < 24) {
        mem.signalCandidates[ci].done = true;
      }
    }

    if (resume === "RETURN" || resume === "SITE") resume = "SELECT";
    if (wasActiveHint) {
      mem.mode = "SELECT";
      mem.activeHint = -1;
      mem.scanPoints = [];
      mem.scanIndex = 0;
      mem.scanSource = "";
      mem.navKey = null;
    } else {
      mem.mode = resume;
    }

    mem.siteActive = false;
    mem.siteDrillStarted = false;
    mem.siteResume = null;
    mem.siteAssoc = -1;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.siteMiss = 0;
    mem.lastDrill = false;
    mem.navKey = null;
  }

  function siteControl() {
    var s = obs.site && typeof obs.site === "object" ? obs.site : null;
    var d;
    var bearing;

    if (s) {
      updateSiteGoal(s);
      d = Math.max(0, num(s.distance, 8));
      bearing = num(s.bearing, 0);
      mem.siteLastDistance = d;
      mem.siteMiss = 0;
    } else {
      mem.siteMiss = num(mem.siteMiss, 0) + 1;
      if (mem.siteGX !== null && mem.siteGY !== null) {
        var dx = mem.siteGX - mem.poseX;
        var dy = mem.siteGY - mem.poseY;
        d = Math.sqrt(dx * dx + dy * dy);
        bearing = wrap(Math.atan2(dy, dx) - mem.yaw) * 180 / PI;
      } else {
        d = num(mem.siteLastDistance, 8);
        bearing = 0;
      }

      if (mem.siteMiss > 140 &&
          !mem.siteDrillStarted &&
          drilling <= 0.01) {
        mem.siteActive = false;
        mem.mode = mem.siteResume || "SELECT";
        if (mem.mode === "SITE" || mem.mode === "RETURN") {
          mem.mode = "SELECT";
        }
        mem.siteResume = null;
        mem.siteAssoc = -1;
        mem.siteGX = null;
        mem.siteGY = null;
        mem.navKey = null;
        return idleOutput();
      }
    }

    if (drilling > 0.01 || mem.lastDrill) {
      mem.siteDrillStarted = true;
    }

    if (mem.siteDrillStarted) {
      return moveOutput(0, 0, true, true);
    }

    if (d > 1.42) {
      return driveRelative(bearing * PI / 180, d, 1.12, 0.22);
    }

    var still = Math.max(Math.abs(wheelL), Math.abs(wheelR)) < 0.12;
    if (d <= 1.48 && still) {
      mem.siteDrillStarted = true;
      return moveOutput(0, 0, true, true);
    }

    return moveOutput(0, 0, false, true);
  }

  function beginScan(cx, cy, source, hintIndex, signalIndex, lanes) {
    var p = clampPoint(cx, cy, 4);
    mem.scanCenterX = p.x;
    mem.scanCenterY = p.y;
    mem.scanSource = source;
    mem.scanHintIndex = hintIndex;
    mem.scanSignalIndex = signalIndex;
    mem.scanLanes = lanes;
    mem.scanPoints = patternPoints(p.x, p.y, source, lanes);
    mem.scanIndex = 0;
    mem.activeHint = source === "hint" ? hintIndex : -1;
    mem.mode = "SCAN";
    mem.navKey = null;
    mem.navDetour = null;
  }

  function finishScan() {
    if (mem.scanSource === "hint") {
      var hi = Math.floor(num(mem.scanHintIndex, -1));
      if (hi >= 0 && hi < mem.hints.length &&
          mem.hints[hi].status === 0) {
        mem.hints[hi].status = 2;
      }
    } else {
      var si = Math.floor(num(mem.scanSignalIndex, -1));
      if (si >= 0 && si < mem.signalCandidates.length) {
        mem.signalCandidates[si].done = true;
      }
    }

    mem.mode = "SELECT";
    mem.activeHint = -1;
    mem.scanPoints = [];
    mem.scanIndex = 0;
    mem.scanSource = "";
    mem.scanHintIndex = -1;
    mem.scanSignalIndex = -1;
    mem.navKey = null;
    mem.navDetour = null;
  }

  function chooseHint() {
    if (carried >= capacity) return null;

    var best = null;
    var bestScore = -1;

    for (var i = 0; i < mem.hints.length; i++) {
      var hh = mem.hints[i];
      if (!hh || hh.status !== 0) continue;

      var outDist = dist(mem.poseX, mem.poseY, hh.x, hh.y);
      var homeDist = dist(mem.baseX, mem.baseY, hh.x, hh.y);
      var chosenLanes = 0;
      var chosenRoute = 0;

      for (var lanes = 3; lanes >= 2; lanes--) {
        var searchLen = patternLength(lanes, "hint");
        var route = outDist + searchLen + homeDist + 16;
        var need = energyNeed(route, carried + 1) + 0.07;
        var timeNeed = route / 0.31 + 32;

        if (battery > need && timeLeft > timeNeed) {
          chosenLanes = lanes;
          chosenRoute = route;
          break;
        }
      }

      if (chosenLanes === 0) continue;

      var score = hh.value /
        (42 + 0.66 * outDist + 0.55 * patternLength(chosenLanes, "hint") +
         0.88 * homeDist);

      if (score > bestScore) {
        bestScore = score;
        best = {
          index: i,
          lanes: chosenLanes,
          route: chosenRoute,
          score: score
        };
      }
    }

    return best;
  }

  function chooseSignal() {
    if (carried >= capacity ||
        !Array.isArray(mem.signalCandidates)) return null;

    var best = null;
    var bestScore = -1e30;

    for (var i = 0; i < mem.signalCandidates.length; i++) {
      var c = mem.signalCandidates[i];
      if (!c || c.done || c.value < signalThreshold) continue;
      if (tick - num(c.tick, 0) > 5500) continue;

      var nearHint = false;
      for (var hi = 0; hi < mem.hints.length; hi++) {
        if (mem.hints[hi].status === 0 &&
            dist(c.x, c.y, mem.hints[hi].x, mem.hints[hi].y) < 28) {
          nearHint = true;
          break;
        }
      }
      if (nearHint) continue;

      if (mem.lastSampleX !== null &&
          dist(c.x, c.y, mem.lastSampleX, mem.lastSampleY) < 18) {
        continue;
      }

      var outDist = dist(mem.poseX, mem.poseY, c.x, c.y);
      var homeDist = dist(mem.baseX, mem.baseY, c.x, c.y);
      var searchLen = patternLength(3, "signal");
      var route = outDist + searchLen + homeDist + 14;

      if (battery < energyNeed(route, carried + 1) + 0.07) continue;
      if (timeLeft < route / 0.31 + 30) continue;

      var score = c.value /
        (36 + 0.76 * outDist + 0.60 * homeDist + 0.42 * searchLen);

      if (score > bestScore) {
        bestScore = score;
        best = { index: i, score: score };
      }
    }

    return best;
  }

  function chooseExploreTarget() {
    var best = -1;
    var bestD = 1e30;

    for (var i = 0; i < mem.explorePts.length; i++) {
      var p = mem.explorePts[i];
      if (p.done) continue;
      var d = dist(mem.poseX, mem.poseY, p.x, p.y);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }

    return best;
  }

  function enterReturn() {
    if (mem.mode === "RETURN") return;

    var from = mem.mode || "SELECT";
    if (from === "SITE") from = mem.siteResume || "SELECT";
    if (from === "RETURN") from = "SELECT";

    mem.returnFrom = from;
    mem.mode = "RETURN";
    mem.siteActive = false;
    mem.siteDrillStarted = false;
    mem.siteResume = null;
    mem.siteAssoc = -1;
    mem.siteGX = null;
    mem.siteGY = null;
    mem.navKey = null;
    mem.navDetour = null;
  }

  function returnControl() {
    if (docked) return idleOutput();

    var b = obs.beacon && typeof obs.beacon === "object" ? obs.beacon : null;
    if (b) {
      var bd = Math.max(0, num(b.distance, 20));
      if (bd <= 1.35) return idleOutput();
      return driveRelative(num(b.bearing, 0) * PI / 180,
                           bd, 1.15, 0.32);
    }

    var d = baseDistance();
    if (d <= 1.25) return idleOutput();
    return navTo(mem.baseX, mem.baseY, 1.20, "home", 0.32);
  }

  function abandonTask() {
    if (mem.mode === "TRAVEL") {
      var ti = Math.floor(num(mem.activeHint, -1));
      if (ti >= 0 && ti < mem.hints.length &&
          mem.hints[ti].status === 0) {
        mem.hints[ti].status = 2;
      }
    } else if (mem.mode === "SCAN") {
      if (mem.scanSource === "hint") {
        var hi = Math.floor(num(mem.scanHintIndex, -1));
        if (hi >= 0 && hi < mem.hints.length &&
            mem.hints[hi].status === 0) {
          mem.hints[hi].status = 2;
        }
      } else {
        var si = Math.floor(num(mem.scanSignalIndex, -1));
        if (si >= 0 && si < mem.signalCandidates.length) {
          mem.signalCandidates[si].done = true;
        }
      }
    } else if (mem.mode === "EXPLORE" &&
               mem.exploreTarget >= 0 &&
               mem.exploreTarget < mem.explorePts.length) {
      mem.explorePts[mem.exploreTarget].done = true;
      mem.exploreTarget = -1;
    }

    mem.mode = "SELECT";
    mem.activeHint = -1;
    mem.scanPoints = [];
    mem.scanIndex = 0;
    mem.scanSource = "";
    mem.navKey = null;
    mem.navDetour = null;
  }

  function chargeTarget() {
    return Math.max(0.65, Math.min(mem.batteryMax * 0.88,
                                   mem.batteryMax - 0.025));
  }

  var siteObs = obs.site && typeof obs.site === "object" ? obs.site : null;
  var justFinishedSite = false;

  if (mem.siteActive &&
      carried > num(mem.sampleStartCarried, carried)) {
    finishSite();
    justFinishedSite = true;
  }

  if (mem.mode === "RETURN") {
    if (!docked) return returnControl();
    if (carried > 0) return idleOutput();

    if (battery < chargeTarget() && timeLeft > 55) {
      return idleOutput();
    }

    mem.mode = mem.returnFrom || "SELECT";
    if (mem.mode === "RETURN" || mem.mode === "SITE") {
      mem.mode = "SELECT";
    }
    mem.returnFrom = "SELECT";
    mem.navKey = null;
    mem.navDetour = null;
