      if (sr.i < sr.pts.length) break;
      if (!sr.extended && elapsed < 80 &&
          hint.val > 0.35 * (mem.maxHintVal || 1) &&
          sr.maxSci > 0.00005 && timeLeft > 100) {
        let oldLen = sr.pts.length;
        sr.pts = makeSearchPoints(hint.x, hint.y, true);
        sr.i = oldLen;
        sr.extended = true;
        continue;
      }
      finished = true;
      break;
    }
    if (finished) {
      hint.done = true;
      mem.activeHint = -1;
      mem.search = null;
      mem.path = null;
      let wc = wheelControl(mem, obs, 0, 0, dt);
      return { left: wc.left, right: wc.right, drill: false };
    }
    let p = sr.pts[sr.i];
    let key = "S" + mem.activeHint + "_" + sr.i + "_" + (sr.extended ? 1 : 0);
    let w = navigateTo(mem, obs, mem.posX, mem.posY, trueH, tick,
                       p.x, p.y, 0, vnav, key, dt);
    return { left: w.left, right: w.right, drill: false };
  } else {
    let key = "H" + mem.activeHint;
    let w = navigateTo(mem, obs, mem.posX, mem.posY, trueH, tick,
                       hint.x, hint.y, 0, vnav, key, dt);
    return { left: w.left, right: w.right, drill: false };
  }
}

