          }
          mem.drill = {
            start: now, x: st.x, y: st.y, val: st.val, hintIdx: hi
          };
          mem.siteTarget = null;
          let c = holdCommand(mem, obs, dt);
          return ret(mem, c.left, c.right, true);
        } else {
          if (d <= 1.55 && (!same && !recent)) {
            st.fail = (st.fail || 0) + 1;
            if (st.fail >= 2) {
              addIgnore(mem, st.x, st.y, now + 45);
              mem.siteTarget = null;
            }
          }
          if (mem.siteTarget) {
            let c = holdCommand(mem, obs, dt);
            return ret(mem, c.left, c.right, false);
          }
        }
      }
      if (mem.siteTarget) {
        let desired = Math.atan2(st.y - mem.posY, st.x - mem.posX);
        if (!isFinite(desired)) desired = trueH;
        let vmax = d > 4 ? 1.18 : (d > 2 ? 0.82 : 0.50);
        let rc = localDrive(mem, obs, mem.posX, mem.posY, trueH, desired, d, 0.92, vmax, dt);
        let c = wheelCtl(mem, obs, rc.vl, rc.vr, dt);
        return ret(mem, c.left, c.right, false);
      }
    }
  }

  if (carried >= mem.capacity) {
    mem.returning = true;
    return goHome(mem, obs, mem.posX, mem.posY, trueH, baseDist, timeLeft, battery, beacon, dt, now);
  }

  for (let attempt = 0; attempt < 4; attempt++) {
    if (mem.activeHint >= 0) {
      let h = mem.hints[mem.activeHint];
      if (!h || h.state !== 0) {
        mem.activeHint = -1;
        mem.search = null;
        mem.path = null;
        mem.pathT = -9999;
        continue;
      }
      let dHint = Math.hypot(h.x - mem.posX, h.y - mem.posY);
      if (!mem.search && dHint < 34) {
        let rank = h.val / Math.max(0.0001, mem.maxHintVal || 1);
        let maxR = rank > 0.45 ? 22 : (rank > 0.12 ? 15 : 9.5);
        let lim = rank > 0.45 ? 72 : (rank > 0.12 ? 46 : 26);
        if (timeLeft < 300) lim = Math.min(lim, 34);
        if (timeLeft < 150) lim = Math.min(lim, 18);
        h.attempts = (h.attempts || 0) + 1;
        mem.search = {
          pts: makeSearchPoints(mem, h.x, h.y, maxR, 7.5),
          i: 0,
          startT: now,
          limit: lim,
          maxSci: 0,
          centerX: h.x,
          centerY: h.y
        };
        mem.path = null;
        mem.pathT = -9999;
        mem.navKey = "";
      }
      if (mem.search) {
        let sr = mem.search;
        let sci = Number(obs.science) || 0;
        if (sci > sr.maxSci) sr.maxSci = sci;
        while (sr.i < sr.pts.length &&
               Math.hypot(sr.pts[sr.i].x - mem.posX, sr.pts[sr.i].y - mem.posY) < 2.55) {
          sr.i++;
        }
        let elapsed = now - sr.startT;
        let abort = false;
        if (elapsed > sr.limit) abort = true;
        if (sr.i >= sr.pts.length) abort = true;
        if (elapsed > 15 && sr.i > 7 && sr.maxSci < 0.00005 &&
            h.val < 0.60 * Math.max(0.0001, mem.maxHintVal || 1)) abort = true;
        if (abort) {
          h.state = 3;
          mem.activeHint = -1;
          mem.search = null;
          mem.path = null;
          mem.pathT = -9999;
          continue;
        }
        let p = sr.pts[sr.i];
        let vmax = 1.72;
        if (timeLeft < 190) vmax = 1.95;
        if (battery < 0.30) vmax = 1.15;
        vmax *= clamp(mem.traction || 1, 0.55, 1.0);
        let key = "S" + mem.activeHint + "_" + sr.i;
        let w = followTarget(mem, obs, mem.posX, mem.posY, trueH, p.x, p.y, 0, vmax, key, now, dt);
        return ret(mem, w.left, w.right, false);
      } else {
        let vmax = 1.82;
        if (timeLeft < 190) vmax = 2.05;
        if (battery < 0.30) vmax = 1.18;
        vmax *= clamp(mem.traction || 1, 0.55, 1.0);
        let key = "H" + mem.activeHint;
        let w = followTarget(mem, obs, mem.posX, mem.posY, trueH, h.x, h.y, 0, vmax, key, now, dt);
        return ret(mem, w.left, w.right, false);
      }
    } else {
      let idx = chooseHint(mem, obs, mem.posX, mem.posY, baseDist, timeLeft, battery, carried);
      if (idx >= 0) {
        mem.activeHint = idx;
        mem.search = null;
        mem.path = null;
        mem.pathT = -9999;
        mem.navKey = "";
        mem.stuckCount = 0;
        continue;
      } else {
        break;
      }
    }
  }

  if (carried > 0) {
    mem.returning = true;
    mem.activeHint = -1;
    mem.search = null;
    mem.expSearch = null;
    mem.path = null;
    mem.pathT = -9999;
    return goHome(mem, obs, mem.posX, mem.posY, trueH, baseDist, timeLeft, battery, beacon, dt, now);
  }

  if (carried === 0 && !mem.expSearch && (Number(obs.science) || 0) > 0.0005 &&
      timeLeft > 65 && now - (mem.lastScienceSearch || -9999) > 16) {
    let maxR = 22;
    if (timeLeft < 200) maxR = 14;
    mem.expSearch = {
      pts: makeSearchPoints(mem, mem.posX, mem.posY, maxR, 8.0),
      i: 0,
      startT: now,
      limit: maxR > 18 ? 44 : 26
    };
    mem.lastScienceSearch = now;
    mem.path = null;
    mem.pathT = -9999;
    mem.navKey = "";
  }
  if (mem.expSearch) {
    let sr = mem.expSearch;
    while (sr.i < sr.pts.length &&
           Math.hypot(sr.pts[sr.i].x - mem.posX, sr.pts[sr.i].y - mem.posY) < 2.55) {
      sr.i++;
    }
    if (sr.i >= sr.pts.length || now - sr.startT > sr.limit) {
      mem.expSearch = null;
    } else {
      let p = sr.pts[sr.i];
      let vmax = 1.55;
      if (timeLeft < 150) vmax = 1.8;
      vmax *= clamp(mem.traction || 1, 0.55, 1.0);
      let key = "X" + sr.i + "_" + Math.floor(sr.startT);
      let w = followTarget(mem, obs, mem.posX, mem.posY, trueH, p.x, p.y, 0, vmax, key, now, dt);
      return ret(mem, w.left, w.right, false);
    }
  }

  let ep = getExplorePoint(mem, mem.posX, mem.posY, now);
  if (!ep) {
    if (timeLeft < 20) {
      let c = holdCommand(mem, obs, dt);
      return ret(mem, c.left, c.right, false);
    }
    let a = (now * 0.21) % (Math.PI * 2);
    let tx = clamp(mem.size * 0.5 + Math.cos(a) * mem.size * 0.34, 5, mem.size - 5);
    let ty = clamp(mem.size * 0.5 + Math.sin(a) * mem.size * 0.34, 5, mem.size - 5);
    let key = "WANDER_" + Math.floor(now / 22);
    let w = followTarget(mem, obs, mem.posX, mem.posY, trueH, tx, ty, 3.0, 1.55, key, now, dt);
    return ret(mem, w.left, w.right, false);
  }
  let dEp = Math.hypot(ep.x - mem.posX, ep.y - mem.posY);
  if (dEp < 8.0) {
    ep.done = true;
    let c = holdCommand(mem, obs, dt);
    return ret(mem, c.left, c.right, false);
  }
  let vmax = 1.72;
  if (timeLeft < 180) vmax = 1.95;
  if (battery < 0.28) vmax = 1.12;
  vmax *= clamp(mem.traction || 1, 0.55, 1.0);
  let key = "E" + ep.id;
  let w = followTarget(mem, obs, mem.posX, mem.posY, trueH, ep.x, ep.y, 2.0, vmax, key, now, dt);
  return ret(mem, w.left, w.right, false);
}

const D2R = Math.PI / 180;
const R2D = 180 / Math.PI;

function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function wrapPi(a) {
  a = a % (Math.PI * 2);
  if (a > Math.PI) a -= Math.PI * 2;
  if (a < -Math.PI) a += Math.PI * 2;
  return a;
}
function wrapDeg(a) {
  a = a % 360;
  if (a > 180) a -= 360;
  if (a < -180) a += 360;
  return a;
}
function hypot2(x, y) { return Math.sqrt(x * x + y * y); }

function initMem(obs, mem) {
  mem.init = true;
  const m = obs.mission || {};
  mem.size = Number(m.size) || 400;
  mem.seconds = Number(m.seconds) || 1200;
  mem.cap = Number(m.capacity) || 5;
  mem.base = {
    x: (m.base && isFinite(Number(m.base.x))) ? Number(m.base.x) : (Number(obs.x) || 0),
    y: (m.base && isFinite(Number(m.base.y))) ? Number(m.base.y) : (Number(obs.y) || 0)
  };
  mem.x = Number(obs.x) || 0;
  mem.y = Number(obs.y) || 0;
  mem.h = (Number(obs.heading) || 0) * D2R;
  mem.lastRawX = mem.x;
  mem.lastRawY = mem.y;
  mem.lastRawHRad = (Number(obs.heading) || 0) * D2R;
  mem.hBias = 0;
  mem.tick = 0;
  mem.lastTime = null;
  mem.lastBattery = (obs.battery != null && isFinite(Number(obs.battery))) ? Number(obs.battery) : 1;
  mem.lastCarried = Number(obs.carried) || 0;
  mem.lastBumped = !!obs.bumped;
  mem.ePerM = 0.0012;
  mem.eCost = 0;
  mem.eDist = 0;
  mem.traction = 1.0;
  mem.moveDist = 0;
  mem.wheelAvg = 0;
  mem.yawRate = 0;
  mem.mcL = { eff: 2.6, i: 0 };
  mem.mcR = { eff: 2.6, i: 0 };
  mem.recoverUntil = -1;
  mem.recoverStart = -1;
  mem.recoverSide = 1;
  mem.task = null;
  mem.returning = false;
  mem.lastDelivery = -9999;
  mem.lastSampleT = -9999;
  mem.lastSciSearch = -9999;
  mem.navWorld = null;
  mem.siteLock = null;
  mem.drillState = null;
  mem.lastCmdV = 0;
  mem.explorePts = null;
  mem.gpsFrozen = 0;
  mem.courseX = null;
  mem.courseY = null;
  mem.courseT = -9999;
  mem.posHist = [];
  mem.lastHistT = -9999;

  const hl = (m.hints && m.hints.length) ? m.hints : [];
  mem.hints = [];
  mem.maxHintVal = 0.000001;
  for (let i = 0; i < hl.length; i++) {
    const q = hl[i];
    let x = Number(q.x), y = Number(q.y), v = Number(q.estimate);
    if (!isFinite(x) || !isFinite(y)) continue;
    if (!isFinite(v) || v <= 0) v = 0.000001;
    x = clamp(x, 2, mem.size - 2);
    y = clamp(y, 2, mem.size - 2);
    mem.hints.push({ x: x, y: y, val: Math.max(0.000001, v), state: 0 });
    if (v > mem.maxHintVal) mem.maxHintVal = v;
  }
  if (!(mem.maxHintVal > 0)) mem.maxHintVal = 1;

  mem.explorePts = [];
  const step = Math.max(48, mem.size / 8);
  for (let x = step * 0.55; x < mem.size - 8; x += step) {
    for (let y = step * 0.55; y < mem.size - 8; y += step) {
      mem.explorePts.push({ x: x, y: y, visited: false });
    }
  }
}

function wheelCtrl(mem, obs, side, target, actual, dt) {
  const st = (side === "L") ? mem.mcL : mem.mcR;
  target = clamp(Number(target) || 0, -3.0, 3.0);
  actual = Number(actual) || 0;
  const dz = 0.035;
  let err = target - actual;
  st.i += err * dt * 0.48;
  st.i = clamp(st.i, -0.65, 0.65);
  let u = target / Math.max(1.0, st.eff) + 0.78 * err + st.i;
  if (Math.abs(target) > 0.025) {
    if (u > 0.012) u += dz;
    else if (u < -0.012) u -= dz;
  } else {
    u = -0.95 * actual + st.i * 0.55;
    if (Math.abs(actual) < 0.022) {
      u = 0;
      st.i *= 0.985;
    }
  }
  if (u > 1) {
    u = 1;
    st.i -= err * dt * 0.18;
  } else if (u < -1) {
    u = -1;
    st.i -= err * dt * 0.18;
  }
  if (Math.abs(target) > 0.38 && Math.abs(actual) > 0.12 &&
      Math.abs(u) < 0.97 && target * actual > 0) {
    const de = Math.abs(u) - dz;
    if (de > 0.06) {
      const est = Math.abs(actual) / de;
      if (est > 0.55 && est < 8.0) {
        st.eff = clamp(st.eff * 0.9965 + est * 0.0035, 1.0, 8.0);
      }
    }
  }
  return clamp(u, -1, 1);
}

function applyDrive(mem, obs, tl, tr, dt, pitchFF) {
  let ul = wheelCtrl(mem, obs, "L", tl, obs.wheelLeft, dt);
  let ur = wheelCtrl(mem, obs, "R", tr, obs.wheelRight, dt);
  if (pitchFF) {
    const p = Number(obs.pitch) || 0;
    const ff = clamp(p * 0.0045, -0.10, 0.10);
    if (Math.abs(tl) + Math.abs(tr) > 0.18) {
      ul = clamp(ul + ff, -1, 1);
      ur = clamp(ur + ff, -1, 1);
    }
  }
  return { left: clamp(ul, -1, 1), right: clamp(ur, -1, 1), drill: false };
}

function holdCmd(mem, obs, dt) {
  let cmd = applyDrive(mem, obs, 0, 0, dt, false);
  const p = Number(obs.pitch) || 0;
  const ff = clamp(p * 0.012, -0.18, 0.18);
  cmd.left = clamp(cmd.left + ff, -1, 1);
  cmd.right = clamp(cmd.right + ff, -1, 1);
  return cmd;
}

function triggerRecovery(mem, obs, now, why) {
  if (now < mem.recoverUntil - 0.10) return;
  const rays = obs.rays || [];
  let left = 0, right = 0;
  for (let i = 0; i < rays.length && i < 9; i++) {
    let d = Number(rays[i]);
    if (!isFinite(d) || d < 0 || d > 15) d = 10;
    if (i <= 3) right += d;
    else if (i >= 5) left += d;
  }
  let side = (left >= right) ? 1 : -1;
  if (why === "bump" && Math.abs(left - right) < 0.6) side = (mem.recoverSide || 1);
  mem.recoverSide = side;
  mem.recoverStart = now;
  mem.recoverUntil = now + (why === "bump" ? 1.15 : 1.35);
  mem.navWorld = null;
  mem.drillState = null;
  mem.siteLock = null;
  if (mem.task) mem.task.pi = Math.max(0, (mem.task.pi || 0) - 2);
}

function updatePose(mem, obs, now, dt) {
  const wl = Number(obs.wheelLeft) || 0;
  const wr = Number(obs.wheelRight) || 0;
  mem.wheelAvg = (wl + wr) * 0.5;
  mem.yawRate = (wr - wl) / 0.6;
  const rh = (Number(obs.heading) || 0) * D2R;
  if (mem.lastRawHRad == null) mem.lastRawHRad = rh;
  const expectedYaw = mem.yawRate * dt;
  const deltaRaw = wrapPi(rh - mem.lastRawHRad);
  let baseH;
  if (Math.abs(deltaRaw - expectedYaw) > 0.95 &&
      Math.abs(deltaRaw) > 0.75 &&
      Math.abs(expectedYaw) < 0.9) {
    baseH = mem.h + expectedYaw;
  } else {
    baseH = rh + mem.hBias;
  }
  const predH = mem.h + expectedYaw;
  const eh = wrapPi(baseH - predH);
  mem.h = wrapPi(predH + clamp(eh, -0.45, 0.45) * 0.46);
  mem.lastRawHRad = rh;

  let rawX = Number(obs.x), rawY = Number(obs.y);
  if (!isFinite(rawX) || !isFinite(rawY)) {
    rawX = mem.lastRawX;
    rawY = mem.lastRawY;
  }
  const rawStep = hypot2(rawX - (mem.lastRawX == null ? rawX : mem.lastRawX),
                         rawY - (mem.lastRawY == null ? rawY : mem.lastRawY));
  const motion = Math.abs(mem.wheelAvg) * dt;
  let plausible = rawStep < Math.max(2.8, motion * 9 + 1.8);
  if (mem.gpsFrozen > 0.4 && rawStep < 45) plausible = true;
  const prevX = mem.x, prevY = mem.y;
  if (plausible && (rawStep > 0.0008 || motion < 0.018)) {
    let alpha = 0.40;
    if (rawStep > 3.0) alpha = 0.82;
    if (mem.gpsFrozen > 0.6) alpha = Math.max(alpha, 0.75);
    mem.x += (rawX - mem.x) * alpha;
    mem.y += (rawY - mem.y) * alpha;
    mem.gpsFrozen = 0;
    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
  } else {
    mem.x += Math.cos(mem.h) * mem.wheelAvg * dt;
    mem.y += Math.sin(mem.h) * mem.wheelAvg * dt;
    mem.gpsFrozen = (mem.gpsFrozen || 0) + dt;
  }
  mem.x = clamp(mem.x, 0.5, mem.size - 0.5);
  mem.y = clamp(mem.y, 0.5, mem.size - 0.5);
  mem.moveDist = hypot2(mem.x - prevX, mem.y - prevY);

  if (Math.abs(mem.wheelAvg) > 0.30) {
    if (mem.courseX == null) {
      mem.courseX = mem.x;
      mem.courseY = mem.y;
      mem.courseT = now;
    } else {
      const dx = mem.x - mem.courseX;
      const dy = mem.y - mem.courseY;
      const dd = hypot2(dx, dy);
      if (dd > 1.0 && now - mem.courseT > 0.8) {
        if (Math.abs(wr - wl) < 0.35) {
          const course = Math.atan2(dy, dx);
          const err = wrapPi(course - mem.h);
          if (Math.abs(err) < 0.55) {
            mem.h = wrapPi(mem.h + err * 0.055);
            mem.hBias = wrapPi(mem.hBias + err * 0.018);
          }
        }
        mem.courseX = mem.x;
        mem.courseY = mem.y;
        mem.courseT = now;
      }
    }
  } else {
    mem.courseX = null;
    mem.courseY = null;
  }

  const b = obs.beacon;
  if (b && b.distance != null && isFinite(Number(b.distance)) &&
      Number(b.distance) < 20) {
    const expected = Math.atan2(mem.base.y - mem.y, mem.base.x - mem.x);
    const observed = mem.h + (Number(b.bearing) || 0) * D2R;
    const err = wrapPi(expected - observed);
    if (Math.abs(err) < 0.8) {
      mem.h = wrapPi(mem.h + err * 0.12);
      mem.hBias = wrapPi(mem.hBias + err * 0.025);
    }
  }

  if (mem.courseX == null && Math.abs(mem.wheelAvg) < 0.03) {
    mem.courseX = mem.x;
    mem.courseY = mem.y;
    mem.courseT = now;
  }
}

function updateEnergyTraction(mem, obs, dt) {
  const battery = Number(obs.battery);
  const bat = isFinite(battery) ? battery : (mem.lastBattery || 0);
  const solar = Number(obs.solar) || 0;
  const cost = (mem.lastBattery || 0) - bat + solar * dt;
  if (!obs.docked && !mem.drillState &&
      mem.moveDist > 0.012 && Math.abs(mem.wheelAvg) > 0.08) {
    mem.eCost += Math.max(0, cost);
    mem.eDist += mem.moveDist;
    if (mem.eDist > 12) {
      const es = mem.eCost / mem.eDist;
      if (es > 0.000015 && es < 0.06) {
        mem.ePerM = clamp(mem.ePerM * 0.80 + es * 0.20, 0.00018, 0.06);
      }
      mem.eCost = 0;
      mem.eDist = 0;
    }
  }
  if (mem.gpsFrozen < 0.5 && Math.abs(mem.wheelAvg) > 0.20 && dt > 0) {
    const pred = Math.abs(mem.wheelAvg) * dt;
    if (pred > 0.020) {
      const ratio = mem.moveDist / pred;
      if (ratio > 0.05 && ratio < 2.2) {
        mem.traction = clamp(mem.traction * 0.97 + ratio * 0.03, 0.25, 1.30);
      }
    }
  }
  mem.lastBattery = bat;
}

function makeSpiral(cx, cy, R, spacing, size) {
  const turns = Math.max(1, Math.ceil(R / Math.max(6, spacing)));
  const A = Math.PI * 2 * turns;
  const pts = [];
  const dA = 0.30;
  for (let a = 0; a <= A + 1e-6; a += dA) {
    const r = R * a / A;
    let x = cx + Math.cos(a) * r;
    let y = cy + Math.sin(a) * r;
    x = clamp(x, 3, size - 3);
    y = clamp(y, 3, size - 3);
    if (pts.length === 0 ||
        hypot2(x - pts[pts.length - 1].x, y - pts[pts.length - 1].y) > 1.8) {
      pts.push({ x: x, y: y });
    }
  }
  const lastX = cx + Math.cos(A) * R;
  const lastY = cy + Math.sin(A) * R;
  if (pts.length === 0 ||
      hypot2(lastX - pts[pts.length - 1].x, lastY - pts[pts.length - 1].y) > 1.2) {
    pts.push({ x: clamp(lastX, 3, size - 3), y: clamp(lastY, 3, size - 3) });
  }
  return pts;
}

function searchRadius(mem, h, timeLeft) {
  const rel = clamp((h.val || 0) / Math.max(0.000001, mem.maxHintVal), 0, 1.4);
  let R = 13 + 8 * Math.min(1.1, rel);
  if (timeLeft < 360) R = Math.min(R, 14.5);
  if (timeLeft < 210) R = Math.min(R, 11.5);
  if (h.state !== 0) R *= 0.7;
  return clamp(R, 8, 22);
}

function chooseDirectionRel(mem, obs, desiredRel) {
  const rays = obs.rays || [];
  let bestRel = wrapPi(desiredRel);
  let bestScore = 1e100;
  const prevWorld = mem.navWorld;
  const mh = mem.h;
  for (let oi = -10; oi <= 10; oi++) {
    const off = oi * 10 * D2R;
    const cand = wrapPi(desiredRel + off);
    const candWorld = mh + cand;
    let risk = 0;

    for (let i = 0; i < rays.length && i < 9; i++) {
      let d = Number(rays[i]);
      if (!isFinite(d) || d < 0) continue;
      if (d > 15) d = 15;
      const ra = ((-80 + 20 * i) * D2R);
      const diff = Math.abs(wrapPi(ra - cand));
      if (diff < 0.88) {
        const prox = Math.max(0, 7 - d);
        risk += prox * prox * (1 - diff / 0.88) * 0.085;
        if (d < 1.35 && diff < 0.42) risk += 90;
        else if (d < 2.25 && diff < 0.62) risk += (2.25 - d) * 9.0;
      }
    }

    const bx = Math.cos(candWorld);
    const by = Math.sin(candWorld);
    const margin = 3.5;
    let edge = 1e9;
    if (bx > 1e-6) edge = Math.min(edge, (mem.size - margin - mem.x) / bx);
    else if (bx < -1e-6) edge = Math.min(edge, (margin - mem.x) / bx);
    if (by > 1e-6) edge = Math.min(edge, (mem.size - margin - mem.y) / by);
    else if (by < -1e-6) edge = Math.min(edge, (margin - mem.y) / by);
    if (edge < 6.5) {
      const ed = Math.max(0, edge);
      risk += (6.5 - ed) * (6.5 - ed) * 0.45;
      if (edge < 1.4) risk += 180;
    }

    if (prevWorld != null) {
      const dv = wrapPi(candWorld - prevWorld);
      risk += (1 - Math.cos(dv)) * 0.85;
    }
    risk += Math.abs(off) * 0.16;

    if (risk < bestScore) {
      bestScore = risk;
      bestRel = cand;
    }
  }
  mem.navWorld = wrapPi(mh + bestRel);
  return bestRel;
}

function driveRelative(mem, obs, desiredRel, speedMax, distToTarget, stopDist, dt) {
  const rays = obs.rays || [];
  const chosenRel = chooseDirectionRel(mem, obs, desiredRel);
  const chosenWorld = mem.h + chosenRel;
  const err = wrapPi(chosenRel);

  let clear = 15;
  for (let i = 0; i < rays.length && i < 9; i++) {
    let d = Number(rays[i]);
    if (!isFinite(d) || d < 0) continue;
    if (d > 15) d = 15;
    const ra = ((-80 + 20 * i) * D2R);
    const diff = Math.abs(wrapPi(ra - chosenRel));
    if (diff < 0.86) {
      const proj = d * Math.cos(diff);
      if (proj < clear) clear = proj;
    }
  }
  const bx = Math.cos(chosenWorld);
  const by = Math.sin(chosenWorld);
  const margin = 3.5;
  let edgeClear = 1e9;
  if (bx > 1e-6) edgeClear = Math.min(edgeClear, (mem.size - margin - mem.x) / bx);
  else if (bx < -1e-6) edgeClear = Math.min(edgeClear, (margin - mem.x) / bx);
  if (by > 1e-6) edgeClear = Math.min(edgeClear, (mem.size - margin - mem.y) / by);
  else if (by < -1e-6) edgeClear = Math.min(edgeClear, (margin - mem.y) / by);
  if (edgeClear < clear) clear = Math.max(0, edgeClear);

  const omega = clamp(2.05 * err - 0.12 * mem.yawRate, -1.85, 1.85);
  let v = clamp(Number(speedMax) || 0, 0, 2.9);

  if (distToTarget != null && stopDist != null) {
    const rem = distToTarget - stopDist;
    if (rem <= 0.08) {
      v = 0;
    } else if (rem < 2.1) {
      v = Math.min(v, Math.max(0.10, rem * 0.75));
    }
  }

  if (Math.abs(err) > 1.15) v = 0;
  else if (Math.abs(err) > 0.56) v *= 0.32;
  else v *= Math.max(0.16, Math.cos(err));

  if (clear < 1.05) v = 0;
  else if (clear < 3.6) v = Math.min(v, Math.max(0.08, (clear - 0.78) * 0.78));

  v = clamp(v, 0, 2.85);
  const slip = clamp(1 / Math.max(0.35, mem.traction || 1), 1, 1.65);
  const vw = clamp(v * slip, 0, 2.9);

  let tl, tr;
  if (v < 0.030 && Math.abs(err) > 0.10) {
    tl = -omega * 0.3;
    tr = omega * 0.3;
  } else {
    tl = vw - omega * 0.3;
    tr = vw + omega * 0.3;
  }
  if (v === 0 && Math.abs(err) < 0.12 &&
      distToTarget != null && stopDist != null &&
      distToTarget <= stopDist + 0.22) {
    tl = 0;
    tr = 0;
  }
  tl = clamp(tl, -2.95, 2.95);
  tr = clamp(tr, -2.95, 2.95);
  mem.lastCmdV = v;
  return applyDrive(mem, obs, tl, tr, dt, true);
}

function navigatePoint(mem, obs, tx, ty, speed, stopDist, dt) {
  const dx = tx - mem.x;
  const dy = ty - mem.y;
  const d = hypot2(dx, dy);
  const desired = (d > 0.05) ? Math.atan2(dy, dx) : mem.h;
  return driveRelative(mem, obs, wrapPi(desired - mem.h), speed, d, stopDist, dt);
}

function goBase(mem, obs, now, dt, timeLeft, battery) {
  const b = obs.beacon;
  if (b && b.distance != null && isFinite(Number(b.distance)) &&
      Number(b.distance) < 30) {
    const d = Number(b.distance);
    const bearing = (Number(b.bearing) || 0) * D2R;
    if (d <= 2.15) return holdCmd(mem, obs, dt);
    let sp = 1.75;
    if (d < 5) sp = 0.85;
    else if (d < 10) sp = 1.25;
    if (battery < 0.25) sp = Math.min(sp, 1.15);
    if (timeLeft < 65) sp = Math.max(sp, 1.8);
    return driveRelative(mem, obs, bearing, sp, d, 1.35, dt);
  }
  const bd = hypot2(mem.base.x - mem.x, mem.base.y - mem.y);
  if (bd <= 2.25) return holdCmd(mem, obs, dt);
  let sp = 1.75;
  if (battery < 0.25) sp = 1.15;
  if (timeLeft < 60) sp = 2.0;
  return navigatePoint(mem, obs, mem.base.x, mem.base.y, sp, 1.8, dt);
}

function startSpiralTask(mem, obs, cx, cy, R, hintIdx, now, timeLeft, exploreP) {
  const pts = makeSpiral(cx, cy, R, 13, mem.size);
  const turns = Math.max(1, Math.ceil(R / 13));
  const pathLen = Math.PI * Math.max(1, R) * turns;
  const dd = hypot2(cx - mem.x, cy - mem.y);
  let searchAllow = Math.min(170, 22 + pathLen / 0.78);
  let maxT = Math.min(230, dd / 0.65 + searchAllow + 18);
  if (timeLeft < 110) maxT = Math.min(maxT, Math.max(14, timeLeft - 18));
  mem.task = {
    type: "spiral",
    hintIdx: hintIdx,
    exploreP: exploreP || null,
    cx: cx,
    cy: cy,
    R: R,
    pts: pts,
    pi: 0,
    start: now,
    deadline: now + Math.max(10, maxT),
    maxSci: 0
  };
  mem.navWorld = null;
}

function finishTask(mem, sampled) {
  const t = mem.task;
  if (!t) return;
  if (t.hintIdx != null && t.hintIdx >= 0 && mem.hints[t.hintIdx]) {
    const h = mem.hints[t.hintIdx];
    if (sampled) h.state = 1;
    else if (h.state === 0) h.state = 2;
  }
  if (t.exploreP) t.exploreP.visited = true;
  mem.task = null;
  mem.navWorld = null;
}

function runTask(mem, obs, now, timeLeft, battery, carried, dt) {
  const t = mem.task;
  if (!t) return null;

  if (t.type === "spiral") {
    const pts = t.pts;
    while (t.pi < pts.length &&
           hypot2(pts[t.pi].x - mem.x, pts[t.pi].y - mem.y) < 2.8) {
      t.pi++;
    }
    if (t.pi >= pts.length || now > t.deadline) {
      finishTask(mem, false);
      return null;
    }
    const sci = Number(obs.science) || 0;
    if (sci > t.maxSci) t.maxSci = sci;

    const elapsed = now - t.start;
    if (t.hintIdx != null && t.hintIdx >= 0 &&
        t.pi > pts.length * 0.68 && elapsed > 22 &&
        t.maxSci < 0.0009) {
      const h = mem.hints[t.hintIdx];
      const rel = h ? (h.val / Math.max(0.000001, mem.maxHintVal)) : 0;
      if (rel < 0.26 || timeLeft < 430) {
        finishTask(mem, false);
        return null;
      }
    }

    const p = pts[t.pi];
    let sp = 1.32;
    if (elapsed > (t.deadline - t.start) * 0.75) sp = 1.55;
    if (timeLeft < 160) sp = 1.60;
    if (battery < 0.24) sp = 0.95;
    return navigatePoint(mem, obs, p.x, p.y, sp, 0.15, dt);
  }
  return null;
}

function hintFeasible(mem, obs, h, carried, timeLeft, battery, now) {
  const d = hypot2(h.x - mem.x, h.y - mem.y);
  const db = hypot2(h.x - mem.base.x, h.y - mem.base.y);
  const R = searchRadius(mem, h, timeLeft);
  const turns = Math.max(1, Math.ceil(R / 13));
  const pathLen = Math.PI * R * turns;
  const e = Math.max(0.00055, mem.ePerM || 0.0012);
  const route = d + db + pathLen * 0.75 + 22;
  const eCost = route * e * (1 + 0.26 * (carried + 1)) + 0.045;
  if (battery < eCost * 1.22 + 0.075) return false;
  const tCost = route / 0.62 + 30 + 7 * (carried + 1);
  if (timeLeft < tCost + 15) return false;
  return true;
}

function chooseHint(mem, obs, now, carried, timeLeft, battery, bdist) {
  let best = -1;
  let bestScore = -1e100;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (!h || h.state !== 0) continue;
    if (!hintFeasible(mem, obs, h, carried, timeLeft, battery, now)) continue;
    const d = hypot2(h.x - mem.x, h.y - mem.y);
    const db = hypot2(h.x - mem.base.x, h.y - mem.base.y);
    const R = searchRadius(mem, h, timeLeft);
    const turns = Math.max(1, Math.ceil(R / 13));
    const pathLen = Math.PI * R * turns;
    let denom = d + 18 + pathLen * 0.16;
    if (carried > 0) denom += 0.82 * db;
    else denom += 0.30 * db;
    let score = Math.pow(Math.max(0.000001, h.val), 1.12) / (denom + 16);
    if (timeLeft < 320) score *= 1 / (1 + db / 130);
    if (timeLeft < 180) score *= 1 / (1 + d / 70);
    if (carried > 0 && db > bdist + d + 55) score *= 0.72;
    if (score > bestScore) {
      bestScore = score;
      best = i;
    }
  }
  return best;
}

function chooseExplorePoint(mem, obs, now, timeLeft) {
  if (!mem.explorePts || mem.explorePts.length === 0) return null;
  for (let i = 0; i < mem.explorePts.length; i++) {
    const p = mem.explorePts[i];
    if (!p.visited && hypot2(p.x - mem.x, p.y - mem.y) < 8.0) p.visited = true;
  }
  let best = null;
  let bestScore = 1e100;
  for (let i = 0; i < mem.explorePts.length; i++) {
    const p = mem.explorePts[i];
    if (p.visited) continue;
    const d = hypot2(p.x - mem.x, p.y - mem.y);
    const db = hypot2(p.x - mem.base.x, p.y - mem.base.y);
    let s = d + 0.12 * db;
    if (timeLeft < 180) s += 0.35 * db;
    if (s < bestScore) {
      bestScore = s;
      best = p;
    }
  }
  return best;
}

function siteApproachOrDrill(mem, obs, now, timeLeft, battery, carried, dt) {
  const s = obs.site;
  if (s == null) {
    if (mem.siteLock && now - mem.siteLock.lastSeen < 1.25) {
      return navigatePoint(mem, obs, mem.siteLock.x, mem.siteLock.y, 0.78, 1.15, dt);
    }
    mem.siteLock = null;
    return null;
  }
  const d = Number(s.distance);
  const b = (Number(s.bearing) || 0) * D2R;
  if (!isFinite(d) || d < 0) return null;
  if (carried >= mem.cap || timeLeft < 11 || battery < 0.035) return null;

  const sx = mem.x + Math.cos(mem.h + b) * d;
  const sy = mem.y + Math.sin(mem.h + b) * d;
  mem.siteLock = { x: sx, y: sy, lastSeen: now };

  const speed = Math.abs((Number(obs.wheelLeft) || 0) + (Number(obs.wheelRight) || 0)) * 0.5;

  if (d <= 1.44) {
    if (speed < 0.105) {
      mem.drillState = { start: now, carried0: carried };
      const cmd = holdCmd(mem, obs, dt);
      cmd.drill = true;
      return cmd;
    }
    return holdCmd(mem, obs, dt);
  }

  let sp = 1.30;
  if (d > 5.0) sp = 1.45;
  else if (d > 3.0) sp = 0.95;
  else if (d > 2.0) sp = 0.52;
  else sp = 0.26;

  return driveRelative(mem, obs, b, sp, d, 1.22, dt);
}

function act(obs, mem) {
  try {
    if (!mem.init) initMem(obs, mem);

    let now;
    if (obs.t != null && isFinite(Number(obs.t))) now = Number(obs.t);
    else now = (mem.tick || 0) * 0.1;

    let dt = 0.1;
    if (mem.lastTime != null && now > mem.lastTime) {
      dt = clamp(now - mem.lastTime, 0.01, 0.55);
    }
    mem.lastTime = now;
    mem.tick = (mem.tick || 0) + 1;

    const timeLeft = (obs.timeLeft != null && isFinite(Number(obs.timeLeft))) ?
      Number(obs.timeLeft) : Math.max(0, mem.seconds - now);
    const battery = (obs.battery != null && isFinite(Number(obs.battery))) ?
      Number(obs.battery) : (mem.lastBattery || 0);
    const carried = Number(obs.carried) || 0;

    updatePose(mem, obs, now, dt);

    if (obs.bumped && !mem.lastBumped) {
      triggerRecovery(mem, obs, now, "bump");
    }
    mem.lastBumped = !!obs.bumped;

    if (mem.drillState) {
      const s = obs.site;
      const d = s ? Number(s.distance) : 999;
      const spd = Math.abs((Number(obs.wheelLeft) || 0) + (Number(obs.wheelRight) || 0)) * 0.5;
      const dur = now - mem.drillState.start;
      if (!s || !isFinite(d) || d > 1.58 || dur > 10.5 ||
          timeLeft < 5 || battery < 0.022 ||
          carried > mem.drillState.carried0) {
        mem.drillState = null;
      } else {
        const cmd = holdCmd(mem, obs, dt);
        cmd.drill = true;
        return cmd;
      }
    }

    if (carried > mem.lastCarried) {
      mem.lastSampleT = now;
      const hx = mem.x, hy = mem.y;
      let bestH = -1, bestD = 17.5;
      for (let i = 0; i < mem.hints.length; i++) {
        const h = mem.hints[i];
        if (!h || h.state !== 0) continue;
        const d = hypot2(h.x - hx, h.y - hy);
        if (d < bestD) {
          bestD = d;
          bestH = i;
        }
      }
      if (bestH >= 0) mem.hints[bestH].state = 1;
      if (mem.task && mem.task.hintIdx != null && mem.task.hintIdx >= 0) {
        const h = mem.hints[mem.task.hintIdx];
        if (h && hypot2(h.x - hx, h.y - hy) < (mem.task.R || 15) + 12) {
          h.state = 1;
        }
      }
      if (mem.task) {
        if (mem.task.exploreP) mem.task.exploreP.visited = true;
        mem.task = null;
      }
      mem.navWorld = null;
      mem.siteLock = null;
      mem.drillState = null;
      if (carried >= mem.cap) mem.returning = true;
    } else if (carried < mem.lastCarried) {
      mem.lastDelivery = now;
      mem.returning = false;
      mem.task = null;
      mem.siteLock = null;
      mem.drillState = null;
      mem.navWorld = null;
    }
    mem.lastCarried = carried;

    updateEnergyTraction(mem, obs, dt);

    let bdist = hypot2(mem.base.x - mem.x, mem.base.y - mem.y);
    const beacon = obs.beacon;
    if (beacon && beacon.distance != null && isFinite(Number(beacon.distance)) &&
        Number(beacon.distance) < 30) {
      bdist = Math.min(bdist, Number(beacon.distance));
    }

    let atBase = false;
    if (obs.docked) atBase = true;
    if (beacon && beacon.distance != null && isFinite(Number(beacon.distance)) &&
        Number(beacon.distance) <= 3.0) atBase = true;
    if (!atBase && mem.gpsFrozen < 0.6 && bdist <= 2.55) atBase = true;
    if (!atBase && beacon == null && mem.gpsFrozen > 0.6 && bdist <= 1.15) atBase = true;

    if (now < mem.recoverUntil) {
      const elapsed = now - mem.recoverStart;
      const side = mem.recoverSide || 1;
      let tl, tr;
      if (elapsed < 0.54) {
        tl = -0.55;
        tr = -0.55;
      } else {
        tl = -0.44 * side;
        tr = 0.44 * side;
      }
      return applyDrive(mem, obs, tl, tr, dt, false);
    }

    if (carried >= mem.cap) mem.returning = true;
    if (carried > 0 && atBase) mem.returning = true;

    if (carried > 0 && !mem.returning) {
      const e = Math.max(0.00055, mem.ePerM || 0.0012);
      const needE = bdist * e * 1.85 * (1 + 0.26 * carried) + 0.075;
      const needT = bdist / 0.62 + 16 + 7 * carried;
      if (battery < needE + 0.035 || timeLeft < needT + 8) {
        mem.returning = true;
      }
      if (battery < 0.20 + 0.025 * carried) mem.returning = true;
      if (carried >= 3 && timeLeft < bdist / 0.55 + 55) mem.returning = true;
    }
    if (carried === 0 && !atBase && battery < 0.085 && timeLeft > 12) {
      mem.returning = true;
    }
    if (timeLeft < 8 && carried > 0) mem.returning = true;

    if (mem.returning) {
      if (atBase) {
        if (carried > 0) {
          return holdCmd(mem, obs, dt);
        }
        mem.returning = false;
      } else {
        return goBase(mem, obs, now, dt, timeLeft, battery);
      }
    }

    if (atBase && carried > 0) {
      return holdCmd(mem, obs, dt);
    }

    if (atBase && carried === 0) {
      let target = 0.78;
      if (timeLeft < 520) target = 0.65;
      if (timeLeft < 260) target = 0.52;
      let wait = false;
      if (obs.docked && timeLeft > 85 && battery < target) {
        if ((now - (mem.lastDelivery || -9999) < 11) ||
            battery < 0.33) {
          wait = true;
        } else {
          const idxTmp = chooseHint(mem, obs, now, carried, timeLeft, battery, bdist);
          if (idxTmp < 0) wait = true;
        }
      }
      if (wait) return holdCmd(mem, obs, dt);
    }

    const siteCmd = siteApproachOrDrill(mem, obs, now, timeLeft, battery, carried, dt);
    if (siteCmd) return siteCmd;

    if (!mem.task) {
      const idx = chooseHint(mem, obs, now, carried, timeLeft, battery, bdist);
      if (idx >= 0) {
        const h = mem.hints[idx];
        const R = searchRadius(mem, h, timeLeft);
        startSpiralTask(mem, obs, h.x, h.y, R, idx, now, timeLeft, null);
      } else {
        if (carried > 0) {
          mem.returning = true;
          return goBase(mem, obs, now, dt, timeLeft, battery);
        }

        if (!atBase && battery < 0.115 && timeLeft > 12) {
          mem.returning = true;
          return goBase(mem, obs, now, dt, timeLeft, battery);
        }

        if (atBase) {
          const target = (timeLeft > 450) ? 0.72 : (timeLeft > 180 ? 0.58 : 0.46);
          if (obs.docked && battery < target && timeLeft > 70) {
            return holdCmd(mem, obs, dt);
          }
        }

        if (timeLeft < 14 && carried === 0) {
          return holdCmd(mem, obs, dt);
        }

        if ((Number(obs.science) || 0) > 0.045 &&
            timeLeft > 85 &&
            now - (mem.lastSciSearch || -9999) > 42) {
          mem.lastSciSearch = now;
          startSpiralTask(mem, obs, mem.x, mem.y, 14.0, -1, now, timeLeft, null);
        } else {
          const ep = chooseExplorePoint(mem, obs, now, timeLeft);
          if (ep) {
            startSpiralTask(mem, obs, ep.x, ep.y, 11.5, -1, now, timeLeft, ep);
          } else {
            if (timeLeft > 35 && obs.science != null) {
              const a = now * 0.18;
              const tx = clamp(mem.size * 0.5 + Math.cos(a) * mem.size * 0.32, 8, mem.size - 8);
              const ty = clamp(mem.size * 0.5 + Math.sin(a) * mem.size * 0.32, 8, mem.size - 8);
              return navigatePoint(mem, obs, tx, ty, 1.2, 1.0, dt);
            }
            return holdCmd(mem, obs, dt);
          }
        }
      }
    }

    if (mem.task) {
      const cmd = runTask(mem, obs, now, timeLeft, battery, carried, dt);
      if (cmd) return cmd;
    }

    return holdCmd(mem, obs, dt);
  } catch (e) {
    return { left: 0, right: 0, drill: false };
  }
}

const D2R = Math.PI / 180;

function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function wrapPi(a) {
  a = a % (Math.PI * 2);
  if (a > Math.PI) a -= Math.PI * 2;
  if (a < -Math.PI) a += Math.PI * 2;
  return a;
}

function initMem(obs, mem) {
  mem.init = true;
  const m = obs.mission || {};
  mem.size = Number(m.size) || 400;
  mem.seconds = Number(m.seconds) || 1200;
  mem.cap = Number(m.capacity) || 5;
  mem.baseX = (m.base && isFinite(Number(m.base.x))) ? Number(m.base.x) : (Number(obs.x) || 0);
  mem.baseY = (m.base && isFinite(Number(m.base.y))) ? Number(m.base.y) : (Number(obs.y) || 0);

  mem.x = Number(obs.x) || mem.baseX;
  mem.y = Number(obs.y) || mem.baseY;
  mem.h = (Number(obs.heading) || 0) * D2R;
  mem.hBias = 0;
  mem.lastRawH = mem.h;
  mem.lastRawX = mem.x;
  mem.lastRawY = mem.y;
  mem.lastT = (obs.t != null && isFinite(Number(obs.t))) ? Number(obs.t) : 0;
  mem.tick = 0;
  mem.lastBattery = (obs.battery != null && isFinite(Number(obs.battery))) ? Number(obs.battery) : 1;
  mem.carried = Number(obs.carried) || 0;
  mem.lastBumped = false;
  mem.deliveredSamples = 0;
  mem.samplesCollected = 0;
  mem.ePerM = 0.0012;
  mem.eCost = 0;
  mem.eDist = 0;
  mem.traction = 1.0;
  mem.moveDist = 0;
  mem.wheelAvg = 0;
  mem.gpsFrozen = false;
  mem.freezeT = 0;
  mem.compassJumps = 0;

  mem.mL = { eff: 2.6, i: 0, dz: 0.035 };
  mem.mR = { eff: 2.6, i: 0, dz: 0.035 };
  mem.lastCmdMag = 0;
  mem.lastCmdAvg = 0;

  mem.recoverUntil = -1;
  mem.recoverStart = -1;
  mem.recoverSide = 1;
  mem.stuckT = 0;
  mem.targetStuck = 0;

  mem.phase = "idle";
  mem.target = null;
  mem.targetHint = null;
  mem.activeHint = -1;
  mem.search = null;
  mem.searchCount = 0;
  mem.path = null;
  mem.pathKey = "";
  mem.pathT = -9999;
  mem.pathGoal = null;
  mem.pathI = 0;
  mem.pathFound = false;
  mem.lastSteerWorld = null;
  mem.lastSteerT = -9999;
  mem.targetStart = -9999;
  mem.lastProgressT = -9999;
  mem.bestTargetDist = 1e9;
  mem.drillState = null;
  mem.drillAttempts = 0;
  mem.chargeWaitStart = null;
  mem.chargeBattery = 0;
  mem.chargeCheck = -9999;
  mem.ignored = [];
  mem.lastDelivery = -9999;
  mem.lastScienceSearch = -9999;

  mem.N = 200;
  mem.cell = mem.size / mem.N;
  const n2 = mem.N * mem.N;
  mem.occ = new Float32Array(n2);
  mem.gStamp = new Int32Array(n2);
  mem.gScore = new Float32Array(n2);
  mem.parent = new Int32Array(n2);
  mem.closedStamp = new Int32Array(n2);
  mem.planStamp = 0;
  const hcap = n2 * 8;
  mem.heapI = new Int32Array(hcap);
  mem.heapF = new Float32Array(hcap);

  const hl = (m.hints && m.hints.length) ? m.hints : [];
  mem.hints = [];
  mem.maxHintVal = 0.000001;
  for (let i = 0; i < hl.length; i++) {
    const q = hl[i];
    let x = Number(q.x), y = Number(q.y), v = Number(q.estimate);
    if (!isFinite(x) || !isFinite(y)) continue;
    if (!isFinite(v) || v <= 0) v = 0.000001;
    x = clamp(x, 2, mem.size - 2);
    y = clamp(y, 2, mem.size - 2);
    mem.hints.push({ x: x, y: y, val: Math.max(0.000001, v), state: 0 });
    if (v > mem.maxHintVal) mem.maxHintVal = v;
  }
  if (!(mem.maxHintVal > 0)) mem.maxHintVal = 1;

  mem.explorePts = [];
  const step = Math.max(55, mem.size / 7);
  for (let x = step * 0.55; x < mem.size - 12; x += step) {
    for (let y = step * 0.55; y < mem.size - 12; y += step) {
      mem.explorePts.push({ x: x, y: y, visited: false, id: mem.explorePts.length });
    }
  }
  mem.raysBad = false;
}

function wheelCtl(st, target, actual, dt) {
  target = clamp(Number(target) || 0, -3.0, 3.0);
  actual = Number(actual) || 0;
  let err = target - actual;
  if (Math.abs(target) < 0.015) {
    let u = -1.0 * actual;
    if (Math.abs(actual) < 0.025) u = 0;
    st.i *= Math.max(0, 1 - 3 * dt);
    return clamp(u, -1, 1);
  }
  st.i += err * dt * 0.35;
  st.i = clamp(st.i, -0.65, 0.65);
  const dz = st.dz || 0.035;
  const ff = target / Math.max(1.2, st.eff);
  let u = ff + 0.75 * err + st.i;
  if (Math.abs(target) > 0.03 && Math.abs(u) > 0.002) {
    if (u > 0) u += dz;
    else u -= dz;
  }
  if (u > 1) { u = 1; st.i -= err * dt * 0.15; }
  else if (u < -1) { u = -1; st.i -= err * dt * 0.15; }
  if (Math.abs(target) > 0.4 && Math.abs(actual) > 0.1 &&
      target * actual > 0 && Math.abs(u) > 0.18) {
    const effA = Math.abs(actual) / Math.max(0.05, Math.abs(u) - dz);
    if (effA > 0.5 && effA < 8.0) {
      st.eff = clamp(st.eff * 0.997 + effA * 0.003, 1.0, 7.0);
    }
  }
  return clamp(u, -1, 1);
}

function applyWheels(mem, obs, tl, tr, dt) {
  let uL = wheelCtl(mem.mL, tl, Number(obs.wheelLeft) || 0, dt);
  let uR = wheelCtl(mem.mR, tr, Number(obs.wheelRight) || 0, dt);
  const p = Number(obs.pitch) || 0;
  let ff;
  if (Math.abs(tl) + Math.abs(tr) < 0.05) {
    ff = clamp(p * 0.012, -0.18, 0.18);
  } else {
    ff = clamp(p * 0.004, -0.08, 0.08);
  }
  const left = clamp(uL + ff, -1, 1);
  const right = clamp(uR + ff, -1, 1);
  mem.lastCmdMag = Math.abs(left) + Math.abs(right);
  mem.lastCmdAvg = (left + right) * 0.5;
  return { left: left, right: right, drill: false };
}

function holdCmd(mem, obs, dt, drill) {
  const c = applyWheels(mem, obs, 0, 0, dt);
  c.drill = !!drill;
  return c;
}

function addIgnore(mem, x, y, until) {
  if (!mem.ignored) mem.ignored = [];
  mem.ignored.push({ x: x, y: y, until: until });
  while (mem.ignored.length > 60) mem.ignored.shift();
}

function isIgnored(mem, x, y, now) {
  if (!mem.ignored) return false;
  for (let i = mem.ignored.length - 1; i >= 0; i--) {
    const q = mem.ignored[i];
    if (now < q.until && Math.hypot(q.x - x, q.y - y) < 3.5) return true;
  }
  return false;
}

function markOcc(mem, x, y, w) {
  const N = mem.N, C = mem.cell;
  let ccx = Math.floor(x / C), ccy = Math.floor(y / C);
  for (let dx = -1; dx <= 1; dx++) {
    for (let dy = -1; dy <= 1; dy++) {
      const cx = ccx + dx, cy = ccy + dy;
      if (cx < 1 || cx >= N - 1 || cy < 1 || cy >= N - 1) continue;
      const mx = (cx + 0.5) * C, my = (cy + 0.5) * C;
      const dd = Math.hypot(mx - x, my - y);
      if (dd < C * 1.35) {
        const id = cy * N + cx;
        mem.occ[id] = Math.min(20, mem.occ[id] + w * (1 - dd / (C * 1.35)));
      }
    }
  }
}

function updateMap(mem, obs) {
  const rays = obs.rays || [];
  const N = mem.N, C = mem.cell;
  let valid = 0, first = null, same = true;
  for (let i = 0; i < rays.length && i < 9; i++) {
    const d = Number(rays[i]);
    if (isFinite(d) && d >= 0) {
      valid++;
      if (first == null) first = d;
      else if (Math.abs(d - first) > 0.3) same = false;
    }
  }
  const bad = (valid >= 7 && same && first != null && first < 10);
  mem.raysBad = bad;
  if (bad) return;

  for (let i = 0; i < 9; i++) {
    let d = Number(rays[i]);
    if (!isFinite(d) || d < 0) continue;
    if (d > 15.2) d = 15;
    const a = mem.h + (-80 + i * 20) * D2R;
    const ca = Math.cos(a), sa = Math.sin(a);
    const fr = d - 0.65;
    for (let r = 0.6; r < fr; r += 1.15) {
      const x = mem.x + ca * r, y = mem.y + sa * r;
      const cx = Math.floor(x / C), cy = Math.floor(y / C);
      if (cx > 0 && cx < N - 1 && cy > 0 && cy < N - 1) {
        const id = cy * N + cx;
        mem.occ[id] = Math.max(0, mem.occ[id] - 0.03);
      }
    }
    if (d < 14.8) {
      const x = mem.x + ca * d, y = mem.y + sa * d;
      markOcc(mem, x, y, 0.8);
    }
  }
}

function updatePose(mem, obs, dt) {
  const wl = Number(obs.wheelLeft) || 0;
  const wr = Number(obs.wheelRight) || 0;
  mem.wheelAvg = (wl + wr) * 0.5;
  const yawRate = (wr - wl) / 0.6;
  const pred = wrapPi(mem.h + yawRate * dt);

  let rawHdeg = Number(obs.heading);
  let rawH = isFinite(rawHdeg) ? rawHdeg * D2R : mem.lastRawH;
  const jump = Math.abs(wrapPi(rawH - mem.lastRawH));
  const expected = Math.abs(yawRate * dt);
  let errH = wrapPi(rawH + mem.hBias - pred);
  if (jump > 1.0 && expected < 0.25 && mem.tick > 5 && Math.abs(errH) > 1.1) {
    mem.compassJumps++;
    if (mem.compassJumps < 8) mem.h = pred;
    else { mem.h = wrapPi(pred + errH * 0.2); mem.compassJumps = 0; }
  } else {
    mem.compassJumps = 0;
    if (Math.abs(errH) > 1.6 && expected < 0.25) mem.h = pred;
    else mem.h = wrapPi(pred + errH * 0.55);
  }
  mem.lastRawH = rawH;

  const prevX = mem.x, prevY = mem.y;
  const rawX = Number(obs.x), rawY = Number(obs.y);
  const wheelStep = Math.abs(mem.wheelAvg) * dt;
  if (isFinite(rawX) && isFinite(rawY)) {
    const stepRaw = Math.hypot(rawX - mem.lastRawX, rawY - mem.lastRawY);
    if (wheelStep > 0.03 && stepRaw < 0.002 && !obs.bumped) mem.freezeT += dt;
    else mem.freezeT = Math.max(0, mem.freezeT - dt * 2);
    if (mem.freezeT > 1.5) mem.gpsFrozen = true;
    if (stepRaw > 0.05) mem.gpsFrozen = false;

    const plausible = stepRaw < Math.max(6, wheelStep * 10 + 2);
    if (!mem.gpsFrozen && plausible) {
      let alpha = 0.6;
      if (stepRaw > 2.5) alpha = 0.88;
      mem.x += (rawX - mem.x) * alpha;
      mem.y += (rawY - mem.y) * alpha;
      mem.lastRawX = rawX;
      mem.lastRawY = rawY;
    } else {
      mem.x += Math.cos(mem.h) * mem.wheelAvg * dt;
      mem.y += Math.sin(mem.h) * mem.wheelAvg * dt;
    }
  } else {
    mem.x += Math.cos(mem.h) * mem.wheelAvg * dt;
    mem.y += Math.sin(mem.h) * mem.wheelAvg * dt;
  }

  mem.x = clamp(mem.x, 0.25, mem.size - 0.25);
  mem.y = clamp(mem.y, 0.25, mem.size - 0.25);
  mem.moveDist = Math.hypot(mem.x - prevX, mem.y - prevY);

  const b = obs.beacon;
  if (b && b.distance != null && isFinite(Number(b.distance)) &&
      Number(b.distance) < 20 && !mem.gpsFrozen) {
    const expectedAng = Math.atan2(mem.baseY - mem.y, mem.baseX - mem.x);
    const observed = mem.h + (Number(b.bearing) || 0) * D2R;
    const e = wrapPi(expectedAng - observed);
    if (Math.abs(e) < 1.0) {
      const corr = clamp(e, -0.2, 0.2);
      mem.h = wrapPi(mem.h + corr * 0.22);
      mem.hBias = wrapPi(mem.hBias + corr * 0.02);
    }
  }
}

function updateEnergy(mem, obs, dt) {
  const batt = (obs.battery != null && isFinite(Number(obs.battery))) ? Number(obs.battery) : (mem.lastBattery || 0);
  const solar = Number(obs.solar) || 0;
  if (!obs.docked && !mem.drillState && mem.moveDist > 0.01 && Math.abs(mem.wheelAvg) > 0.08) {
    const cost = Math.max(0, (mem.lastBattery || 0) - batt + solar * dt);
    mem.eCost += cost;
    mem.eDist += mem.moveDist;
    if (mem.eDist > 10) {
      const es = mem.eCost / mem.eDist;
      if (es > 0.000015 && es < 0.05) {
        mem.ePerM = clamp(mem.ePerM * 0.84 + es * 0.16, 0.0003, 0.03);
      }
      mem.eCost = 0;
      mem.eDist = 0;
    }
  }
  if (!mem.gpsFrozen && Math.abs(mem.wheelAvg) > 0.2 && mem.moveDist > 0.005) {
    const pred = Math.abs(mem.wheelAvg) * dt;
    if (pred > 0.01) {
      const ratio = mem.moveDist / pred;
      if (ratio > 0.08 && ratio < 2.2) {
        mem.traction = clamp(mem.traction * 0.98 + ratio * 0.02, 0.25, 1.2);
      }
    }
  }
  mem.lastBattery = batt;
}

function edgeDist(mem, px, py, a, margin) {
  const ca = Math.cos(a), sa = Math.sin(a);
  let ex = 1e9;
  if (ca > 1e-6) ex = Math.min(ex, (mem.size - margin - px) / ca);
  else if (ca < -1e-6) ex = Math.min(ex, (margin - px) / ca);
  if (sa > 1e-6) ex = Math.min(ex, (mem.size - margin - py) / sa);
  else if (sa < -1e-6) ex = Math.min(ex, (margin - py) / sa);
  return Math.max(0, ex);
}

function planPath(mem, sx, sy, gx, gy) {
  const N = mem.N, C = mem.cell;
  let scx = clamp(Math.floor(sx / C), 1, N - 2);
  let scy = clamp(Math.floor(sy / C), 1, N - 2);
  let gcx = clamp(Math.floor(gx / C), 1, N - 2);
  let gcy = clamp(Math.floor(gy / C), 1, N - 2);
  const start = scy * N + scx;
  const goal = gcy * N + gcx;
  if (start === goal) return { pts: [{ x: gx, y: gy }], found: true };

  let stamp = (mem.planStamp || 0) + 1;
  if (stamp > 1000000000) {
    mem.gStamp.fill(0);
    mem.closedStamp.fill(0);
    stamp = 1;
  }
  mem.planStamp = stamp;

  const gStamp = mem.gStamp, gScore = mem.gScore, parent = mem.parent;
  const closed = mem.closedStamp, heapI = mem.heapI, heapF = mem.heapF;
  let hs = 0;

  function push(id, f) {
    if (hs >= heapI.length - 2) return;
    let i = hs++;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heapF[p] <= f) break;
      heapI[i] = heapI[p];
      heapF[i] = heapF[p];
      i = p;
    }
    heapI[i] = id;
    heapF[i] = f;
  }
  function pop() {
    const r = heapI[0];
    hs--;
    if (hs > 0) {
      const li = heapI[hs], lf = heapF[hs];
      let i = 0;
      while (true) {
        let l = i * 2 + 1;
        if (l >= hs) break;
        const rr = l + 1;
        const c = (rr < hs && heapF[rr] < heapF[l]) ? rr : l;
        if (heapF[c] >= lf) break;
        heapI[i] = heapI[c];
        heapF[i] = heapF[c];
        i = c;
      }
      heapI[i] = li;
      heapF[i] = lf;
    }
    return r;
  }

  gStamp[start] = stamp;
  gScore[start] = 0;
  parent[start] = -1;
  const h0 = Math.hypot(scx - gcx, scy - gcy);
  push(start, h0);
  let best = start, bestH = h0, found = false, exp = 0;
  const maxExp = Math.min(12000, N * N);

  while (hs > 0 && exp++ < maxExp) {
    const cur = pop();
    if (closed[cur] === stamp) continue;
    closed[cur] = stamp;
    const cx = cur % N, cy = Math.floor(cur / N);
    const hc = Math.hypot(cx - gcx, cy - gcy);
    if (hc < bestH) { bestH = hc; best = cur; }
    if (cur === goal) { found = true; best = cur; break; }

    const g0 = gScore[cur];
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;
        const nx = cx + dx, ny = cy + dy;
        if (nx < 1 || nx >= N - 1 || ny < 1 || ny >= N - 1) continue;
        const ni = ny * N + nx;
        if (ni !== goal && mem.occ[ni] > 1.05) continue;
        if (dx !== 0 && dy !== 0) {
          if (mem.occ[cy * N + cx + dx] > 1.05 || mem.occ[(cy + dy) * N + cx] > 1.05) continue;
        }
        const step = (dx !== 0 && dy !== 0) ? 1.41421356 : 1.0;
        const conf = mem.occ[ni] || 0;
        const add = step * (1 + Math.min(2.5, Math.max(0, conf)) * 0.45);
        const ng = g0 + add;
        if (gStamp[ni] !== stamp || ng < gScore[ni] - 1e-6) {
          gStamp[ni] = stamp;
          gScore[ni] = ng;
          parent[ni] = cur;
          const hh = Math.hypot(nx - gcx, ny - gcy);
          push(ni, ng + hh * 1.02);
        }
      }
    }
  }

  const target = found ? goal : best;
  const arr = [];
  let cur = target, guard = 0;
  while (cur !== start && cur >= 0 && guard++ < N * N) {
    const cx = cur % N, cy = Math.floor(cur / N);
    arr.push({ x: (cx + 0.5) * C, y: (cy + 0.5) * C });
    const p = parent[cur];
    if (p === undefined || p < 0 || p === cur) break;
    cur = p;
  }
  arr.reverse();
  if (found) arr.push({ x: gx, y: gy });
  if (arr.length === 0) arr.push({ x: gx, y: gy });
  return { pts: arr, found: found };
}

function steerTo(mem, obs, now, dt, desired, goalDist, stopDist, speed) {
  const rem = goalDist - stopDist;
  if (rem <= 0.12) return holdCmd(mem, obs, dt, false);

  const h = mem.h;
  const rays = obs.rays || [];
  let bestA = desired, bestCost = 1e100;

  for (let deg = -120; deg <= 120; deg += 15) {
    const off = deg * D2R;
    const a = desired + off;
    let cost = Math.abs(off) * 1.25 + (deg * deg) * 0.0008;

    if (!mem.raysBad) {
      for (let i = 0; i < 9; i++) {
        let d = Number(rays[i]);
        if (!isFinite(d) || d < 0) continue;
        if (d > 15) d = 15;
        const rayAng = h + (-80 + i * 20) * D2R;
        const diff = Math.abs(wrapPi(rayAng - a));
        if (diff < 0.95) {
          const prox = Math.max(0, 7 - d);
          cost += prox * prox * (1 - diff / 0.95) * 0.10;
          if (d < 1.25 && diff < 0.55) cost += 65;
          else if (d < 2.2 && diff < 0.70) cost += (2.2 - d) * 9.0;
        }
      }
    } else {
      for (let rr = 1.0; rr <= 6.0; rr += 1.0) {
        const xx = mem.x + Math.cos(a) * rr;
        const yy = mem.y + Math.sin(a) * rr;
        const cx = Math.floor(xx / mem.cell), cy = Math.floor(yy / mem.cell);
        if (cx < 1 || cx >= mem.N - 1 || cy < 1 || cy >= mem.N - 1) break;
        const id = cy * mem.N + cx;
        if (mem.occ[id] > 1.05) {
          cost += (7 - rr) * (7 - rr) * 2.0;
          break;
        }
      }
    }

    const ed = edgeDist(mem, mem.x, mem.y, a, 2.5);
    if (ed < 6) {
      cost += (6 - ed) * (6 - ed) * 0.45;
      if (ed < 1.2) cost += 120;
    }

    const hd = Math.abs(wrapPi(a - h));
    cost += hd * 0.18;
    if (mem.lastSteerWorld != null && now - mem.lastSteerT < 1.2) {
      const dh = Math.abs(wrapPi(a - mem.lastSteerWorld));
      cost += dh * 0.55;
    }

    if (cost < bestCost) {
      bestCost = cost;
      bestA = a;
    }
  }

  const a = bestA;
  let vmax = clamp(Number(speed) || 0, 0, 2.8);
  if (rem <= 0.35) vmax = 0;
  else if (rem < 2.5) vmax = Math.min(vmax, Math.max(0.12, rem * 0.72));

  let clear = 15;
  if (!mem.raysBad) {
    for (let i = 0; i < 9; i++) {
      let d = Number(rays[i]);
      if (!isFinite(d) || d < 0) continue;
      if (d > 15) d = 15;
      const rayAng = h + (-80 + i * 20) * D2R;
      const diff = Math.abs(wrapPi(rayAng - a));
      if (diff < 0.7) {
        const proj = d * Math.cos(diff);
        if (proj < clear) clear = proj;
      }
    }
  } else {
    clear = 10;
    for (let rr = 1.0; rr <= 10; rr += 1.0) {
      const xx = mem.x + Math.cos(a) * rr;
      const yy = mem.y + Math.sin(a) * rr;
      const cx = Math.floor(xx / mem.cell), cy = Math.floor(yy / mem.cell);
      if (cx < 1 || cx >= mem.N - 1 || cy < 1 || cy >= mem.N - 1) { clear = rr; break; }
      if (mem.occ[cy * mem.N + cx] > 1.05) { clear = rr; break; }
    }
  }
  const ed2 = edgeDist(mem, mem.x, mem.y, a, 2.5);
  if (ed2 < clear) clear = ed2;

  if (clear < 0.75) vmax = 0;
  else if (clear < 2.6) vmax = Math.min(vmax, Math.max(0.08, (clear - 0.55) * 0.85));

  const err = wrapPi(a - h);
  let omega = clamp(2.05 * err, -2.2, 2.2);
  let vl = vmax - omega * 0.3;
  let vr = vmax + omega * 0.3;

  if (vmax < 0.035) {
    if (Math.abs(err) > 0.08) {
      const turn = clamp(2.1 * err, -1.5, 1.5);
      vl = -turn * 0.3;
      vr = turn * 0.3;
    } else {
      vl = 0;
      vr = 0;
    }
  }

  vl = clamp(vl, -3.0, 3.0);
  vr = clamp(vr, -3.0, 3.0);
  mem.lastSteerWorld = a;
  mem.lastSteerT = now;
  return applyWheels(mem, obs, vl, vr, dt);
}

function navTo(mem, obs, now, dt, gx, gy, speed, stopDist, key) {
  const dx = gx - mem.x, dy = gy - mem.y;
  const d = Math.hypot(dx, dy);
  if (d <= stopDist + 0.08) return holdCmd(mem, obs, dt, false);

  let wx = gx, wy = gy;
  const usePath = d > 5.0;
  if (usePath) {
    let need = false;
    if (!mem.path || mem.pathKey !== key || now - (mem.pathT || -9999) > 1.5 ||
        !mem.pathGoal || Math.hypot(mem.pathGoal.x - gx, mem.pathGoal.y - gy) > 2.5) {
      need = true;
    }
    if (need) {
      const res = planPath(mem, mem.x, mem.y, gx, gy);
      mem.path = res.pts || [];
      mem.pathFound = !!res.found;
      mem.pathT = now;
      mem.pathGoal = { x: gx, y: gy };
      mem.pathKey = key;
      mem.pathI = 0;
    }
    const pts = mem.path || [];
    while (mem.pathI < pts.length &&
           Math.hypot(pts[mem.pathI].x - mem.x, pts[mem.pathI].y - mem.y) < 2.0) {
      mem.pathI++;
    }
    if (mem.pathI < pts.length) {
      let p = pts[mem.pathI];
      let li = mem.pathI;
      let accum = Math.hypot(p.x - mem.x, p.y - mem.y);
      while (li + 1 < pts.length && accum < 3.8) {
        const q = pts[li + 1];
        accum += Math.hypot(q.x - p.x, q.y - p.y);
        p = q;
        li++;
      }
      wx = p.x;
      wy = p.y;
    }
  }

  let desired = Math.atan2(wy - mem.y, wx - mem.x);
  if (!isFinite(desired)) desired = mem.h;
  return steerTo(mem, obs, now, dt, desired, d, stopDist, speed);
}

function startRecovery(mem, obs, now, why) {
  if (now < (mem.recoverUntil || -1) - 0.05) return;
  mem.recoverUntil = now + (why === "bump" ? 1.15 : 0.95);
  mem.recoverStart = now;

  const rays = obs.rays || [];
  let left = 0, right = 0;
  for (let i = 0; i < 9; i++) {
    let d = Number(rays[i]);
    if (!isFinite(d) || d < 0 || d > 15) d = 9;
    if (i <= 3) right += d;
    else if (i >= 5) left += d;
  }
  let side = (left >= right) ? 1 : -1;
  if (why === "bump" && Math.abs(left - right) < 0.8) side = mem.recoverSide || 1;
  mem.recoverSide = side;

  mem.path = null;
  mem.pathKey = "";
  mem.lastSteerWorld = null;

  if (mem.phase === "drill") {
    mem.drillState = null;
    mem.phase = mem.target ? "toSite" : "idle";
  }

  const bx = mem.x + Math.cos(mem.h) * 0.9;
  const by = mem.y + Math.sin(mem.h) * 0.9;
  markOcc(mem, bx, by, why === "bump" ? 5.0 : 2.5);

  if (mem.phase === "toHint" || mem.phase === "search" ||
      mem.phase === "toSite" || mem.phase === "drill") {
    mem.targetStuck = (mem.targetStuck || 0) + 1;
  }
}

function makeSpiral(cx, cy, R, spacing, size, off) {
  const pts = [{ x: clamp(cx, 3, size - 3), y: clamp(cy, 3, size - 3) }];
  let last = pts[0];
  const turns = R / spacing;
  const maxA = Math.PI * 2 * turns;
  for (let aa = 0; aa <= maxA + 0.1; aa += 0.24) {
    const r = spacing * aa / (Math.PI * 2);
    if (r > R + 0.01) break;
    const ang = aa + off;
    let x = cx + Math.cos(ang) * r;
    let y = cy + Math.sin(ang) * r;
    x = clamp(x, 3, size - 3);
    y = clamp(y, 3, size - 3);
    if (Math.hypot(x - last.x, y - last.y) > 2.1) {
      pts.push({ x: x, y: y });
      last = { x: x, y: y };
    }
  }
  const ex = clamp(cx + Math.cos(maxA + off) * R, 3, size - 3);
  const ey = clamp(cy + Math.sin(maxA + off) * R, 3, size - 3);
  if (Math.hypot(ex - last.x, ey - last.y) > 1.5) pts.push({ x: ex, y: ey });
  return pts;
}

function startSearch(mem, now, hintIdx, cx, cy, exploreId) {
  let rel = 0.45;
  if (hintIdx >= 0 && mem.hints[hintIdx]) {
    rel = clamp(mem.hints[hintIdx].val / Math.max(0.000001, mem.maxHintVal), 0, 1.4);
  }
  const R = clamp(14.0 + 7.0 * Math.sqrt(Math.min(1.2, rel)), 13, 22);
  const off = (mem.searchCount = (mem.searchCount || 0) + 0.77);
  const pts = makeSpiral(cx, cy, R, 8.0, mem.size, off);
  const maxT = Math.min(90, 35 + 45 * Math.min(1, rel));
  mem.search = {
    hintIdx: hintIdx,
    exploreId: exploreId,
    cx: cx, cy: cy, R: R,
    pts: pts,
    i: 0,
    start: now,
    deadline: now + maxT,
    lastAdv: now,
    bestSci: 0
  };
  mem.phase = "search";
  mem.target = null;
  mem.path = null;
  mem.pathKey = "";
}

function finishSearch(mem, success) {
  const s = mem.search;
  if (s) {
    if (s.hintIdx >= 0 && mem.hints[s.hintIdx] && mem.hints[s.hintIdx].state === 0) {
      mem.hints[s.hintIdx].state = success ? 1 : 2;
    }
    if (s.exploreId != null && mem.explorePts[s.exploreId]) {
      mem.explorePts[s.exploreId].visited = true;
    }
  }
  mem.search = null;
  mem.phase = "idle";
  mem.activeHint = -1;
  mem.target = null;
  mem.path = null;
  mem.pathKey = "";
}

function failHint(mem, now) {
  if (mem.targetHint) {
    if (mem.targetHint.idx >= 0 && mem.hints[mem.targetHint.idx] &&
        mem.hints[mem.targetHint.idx].state === 0) {
      mem.hints[mem.targetHint.idx].state = 2;
    }
    if (mem.targetHint.exploreId != null &&
        mem.explorePts[mem.targetHint.exploreId]) {
      mem.explorePts[mem.targetHint.exploreId].visited = true;
    }
  }
  mem.targetHint = null;
  mem.phase = "idle";
  mem.activeHint = -1;
  mem.path = null;
  mem.pathKey = "";
}

function abortSite(mem, now) {
  if (mem.target) addIgnore(mem, mem.target.x, mem.target.y, now + 80);
  mem.target = null;
  mem.drillState = null;
  if (mem.search) {
    mem.phase = "search";
  } else if (mem.activeHint >= 0 && mem.hints[mem.activeHint] &&
             mem.hints[mem.activeHint].state === 0) {
    mem.phase = "toHint";
  } else {
    mem.phase = "idle";
  }
  mem.path = null;
  mem.pathKey = "";
}

function noteSample(mem, now, sx, sy) {
  let bi = -1, bd = 32;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (!h || h.state !== 0) continue;
    const d = Math.hypot(h.x - sx, h.y - sy);
    if (d < bd) { bd = d; bi = i; }
  }
  if (bi >= 0) mem.hints[bi].state = 1;
  if (mem.activeHint >= 0 && mem.hints[mem.activeHint] &&
      mem.hints[mem.activeHint].state === 0) {
    const h = mem.hints[mem.activeHint];
    if (Math.hypot(h.x - sx, h.y - sy) < 42) h.state = 1;
  }
  mem.drillAttempts = 0;
}

function chooseHint(mem, obs, now, timeLeft, battery) {
  let best = -1, bestScore = 1e100;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (!h || h.state !== 0) continue;
    const d = Math.hypot(h.x - mem.x, h.y - mem.y);
    const db = Math.hypot(h.x - mem.baseX, h.y - mem.baseY);
    const rel = clamp(h.val / Math.max(0.000001, mem.maxHintVal), 0, 1.4);
    const tNeed = (d + db) / 1.1 + 15 + 52 * Math.sqrt(rel + 0.08);
    if (timeLeft < tNeed + 8) continue;
    const eNeed = (d + db + 40) * Math.max(0.0005, mem.ePerM) * 1.5 + 0.10;
    if (battery < eNeed) continue;

    let score;
    if (mem.deliveredSamples === 0) {
      score = d + 0.35 * db + 9 - 4.0 * rel;
    } else {
      score = (d + 0.35 * db + 10) / (0.72 + 0.75 * Math.sqrt(rel));
    }
    if (score < bestScore) {
      bestScore = score;
      best = i;
    }
  }
  return best;
}

function chooseExplorePoint(mem, obs, now, timeLeft, battery) {
  if (!mem.explorePts || mem.explorePts.length === 0) return null;
  for (let i = 0; i < mem.explorePts.length; i++) {
    const p = mem.explorePts[i];
    if (!p.visited && Math.hypot(p.x - mem.x, p.y - mem.y) < 9) p.visited = true;
  }
  let best = null, bestScore = 1e100;
  for (let i = 0; i < mem.explorePts.length; i++) {
    const p = mem.explorePts[i];
    if (p.visited) continue;
    const d = Math.hypot(p.x - mem.x, p.y - mem.y);
    const db = Math.hypot(p.x - mem.baseX, p.y - mem.baseY);
    if (timeLeft < d / 1.0 + 25) continue;
    const eNeed = (d + db + 30) * Math.max(0.0005, mem.ePerM) * 1.5 + 0.08;
    if (battery < eNeed) continue;
    const score = d + 0.25 * db;
    if (score < bestScore) {
      bestScore = score;
      best = p;
    }
  }
  return best;
}

function chooseAndSetTask(mem, obs, now, timeLeft, battery, baseDist) {
  const idx = chooseHint(mem, obs, now, timeLeft, battery);
  if (idx >= 0) {
    const h = mem.hints[idx];
    mem.activeHint = idx;
    mem.phase = "toHint";
    mem.targetHint = { x: h.x, y: h.y, idx: idx, exploreId: null };
    mem.targetStart = now;
    mem.lastProgressT = now;
    mem.bestTargetDist = Math.hypot(h.x - mem.x, h.y - mem.y);
    mem.targetStuck = 0;
    mem.target = null;
    mem.search = null;
    mem.path = null;
    mem.pathKey = "";
    return true;
  }

  const ep = chooseExplorePoint(mem, obs, now, timeLeft, battery);
  if (ep) {
    mem.activeHint = -1;
    mem.phase = "toHint";
    mem.targetHint = { x: ep.x, y: ep.y, idx: -1, exploreId: ep.id };
    mem.targetStart = now;
    mem.lastProgressT = now;
    mem.bestTargetDist = Math.hypot(ep.x - mem.x, ep.y - mem.y);
    mem.targetStuck = 0;
    mem.target = null;
    mem.search = null;
    mem.path = null;
    mem.pathKey = "";
    return true;
  }

  const sci = Number(obs.science) || 0;
  if (sci > 0.000005 && timeLeft > 70) {
    startSearch(mem, now, -2, mem.x, mem.y, null);
    return true;
  }
  return false;
}

function goBase(mem, obs, now, dt, timeLeft, battery) {
  const b = obs.beacon;
  if (b && b.distance != null && isFinite(Number(b.distance)) && Number(b.distance) < 20) {
    const bd = Number(b.distance);
    if (bd <= 1.15) return holdCmd(mem, obs, dt, false);
    let desired = mem.h + (Number(b.bearing) || 0) * D2R;
    let sp = 2.0;
    if (timeLeft < 70) sp = 2.4;
    if (battery < 0.22) sp = Math.min(sp, 1.5);
    return steerTo(mem, obs, now, dt, desired, bd, 0.9, sp);
  }
  const d = Math.hypot(mem.baseX - mem.x, mem.baseY - mem.y);
  if (d <= 1.15) return holdCmd(mem, obs, dt, false);
  let sp = 1.95;
  if (timeLeft < 70) sp = 2.35;
  if (battery < 0.22) sp = Math.min(sp, 1.5);
  return navTo(mem, obs, now, dt, mem.baseX, mem.baseY, sp, 0.9, "BASE");
}

function act(obs, mem) {
  try {
    if (!mem.init) initMem(obs, mem);

    let now = (obs.t != null && isFinite(Number(obs.t))) ? Number(obs.t) : (mem.tick || 0) * 0.1;
    let dt = 0.1;
    if (mem.lastT != null && now > mem.lastT) {
      dt = clamp(now - mem.lastT, 0.02, 0.5);
    }
    mem.lastT = now;
    mem.tick = (mem.tick || 0) + 1;

    const timeLeft = (obs.timeLeft != null && isFinite(Number(obs.timeLeft))) ?
      Number(obs.timeLeft) : Math.max(0, mem.seconds - now);
    let battery = (obs.battery != null && isFinite(Number(obs.battery))) ?
      Number(obs.battery) : (mem.lastBattery || 0);
    const carried = Number(obs.carried) || 0;
    const wl = Number(obs.wheelLeft) || 0;
    const wr = Number(obs.wheelRight) || 0;
    const roverSpeed = Math.abs((wl + wr) * 0.5);

    updatePose(mem, obs, dt);
    updateEnergy(mem, obs, dt);
    updateMap(mem, obs);

    const prevCarried = mem.carried || 0;
    if (carried > prevCarried) {
      let sx = mem.drillState ? mem.drillState.x : mem.x;
      let sy = mem.drillState ? mem.drillState.y : mem.y;
      noteSample(mem, now, sx, sy);
      if (mem.search && mem.search.exploreId != null && mem.explorePts[mem.search.exploreId]) {
        mem.explorePts[mem.search.exploreId].visited = true;
      }
      mem.drillState = null;
      mem.target = null;
      mem.search = null;
      mem.targetHint = null;
      mem.activeHint = -1;
      mem.phase = "return";
      mem.path = null;
      mem.pathKey = "";
      mem.chargeWaitStart = null;
    }
    if (carried < prevCarried) {
      mem.deliveredSamples += (prevCarried - carried);
      mem.lastDelivery = now;
      mem.drillState = null;
      mem.target = null;
      mem.search = null;
      mem.targetHint = null;
      mem.activeHint = -1;
      mem.phase = "idle";
      mem.path = null;
      mem.pathKey = "";
      mem.chargeWaitStart = now;
      mem.chargeBattery = battery;
      mem.chargeCheck = now;
      mem.targetStuck = 0;
    }
    mem.carried = carried;

    if (obs.bumped && !mem.lastBumped) {
      startRecovery(mem, obs, now, "bump");
    }
    mem.lastBumped = !!obs.bumped;

    if (now < (mem.recoverUntil || -1)) {
      const el = now - mem.recoverStart;
      let tl, tr;
      if (el < 0.48) {
        tl = -0.65;
        tr = -0.65;
      } else {
        const side = mem.recoverSide || 1;
        tl = -0.38 * side;
        tr = 0.58 * side;
      }
      return applyWheels(mem, obs, tl, tr, dt);
    }

    if (mem.targetStuck > 2 &&
        mem.phase !== "idle" && mem.phase !== "return") {
      if (mem.phase === "search") finishSearch(mem, false);
      else if (mem.phase === "toHint") failHint(mem, now);
      else if (mem.phase === "toSite" || mem.phase === "drill") abortSite(mem, now);
      mem.targetStuck = 0;
    }

    const beacon = obs.beacon;
    let beaconDist = null, beaconBearing = 0;
    if (beacon && beacon.distance != null && isFinite(Number(beacon.distance))) {
      beaconDist = Number(beacon.distance);
      beaconBearing = Number(beacon.bearing) || 0;
    }
    const coordDist = Math.hypot(mem.baseX - mem.x, mem.baseY - mem.y);
    let baseDist = (beaconDist != null && beaconDist < 25) ? Math.min(coordDist, beaconDist) : coordDist;
    const atBase = !!obs.docked ||
      (beaconDist != null && beaconDist <= 3.0) ||
      coordDist <= 2.55;

    if (timeLeft < 4 && carried === 0) {
      return holdCmd(mem, obs, dt, false);
    }

    if (carried > 0 || mem.phase === "return") {
      if (atBase) return holdCmd(mem, obs, dt, false);
      return goBase(mem, obs, now, dt, timeLeft, battery);
    }

    if (!atBase && mem.phase !== "returnEmpty") {
      const needE = (baseDist + 8) * Math.max(0.00045, mem.ePerM * 1.6) + 0.075;
      if (battery < needE && timeLeft > 15) {
        mem.phase = "returnEmpty";
      }
    }
    if (mem.phase === "returnEmpty") {
      if (atBase) mem.phase = "idle";
      else return goBase(mem, obs, now, dt, timeLeft, battery);
    }

    if (atBase) {
      if (mem.phase === "return") mem.phase = "idle";
      let targetCharge;
      if (timeLeft > 600) targetCharge = 0.85;
      else if (timeLeft > 320) targetCharge = 0.70;
      else if (timeLeft > 150) targetCharge = 0.55;
      else targetCharge = 0.42;

      const needCharge = (battery < targetCharge - 0.005) && (timeLeft > 85);
      if (needCharge) {
        if (mem.chargeWaitStart == null) {
          mem.chargeWaitStart = now;
          mem.chargeBattery = battery;
          mem.chargeCheck = now;
        }
        let maxWait = 32;
        if (battery < 0.30) maxWait = 65;
        if (timeLeft < 170) maxWait = Math.min(maxWait, 15);
        if (now - mem.chargeCheck > 5.5) {
          if (battery < mem.chargeBattery + 0.004 && obs.docked) {
            mem.chargeWaitStart = now - (maxWait - 4);
          }
          mem.chargeBattery = battery;
          mem.chargeCheck = now;
        }
        if (now - mem.chargeWaitStart < maxWait) {
          if (!obs.docked && coordDist > 0.8 && beaconDist != null && beaconDist < 20) {
            let desired = mem.h + beaconBearing * D2R;
            return steerTo(mem, obs, now, dt, desired, beaconDist, 0.55, 0.5);
          }
          return holdCmd(mem, obs, dt, false);
        }
      } else {
        mem.chargeWaitStart = null;
      }
    }

    if (obs.site && carried === 0 && !mem.drillState && mem.phase !== "drill") {
      const sd = Number(obs.site.distance);
      const sb = Number(obs.site.bearing);
      const sv = Number(obs.site.value);
      if (isFinite(sd) && isFinite(sb) && isFinite(sv) && sd >= 0 && sd <= 8.2 && sv > 0) {
        const wx = mem.x + Math.cos(mem.h + sb * D2R) * sd;
        const wy = mem.y + Math.sin(mem.h + sb * D2R) * sd;
        if (!isIgnored(mem, wx, wy, now)) {
          const curr = mem.target;
          let should = false;
          if (mem.phase !== "toSite" && mem.phase !== "drill") should = true;
          else if (!curr) should = true;
          else if (Math.hypot(curr.x - wx, curr.y - wy) > 5.5 && sd < 4.5) should = true;
          else if (now - (curr.lastSeen || -9999) > 2.5 && sd < 6.0) should = true;

          if (should) {
            mem.target = {
              x: wx, y: wy, val: sv, lastSeen: now, hint: mem.activeHint
            };
            mem.phase = "toSite";
            mem.path = null;
            mem.pathKey = "";
            mem.targetStart = now;
            mem.lastProgressT = now;
            mem.bestTargetDist = sd;
            mem.targetStuck = 0;
            mem.drillAttempts = 0;
          } else if (curr) {
            if (Math.hypot(curr.x - wx, curr.y - wy) < 5.0 || sd < 3.0) {
              curr.x = wx;
              curr.y = wy;
              curr.val = sv;
              curr.lastSeen = now;
            }
          }
        }
      }
    }

    if (atBase && mem.phase === "idle") {
      if (!chooseAndSetTask(mem, obs, now, timeLeft, battery, baseDist)) {
        return holdCmd(mem, obs, dt, false);
      }
    }

    if (mem.phase === "toHint") {
      const th = mem.targetHint;
      if (!th) {
        mem.phase = "idle";
        return holdCmd(mem, obs, dt, false);
      }
      const d = Math.hypot(th.x - mem.x, th.y - mem.y);
      if (d < (mem.bestTargetDist || 1e9) - 0.5) {
        mem.bestTargetDist = d;
        mem.lastProgressT = now;
      }
      if (d <= 3.2) {
        startSearch(mem, now, th.idx, th.x, th.y, th.exploreId);
        return holdCmd(mem, obs, dt, false);
      }
      if (now - (mem.targetStart || now) > 220 ||
          now - (mem.lastProgressT || now) > 60) {
        failHint(mem, now);
        return holdCmd(mem, obs, dt, false);
      }
      let sp = 1.85;
      if (timeLeft < 160) sp = 2.1;
      let key = "H" + (th.idx >= 0 ? th.idx : ("E" + th.exploreId));
      return navTo(mem, obs, now, dt, th.x, th.y, sp, 1.0, key);
    }

    if (mem.phase === "search") {
      const s = mem.search;
      if (!s) {
        mem.phase = "idle";
        return holdCmd(mem, obs, dt, false);
      }
      const sci = Number(obs.science) || 0;
      if (sci > s.bestSci) s.bestSci = sci;

      let advanced = false;
      while (s.i < s.pts.length &&
             Math.hypot(s.pts[s.i].x - mem.x, s.pts[s.i].y - mem.y) < 2.2) {
        s.i++;
        advanced = true;
      }
      if (advanced) s.lastAdv = now;

      if (s.i >= s.pts.length || now > s.deadline ||
          now - s.lastAdv > 24 ||
          (now - s.start > 12 && s.bestSci < 0.0000001 &&
           Math.hypot(s.cx - mem.x, s.cy - mem.y) < 55)) {
        finishSearch(mem, false);
        return holdCmd(mem, obs, dt, false);
      }

      const p = s.pts[s.i];
      let sp = 1.55;
      if (timeLeft < 160) sp = 1.75;
      let key = "S" + (s.hintIdx >= 0 ? s.hintIdx : ("X" + s.i + "_" + Math.floor(s.start)));
      return navTo(mem, obs, now, dt, p.x, p.y, sp, 0.45, key);
    }

    if (mem.phase === "toSite" || mem.phase === "drill") {
      if (mem.phase === "drill" && mem.drillState) {
        const ds = mem.drillState;
        let liveDist = null;
        if (obs.site && Number(obs.site.distance) != null &&
            isFinite(Number(obs.site.distance))) {
          liveDist = Number(obs.site.distance);
        }
        if (liveDist != null && liveDist > 2.5) ds.out = (ds.out || 0) + 1;
        else ds.out = 0;

        if (now - ds.start > 15.5 || (ds.out || 0) > 10 || battery < 0.018) {
          mem.drillState = null;
          mem.drillAttempts = (mem.drillAttempts || 0) + 1;
          if (mem.drillAttempts >= 2) {
            abortSite(mem, now);
            return holdCmd(mem, obs, dt, false);
          }
          mem.phase = "toSite";
          return holdCmd(mem, obs, dt, false);
        }
        return holdCmd(mem, obs, dt, true);
      }

      const t = mem.target;
      if (!t) {
        mem.phase = "idle";
        return holdCmd(mem, obs, dt, false);
      }

      let liveDist = null;
      let liveAng = null;
      if (obs.site && carried === 0) {
        const sd = Number(obs.site.distance);
        const sb = Number(obs.site.bearing);
        const sv = Number(obs.site.value);
        if (isFinite(sd) && isFinite(sb) && isFinite(sv) && sd >= 0 && sd <= 8.4) {
          const wx = mem.x + Math.cos(mem.h + sb * D2R) * sd;
          const wy = mem.y + Math.sin(mem.h + sb * D2R) * sd;
          if (!isIgnored(mem, wx, wy, now) &&
              (Math.hypot(wx - t.x, wy - t.y) < 6.0 ||
               now - (t.lastSeen || -9999) > 2.0)) {
            liveDist = sd;
            liveAng = mem.h + sb * D2R;
            t.x = wx;
            t.y = wy;
            t.val = sv;
            t.lastSeen = now;
          }
        }
      }

      let d = (liveDist != null) ? liveDist : Math.hypot(t.x - mem.x, t.y - mem.y);
      let desired = (liveAng != null) ? liveAng : Math.atan2(t.y - mem.y, t.x - mem.x);
      if (!isFinite(desired)) desired = mem.h;

      if (d < (mem.bestTargetDist || 1e9) - 0.4) {
        mem.bestTargetDist = d;
        mem.lastProgressT = now;
      }
      if (now - (mem.lastProgressT || now) > 25) {
        mem.drillAttempts = (mem.drillAttempts || 0) + 1;
        if (mem.drillAttempts >= 2) {
          abortSite(mem, now);
          return holdCmd(mem, obs, dt, false);
        }
        mem.lastProgressT = now;
      }

      if (d <= 1.45 && roverSpeed < 0.16) {
        mem.phase = "drill";
        mem.drillState = {
          start: now,
          x: t.x,
          y: t.y,
          hint: mem.activeHint,
          carried0: carried,
          out: 0
        };
        return holdCmd(mem, obs, dt, true);
      }

      if (d <= 1.55) {
        return holdCmd(mem, obs, dt, false);
      }

      let sp;
      if (d > 6.0) sp = 1.75;
      else if (d > 3.5) sp = 1.05;
      else if (d > 2.2) sp = 0.62;
      else sp = 0.28;
      if (timeLeft < 120) sp = Math.min(2.0, sp * 1.15);

      const key = "T" + Math.floor(t.x * 2) + "_" + Math.floor(t.y * 2);
      return steerTo(mem, obs, now, dt, desired, d, 1.05, sp);
    }

    if (mem.phase === "idle") {
      if (chooseAndSetTask(mem, obs, now, timeLeft, battery, baseDist)) {
        return holdCmd(mem, obs, dt, false);
      }
      if (!atBase) return goBase(mem, obs, now, dt, timeLeft, battery);
      return holdCmd(mem, obs, dt, false);
    }

    return holdCmd(mem, obs, dt, false);
  } catch (e) {
    return { left: 0, right: 0, drill: false };
  }
}

const D2R = Math.PI / 180;

function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function wrapPi(a) {
  a = a % (Math.PI * 2);
  if (a > Math.PI) a -= Math.PI * 2;
  if (a < -Math.PI) a += Math.PI * 2;
  return a;
}
function dist2(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }

function initMem(obs, mem) {
  mem.init = true;
  const m = obs.mission || {};
  mem.size = Number(m.size) || 400;
  mem.seconds = Number(m.seconds) || 1200;
  mem.cap = Number(m.capacity) || 5;

  mem.baseX = (m.base && isFinite(Number(m.base.x))) ? Number(m.base.x) : (Number(obs.x) || 0);
  mem.baseY = (m.base && isFinite(Number(m.base.y))) ? Number(m.base.y) : (Number(obs.y) || 0);

  mem.x = isFinite(Number(obs.x)) ? Number(obs.x) : mem.baseX;
  mem.y = isFinite(Number(obs.y)) ? Number(obs.y) : mem.baseY;
  mem.h = (Number(obs.heading) || 0) * D2R;
  mem.lastRawH = mem.h;
  mem.hJumpCount = 0;
  mem.lastRawX = mem.x;
  mem.lastRawY = mem.y;
  mem.lastT = (obs.t != null && isFinite(Number(obs.t))) ? Number(obs.t) : 0;
  mem.tick = 0;
  mem.lastBattery = (obs.battery != null && isFinite(Number(obs.battery))) ? Number(obs.battery) : 1;
  mem.prevCarried = Number(obs.carried) || 0;

  mem.ePerM = 0.0015;
  mem.eCost = 0;
  mem.eDist = 0;
  mem.traction = 1.0;
  mem.moveDist = 0;
  mem.wheelAvg = 0;
  mem.yawRate = 0;
  mem.gpsFrozen = false;
  mem.freezeT = 0;
  mem.stuckT = 0;
  mem.raysBadUntil = -1;
  mem.raysBad = false;
  mem.raysAllMaxT = 0;

  mem.mode = "idle";
  mem.activeHint = -1;
  mem.search = null;
  mem.targetPoint = null;
  mem.searchCount = 0;
  mem.drill = null;
  mem.drillAttempts = 0;
  mem.siteX = null;
  mem.siteY = null;
  mem.siteVal = 0;
  mem.siteLastSeen = -9999;
  mem.siteDist = null;
  mem.ignore = [];
  mem.lastMoveWorld = null;
  mem.recoverUntil = -1;
  mem.recoverStart = -1;
  mem.recoverSide = 1;
  mem.lastBumped = false;
  mem.samplesCollected = 0;
  mem.deliveredSamples = 0;
  mem.lastSampleT = -9999;
  mem.lastDelivery = -9999;
  mem.chargeStart = -9999;
  mem.chargeBattStart = 0;

  mem.wcL = { i: 0, eff: 2.6, dz: 0.035 };
  mem.wcR = { i: 0, eff: 2.6, dz: 0.035 };
  mem.hcL = { i: 0, prev: null, acc: 0 };
  mem.hcR = { i: 0, prev: null, acc: 0 };

  mem.hints = [];
  const hl = (m.hints && m.hints.length) ? m.hints : [];
  let maxV = 0.000001;
  for (let i = 0; i < hl.length; i++) {
    const q = hl[i];
    let x = Number(q.x), y = Number(q.y), v = Number(q.estimate);
    if (!isFinite(x) || !isFinite(y)) continue;
    if (!isFinite(v) || v <= 0) v = 0.000001;
    x = clamp(x, 2, mem.size - 2);
    y = clamp(y, 2, mem.size - 2);
    mem.hints.push({ x: x, y: y, val: v, state: 0 });
    if (v > maxV) maxV = v;
  }
  mem.maxHintVal = maxV;

  mem.explorePts = [];
  const step = Math.max(45, mem.size / 8);
  for (let x = step * 0.5; x < mem.size - 8; x += step) {
    for (let y = step * 0.5; y < mem.size - 8; y += step) {
      mem.explorePts.push({ x: x, y: y, visited: false, id: mem.explorePts.length });
    }
  }
}

function updatePose(mem, obs, now, dt) {
  const wl = Number(obs.wheelLeft) || 0;
  const wr = Number(obs.wheelRight) || 0;
  mem.wheelAvg = (wl + wr) * 0.5;
  mem.yawRate = (wr - wl) / 0.6;

  let rawHdeg = Number(obs.heading);
  let rawH = isFinite(rawHdeg) ? rawHdeg * D2R : mem.lastRawH;
  if (mem.lastRawH == null) mem.lastRawH = rawH;
  const expYaw = mem.yawRate * dt;
  const deltaRaw = wrapPi(rawH - mem.lastRawH);
  let jump = Math.abs(deltaRaw);
  let accept = true;
  if (jump > 1.0 && Math.abs(expYaw) < 0.35 && mem.tick > 5) {
    mem.hJumpCount = (mem.hJumpCount || 0) + 1;
    if (mem.hJumpCount < 8) accept = false;
    else mem.hJumpCount = 0;
  } else {
    mem.hJumpCount = 0;
  }

  if (accept) {
    const pred = wrapPi(mem.h + expYaw);
    const err = wrapPi(rawH - pred);
    const alpha = Math.abs(err) > 1.0 ? 0.25 : 0.60;
    mem.h = wrapPi(pred + clamp(err, -0.7, 0.7) * alpha);
    mem.lastRawH = rawH;
  } else {
    mem.h = wrapPi(mem.h + expYaw);
  }

  const prevX = mem.x, prevY = mem.y;
  let rawX = Number(obs.x), rawY = Number(obs.y);
  if (isFinite(rawX) && isFinite(rawY)) {
    const stepRaw = dist2(rawX, rawY, mem.lastRawX, mem.lastRawY);
    const wheelStep = Math.abs(mem.wheelAvg) * dt;
    if (wheelStep > 0.015 && stepRaw < 0.006 && !obs.bumped) mem.freezeT += dt;
    else mem.freezeT = Math.max(0, mem.freezeT - dt * 1.5);
    if (mem.freezeT > 1.5) mem.gpsFrozen = true;
    if (stepRaw > 0.12) mem.gpsFrozen = false;

    if (mem.gpsFrozen && stepRaw > 1.0) {
      mem.x = rawX;
      mem.y = rawY;
      mem.lastRawX = rawX;
      mem.lastRawY = rawY;
      mem.gpsFrozen = false;
    } else if (!mem.gpsFrozen) {
      const plausible = stepRaw < Math.max(5.0, Math.abs(mem.wheelAvg) * dt * 12 + 2.5);
      if (plausible) {
        const alpha = stepRaw > 2.5 ? 0.85 : 0.55;
        mem.x += (rawX - mem.x) * alpha;
        mem.y += (rawY - mem.y) * alpha;
        mem.lastRawX = rawX;
        mem.lastRawY = rawY;
      } else {
        mem.x += Math.cos(mem.h) * mem.wheelAvg * dt;
        mem.y += Math.sin(mem.h) * mem.wheelAvg * dt;
      }
    } else {
      mem.x += Math.cos(mem.h) * mem.wheelAvg * dt;
      mem.y += Math.sin(mem.h) * mem.wheelAvg * dt;
    }
  } else {
    mem.x += Math.cos(mem.h) * mem.wheelAvg * dt;
    mem.y += Math.sin(mem.h) * mem.wheelAvg * dt;
  }

  mem.x = clamp(mem.x, 0.2, mem.size - 0.2);
  mem.y = clamp(mem.y, 0.2, mem.size - 0.2);
  mem.moveDist = dist2(mem.x, mem.y, prevX, prevY);

  const b = obs.beacon;
  if (!mem.gpsFrozen && b && b.distance != null && isFinite(Number(b.distance)) &&
      Number(b.distance) < 20) {
    const expected = Math.atan2(mem.baseY - mem.y, mem.baseX - mem.x);
    const observed = mem.h + (Number(b.bearing) || 0) * D2R;
    const e = wrapPi(expected - observed);
    if (Math.abs(e) < 0.8) mem.h = wrapPi(mem.h + e * 0.15);
  }
}

function updateEnergy(mem, obs, dt, now) {
  const batt = (obs.battery != null && isFinite(Number(obs.battery))) ?
    Number(obs.battery) : (mem.lastBattery || 1);
  const solar = Number(obs.solar) || 0;
  if (!obs.docked && mem.mode !== "drill" && mem.moveDist > 0.01 &&
      Math.abs(mem.wheelAvg) > 0.08) {
    const cost = (mem.lastBattery || 0) - batt + solar * dt;
    if (cost > 0) {
      mem.eCost += cost;
      mem.eDist += mem.moveDist;
    }
    if (mem.eDist > 10) {
      const es = mem.eCost / mem.eDist;
      if (es > 0.00001 && es < 0.05) {
        mem.ePerM = clamp(mem.ePerM * 0.80 + es * 0.20, 0.0002, 0.03);
      }
      mem.eCost = 0;
      mem.eDist = 0;
    }
  }

  if (!mem.gpsFrozen && Math.abs(mem.wheelAvg) > 0.2 && mem.moveDist > 0.005) {
    const pred = Math.abs(mem.wheelAvg) * dt;
    if (pred > 0.01) {
      const ratio = mem.moveDist / pred;
      if (ratio > 0.05 && ratio < 2.0) {
        mem.traction = clamp((mem.traction || 1) * 0.98 + ratio * 0.02, 0.30, 1.20);
      }
    }
  }
  mem.lastBattery = batt;
}

function updateRays(mem, obs, now, dt) {
  const rays = obs.rays || [];
  let n = 0, first = null, same = true, allMax = true;
  for (let i = 0; i < 9; i++) {
    const d = Number(rays[i]);
    if (isFinite(d) && d >= 0) {
      n++;
      if (first == null) first = d;
      else if (Math.abs(d - first) > 0.25) same = false;
      if (d < 14.5) allMax = false;
    }
  }
  if (n >= 7 && same && first != null && first < 10) {
    mem.raysBadUntil = now + 4.0;
  }
  mem.raysBad = now < (mem.raysBadUntil || -1);
  if (n >= 7 && same && first != null && allMax) {
    mem.raysAllMaxT = (mem.raysAllMaxT || 0) + dt;
  } else {
    mem.raysAllMaxT = Math.max(0, (mem.raysAllMaxT || 0) - dt * 1.5);
  }
}

function isAtBase(mem, obs) {
  if (obs.docked) return true;
  const b = obs.beacon;
  if (b && b.distance != null && isFinite(Number(b.distance)) &&
      Number(b.distance) <= 2.9) return true;
  const d = dist2(mem.x, mem.y, mem.baseX, mem.baseY);
  if (!mem.gpsFrozen && d <= 2.35) return true;
  if (mem.gpsFrozen && d <= 1.2) return true;
  return false;
}

function normalWheel(st, target, actual, dt) {
  target = clamp(Number(target) || 0, -2.95, 2.95);
  actual = Number(actual) || 0;

  if (Math.abs(target) < 0.015) {
    let u = -1.45 * actual + 0.30 * (st.i || 0);
    st.i = (st.i || 0) * Math.max(0, 1 - 2.0 * dt);
    if (Math.abs(actual) < 0.02 && Math.abs(u) < 0.04) u = 0;
    return clamp(u, -1, 1);
  }

  let err = target - actual;
  st.i = (st.i || 0) + err * dt * 0.55;
  st.i = clamp(st.i, -0.8, 0.8);

  let u = target / Math.max(1.2, st.eff || 2.6) + 1.0 * err + st.i;
  const dz = st.dz || 0.035;
  if (Math.abs(u) > 0.015) {
    if (u > 0) u += dz;
    else u -= dz;
  }

  if (u > 1) {
    u = 1;
    st.i -= err * dt * 0.25;
    st.i = clamp(st.i, -0.8, 0.8);
  } else if (u < -1) {
    u = -1;
    st.i -= err * dt * 0.25;
    st.i = clamp(st.i, -0.8, 0.8);
  }

  if (Math.abs(target) > 0.35 && Math.abs(actual) > 0.10 &&
      target * actual > 0 && Math.abs(u) > 0.05) {
    const denom = Math.max(0.05, Math.abs(u) - dz);
    const est = Math.abs(actual) / denom;
    if (est > 0.5 && est < 8.0) {
      st.eff = clamp((st.eff || 2.6) * 0.997 + est * 0.003, 0.8, 7.0);
    }
  }
  return clamp(u, -1, 1);
}

function applyNormal(mem, obs, tl, tr, dt) {
  let ul = normalWheel(mem.wcL, tl, Number(obs.wheelLeft) || 0, dt);
  let ur = normalWheel(mem.wcR, tr, Number(obs.wheelRight) || 0, dt);
  const p = Number(obs.pitch) || 0;
  if (Math.abs(tl) + Math.abs(tr) > 0.12) {
    const ff = clamp(p * 0.0045, -0.09, 0.09);
    ul = clamp(ul + ff, -1, 1);
    ur = clamp(ur + ff, -1, 1);
  }
  mem.lastCmdL = ul;
  mem.lastCmdR = ur;
  return { left: ul, right: ur, drill: false };
}

function holdPid(st, v, pitch, dt) {
  v = Number(v) || 0;
  if (st.prev == null) st.prev = v;
  const e = -v;
  const accRaw = (v - st.prev) / Math.max(dt, 0.03);
  st.prev = v;
  st.acc = st.acc == null ? accRaw : (st.acc * 0.72 + accRaw * 0.28);

  const ff = clamp(pitch * 0.020, -0.12, 0.12);
  let u0 = 3.20 * e + 0.55 * (st.i || 0) - 0.07 * clamp(st.acc, -12, 12) + ff;
  const sat = (u0 > 1 && e > 0) || (u0 < -1 && e < 0);
  if (!sat) {
    st.i = (st.i || 0) + e * dt * 0.90;
    st.i = clamp(st.i, -0.9, 0.9);
  }
  if (Math.abs(v) < 0.025) st.i *= Math.max(0, 1 - 0.25 * dt);

  let u = 3.20 * e + 0.55 * (st.i || 0) - 0.07 * clamp(st.acc, -12, 12) + ff;
  if (u > 0.015) u += 0.035;
  else if (u < -0.015) u -= 0.035;
  return clamp(u, -1, 1);
}

function holdCmd(mem, obs, dt, drill) {
  const p = Number(obs.pitch) || 0;
  const l = holdPid(mem.hcL, Number(obs.wheelLeft) || 0, p, dt);
  const r = holdPid(mem.hcR, Number(obs.wheelRight) || 0, p, dt);
  mem.lastCmdL = l;
  mem.lastCmdR = r;
  return { left: l, right: r, drill: !!drill };
}

function edgeClearWorld(mem, a, margin) {
  const ca = Math.cos(a), sa = Math.sin(a);
  let e = 1e9;
  if (ca > 1e-6) e = Math.min(e, (mem.size - margin - mem.x) / ca);
  else if (ca < -1e-6) e = Math.min(e, (margin - mem.x) / ca);
  if (sa > 1e-6) e = Math.min(e, (mem.size - margin - mem.y) / sa);
  else if (sa < -1e-6) e = Math.min(e, (margin - mem.y) / sa);
  return Math.max(0, e);
}

function chooseHeading(mem, obs, desiredRel) {
  const rays = obs.rays || [];
  const bad = mem.raysBad;
  let best = wrapPi(desiredRel);
  let bestCost = 1e100;

  for (let deg = -170; deg <= 170; deg += 10) {
    const cand = deg * D2R;
    const angErr = Math.abs(wrapPi(cand - desiredRel));
    let cost = angErr * angErr * 0.65 + angErr * 0.25;

    if (!bad) {
      for (let i = 0; i < 9; i++) {
        let d = Number(rays[i]);
        if (!isFinite(d) || d < 0) continue;
        if (d > 15) d = 15;
        const ra = (-80 + i * 20) * D2R;
        const diff = Math.abs(wrapPi(ra - cand));
        if (diff < 0.95) {
          const prox = Math.max(0, 6 - d);
          cost += prox * prox * (1 - diff / 0.95) * 0.12;
          if (d < 1.2 && diff < 0.5) cost += 120;
          else if (d < 2.2 && diff < 0.65) cost += (2.2 - d) * 10;
        }
      }
    }

    const world = mem.h + cand;
    const ed = edgeClearWorld(mem, world, 2.5);
    if (ed < 6) {
      cost += (6 - ed) * (6 - ed) * 0.50;
      if (ed < 1.2) cost += 150;
    }

    if (mem.lastMoveWorld != null) {
      const dw = Math.abs(wrapPi(world - mem.lastMoveWorld));
      cost += (1 - Math.cos(dw)) * 0.60;
    }

    if (cost < bestCost) {
      bestCost = cost;
      best = cand;
    }
  }
  mem.lastMoveWorld = wrapPi(mem.h + best);
  return best;
}

function clearanceRel(obs, rel) {
  const rays = obs.rays || [];
  let clear = 15;
  for (let i = 0; i < 9; i++) {
    let d = Number(rays[i]);
    if (!isFinite(d) || d < 0) continue;
    if (d > 15) d = 15;
    const ra = (-80 + i * 20) * D2R;
    const diff = Math.abs(wrapPi(ra - rel));
    if (diff < 0.80) {
      const proj = d * Math.cos(diff);
      if (proj < clear) clear = proj;
    }
  }
  return clear;
}

function driveRelative(mem, obs, desiredRel, speed, distToTarget, stopDist, dt) {
  speed = clamp(Number(speed) || 0, 0, 2.55);
  if (distToTarget != null && stopDist != null &&
      distToTarget - stopDist <= 0.10) {
    return holdCmd(mem, obs, dt, false);
  }

  const chosen = chooseHeading(mem, obs, desiredRel);
  const err = wrapPi(chosen);
  let v = speed;

  if (distToTarget != null && stopDist != null) {
    const rem = distToTarget - stopDist;
    if (rem <= 0.15) v = 0;
    else if (rem < 2.4) v = Math.min(v, Math.max(0.10, rem * 0.65));
  }

  if (Math.abs(err) > 1.10) v = 0;
  else if (Math.abs(err) > 0.55) v *= 0.30;
  else v *= Math.max(0.15, Math.cos(err));

  let clear = clearanceRel(obs, chosen);
  if (mem.raysBad) clear = Math.max(clear, 8.0);
  const ed = edgeClearWorld(mem, mem.h + chosen, 2.6);
  if (ed < clear) clear = ed;

  if (clear < 0.75) v = 0;
  else if (clear < 3.0) v = Math.min(v, Math.max(0.06, (clear - 0.55) * 0.75));

  if ((mem.raysAllMaxT || 0) > 10 && v > 1.25) v = 1.25;

  const omega = clamp(2.10 * err - 0.04 * (mem.yawRate || 0), -1.8, 1.8);
  let tl, tr;
  if (v < 0.02 && Math.abs(err) > 0.06) {
    tl = -0.30 * omega;
    tr = 0.30 * omega;
  } else {
    tl = v - 0.30 * omega;
    tr = v + 0.30 * omega;
  }
  tl = clamp(tl, -2.8, 2.8);
  tr = clamp(tr, -2.8, 2.8);
  return applyNormal(mem, obs, tl, tr, dt);
}

function navToWorld(mem, obs, tx, ty, speed, stopDist, dt) {
  const dx = tx - mem.x, dy = ty - mem.y;
  const d = Math.hypot(dx, dy);
  if (!isFinite(d)) return holdCmd(mem, obs, dt, false);
  if (d <= stopDist + 0.08) return holdCmd(mem, obs, dt, false);
  const desired = wrapPi(Math.atan2(dy, dx) - mem.h);
  return driveRelative(mem, obs, desired, speed, d, stopDist, dt);
}

function addIgnore(mem, x, y, until) {
  if (!mem.ignore) mem.ignore = [];
  mem.ignore.push({ x: x, y: y, until: until });
  while (mem.ignore.length > 80) mem.ignore.shift();
}

function isIgnored(mem, x, y, now) {
  if (!mem.ignore) return false;
  for (let i = mem.ignore.length - 1; i >= 0; i--) {
    const q = mem.ignore[i];
    if (now < q.until && Math.hypot(q.x - x, q.y - y) < 3.5) return true;
  }
  return false;
}

function makeSpiral(cx, cy, R, spacing, size, off) {
  const pts = [];
  let lastX = null, lastY = null;
  const maxTheta = Math.PI * 2 * R / spacing;
  for (let a = 0; a <= maxTheta + 0.01; a += 0.24) {
    const r = spacing * a / (Math.PI * 2);
    let x = cx + Math.cos(a + off) * r;
    let y = cy + Math.sin(a + off) * r;
    x = clamp(x, 2, size - 2);
    y = clamp(y, 2, size - 2);
    if (lastX == null || Math.hypot(x - lastX, y - lastY) > 2.0) {
      pts.push({ x: x, y: y });
      lastX = x;
      lastY = y;
    }
  }
  return pts;
}

function startSearch(mem, obs, now, timeLeft, cx, cy, hintIdx, exploreId) {
  let rel = 0.5;
  if (hintIdx >= 0 && mem.hints[hintIdx]) {
    rel = clamp(mem.hints[hintIdx].val / mem.maxHintVal, 0, 1.2);
  }
  let R = clamp(16 + 7 * Math.sqrt(Math.min(1.2, rel)), 14, 23);
  if (timeLeft < 220) R = Math.min(R, 19);
  if (timeLeft < 110) R = Math.min(R, 14);
  if (timeLeft < 55) R = Math.min(R, 10);

  const spacing = 10.5;
  const off = (mem.searchCount = (mem.searchCount || 0) + 0.91);
  const pts = makeSpiral(cx, cy, R, spacing, mem.size, off);
  const pathLen = Math.PI * R * R / spacing;
  let maxT = Math.min(112, 25 + pathLen / 1.25);
  if (timeLeft < maxT + 15) maxT = Math.max(8, timeLeft - 15);

  mem.search = {
    cx: cx, cy: cy, R: R, pts: pts, i: 0,
    start: now, deadline: now + maxT, lastAdv: now,
    lastX: mem.x, lastY: mem.y,
    hintIdx: hintIdx, exploreId: exploreId, maxSci: 0
  };
  mem.mode = "search";
  mem.activeHint = hintIdx;
  mem.targetPoint = null;
  mem.lastMoveWorld = null;
}

function finishSearch(mem, success) {
  const s = mem.search;
  if (s) {
    if (s.hintIdx >= 0 && mem.hints[s.hintIdx] &&
        mem.hints[s.hintIdx].state === 0) {
      mem.hints[s.hintIdx].state = success ? 1 : 2;
    }
    if (s.exploreId != null && mem.explorePts[s.exploreId]) {
      mem.explorePts[s.exploreId].visited = true;
    }
  }
  mem.search = null;
  mem.activeHint = -1;
  mem.targetPoint = null;
  mem.mode = "idle";
}

function markSampled(mem, now) {
  const sx = mem.siteX != null ? mem.siteX : mem.x;
  const sy = mem.siteY != null ? mem.siteY : mem.y;
  let best = -1, bestD = 50;

  if (mem.activeHint >= 0 && mem.hints[mem.activeHint] &&
      mem.hints[mem.activeHint].state === 0) {
    const h = mem.hints[mem.activeHint];
    const d = Math.hypot(h.x - sx, h.y - sy);
    if (d < bestD) {
      best = mem.activeHint;
      bestD = d;
    }
  }

  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (!h || h.state !== 0) continue;
    const d = Math.hypot(h.x - sx, h.y - sy);
    if (d < 25 && d < bestD) {
      best = i;
      bestD = d;
    }
  }

  if (best >= 0) mem.hints[best].state = 1;
  if (mem.search && mem.search.exploreId != null &&
      mem.explorePts[mem.search.exploreId]) {
    mem.explorePts[mem.search.exploreId].visited = true;
  }

  mem.activeHint = -1;
  mem.search = null;
  mem.targetPoint = null;
  mem.drill = null;
}

function chargeTarget(timeLeft) {
  if (timeLeft > 700) return 0.82;
  if (timeLeft > 420) return 0.66;
  if (timeLeft > 220) return 0.50;
  return 0.36;
}

function hintSearchRadius(mem, h, timeLeft) {
  const rel = clamp(h.val / Math.max(0.000001, mem.maxHintVal), 0, 1.2);
  let R = clamp(16 + 7 * Math.sqrt(Math.min(1.2, rel)), 14, 23);
  if (timeLeft < 220) R = Math.min(R, 19);
  if (timeLeft < 110) R = Math.min(R, 14);
  return R;
}

function chooseHint(mem, obs, now, timeLeft, battery, atBase) {
  let best = -1, bestScore = -1e100;

  for (let pass = 0; pass < 2; pass++) {
    best = -1;
    bestScore = -1e100;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.state !== 0) continue;

      const dCur = Math.hypot(h.x - mem.x, h.y - mem.y);
      const dB = Math.hypot(h.x - mem.baseX, h.y - mem.baseY);
      const R = hintSearchRadius(mem, h, timeLeft);
      const pathLen = Math.PI * R * R / 10.5 + 20;
      const tNeed = (dCur + pathLen + dB) / 1.05 + 20;
      const eNeed = (dCur + pathLen + dB + 30) * mem.ePerM * 1.45 + 0.10;
      const feasible = timeLeft > tNeed + 12 && battery > eNeed;
      if (pass === 0 && !feasible) continue;

      const rel = clamp(h.val / Math.max(0.000001, mem.maxHintVal), 0, 1.0);
      let score;
      if (mem.deliveredSamples === 0 && mem.samplesCollected === 0) {
        score = -(dCur + 0.40 * dB + 0.12 * pathLen) + 8 * rel;
      } else {
        score = (0.10 + 1.4 * rel) * 100 /
          (dCur + 0.50 * pathLen + 0.80 * dB + 20);
        if (timeLeft < 300) score *= 100 / (80 + dCur + dB);
      }

      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }
    if (best >= 0) return best;
  }
  return best;
}

function chooseExplorePoint(mem, obs, now, timeLeft, battery) {
  if (!mem.explorePts || mem.explorePts.length === 0) return null;

  for (let i = 0; i < mem.explorePts.length; i++) {
    const p = mem.explorePts[i];
    if (!p.visited && Math.hypot(p.x - mem.x, p.y - mem.y) < 8) {
      p.visited = true;
    }
  }

  let best = null, bestScore = 1e100;
  for (let i = 0; i < mem.explorePts.length; i++) {
    const p = mem.explorePts[i];
    if (p.visited) continue;
    const d = Math.hypot(p.x - mem.x, p.y - mem.y);
    const db = Math.hypot(p.x - mem.baseX, p.y - mem.baseY);
    if (timeLeft < (d + db) / 1.1 + 25) continue;
    const eNeed = (d + db + 20) * mem.ePerM * 1.3 + 0.06;
    if (battery < eNeed) continue;

    let score = d + 0.25 * db;
    if (mem.deliveredSamples === 0 && mem.samplesCollected === 0) score = d;
    if (score < bestScore) {
      bestScore = score;
      best = p;
    }
  }
  return best;
}

function startRecovery(mem, obs, now) {
  if (now < (mem.recoverUntil || -1)) return;
  mem.recoverUntil = now + 1.0;
  mem.recoverStart = now;

  const rays = obs.rays || [];
  let left = 0, right = 0;
  for (let i = 0; i < 9; i++) {
    let d = Number(rays[i]);
    if (!isFinite(d) || d < 0 || d > 15) d = 9;
    if (i <= 3) right += d;
    else if (i >= 5) left += d;
  }
  mem.recoverSide = (left >= right) ? 1 : -1;
  mem.lastMoveWorld = null;

  if (mem.search) mem.search.lastAdv = now;
  if (mem.targetPoint) mem.targetPoint.lastProgress = now;
}

function handleSearch(mem, obs, now, timeLeft, battery, dt) {
  const s = mem.search;
  if (!s) {
    mem.mode = "idle";
    return holdCmd(mem, obs, dt, false);
  }

  const sci = Number(obs.science) || 0;
  if (sci > s.maxSci) s.maxSci = sci;

  while (s.i < s.pts.length &&
         Math.hypot(s.pts[s.i].x - mem.x, s.pts[s.i].y - mem.y) < 1.45) {
    s.i++;
  }

  if (s.lastX == null) {
    s.lastX = mem.x;
    s.lastY = mem.y;
    s.lastAdv = now;
  }
  if (Math.hypot(mem.x - s.lastX, mem.y - s.lastY) > 0.8) {
    s.lastX = mem.x;
    s.lastY = mem.y;
    s.lastAdv = now;
  }

  if (now - s.lastAdv > 8.0 && s.i < s.pts.length) {
    s.i++;
    s.lastAdv = now;
    s.lastX = mem.x;
    s.lastY = mem.y;
  }

  if (s.i >= s.pts.length || now > s.deadline || timeLeft < 12) {
    finishSearch(mem, false);
    return holdCmd(mem, obs, dt, false);
  }

  const p = s.pts[s.i];
  let sp = 1.55;
  if (timeLeft < 150) sp = 1.80;
  if (sci > 0.20) sp = Math.min(sp, 1.35);
  return navToWorld(mem, obs, p.x, p.y, sp, 0.45, dt);
}

function handleGo(mem, obs, now, timeLeft, battery, dt) {
  const tp = mem.targetPoint;
  if (!tp) {
    mem.mode = "idle";
    return holdCmd(mem, obs, dt, false);
  }

  const d = Math.hypot(tp.x - mem.x, tp.y - mem.y);
  if (tp.bestDist == null) {
    tp.bestDist = d;
    tp.lastProgress = now;
    tp.start = now;
  }

  if (d < 4.2) {
    startSearch(mem, obs, now, timeLeft, tp.x, tp.y,
      tp.type === "hint" ? tp.idx : -1,
      tp.type === "explore" ? tp.id : null);
    return holdCmd(mem, obs, dt, false);
  }

  if (d < tp.bestDist - 0.35) {
    tp.bestDist = d;
    tp.lastProgress = now;
  }

  if (now - tp.start > Math.min(220, 35 + d * 1.6) ||
      now - tp.lastProgress > 38) {
    if (tp.type === "hint" && mem.hints[tp.idx] &&
        mem.hints[tp.idx].state === 0) {
      mem.hints[tp.idx].state = 2;
    }
    if (tp.type === "explore" && mem.explorePts[tp.id] != null) {
      mem.explorePts[tp.id].visited = true;
    }
    mem.targetPoint = null;
    mem.activeHint = -1;
    mem.mode = "idle";
    return holdCmd(mem, obs, dt, false);
  }

  let sp = 1.75;
  if (timeLeft < 160) sp = 2.0;
  if (battery < 0.25) sp = Math.min(sp, 1.25);
  return navToWorld(mem, obs, tp.x, tp.y, sp, 0.60, dt);
}

function handleSite(mem, obs, now, timeLeft, battery, carried, dt) {
  if (mem.siteX != null && isIgnored(mem, mem.siteX, mem.siteY, now)) {
    mem.mode = "idle";
    mem.siteX = null;
    mem.siteY = null;
    return holdCmd(mem, obs, dt, false);
  }

  const s = obs.site;
  let have = false;
  let d = 999, bearing = 0;

  if (s && isFinite(Number(s.distance)) && isFinite(Number(s.bearing))) {
    const sd = Number(s.distance);
    if (sd >= 0 && sd <= 8.5) {
      have = true;
      const rawH = (Number(obs.heading) || 0) * D2R;
      const b = (Number(s.bearing) || 0) * D2R;
      mem.siteX = mem.x + Math.cos(rawH + b) * sd;
      mem.siteY = mem.y + Math.sin(rawH + b) * sd;
      mem.siteVal = Number(s.value) || mem.siteVal || 0;
      mem.siteLastSeen = now;
      mem.siteDist = sd;
      d = sd;
      bearing = b;
    }
  }

  if (!have && mem.siteX != null) {
    d = Math.hypot(mem.siteX - mem.x, mem.siteY - mem.y);
    bearing = wrapPi(Math.atan2(mem.siteY - mem.y, mem.siteX - mem.x) - mem.h);
  }

  if (!isFinite(d)) {
    mem.mode = "idle";
    return holdCmd(mem, obs, dt, false);
  }

  if (!have && now - mem.siteLastSeen > 6.0) {
    mem.drillAttempts = (mem.drillAttempts || 0) + 1;
    if (mem.drillAttempts > 2 && mem.siteX != null) {
      addIgnore(mem, mem.siteX, mem.siteY, now + 150);
    }
    mem.mode = "idle";
    return holdCmd(mem, obs, dt, false);
  }

  const vmax = Math.max(Math.abs(Number(obs.wheelLeft) || 0),
                        Math.abs(Number(obs.wheelRight) || 0));

  if (have && d <= 1.38 && vmax < 0.11 && battery > 0.012) {
    mem.mode = "drill";
    mem.drill = { start: now, out: 0 };
    return holdCmd(mem, obs, dt, true);
  }

  if (d <= 1.55) {
    if (vmax > 0.10) return holdCmd(mem, obs, dt, false);
    if (have && d > 1.16) {
      return driveRelative(mem, obs, bearing, 0.18, d, 1.05, dt);
    }
    return holdCmd(mem, obs, dt, false);
  }

  let sp;
  if (d > 6) sp = 1.70;
  else if (d > 3.5) sp = 1.05;
  else if (d > 2.2) sp = 0.62;
  else sp = 0.36;
  if (timeLeft < 100) sp = Math.min(2.0, sp * 1.10);

  return driveRelative(mem, obs, bearing, sp, d, 1.10, dt);
}

function handleDrill(mem, obs, now, timeLeft, battery, carried, dt) {
  if (!mem.drill) {
    mem.mode = "site";
    return holdCmd(mem, obs, dt, false);
  }

  const s = obs.site;
  let have = false;
  if (s && isFinite(Number(s.distance)) && isFinite(Number(s.bearing))) {
    const sd = Number(s.distance);
    if (sd >= 0 && sd <= 8.5) {
      have = true;
      const rawH = (Number(obs.heading) || 0) * D2R;
      const b = (Number(s.bearing) || 0) * D2R;
      mem.siteX = mem.x + Math.cos(rawH + b) * sd;
      mem.siteY = mem.y + Math.sin(rawH + b) * sd;
      mem.siteVal = Number(s.value) || mem.siteVal || 0;
      mem.siteLastSeen = now;
      mem.siteDist = sd;
    }
  }

  const elapsed = now - mem.drill.start;
  if (have && Number(s.distance) > 1.90) mem.drill.out += dt;
  else mem.drill.out = 0;
  if (!have && now - (mem.siteLastSeen || -9999) > 3.0) mem.drill.out += dt;

  if (elapsed > 12.5 || mem.drill.out > 1.2 ||
      battery < 0.018 || (timeLeft < 8 && carried === 0)) {
    mem.drillAttempts = (mem.drillAttempts || 0) + 1;
    mem.drill = null;

    if (mem.drillAttempts >= 3) {
      if (mem.siteX != null) addIgnore(mem, mem.siteX, mem.siteY, now + 150);
      if (mem.activeHint >= 0 && mem.hints[mem.activeHint] &&
          mem.hints[mem.activeHint].state === 0) {
        mem.hints[mem.activeHint].state = 2;
      }
      mem.activeHint = -1;
      mem.search = null;
      mem.mode = (battery < 0.025 || timeLeft < 15) ? "return" : "idle";
    } else {
      mem.mode = (battery < 0.025 || timeLeft < 10) ? "return" : "site";
    }
    return holdCmd(mem, obs, dt, false);
  }

  return holdCmd(mem, obs, dt, true);
}

function handleReturn(mem, obs, now, timeLeft, battery, carried, dt) {
  if (isAtBase(mem, obs)) {
    if (carried > 0) {
      const b = obs.beacon;
      if (!obs.docked && b && b.distance != null &&
          isFinite(Number(b.distance)) && Number(b.distance) > 0.85 &&
          timeLeft > 5) {
        const d = Number(b.distance);
        const br = (Number(b.bearing) || 0) * D2R;
        return driveRelative(mem, obs, br, 0.40, d, 0.55, dt);
      }
      return holdCmd(mem, obs, dt, false);
    }
    mem.mode = "idle";
    return holdCmd(mem, obs, dt, false);
  }

  const b = obs.beacon;
  if (b && b.distance != null && isFinite(Number(b.distance)) &&
      Number(b.distance) < 30) {
    const d = Number(b.distance);
    const br = (Number(b.bearing) || 0) * D2R;
    if (d <= 1.05) return holdCmd(mem, obs, dt, false);
    let sp = 1.90;
    if (timeLeft < 90) sp = 2.25;
    if (battery < 0.22) sp = Math.min(sp, 1.30);
    return driveRelative(mem, obs, br, sp, d, 0.90, dt);
  }

  const d = Math.hypot(mem.baseX - mem.x, mem.baseY - mem.y);
  if (d <= 1.20) return holdCmd(mem, obs, dt, false);

  let sp = 1.85;
  if (timeLeft < 90) sp = 2.20;
  if (battery < 0.22) sp = Math.min(sp, 1.25);
  return navToWorld(mem, obs, mem.baseX, mem.baseY, sp, 1.00, dt);
}

function handleCharge(mem, obs, now, timeLeft, battery, atBase, dt) {
  if (!atBase) {
    mem.mode = "return";
    return handleReturn(mem, obs, now, timeLeft, battery, Number(obs.carried) || 0, dt);
  }

  const target = chargeTarget(timeLeft);
  const elapsed = now - (mem.chargeStart || now);
  if (battery >= target - 0.005 || timeLeft < 75 || elapsed > 125) {
    mem.mode = "idle";
    return holdCmd(mem, obs, dt, false);
  }

  const b = obs.beacon;
  if (!obs.docked && b && b.distance != null && isFinite(Number(b.distance)) &&
      Number(b.distance) > 0.75) {
    const d = Number(b.distance);
    const br = (Number(b.bearing) || 0) * D2R;
    return driveRelative(mem, obs, br, 0.38, d, 0.55, dt);
  }

  return holdCmd(mem, obs, dt, false);
}

function handleIdle(mem, obs, now, timeLeft, battery, atBase, dt) {
  if (timeLeft < 5) return holdCmd(mem, obs, dt, false);

  if (!atBase && battery < 0.18 && timeLeft > 25) {
    mem.mode = "return";
    return handleReturn(mem, obs, now, timeLeft, battery, Number(obs.carried) || 0, dt);
  }

  if (atBase) {
    const target = chargeTarget(timeLeft);
    if (battery < target - 0.02 && timeLeft > 65) {
      mem.mode = "charge";
      mem.chargeStart = now;
      mem.chargeBattStart = battery;
      return holdCmd(mem, obs, dt, false);
    }
  }

  const idx = chooseHint(mem, obs, now, timeLeft, battery, atBase);
  if (idx >= 0) {
    const h = mem.hints[idx];
    const d = Math.hypot(h.x - mem.x, h.y - mem.y);
    mem.activeHint = idx;
    mem.targetPoint = {
      x: h.x, y: h.y, type: "hint", idx: idx,
      start: now, lastProgress: now, bestDist: d
    };
    mem.mode = "goHint";
    return holdCmd(mem, obs, dt, false);
  }

  const sci = Number(obs.science) || 0;
  if (sci > 0.02 && timeLeft > 65) {
    startSearch(mem, obs, now, timeLeft, mem.x, mem.y, -1, null);
    return holdCmd(mem, obs, dt, false);
  }

  const ep = chooseExplorePoint(mem, obs, now, timeLeft, battery);
  if (ep) {
    const d = Math.hypot(ep.x - mem.x, ep.y - mem.y);
    mem.targetPoint = {
      x: ep.x, y: ep.y, type: "explore", id: ep.id,
      start: now, lastProgress: now, bestDist: d
    };
    mem.activeHint = -1;
    mem.mode = "goHint";
    return holdCmd(mem, obs, dt, false);
  }

  if (!atBase) {
    mem.mode = "return";
    return handleReturn(mem, obs, now, timeLeft, battery, Number(obs.carried) || 0, dt);
  }

  return holdCmd(mem, obs, dt, false);
}

function act(obs, mem) {
  try {
    if (!mem.init) initMem(obs, mem);

    let now = (obs.t != null && isFinite(Number(obs.t))) ?
      Number(obs.t) : ((mem.tick || 0) * 0.1);
    let dt = 0.1;
    if (mem.lastT != null && now > mem.lastT) {
      dt = clamp(now - mem.lastT, 0.02, 0.5);
    }
    mem.lastT = now;
    mem.tick = (mem.tick || 0) + 1;

    updatePose(mem, obs, now, dt);
    updateRays(mem, obs, now, dt);

    const carried = Number(obs.carried) || 0;
    const battery = (obs.battery != null && isFinite(Number(obs.battery))) ?
      Number(obs.battery) : (mem.lastBattery || 1);
    const timeLeft = (obs.timeLeft != null && isFinite(Number(obs.timeLeft))) ?
      Number(obs.timeLeft) : Math.max(0, mem.seconds - now);

    updateEnergy(mem, obs, dt, now);

    const atBase = isAtBase(mem, obs);
    const prevCarried = mem.prevCarried || 0;

    if (carried > prevCarried) {
      mem.samplesCollected = (mem.samplesCollected || 0) + (carried - prevCarried);
      markSampled(mem, now);
      mem.lastSampleT = now;
      mem.mode = "return";
      mem.drill = null;
      mem.search = null;
      mem.targetPoint = null;
    } else if (carried < prevCarried) {
      mem.deliveredSamples = (mem.deliveredSamples || 0) + (prevCarried - carried);
      mem.lastDelivery = now;
      mem.mode = "idle";
      mem.drill = null;
      mem.search = null;
      mem.targetPoint = null;
      mem.activeHint = -1;
      mem.chargeStart = now;
      mem.chargeBattStart = battery;
    }
    mem.prevCarried = carried;

    if (obs.bumped && !mem.lastBumped && mem.mode !== "drill") {
      startRecovery(mem, obs, now);
    }
    mem.lastBumped = !!obs.bumped;

    if (!mem.gpsFrozen && mem.mode !== "drill" &&
        Math.abs(mem.wheelAvg || 0) > 0.18 && mem.moveDist < 0.006) {
      mem.stuckT = (mem.stuckT || 0) + dt;
    } else {
      mem.stuckT = Math.max(0, (mem.stuckT || 0) - 2.0 * dt);
    }
    if (mem.stuckT > 2.8 && mem.mode !== "drill") {
      startRecovery(mem, obs, now);
      mem.stuckT = 0;
    }

    if (now < (mem.recoverUntil || -1) && mem.mode !== "drill") {
      const elapsed = now - mem.recoverStart;
      const side = mem.recoverSide || 1;
      if (elapsed < 0.45) {
        return applyNormal(mem, obs, -0.65, -0.65, dt);
      }
      return applyNormal(mem, obs, -0.35 * side, 0.35 * side, dt);
    }

    if (timeLeft < 0.3) return holdCmd(mem, obs, dt, false);

    if (carried > 0 && mem.mode !== "return" && mem.mode !== "charge") {
      mem.mode = "return";
    }

    if (carried === 0 && mem.mode !== "return" && mem.mode !== "charge" &&
        mem.mode !== "drill") {
      const s = obs.site;
      if (s && isFinite(Number(s.distance)) && isFinite(Number(s.bearing))) {
        const sd = Number(s.distance);
        if (sd >= 0 && sd <= 8.4 && Number(s.value) > 0) {
          const rawH = (Number(obs.heading) || 0) * D2R;
          const b = (Number(s.bearing) || 0) * D2R;
          const sx = mem.x + Math.cos(rawH + b) * sd;
          const sy = mem.y + Math.sin(rawH + b) * sd;
          if (!isIgnored(mem, sx, sy, now)) {
            if (mem.mode !== "site") {
              mem.drillAttempts = 0;
              mem.siteLastSeen = now;
              mem.siteX = sx;
              mem.siteY = sy;
              mem.siteVal = Number(s.value) || 0;
              mem.siteDist = sd;
              mem.mode = "site";
            }
          }
        }
      }
    }

    if (mem.mode === "drill") {
      return handleDrill(mem, obs, now, timeLeft, battery, carried, dt);
    }
    if (mem.mode === "site") {
      return handleSite(mem, obs, now, timeLeft, battery, carried, dt);
    }
    if (mem.mode === "return") {
      return handleReturn(mem, obs, now, timeLeft, battery, carried, dt);
    }
    if (mem.mode === "charge") {
      return handleCharge(mem, obs, now, timeLeft, battery, atBase, dt);
    }
    if (mem.mode === "goHint") {
      return handleGo(mem, obs, now, timeLeft, battery, dt);
    }
    if (mem.mode === "search") {
      return handleSearch(mem, obs, now, timeLeft, battery, dt);
    }

    return handleIdle(mem, obs, now, timeLeft, battery, atBase, dt);
  } catch (e) {
    return { left: 0, right: 0, drill: false };
  }
}

const D2R = Math.PI / 180;
function clamp(v,a,b){ return v<a?a:(v>b?b:v); }
function wrap(a){
  a = (a + Math.PI) % (Math.PI*2);
  if (a < 0) a += Math.PI*2;
  return a - Math.PI;
}
function hypot2(x,y){ return Math.sqrt(x*x+y*y); }
function dist2(ax,ay,bx,by){ return Math.sqrt((ax-bx)*(ax-bx)+(ay-by)*(ay-by)); }

function initMem(obs,mem){
  const m = obs.mission || {};
  mem.init = true;
  mem.size = Number(m.size) || 400;
  mem.seconds = Number(m.seconds) || 1200;
  mem.cap = Number(m.capacity) || 5;
  mem.baseX = (m.base && isFinite(Number(m.base.x))) ? Number(m.base.x) : (Number(obs.x)||0);
  mem.baseY = (m.base && isFinite(Number(m.base.y))) ? Number(m.base.y) : (Number(obs.y)||0);

  mem.x = isFinite(Number(obs.x)) ? Number(obs.x) : mem.baseX;
  mem.y = isFinite(Number(obs.y)) ? Number(obs.y) : mem.baseY;
  mem.lastRX = mem.x;
  mem.lastRY = mem.y;
  mem.rawH = isFinite(Number(obs.heading)) ? Number(obs.heading)*D2R : 0;
  mem.hFilt = mem.rawH;
  mem.bias = 0;
  mem.biasValid = false;

  mem.lastT = (obs.t != null && isFinite(Number(obs.t))) ? Number(obs.t) : 0;
  mem.dt = 0.1;
  mem.tick = 0;

  mem.prevCarried = Number(obs.carried)||0;
  mem.delivered = 0;
  mem.collected = 0;
  mem.prevBumped = false;

  mem.mode = "calibrate";
  mem.calStart = mem.lastT;
  mem.calX = mem.x;
  mem.calY = mem.y;
  mem.calSum = 0;
  mem.calCount = 0;
  mem.calH0 = mem.hFilt;

  mem.hints = [];
  mem.maxHintVal = 0.000001;
  const hl = (m.hints && m.hints.length) ? m.hints : [];
  for (let i=0;i<hl.length;i++){
    const q = hl[i];
    let x = Number(q.x), y = Number(q.y), v = Number(q.estimate);
    if (!isFinite(x) || !isFinite(y)) continue;
    x = clamp(x, 3, mem.size-3);
    y = clamp(y, 3, mem.size-3);
    if (!isFinite(v) || v <= 0) v = 0.000001;
    mem.hints.push({x:x,y:y,val:v,state:0});
    if (v > mem.maxHintVal) mem.maxHintVal = v;
  }

  mem.activeHint = -1;
  mem.search = null;
  mem.site = null;
  mem.drill = null;
  mem.ignore = [];
  mem.exploreTarget = null;

  mem.goalStart = mem.lastT;
  mem.lastProgress = mem.lastT;
  mem.bestDist = 1e9;
  mem.goalBumps = 0;

  mem.recoverUntil = -1;
  mem.recoverStart = -1;
  mem.recoverSide = 1;
  mem.stuckCount = 0;
  mem.stuckX = mem.x;
  mem.stuckY = mem.y;
  mem.stuckLastT = mem.lastT;

  mem.vLcmd = 0;
  mem.vRcmd = 0;
  mem.wcL = {i:0, eff:2.4};
  mem.wcR = {i:0, eff:2.4};

  mem.chargeStart = null;
  mem.baseWaitStart = null;
  mem.sitePrevMode = "idle";

  mem.explore = [];
  const step = Math.max(50, mem.size/8);
  let eid = 0;
  for (let x=step*0.5; x<mem.size-8; x+=step){
    for (let y=step*0.5; y<mem.size-8; y+=step){
      mem.explore.push({x:x,y:y,visited:false,id:eid++});
    }
  }
}

function isIgnored(mem,x,y,now){
  if (!mem.ignore) return false;
  for (let i=mem.ignore.length-1;i>=0;i--){
    const q = mem.ignore[i];
    if (now < q.until && dist2(q.x,q.y,x,y) < q.rad) return true;
  }
  return false;
}
function addIgnore(mem,x,y,now,rad,dur){
  if (!isFinite(x) || !isFinite(y)) return;
  mem.ignore.push({x:x,y:y,until:now+(dur||240),rad:rad||5});
  while (mem.ignore.length > 40) mem.ignore.shift();
}

function updatePose(mem,obs,dt){
  const wl = Number(obs.wheelLeft)||0;
  const wr = Number(obs.wheelRight)||0;
  const yawRate = (wr-wl)/0.6;
  const rawIn = Number(obs.heading);
  if (isFinite(rawIn)){
    const raw = rawIn*D2R;
    const pred = wrap(mem.hFilt + yawRate*dt);
    const d = wrap(raw - mem.hFilt);
    if (Math.abs(d) > 1.45 && Math.abs(yawRate) < 0.55 && mem.tick > 5){
      mem.hFilt = pred;
      mem.rawH = raw;
    } else {
      mem.hFilt = wrap(mem.hFilt + 0.62*d);
      mem.rawH = raw;
    }
  } else {
    mem.hFilt = wrap(mem.hFilt + yawRate*dt);
    mem.rawH = mem.hFilt - mem.bias;
  }

  const rgb = wrap(mem.hFilt + mem.bias);
  const v = (wl + wr)*0.5;
  const od = Math.abs(v)*dt;
  const rx = Number(obs.x), ry = Number(obs.y);

  if (isFinite(rx) && isFinite(ry)){
    const step = dist2(rx,ry,mem.lastRX,mem.lastRY);
    if (step < Math.max(1.4, od*8 + 0.8)){
      if (step < 0.02 && od > 0.10){
        mem.x += Math.cos(rgb)*v*dt;
        mem.y += Math.sin(rgb)*v*dt;
        mem.gpsFrozen = (mem.gpsFrozen||0) + dt;
      } else {
        const alpha = step > 3 ? 0.8 : 0.42;
        mem.x += (rx - mem.x)*alpha;
        mem.y += (ry - mem.y)*alpha;
        mem.lastRX = rx;
        mem.lastRY = ry;
        mem.gpsFrozen = 0;
      }
    } else {
      mem.x += Math.cos(rgb)*v*dt;
      mem.y += Math.sin(rgb)*v*dt;
      mem.gpsFrozen = (mem.gpsFrozen||0) + dt;
      if ((mem.gpsFrozen||0) > 5){
        mem.x = rx; mem.y = ry;
        mem.lastRX = rx; mem.lastRY = ry;
        mem.gpsFrozen = 0;
      }
    }
  } else {
    mem.x += Math.cos(rgb)*v*dt;
    mem.y += Math.sin(rgb)*v*dt;
  }

  mem.x = clamp(mem.x, 0.3, mem.size-0.3);
  mem.y = clamp(mem.y, 0.3, mem.size-0.3);

  const b = obs.beacon;
  if (b && b.distance != null && isFinite(Number(b.distance)) && Number(b.distance) < 20 && Number(b.distance) > 0.5){
    const d = Number(b.distance);
    const br = (Number(b.bearing)||0)*D2R;
    const world = Math.atan2(mem.baseY-mem.y, mem.baseX-mem.x);
    const trueAng = wrap(world - br);
    const newBias = wrap(trueAng - mem.hFilt);
    const diff = wrap(newBias - mem.bias);
    if (!mem.biasValid){
      mem.bias = newBias;
      mem.biasValid = true;
    } else if (Math.abs(diff) < 0.8){
      mem.bias = wrap(mem.bias + 0.12*diff);
    }
  }
}

function edgeClear(x,y,a,margin,size){
  const ca = Math.cos(a), sa = Math.sin(a);
  let ex = 1e9, ey = 1e9;
  if (ca > 1e-6) ex = Math.min(ex,(size-margin-x)/ca);
  else if (ca < -1e-6) ex = Math.min(ex,(margin-x)/ca);
  if (sa > 1e-6) ey = Math.min(ey,(size-margin-y)/sa);
  else if (sa < -1e-6) ey = Math.min(ey,(margin-y)/sa);
  return Math.max(0,Math.min(ex,ey));
}

function clearanceRel(rel,rays){
  let clear = 15;
  if (!rays) return clear;
  for (let i=0;i<9;i++){
    let d = Number(rays[i]);
    if (!isFinite(d) || d < 0) continue;
    if (d > 15) d = 15;
    const ra = (-80 + i*20)*D2R;
    const diff = Math.abs(wrap(ra - rel));
    if (diff < 0.78){
      const proj = d*Math.cos(diff);
      if (proj < clear) clear = proj;
    }
  }
  return clear;
}

function chooseAvoid(desired,mem,obs){
  const rays = obs.rays || [];
  let best = wrap(desired);
  let bestCost = 1e100;
  const trueH = wrap(mem.hFilt + mem.bias);

  for (let deg=-120; deg<=120; deg+=10){
    const cand = wrap(desired + deg*D2R);
    const ad = Math.abs(wrap(cand - desired));
    let cost = ad*1.4 + (deg*deg)*0.00045;

    for (let i=0;i<9;i++){
      let d = Number(rays[i]);
      if (!isFinite(d) || d < 0) continue;
      if (d > 15) d = 15;
      const ra = (-80 + i*20)*D2R;
      const diff = Math.abs(wrap(ra - cand));
      if (diff < 0.85){
        const prox = Math.max(0, 6.2 - d);
        cost += prox*prox*(1 - diff/0.85)*0.22;
        if (d < 1.05 && diff < 0.45) cost += 220;
        else if (d < 2.1 && diff < 0.62) cost += (2.1-d)*18;
      }
    }

    const wor = wrap(trueH + cand);
    const ed = edgeClear(mem.x,mem.y,wor,2.2,mem.size);
    if (ed < 5.5){
      cost += (5.5-ed)*(5.5-ed)*0.55;
      if (ed < 1.3) cost += 240;
    }

    if (cost < bestCost){
      bestCost = cost;
      best = cand;
    }
  }
  return best;
}

function applyWheels(vl,vr,dt,mem,obs,drill){
  vl = clamp(Number(vl)||0,-1.8,1.8);
  vr = clamp(Number(vr)||0,-1.8,1.8);

  const maxAcc = 2.8*dt;
  mem.vLcmd = (mem.vLcmd||0) + clamp(vl - (mem.vLcmd||0), -maxAcc, maxAcc);
  mem.vRcmd = (mem.vRcmd||0) + clamp(vr - (mem.vRcmd||0), -maxAcc, maxAcc);

  const wl = Number(obs.wheelLeft)||0;
  const wr = Number(obs.wheelRight)||0;
  const pitch = Number(obs.pitch)||0;

  const ul = wheelCtrl(mem.wcL, mem.vLcmd, wl, dt, pitch);
  const ur = wheelCtrl(mem.wcR, mem.vRcmd, wr, dt, pitch);

  return {left:clamp(ul,-1,1), right:clamp(ur,-1,1), drill:!!drill};
}

function wheelCtrl(st,target,actual,dt,pitch){
  target = clamp(target,-1.8,1.8);
  actual = Number(actual)||0;

  if (Math.abs(target) < 0.025){
    st.i *= Math.max(0, 1 - 3.0*dt);
    let u = -1.15*actual + clamp(pitch*0.011,-0.16,0.16);
    if (Math.abs(actual) < 0.018 && Math.abs(u) < 0.045) u = 0;
    if (u > 0.018 && u < 0.075) u = 0.075;
    else if (u < -0.018 && u > -0.075) u = -0.075;
    return clamp(u,-1,1);
  }

  const err = target - actual;
  st.i = (st.i||0) + err*dt*0.13;
  st.i = clamp(st.i,-0.32,0.32);

  const eff = st.eff || 2.4;
  let u = target/eff + 0.52*err + st.i;
  if (u > 0.012) u += 0.034;
  else if (u < -0.012) u -= 0.034;

  if (u > 1){ u = 1; st.i = Math.min(st.i,0.24); }
  else if (u < -1){ u = -1; st.i = Math.max(st.i,-0.24); }

  if (Math.abs(target) > 0.28 && Math.abs(actual) > 0.16 && Math.abs(u) > 0.08){
    const den = Math.max(0.08, Math.abs(u) - 0.034);
    const est = Math.abs(actual)/den;
    if (est > 0.45 && est < 8.0){
      st.eff = clamp(st.eff*0.996 + est*0.004, 0.7, 7.5);
    }
  }
  return clamp(u,-1,1);
}

function driveBody(rel, speed, avoid, mem, obs, dt){
  rel = wrap(rel);
  let chosen = avoid ? chooseAvoid(rel,mem,obs) : rel;
  let err = wrap(chosen);

  let v = clamp(Number(speed)||0, 0, 1.8);
  let clear = clearanceRel(chosen, obs.rays);
  if (clear < 0.85) v = 0;
  else if (clear < 2.6) v = Math.min(v, Math.max(0.06, (clear-0.55)*0.72));

  const trueH = wrap(mem.hFilt + mem.bias);
  const world = wrap(trueH + chosen);
  const ed = edgeClear(mem.x,mem.y,world,2.2,mem.size);
  if (ed < 3.2) v = Math.min(v, Math.max(0.05, (ed-0.85)*0.62));
  if (ed < 1.1) v = 0;

  if (Math.abs(err) > 1.06) v = 0;
  else if (Math.abs(err) > 0.46) v *= 0.42;

  let vl, vr;
  if (v < 0.035 && Math.abs(err) > 0.055){
    const om = clamp(1.10*err,-0.90,0.90);
    vl = -0.30*om;
    vr =  0.30*om;
  } else {
    const omega = clamp(1.55*err,-1.35,1.35);
    vl = v - 0.30*omega;
    vr = v + 0.30*omega;
  }
  return applyWheels(vl,vr,dt,mem,obs,false);
}

function goToPoint(tx,ty,speed,stopDist,avoid,mem,obs,dt){
  const dx = tx - mem.x;
  const dy = ty - mem.y;
  const d = Math.sqrt(dx*dx + dy*dy);
  if (!isFinite(d)) return applyWheels(0,0,dt,mem,obs,false);
  if (stopDist > 0 && d <= stopDist + 0.05){
    return applyWheels(0,0,dt,mem,obs,false);
  }
  const desiredWorld = Math.atan2(dy,dx);
  const trueH = wrap(mem.hFilt + mem.bias);
  const rel = wrap(desiredWorld - trueH);
  let sp = speed;
  if (stopDist > 0 && d < stopDist + 2.0){
    sp = Math.min(sp, Math.max(0.08,(d-stopDist)*0.80));
  }
  return driveBody(rel, sp, avoid, mem, obs, dt);
}

function isAtBase(mem,obs){
  if (obs.docked) return true;
  const b = obs.beacon;
  if (b && b.distance != null && isFinite(Number(b.distance)) && Number(b.distance) <= 2.9) return true;
  if (dist2(mem.x,mem.y,mem.baseX,mem.baseY) <= 2.45) return true;
  return false;
}

function makeSearch(cx,cy,step,maxR,size){
  const pts = [{x:clamp(cx,5,size-5), y:clamp(cy,5,size-5)}];
  let x = pts[0].x, y = pts[0].y;
  const dirs = [[1,0],[0,1],[-1,0],[0,-1]];
  let dir = 0;
  let len = step;
  let total = 0;
  let guard = 0;

  while (guard++ < 90){
    for (let rep=0; rep<2; rep++){
      const dx = dirs[dir][0], dy = dirs[dir][1];
      const nx = clamp(x + dx*len, 5, size-5);
      const ny = clamp(y + dy*len, 5, size-5);
      const dd = Math.sqrt((nx-x)*(nx-x) + (ny-y)*(ny-y));
      total += dd;
      if (dd > 0.6) pts.push({x:nx,y:ny});
      x = nx; y = ny;
      dir = (dir+1)&3;
    }
    len += step;
    const mx = Math.max(Math.abs(x-cx), Math.abs(y-cy));
    if (mx > maxR) break;
    if (pts.length > 220) break;
  }
  return {pts:pts, length:total};
}

function startSearch(mem,now,timeLeft,centerX,centerY,hintIdx,forcedR){
  let rel = 0.55;
  if (hintIdx >= 0 && mem.hints[hintIdx]){
    rel = clamp(mem.hints[hintIdx].val / mem.maxHintVal, 0, 1);
  }
  let R = (forcedR != null) ? forcedR : clamp(13 + 7*Math.sqrt(rel), 13, 20);
  if (timeLeft < 220) R = Math.min(R,16);
  if (timeLeft < 110) R = Math.min(R,12);
  const step = 7.0;
  const res = makeSearch(centerX,centerY,step,R,mem.size);
  let total = res.length;
  let dur = 55 + total*1.35;
  dur = clamp(dur,60,300);
  if (timeLeft < dur + 25) dur = Math.max(30, timeLeft - 25);

  mem.search = {
    pts: res.pts,
    i: 0,
    cx: centerX,
    cy: centerY,
    start: now,
    deadline: now + dur,
    lastProgress: now,
    bestD: 1e9,
    hintIdx: hintIdx
  };
  mem.mode = "search";
  mem.activeHint = hintIdx;
  mem.site = null;
  mem.drill = null;
  mem.goalBumps = 0;
}

function failSearch(mem,now,obs,dt){
  const s = mem.search;
  if (s && s.hintIdx >= 0 && mem.hints[s.hintIdx] && mem.hints[s.hintIdx].state === 0){
    mem.hints[s.hintIdx].state = 2;
  }
  mem.search = null;
  mem.site = null;
  mem.drill = null;
  mem.activeHint = -1;
  mem.mode = "idle";
  return applyWheels(0,0,dt,mem,obs,false);
}

function failSite(mem,now,obs,dt){
  if (mem.site) addIgnore(mem, mem.site.x, mem.site.y, now, 5.0, 260);
  mem.site = null;
  mem.drill = null;
  const pm = mem.sitePrevMode || "idle";
  if (pm === "search" && mem.search && mem.search.i < mem.search.pts.length && now < mem.search.deadline){
    mem.mode = "search";
  } else if (pm === "toHint" && mem.activeHint >= 0 && mem.hints[mem.activeHint] && mem.hints[mem.activeHint].state === 0){
    mem.mode = "toHint";
  } else if (pm === "toExplore" && mem.exploreTarget){
    mem.mode = "toExplore";
  } else {
    mem.mode = "idle";
    mem.activeHint = -1;
  }
  return applyWheels(0,0,dt,mem,obs,false);
}

function handleToSite(obs,mem,now,dt,timeLeft,battery){
  if (mem.mode === "drill") return handleDrill(obs,mem,now,dt,timeLeft,battery);

  const s = obs.site;
  let have = false;
  let sd = 999, sb = 0, sv = 0;

  if (s && isFinite(Number(s.distance)) && isFinite(Number(s.bearing))){
    sd = Number(s.distance);
    sb = (Number(s.bearing)||0)*D2R;
    sv = Number(s.value)||0;
    if (sd >= 0 && sd <= 8.2 && sv > 0) have = true;
  }

  const wl = Number(obs.wheelLeft)||0;
  const wr = Number(obs.wheelRight)||0;
  const maxWheel = Math.max(Math.abs(wl),Math.abs(wr));

  if (have){
    const trueH = wrap(mem.hFilt + mem.bias);
    const wx = mem.x + Math.cos(trueH + sb)*sd;
    const wy = mem.y + Math.sin(trueH + sb)*sd;
    if (isIgnored(mem,wx,wy,now)){
      return failSite(mem,now,obs,dt);
    }
    if (mem.site){
      mem.site.x = mem.site.x*0.75 + wx*0.25;
      mem.site.y = mem.site.y*0.75 + wy*0.25;
      mem.site.val = sv;
      mem.site.lastSeen = now;
      mem.site.dist = sd;
      mem.site.bearing = sb;
    } else {
      mem.site = {x:wx,y:wy,val:sv,lastSeen:now,dist:sd,bearing:sb};
    }

    if (sd <= 1.45 && maxWheel < 0.105){
      mem.drill = {start:now, siteX:wx, siteY:wy, attempts:(mem.drill?mem.drill.attempts:0)};
      mem.mode = "drill";
      return applyWheels(0,0,dt,mem,obs,true);
    }

    if (sd <= 1.55){
      if (sd > 1.34 && maxWheel < 0.06){
        return driveBody(sb, 0.10, false, mem, obs, dt);
      }
      return applyWheels(0,0,dt,mem,obs,false);
    }

    let sp;
    if (sd > 6.0) sp = 1.20;
    else if (sd > 4.0) sp = 0.85;
    else if (sd > 2.6) sp = 0.52;
    else if (sd > 1.9) sp = 0.30;
    else sp = 0.14;

    if (timeLeft < 90) sp = Math.min(1.4, sp*1.15);
    if (battery < 0.22) sp = Math.min(sp,0.8);

    return driveBody(sb, sp, false, mem, obs, dt);
  }

  if (mem.site && now - mem.site.lastSeen < 4.0){
    const d = dist2(mem.x,mem.y,mem.site.x,mem.site.y);
    if (d < 0.90) return applyWheels(0,0,dt,mem,obs,false);
    const sp = d > 3 ? 0.75 : 0.24;
    return goToPoint(mem.site.x, mem.site.y, sp, 0.55, true, mem, obs, dt);
  }

  return failSite(mem,now,obs,dt);
}

function handleDrill(obs,mem,now,dt,timeLeft,battery){
  if (!mem.drill){
    mem.mode = "toSite";
    return applyWheels(0,0,dt,mem,obs,false);
  }

  const s = obs.site;
  let sd = 999;
  if (s && isFinite(Number(s.distance))){
    sd = Number(s.distance);
  }

  const maxWheel = Math.max(Math.abs(Number(obs.wheelLeft)||0), Math.abs(Number(obs.wheelRight)||0));
  const elapsed = now - mem.drill.start;

  let abort = false;
  if (elapsed > 15.0) abort = true;
  if (battery < 0.018) abort = true;
  if (!s || sd > 3.0) abort = true;
  if (maxWheel > 0.24 && elapsed > 1.5) abort = true;

  if (abort){
    mem.drill = null;
    if (mem.site) addIgnore(mem,mem.site.x,mem.site.y,now,4.5,240);
    mem.site = null;
    mem.mode = "idle";
    mem.activeHint = -1;
    mem.search = null;
    return applyWheels(0,0,dt,mem,obs,false);
  }

  return applyWheels(0,0,dt,mem,obs,true);
}

function handleSearch(obs,mem,now,dt,timeLeft,battery){
  const s = mem.search;
  if (!s){
    mem.mode = "idle";
    return applyWheels(0,0,dt,mem,obs,false);
  }

  if (s.i >= s.pts.length || now > s.deadline){
    return failSearch(mem,now,obs,dt);
  }

  let p = s.pts[s.i];
  let d = dist2(mem.x,mem.y,p.x,p.y);
  let guard = 0;

  while (s.i < s.pts.length-1 && d < 2.6 && guard++ < 6){
    s.i++;
    p = s.pts[s.i];
    d = dist2(mem.x,mem.y,p.x,p.y);
    s.lastProgress = now;
    s.bestD = 1e9;
  }

  if (s.i >= s.pts.length){
    return failSearch(mem,now,obs,dt);
  }

  if (d < s.bestD - 0.35){
    s.bestD = d;
    s.lastProgress = now;
  }

  if (now - s.lastProgress > 14.0){
    s.i++;
    s.lastProgress = now;
    s.bestD = 1e9;
    if (s.i >= s.pts.length){
      return failSearch(mem,now,obs,dt);
    }
    p = s.pts[s.i];
    d = dist2(mem.x,mem.y,p.x,p.y);
  }

  let sp = 1.32;
  if (timeLeft < 170) sp = 1.50;
  if (battery < 0.25) sp = Math.min(sp,0.95);

  return goToPoint(p.x,p.y,sp,0.0,true,mem,obs,dt);
}

function failHint(mem,now,obs,dt){
  if (mem.activeHint >= 0 && mem.hints[mem.activeHint] && mem.hints[mem.activeHint].state === 0){
    mem.hints[mem.activeHint].state = 2;
  }
  mem.activeHint = -1;
  mem.search = null;
  mem.mode = "idle";
  return applyWheels(0,0,dt,mem,obs,false);
}

function handleToHint(obs,mem,now,dt,timeLeft,battery){
  if (mem.activeHint < 0 || !mem.hints[mem.activeHint]){
    mem.mode = "idle";
    return applyWheels(0,0,dt,mem,obs,false);
  }

  const h = mem.hints[mem.activeHint];
  if (h.state !== 0){
    mem.activeHint = -1;
    mem.mode = "idle";
    return applyWheels(0,0,dt,mem,obs,false);
  }

  const d = dist2(mem.x,mem.y,h.x,h.y);
  if (d < (mem.bestDist||1e9) - 0.45){
    mem.bestDist = d;
    mem.lastProgress = now;
  }

  let startD = 7.5;
  if ((Number(obs.science)||0) > 1.0) startD = 12.0;
  if (d < startD){
    startSearch(mem,now,timeLeft,h.x,h.y,mem.activeHint,null);
    return applyWheels(0,0,dt,mem,obs,false);
  }

  if (now - mem.lastProgress > 48 || now - mem.goalStart > 70 + d*1.8){
    return failHint(mem,now,obs,dt);
  }

  let sp = 1.45;
  if (d < 18) sp = 1.05;
  if (timeLeft < 230) sp = 1.65;
  if (battery < 0.22) sp = Math.min(sp,1.0);

  return goToPoint(h.x,h.y,sp,2.0,true,mem,obs,dt);
}

function handleToExplore(obs,mem,now,dt,timeLeft,battery){
  const ep = mem.exploreTarget;
  if (!ep){
    mem.mode = "idle";
    return applyWheels(0,0,dt,mem,obs,false);
  }

  const d = dist2(mem.x,mem.y,ep.x,ep.y);
  if (d < (mem.bestDist||1e9) - 0.45){
    mem.bestDist = d;
    mem.lastProgress = now;
  }

  if (d < 8.0){
    startSearch(mem,now,timeLeft,ep.x,ep.y,-1,16);
    return applyWheels(0,0,dt,mem,obs,false);
  }

  if (now - mem.lastProgress > 60 || now - mem.goalStart > 100 + d*2.0){
    mem.exploreTarget = null;
    mem.mode = "idle";
    return applyWheels(0,0,dt,mem,obs,false);
  }

  const sp = timeLeft < 200 ? 1.7 : 1.45;
  return goToPoint(ep.x,ep.y,sp,2.0,true,mem,obs,dt);
}

function handleReturn(obs,mem,now,dt,timeLeft,battery){
  const b = obs.beacon;
  const carried = Number(obs.carried)||0;

  if (isAtBase(mem,obs)){
    if (carried > 0){
      if (mem.baseWaitStart == null) mem.baseWaitStart = now;
      if (now - mem.baseWaitStart > 2.2){
        const bd = (b && b.distance != null && isFinite(Number(b.distance))) ? Number(b.distance) : 0;
        if (bd > 0.9){
          const br = (Number(b.bearing)||0)*D2R;
          return driveBody(br,0.28,false,mem,obs,dt);
        }
      }
      return applyWheels(0,0,dt,mem,obs,false);
    }
    mem.mode = "idle";
    return applyWheels(0,0,dt,mem,obs,false);
  }

  mem.baseWaitStart = null;

  if (b && b.distance != null && isFinite(Number(b.distance)) && Number(b.distance) < 20.5){
    const d = Number(b.distance);
    const br = (Number(b.bearing)||0)*D2R;
    if (d <= 1.0) return applyWheels(0,0,dt,mem,obs,false);
    let sp = 1.65;
    if (timeLeft < 80) sp = 1.95;
    if (battery < 0.20) sp = Math.min(sp,1.25);
    if (d < 4) sp = Math.min(sp, Math.max(0.25, d*0.45));
    return driveBody(br,sp,false,mem,obs,dt);
  }

  const d = dist2(mem.x,mem.y,mem.baseX,mem.baseY);
  if (d <= 1.35) return applyWheels(0,0,dt,mem,obs,false);

  let sp = 1.60;
  if (timeLeft < 80) sp = 1.90;
  if (battery < 0.20) sp = Math.min(sp,1.20);
  return goToPoint(mem.baseX,mem.baseY,sp,1.6,true,mem,obs,dt);
}

function chargeTarget(timeLeft){
  if (timeLeft > 650) return 0.95;
  if (timeLeft > 430) return 0.78;
  if (timeLeft > 250) return 0.60;
  if (timeLeft > 140) return 0.46;
  return 0.34;
}

function chooseExplore(mem,obs,now,timeLeft,battery){
  if (!mem.explore || mem.explore.length === 0) return null;

  for (let i=0;i<mem.explore.length;i++){
    const p = mem.explore[i];
    if (!p.visited && dist2(mem.x,mem.y,p.x,p.y) < 12) p.visited = true;
  }

  let best = null;
  let bestScore = 1e9;

  for (let i=0;i<mem.explore.length;i++){
    const p = mem.explore[i];
    if (p.visited) continue;
    const d = dist2(mem.x,mem.y,p.x,p.y);
    const db = dist2(p.x,p.y,mem.baseX,mem.baseY);
    if (timeLeft < (d+db)/1.2 + 70) continue;
    if (battery < 0.20) continue;
    let score = d + 0.25*db;
    if (score < bestScore){
      bestScore = score;
      best = p;
    }
  }
  return best;
}

function chooseGoal(mem,obs,now,timeLeft,battery){
  if (timeLeft < 35) return false;

  let bestIdx = -1;
  let bestScore = 1e100;

  for (let i=0;i<mem.hints.length;i++){
    const h = mem.hints[i];
    if (!h || h.state !== 0) continue;

    const d = dist2(mem.x,mem.y,h.x,h.y);
    const db = dist2(h.x,h.y,mem.baseX,mem.baseY);
    const rel = clamp(h.val / mem.maxHintVal, 0, 1);
    const sr = clamp(13 + 7*Math.sqrt(rel),13,20);
    const pathLen = Math.max(80, 1.2 * 4.2 * sr * sr / 7.0);
    const searchCost = pathLen/1.0 + 30;
    const needTime = (d+db)/1.1 + searchCost + 45;
    const feasible = timeLeft > needTime && battery > 0.17;

    let score = d + 0.35*db - 6.0*rel;
    if (mem.delivered === 0) score = d + 0.25*db - 4.0*rel;
    if (!feasible){
      score += 500;
      if (timeLeft < 160) score += 500;
    }
    if (!mem.biasValid) score += d*0.10;

    if (score < bestScore){
      bestScore = score;
      bestIdx = i;
    }
  }

  if (bestIdx >= 0 && timeLeft > 65){
    const h = mem.hints[bestIdx];
    mem.activeHint = bestIdx;
    mem.search = null;
    mem.site = null;
    mem.drill = null;
    mem.mode = "toHint";
    mem.goalStart = now;
    mem.lastProgress = now;
    mem.bestDist = dist2(mem.x,mem.y,h.x,h.y);
    mem.targetX = h.x;
    mem.targetY = h.y;
    mem.goalBumps = 0;
    return true;
  }

  const ep = chooseExplore(mem,obs,now,timeLeft,battery);
  if (ep){
    ep.visited = true;
    mem.exploreTarget = ep;
    mem.activeHint = -1;
    mem.search = null;
    mem.site = null;
    mem.drill = null;
    mem.mode = "toExplore";
    mem.goalStart = now;
    mem.lastProgress = now;
    mem.bestDist = dist2(mem.x,mem.y,ep.x,ep.y);
    mem.targetX = ep.x;
    mem.targetY = ep.y;
    mem.goalBumps = 0;
    return true;
  }

  const sci = Number(obs.science)||0;
  if (sci > 0.035 && timeLeft > 95 && !isAtBase(mem,obs)){
    mem.activeHint = -1;
    startSearch(mem,now,timeLeft,mem.x,mem.y,-1,15);
    return true;
  }

  return false;
}

function handleIdle(obs,mem,now,dt,timeLeft,battery,atBase){
  const carried = Number(obs.carried)||0;

  if (timeLeft < 12 && carried === 0){
    return applyWheels(0,0,dt,mem,obs,false);
  }

  if (atBase){
    const target = chargeTarget(timeLeft);
    if (battery < target - 0.01 && timeLeft > 150 && timeLeft > 0){
      if (mem.chargeStart == null) mem.chargeStart = now;
      if (now - mem.chargeStart < 28){
        const b = obs.beacon;
        if (!obs.docked && b && b.distance != null && isFinite(Number(b.distance)) && Number(b.distance) > 1.1){
          const d = Number(b.distance);
          const br = (Number(b.bearing)||0)*D2R;
          return driveBody(br,0.30,false,mem,obs,dt);
        }
        return applyWheels(0,0,dt,mem,obs,false);
      }
      mem.chargeStart = null;
    } else {
      mem.chargeStart = null;
    }
  }

  if (chooseGoal(mem,obs,now,timeLeft,battery)){
    return applyWheels(0,0,dt,mem,obs,false);
  }

  if (!atBase && timeLeft > 25){
    return handleReturn(obs,mem,now,dt,timeLeft,battery);
  }

  return applyWheels(0,0,dt,mem,obs,false);
}

function startRecovery(mem,obs,now){
  if (now < (mem.recoverUntil||-1)) return;
  mem.recoverUntil = now + 1.10;
  mem.recoverStart = now;

  const rays = obs.rays || [];
  let left = 0, right = 0;
  for (let i=0;i<9;i++){
    let d = Number(rays[i]);
    if (!isFinite(d) || d < 0 || d > 15) d = 9;
    if (i <= 3) right += d;
    else if (i >= 5) left += d;
  }
  mem.recoverSide = (left >= right) ? 1 : -1;

  mem.goalBumps = (mem.goalBumps||0) + 1;
  if (mem.goalBumps >= 4){
    if (mem.activeHint >= 0 && mem.hints[mem.activeHint] && mem.hints[mem.activeHint].state === 0){
      mem.hints[mem.activeHint].state = 2;
    }
    if (mem.site) addIgnore(mem,mem.site.x,mem.site.y,now,5,260);
    mem.site = null;
    mem.drill = null;
    mem.search = null;
    mem.activeHint = -1;
    mem.mode = "idle";
    mem.exploreTarget = null;
    mem.goalBumps = 0;
  }

  mem.vLcmd = 0;
  mem.vRcmd = 0;
}

function updateStuck(mem,obs,now,dt){
  if (mem.mode === "drill" || mem.mode === "calibrate" || now < (mem.recoverUntil||-1)) return;
  if (mem.mode !== "toHint" && mem.mode !== "search" && mem.mode !== "toSite" &&
      mem.mode !== "toExplore" && mem.mode !== "return") return;

  const cmd = Math.abs(mem.vLcmd||0) + Math.abs(mem.vRcmd||0);
  const wheel = Math.abs(Number(obs.wheelLeft)||0) + Math.abs(Number(obs.wheelRight)||0);

  if (now - (mem.stuckLastT||now) > 1.0){
    const moved = dist2(mem.x,mem.y,mem.stuckX,mem.stuckY);
    if (cmd > 0.25 && moved < 0.28 && (wheel < 0.14 || wheel > 0.25)){
      mem.stuckCount = (mem.stuckCount||0) + 1;
    } else if (moved > 0.60){
      mem.stuckCount = 0;
    } else {
      mem.stuckCount = Math.max(0,(mem.stuckCount||0)-1);
    }
    mem.stuckX = mem.x;
    mem.stuckY = mem.y;
    mem.stuckLastT = now;
    if (mem.stuckCount >= 3){
      startRecovery(mem,obs,now);
      mem.stuckCount = 0;
    }
  }
}

function act(obs, mem) {
  try {
    if (!mem.init) initMem(obs, mem);

    const now = (obs.t != null && isFinite(Number(obs.t))) ? Number(obs.t) : ((mem.tick||0)*0.1);
    let dt = 0.1;
    if (mem.lastT != null && now > mem.lastT){
      dt = clamp(now - mem.lastT, 0.02, 0.5);
    } else if (mem.lastT != null && now === mem.lastT){
      dt = mem.dt || 0.1;
    }
    mem.dt = dt;
    mem.lastT = now;
    mem.tick = (mem.tick||0) + 1;

    updatePose(mem,obs,dt);

    const timeLeft = (obs.timeLeft != null && isFinite(Number(obs.timeLeft))) ?
      Number(obs.timeLeft) : Math.max(0, mem.seconds - now);
    const battery = (obs.battery != null && isFinite(Number(obs.battery))) ?
      Number(obs.battery) : 1;
    const carried = Number(obs.carried)||0;
    const wl = Number(obs.wheelLeft)||0;
    const wr = Number(obs.wheelRight)||0;

    const siteRaw = obs.site;
    if (siteRaw && isFinite(Number(siteRaw.distance)) && isFinite(Number(siteRaw.bearing))){
      const sd = Number(siteRaw.distance);
      const sb = (Number(siteRaw.bearing)||0)*D2R;
      const sv = Number(siteRaw.value)||0;
      if (sd >= 0 && sd <= 8.2 && sv > 0){
        const trueH = wrap(mem.hFilt + mem.bias);
        const wx = mem.x + Math.cos(trueH + sb)*sd;
        const wy = mem.y + Math.sin(trueH + sb)*sd;
        if (!isIgnored(mem,wx,wy,now)){
          if (mem.site && now - mem.site.lastSeen < 0.7){
            mem.site.x = mem.site.x*0.72 + wx*0.28;
            mem.site.y = mem.site.y*0.72 + wy*0.28;
          } else {
            mem.site = {x:wx,y:wy,val:sv,lastSeen:now,dist:sd,bearing:sb};
          }
          mem.site.lastSeen = now;
          mem.site.dist = sd;
          mem.site.bearing = sb;
          mem.site.val = sv;
        }
      }
    }
    if (mem.site && now - mem.site.lastSeen > 4.0){
      mem.site = null;
    }

    if (carried > (mem.prevCarried||0)){
      mem.collected += carried - (mem.prevCarried||0);
      let sx = mem.site ? mem.site.x : mem.x;
      let sy = mem.site ? mem.site.y : mem.y;
      for (let i=0;i<mem.hints.length;i++){
        const h = mem.hints[i];
        if (h.state === 0 && dist2(h.x,h.y,sx,sy) < 38){
          h.state = 1;
        }
      }
      if (mem.activeHint >= 0 && mem.hints[mem.activeHint] && mem.hints[mem.activeHint].state === 0){
        mem.hints[mem.activeHint].state = 1;
      }
      mem.mode = "return";
      mem.search = null;
      mem.site = null;
      mem.drill = null;
      mem.activeHint = -1;
      mem.exploreTarget = null;
      mem.chargeStart = null;
      mem.baseWaitStart = null;
      mem.vLcmd = 0;
      mem.vRcmd = 0;
    } else if (carried < (mem.prevCarried||0)){
      mem.delivered += (mem.prevCarried||0) - carried;
      mem.mode = "idle";
      mem.search = null;
      mem.site = null;
      mem.drill = null;
      mem.activeHint = -1;
      mem.exploreTarget = null;
      mem.chargeStart = now;
      mem.baseWaitStart = now;
      mem.vLcmd = 0;
      mem.vRcmd = 0;
    }
    mem.prevCarried = carried;

    if (obs.bumped && !mem.prevBumped){
      if (mem.mode !== "calibrate" && mem.mode !== "drill" && now >= (mem.recoverUntil||-1)){
        startRecovery(mem,obs,now);
      }
    }
    mem.prevBumped = !!obs.bumped;

    if (mem.mode === "calibrate"){
      mem.calSum = (mem.calSum||0) + mem.rawH;
      mem.calCount = (mem.calCount||0) + 1;
      const dx = mem.x - mem.calX;
      const dy = mem.y - mem.calY;
      const d = Math.sqrt(dx*dx + dy*dy);
      const minRay = (function(){
        let m = 15;
        const rays = obs.rays || [];
        for (let i=0;i<9;i++){
          let q = Number(rays[i]);
          if (!isFinite(q) || q < 0) continue;
          if (q > 15) q = 15;
          if (q < m) m = q;
        }
        return m;
      })();

      if (d > 2.2 || now - mem.calStart > 4.0 || minRay < 1.0){
        if (d > 0.8 && mem.calCount > 3){
          const course = Math.atan2(dy,dx);
          const rawAvg = mem.calSum / mem.calCount;
          mem.bias = wrap(course - rawAvg);
          mem.biasValid = true;
        }
        mem.mode = "idle";
        mem.goalStart = now;
        mem.lastProgress = now;
        return applyWheels(0,0,dt,mem,obs,false);
      }

      const err = wrap(mem.calH0 - mem.rawH);
      const om = clamp(1.0*err,-0.55,0.55);
      const v = (d < 0.15) ? 0.50 : 0.60;
      return applyWheels(v - 0.30*om, v + 0.30*om, dt, mem, obs, false);
    }

    if (now < (mem.recoverUntil||-1) && mem.mode !== "drill"){
      const el = now - mem.recoverStart;
      if (el < 0.45){
        return applyWheels(-0.35,-0.35,dt,mem,obs,false);
      }
      const side = mem.recoverSide || 1;
      return applyWheels(-0.25*side, 0.25*side, dt, mem, obs, false);
    }

    updateStuck(mem,obs,now,dt);

    const atBase = isAtBase(mem,obs);

    if (timeLeft < 3.0){
      return applyWheels(0,0,dt,mem,obs,false);
    }

    if (carried > 0 || mem.mode === "return"){
      if (atBase && carried > 0){
        if (mem.baseWaitStart == null) mem.baseWaitStart = now;
        if (now - mem.baseWaitStart > 2.2){
          const b = obs.beacon;
          const bd = (b && b.distance != null && isFinite(Number(b.distance))) ? Number(b.distance) : 0;
          if (bd > 0.9){
            const br = (Number(b.bearing)||0)*D2R;
            return driveBody(br,0.28,false,mem,obs,dt);
          }
        }
        return applyWheels(0,0,dt,mem,obs,false);
      }
      if (atBase && carried === 0){
        mem.mode = "idle";
      } else {
        return handleReturn(obs,mem,now,dt,timeLeft,battery);
      }
    }

    if (carried === 0 && battery < 0.115 && timeLeft > 18 && !atBase){
      return handleReturn(obs,mem,now,dt,timeLeft,battery);
    }

    if (mem.mode === "drill"){
      return handleDrill(obs,mem,now,dt,timeLeft,battery);
    }

    if (mem.mode === "toSite"){
      return handleToSite(obs,mem,now,dt,timeLeft,battery);
    }

    if (carried === 0 && siteRaw && isFinite(Number(siteRaw.distance)) && isFinite(Number(siteRaw.bearing))){
      const sd = Number(siteRaw.distance);
      const sv = Number(siteRaw.value)||0;
      if (sd >= 0 && sd <= 8.2 && sv > 0){
        const sb = (Number(siteRaw.bearing)||0)*D2R;
        const trueH = wrap(mem.hFilt + mem.bias);
        const wx = mem.x + Math.cos(trueH + sb)*sd;
        const wy = mem.y + Math.sin(trueH + sb)*sd;
        if (!isIgnored(mem,wx,wy,now)){
          mem.sitePrevMode = mem.mode;
          mem.site = {x:wx,y:wy,val:sv,lastSeen:now,dist:sd,bearing:sb};
          mem.mode = "toSite";
          mem.drill = null;
          mem.goalBumps = 0;
          return handleToSite(obs,mem,now,dt,timeLeft,battery);
        }
      }
    }

    if (mem.mode === "search"){
      return handleSearch(obs,mem,now,dt,timeLeft,battery);
    }

    if (mem.mode === "toHint"){
      return handleToHint(obs,mem,now,dt,timeLeft,battery);
    }

    if (mem.mode === "toExplore"){
      return handleToExplore(obs,mem,now,dt,timeLeft,battery);
    }

    return handleIdle(obs,mem,now,dt,timeLeft,battery,atBase);
  } catch (e){
    return {left:0,right:0,drill:false};
  }
}

const D2R = Math.PI / 180;

function wrap(a) {
  a = a % (Math.PI * 2);
  if (a > Math.PI) a -= Math.PI * 2;
  if (a < -Math.PI) a += Math.PI * 2;
  return a;
}
function clamp(v, a, b) {
  v = Number(v);
  if (!isFinite(v)) v = a;
  return v < a ? a : (v > b ? b : v);
}
function dist(ax, ay, bx, by) {
  const dx = ax - bx, dy = ay - by;
  return Math.sqrt(dx * dx + dy * dy);
}
function edgeClear(x, y, ang, margin, size) {
  const ca = Math.cos(ang), sa = Math.sin(ang);
  let e = 1e9;
  if (ca > 1e-6) e = Math.min(e, (size - margin - x) / ca);
  else if (ca < -1e-6) e = Math.min(e, (margin - x) / ca);
  if (sa > 1e-6) e = Math.min(e, (size - margin - y) / sa);
  else if (sa < -1e-6) e = Math.min(e, (margin - y) / sa);
  return Math.max(0, e);
}
function frontClearance(rays) {
  if (!rays) return 15;
  let m = 15;
  for (let i = 2; i <= 6; i++) {
    let d = Number(rays[i]);
    if (isFinite(d) && d >= 0 && d < m) m = d;
  }
  return m;
}
function clearanceInDir(rel, rays) {
  if (!rays) return 15;
  let best = 15;
  for (let i = 0; i < 9; i++) {
    let d = Number(rays[i]);
    if (!isFinite(d) || d < 0) continue;
    if (d > 15) d = 15;
    const ra = (-80 + i * 20) * D2R;
    const diff = Math.abs(wrap(ra - rel));
    if (diff < 0.95) {
      const proj = d * Math.cos(diff);
      if (proj < best) best = proj;
    }
  }
  return best;
}

function initMem(obs, mem) {
  mem.init = true;
  const m = obs.mission || {};
  mem.size = Number(m.size) || 400;
  mem.seconds = Number(m.seconds) || 1200;
  mem.cap = Number(m.capacity) || 5;
  mem.baseX = (m.base && isFinite(Number(m.base.x))) ? Number(m.base.x) : (Number(obs.x) || 0);
  mem.baseY = (m.base && isFinite(Number(m.base.y))) ? Number(m.base.y) : (Number(obs.y) || 0);

  mem.x = isFinite(Number(obs.x)) ? Number(obs.x) : mem.baseX;
  mem.y = isFinite(Number(obs.y)) ? Number(obs.y) : mem.baseY;
  mem.rawH = isFinite(Number(obs.heading)) ? Number(obs.heading) * D2R : 0;
  mem.trueH = mem.rawH;
  mem.bias = 0;
  mem.biasValid = false;
  mem.hJumpCount = 0;
  mem.lastGpsX = mem.x;
  mem.lastGpsY = mem.y;
  mem.gpsFrozen = false;
  mem.gpsFreezeT = 0;
  mem.gpsHist = [];

  mem.lastT = (obs.t != null && isFinite(Number(obs.t))) ? Number(obs.t) : 0;
  mem.tick = 0;
  mem.dt = 0.1;

  mem.mode = "calib";
  mem.calStart = mem.lastT;
  mem.calX = mem.x;
  mem.calY = mem.y;
  mem.calSin = 0;
  mem.calCos = 0;
  mem.calCount = 0;

  mem.prevCarried = Number(obs.carried) || 0;
  mem.samplesCollected = 0;
  mem.deliveredSamples = 0;
  mem.lastDeliveryT = -9999;
  mem.chargeStart = -1;
  mem.chargeTarget = 1.0;

  mem.wheelL = { i: 0, lastCmd: 0, eff: 2.4, dz: 0.04 };
  mem.wheelR = { i: 0, lastCmd: 0, eff: 2.4, dz: 0.04 };
  mem.lastCmdL = 0;
  mem.lastCmdR = 0;

  mem.siteInfo = null;
  mem.siteModeStart = -9999;
  mem.siteAttempts = 0;
  mem.drillStart = null;
  mem.drillSite = null;
  mem.search = null;
  mem.target = null;
  mem.exploreTarget = null;
  mem.activeHint = -1;
  mem.ignore = [];

  mem.recoverUntil = -1;
  mem.recoverStart = -1;
  mem.recoverSide = 1;
  mem.bumpCount = 0;
  mem.lastBumpT = -9999;
  mem.prevBumped = !!obs.bumped;

  mem.stuckX = mem.x;
  mem.stuckY = mem.y;
  mem.stuckCheckT = mem.lastT;
  mem.stuckCount = 0;

  mem.lastAvoidRel = null;
  mem.lastScienceSearch = -9999;
  mem.raysBad = false;
  mem.raysMin = 15;

  mem.hints = [];
  mem.maxHintVal = 0.000001;
  const hl = (m.hints && m.hints.length) ? m.hints : [];
  for (let i = 0; i < hl.length; i++) {
    const q = hl[i];
    let x = Number(q.x), y = Number(q.y), v = Number(q.estimate);
    if (!isFinite(x) || !isFinite(y)) continue;
    x = clamp(x, 2, mem.size - 2);
    y = clamp(y, 2, mem.size - 2);
    if (!isFinite(v) || v <= 0) v = 0.000001;
    mem.hints.push({ x: x, y: y, val: v, state: 0 });
    if (v > mem.maxHintVal) mem.maxHintVal = v;
  }

  mem.explore = [];
  const exStep = Math.max(55, mem.size / 7);
  let eid = 0;
  for (let x = exStep * 0.5; x < mem.size; x += exStep) {
    for (let y = exStep * 0.5; y < mem.size; y += exStep) {
      mem.explore.push({ x: clamp(x, 4, mem.size - 4), y: clamp(y, 4, mem.size - 4), visited: false, id: eid++ });
    }
  }
}

function updateRays(obs, mem) {
  const rays = obs.rays || [];
  let valid = 0, mn = 15, mx = 0;
  for (let i = 0; i < 9; i++) {
    let d = Number(rays[i]);
    if (isFinite(d) && d >= 0) {
      valid++;
      if (d < mn) mn = d;
      if (d > mx) mx = d;
    }
  }
  mem.raysMin = mn;
  mem.raysBad = (valid >= 7 && mx - mn < 0.02 && mn < 10);
}

function observeSite(obs, mem, now, carried) {
  if (carried > 0) return null;
  const s = obs.site;
  if (!s) return null;
  let d = Number(s.distance);
  let br = Number(s.bearing);
  let val = Number(s.value) || 0;
  if (!isFinite(d) || !isFinite(br) || d < 0 || d > 8.2) return null;
  if (val <= 0) val = 0.0001;
  const a = mem.trueH + br * D2R;
  const sx = mem.x + Math.cos(a) * d;
  const sy = mem.y + Math.sin(a) * d;
  if (isIgnored(mem, sx, sy, now)) return null;

  if (mem.siteInfo && now - mem.siteInfo.lastSeen < 0.55 &&
      dist(sx, sy, mem.siteInfo.x, mem.siteInfo.y) < 5.0) {
    mem.siteInfo.x = mem.siteInfo.x * 0.65 + sx * 0.35;
    mem.siteInfo.y = mem.siteInfo.y * 0.65 + sy * 0.35;
    mem.siteInfo.d = d;
    mem.siteInfo.b = br * D2R;
    mem.siteInfo.val = val;
    mem.siteInfo.lastSeen = now;
  } else {
    mem.siteInfo = { x: sx, y: sy, d: d, b: br * D2R, val: val, lastSeen: now };
  }
  return { x: mem.siteInfo.x, y: mem.siteInfo.y, d: d, b: br * D2R, val: val };
}

function isIgnored(mem, x, y, now) {
  if (!mem.ignore) return false;
  for (let i = mem.ignore.length - 1; i >= 0; i--) {
    const q = mem.ignore[i];
    if (now < q.until && dist(q.x, q.y, x, y) < q.rad) return true;
  }
  return false;
}
function addIgnore(mem, x, y, now, dur, rad) {
  if (!isFinite(x) || !isFinite(y)) return;
  mem.ignore.push({ x: x, y: y, until: now + (dur || 120), rad: rad || 3 });
  while (mem.ignore.length > 50) mem.ignore.shift();
}

function updatePose(obs, mem, now, dt) {
  const wl = Number(obs.wheelLeft) || 0;
  const wr = Number(obs.wheelRight) || 0;
  const yawRate = (wr - wl) / 0.6;

  const hr = Number(obs.heading);
  if (isFinite(hr)) {
    const r = hr * D2R;
    const pred = wrap(mem.rawH + yawRate * dt);
    let diff = wrap(r - pred);
    if (Math.abs(diff) > 1.2 && Math.abs(yawRate) < 0.7 && mem.tick > 5) {
      mem.hJumpCount = (mem.hJumpCount || 0) + 1;
      if (mem.hJumpCount < 5) {
        mem.rawH = pred;
      } else {
        mem.rawH = wrap(pred + diff);
        mem.hJumpCount = 0;
      }
    } else {
      mem.hJumpCount = 0;
      mem.rawH = wrap(mem.rawH + diff * 0.78);
    }
  } else {
    mem.rawH = wrap(mem.rawH + yawRate * dt);
  }
  mem.trueH = wrap(mem.rawH + mem.bias);

  const v = (wl + wr) * 0.5;
  const rx = Number(obs.x), ry = Number(obs.y);
  const rxOk = isFinite(rx) && isFinite(ry);
  let stepRaw = 0;
  if (rxOk) {
    stepRaw = dist(rx, ry, mem.lastGpsX, mem.lastGpsY);
    if (Math.abs(v) > 0.05 && stepRaw < 0.006) mem.gpsFreezeT += dt;
    else mem.gpsFreezeT = Math.max(0, mem.gpsFreezeT - dt * 2.0);
    if (mem.gpsFreezeT > 1.2) mem.gpsFrozen = true;
    if (mem.gpsFrozen && stepRaw > 0.4) {
      mem.gpsFrozen = false;
      mem.gpsFreezeT = 0;
      mem.x = rx;
      mem.y = ry;
      mem.lastGpsX = rx;
      mem.lastGpsY = ry;
    }
  }

  if (rxOk && !mem.gpsFrozen) {
    const jump = dist(rx, ry, mem.x, mem.y);
    const plausible = jump < Math.max(4.0, Math.abs(v) * dt * 30 + 1.0);
    if (plausible || mem.gpsFreezeT > 1.0) {
      const alpha = jump > 1.5 ? 0.80 : 0.55;
      mem.x += (rx - mem.x) * alpha;
      mem.y += (ry - mem.y) * alpha;
      mem.lastGpsX = rx;
      mem.lastGpsY = ry;
    } else {
      mem.x += Math.cos(mem.trueH) * v * dt;
      mem.y += Math.sin(mem.trueH) * v * dt;
    }
  } else {
    mem.x += Math.cos(mem.trueH) * v * dt;
    mem.y += Math.sin(mem.trueH) * v * dt;
  }
  mem.x = clamp(mem.x, 1, mem.size - 1);
  mem.y = clamp(mem.y, 1, mem.size - 1);

  if (mem.gpsHist.length > 10 && Math.abs(wr - wl) < 0.8 &&
      Math.abs(v) > 0.20 && !mem.gpsFrozen) {
    const targetT = now - 1.3;
    let old = null;
    for (let i = mem.gpsHist.length - 1; i >= 0; i--) {
      if (mem.gpsHist[i].t <= targetT) { old = mem.gpsHist[i]; break; }
    }
    if (old) {
      const dx = mem.x - old.x, dy = mem.y - old.y;
      const dd = Math.sqrt(dx * dx + dy * dy);
      if (dd > 0.35 && dd < 5.0) {
        const course = Math.atan2(dy, dx);
        const rawAvg = Math.atan2(Math.sin(old.h) + Math.sin(mem.rawH),
                                  Math.cos(old.h) + Math.cos(mem.rawH));
        const nb = wrap(course - rawAvg);
        if (!mem.biasValid) {
          mem.bias = nb;
          mem.biasValid = true;
        } else {
          const df = wrap(nb - mem.bias);
          if (Math.abs(df) < 0.8) mem.bias = wrap(mem.bias + df * 0.04);
        }
      }
    }
  }

  const b = obs.beacon;
  if (b && isFinite(Number(b.distance))) {
    const bd = Number(b.distance);
    const br = Number(b.bearing) * D2R;
    if (bd > 0.3 && bd < 18 && isFinite(br)) {
      const expected = Math.atan2(mem.baseY - mem.y, mem.baseX - mem.x);
      const trueFrom = wrap(expected - br);
      const nb = wrap(trueFrom - mem.rawH);
      if (!mem.biasValid) {
        mem.bias = nb;
        mem.biasValid = true;
      } else {
        const df = wrap(nb - mem.bias);
        if (Math.abs(df) < 0.6) mem.bias = wrap(mem.bias + df * 0.10);
      }
      mem.trueH = wrap(mem.rawH + mem.bias);
    }
  }

  mem.gpsHist.push({ t: now, x: mem.x, y: mem.y, h: mem.rawH });
  while (mem.gpsHist.length > 100) mem.gpsHist.shift();
}

function wheelControl(st, target, actual, pitch, dt) {
  target = clamp(target, -1.10, 1.10);
  actual = Number(actual) || 0;
  const err = target - actual;
  let u;

  if (Math.abs(target) < 0.025) {
    st.i = (st.i || 0) + (0 - actual) * dt * 1.2;
    st.i = clamp(st.i, -0.8, 0.8);
    u = 1.8 * (0 - actual) + st.i;
    if (Math.abs(actual) < 0.02) {
      st.i *= Math.max(0, 1 - 0.4 * dt);
      if (Math.abs(u) < 0.045) u = 0;
    }
  } else {
    const eff = st.eff || 2.4;
    st.i = (st.i || 0) + err * dt * 0.7;
    st.i = clamp(st.i, -0.8, 0.8);
    const ff = clamp((Number(pitch) || 0) * 0.012, -0.12, 0.12);
    u = target / eff + 1.3 * err + st.i + ff;
    const dz = st.dz || 0.04;
    if (u > 0.015) u += dz;
    else if (u < -0.015) u -= dz;

    const lc = st.lastCmd || 0;
    if (Math.abs(lc) > 0.15 && Math.abs(actual) > 0.12 &&
        lc * actual > 0 && target * actual > 0) {
      const den = Math.max(0.12, Math.abs(lc) - dz);
      const est = Math.abs(actual) / den;
      if (est > 0.4 && est < 7.0) {
        st.eff = clamp((st.eff || 2.4) * 0.99 + est * 0.01, 0.7, 6.0);
      }
    }
  }

  u = clamp(u, -1, 1);
  if (u >= 1 && err > 0) st.i = clamp(st.i - 0.4 * err * dt, -0.8, 0.8);
  if (u <= -1 && err < 0) st.i = clamp(st.i - 0.4 * err * dt, -0.8, 0.8);

  const prev = st.lastCmd || 0;
  const maxStep = 15 * dt;
  if (u > prev + maxStep) u = prev + maxStep;
  else if (u < prev - maxStep) u = prev - maxStep;
  st.lastCmd = u;
  return u;
}

function applyWheels(vL, vR, obs, mem, dt, drill) {
  let wl = Number(obs.wheelLeft) || 0;
  let wr = Number(obs.wheelRight) || 0;
  const maxAct = Math.max(Math.abs(wl), Math.abs(wr));
  const front = frontClearance(obs.rays);

  if ((vL > 0.01 || vR > 0.01) && front < 0.75 && maxAct > 0.70) {
    vL = 0;
    vR = 0;
  }
  if (maxAct > 1.25) {
    vL = -0.35;
    vR = -0.35;
  }

  vL = clamp(vL, -1.0, 1.0);
  vR = clamp(vR, -1.0, 1.0);

  const pitch = Number(obs.pitch) || 0;
  const uL = wheelControl(mem.wheelL, vL, wl, pitch, dt);
  const uR = wheelControl(mem.wheelR, vR, wr, pitch, dt);
  mem.lastCmdL = uL;
  mem.lastCmdR = uR;
  return { left: uL, right: uR, drill: !!drill };
}

function chooseAvoid(desiredRel, obs, mem) {
  const rays = obs.rays || [];
  let best = wrap(desiredRel);
  let bestCost = 1e100;

  for (let deg = -170; deg <= 170; deg += 10) {
    const cand = deg * D2R;
    const ad = Math.abs(wrap(cand - desiredRel));
    let cost = ad * ad * 2.2 + ad * 0.3;

    if (mem.lastAvoidRel != null) {
      cost += (1 - Math.cos(wrap(cand - mem.lastAvoidRel))) * 0.22;
    }

    if (!mem.raysBad) {
      for (let i = 0; i < 9; i++) {
        let d = Number(rays[i]);
        if (!isFinite(d) || d < 0) continue;
        if (d > 15) d = 15;
        const ra = (-80 + i * 20) * D2R;
        const diff = Math.abs(wrap(ra - cand));
        if (diff < 0.95) {
          const proj = d * Math.cos(diff);
          if (proj < 0.9) {
            cost += 800 * (1.0 - proj + 0.1) * (1 - diff / 0.95);
          } else if (proj < 2.2) {
            cost += (2.2 - proj) * (2.2 - proj) * 25 * (1 - diff / 0.95);
          } else if (proj < 4.5) {
            cost += (4.5 - proj) * 2.5 * (1 - diff / 0.95);
          }
        }
      }
    }

    const world = wrap(mem.trueH + cand);
    const ed = edgeClear(mem.x, mem.y, world, 3.0, mem.size);
    if (ed < 4.0) {
      cost += (4 - ed) * (4 - ed) * 12;
      if (ed < 1.0) cost += 600;
    }

    if (cost < bestCost) {
      bestCost = cost;
      best = cand;
    }
  }
  mem.lastAvoidRel = best;
  return best;
}

function driveRelative(desiredRel, vTarget, obs, mem, dt) {
  const chosen = chooseAvoid(wrap(desiredRel), obs, mem);
  const err = wrap(chosen);
  let v = clamp(vTarget, 0, 0.85);

  let clear = clearanceInDir(err, obs.rays);
  if (mem.raysBad) {
    clear = 10;
    v = Math.min(v, 0.50);
  } else {
    if (clear < 0.80) v = 0;
    else if (clear < 2.5) v = Math.min(v, Math.max(0.05, (clear - 0.60) * 0.70));
  }

  if (Math.abs(err) > 1.20) v = 0;
  else if (Math.abs(err) > 0.60) v *= 0.40;
  else v *= Math.max(0.20, Math.cos(err));

  let omega = clamp(2.2 * err, -1.8, 1.8);
  const maxT = 0.95;
  if (v + 0.3 * Math.abs(omega) > maxT) {
    v = Math.max(0, maxT - 0.3 * Math.abs(omega));
  }

  let vL, vR;
  if (v < 0.03 && Math.abs(err) > 0.08) {
    vL = -0.3 * omega;
    vR = 0.3 * omega;
  } else if (v < 0.03) {
    vL = 0;
    vR = 0;
  } else {
    vL = v - 0.3 * omega;
    vR = v + 0.3 * omega;
  }

  return applyWheels(vL, vR, obs, mem, dt, false);
}

function navigateToPoint(tx, ty, maxSpeed, stopDist, obs, mem, dt) {
  const d = dist(mem.x, mem.y, tx, ty);
  if (!isFinite(d)) return applyWheels(0, 0, obs, mem, dt, false);
  if (d <= stopDist + 0.10) return applyWheels(0, 0, obs, mem, dt, false);

  const desiredWorld = Math.atan2(ty - mem.y, tx - mem.x);
  const rel = wrap(desiredWorld - mem.trueH);
  let v = Math.min(maxSpeed, Math.max(0.10, (d - stopDist) * 0.80));
  if (d < stopDist + 2.0) v = Math.min(v, Math.max(0.08, (d - stopDist) * 0.55));
  return driveRelative(rel, v, obs, mem, dt);
}

function makeSpiral(cx, cy, R, step, size) {
  const pts = [{ x: clamp(cx, 4, size - 4), y: clamp(cy, 4, size - 4) }];
  let x = 0, y = 0;
  let len = step;
  let dir = 0;
  const dirs = [[1, 0], [0, 1], [-1, 0], [0, -1]];
  let guard = 0;

  while (len < 2 * R + 2 * step && guard++ < 40) {
    for (let rep = 0; rep < 2; rep++) {
      x += dirs[dir][0] * len;
      y += dirs[dir][1] * len;
      const px = clamp(cx + x, 4, size - 4);
      const py = clamp(cy + y, 4, size - 4);
      const last = pts[pts.length - 1];
      if (!last || dist(px, py, last.x, last.y) > 2.0) {
        pts.push({ x: px, y: py });
      }
      dir = (dir + 1) % 4;
      if (Math.abs(x) > R + step * 1.5 && Math.abs(y) > R + step * 1.5) break;
    }
    len += step;
    if (Math.abs(x) > R + step * 1.5 && Math.abs(y) > R + step * 1.5) break;
  }
  return pts;
}

function startSearch(mem, now, timeLeft, cx, cy, hintIdx, forcedR, exploreId) {
  let R = forcedR != null ? forcedR : 18;
  if (timeLeft < 250) R = Math.min(R, 15);
  if (timeLeft < 150) R = Math.min(R, 12);
  if (timeLeft < 90) R = Math.min(R, 9);

  const pts = makeSpiral(cx, cy, R, 9.5, mem.size);
  let pathLen = 0;
  for (let i = 1; i < pts.length; i++) pathLen += dist(pts[i - 1].x, pts[i - 1].y, pts[i].x, pts[i].y);

  let maxDur = Math.min(260, 30 + pathLen / 0.55);
  if (timeLeft < maxDur + 20) maxDur = Math.max(20, timeLeft - 20);

  mem.search = {
    cx: cx, cy: cy, pts: pts, idx: 0,
    start: now, deadline: now + maxDur,
    lastProgress: now, bestDist: 1e9,
    hintIdx: hintIdx, exploreId: exploreId
  };
  mem.mode = "search";
  mem.target = null;
  mem.siteInfo = null;
  mem.activeHint = hintIdx;
}

function finishSearch(mem, obs, now, dt) {
  const s = mem.search;
  if (s && s.hintIdx >= 0 && mem.hints[s.hintIdx] && mem.hints[s.hintIdx].state === 0) {
    mem.hints[s.hintIdx].state = 2;
  }
  if (s && s.exploreId != null && mem.explore[s.exploreId]) {
    mem.explore[s.exploreId].visited = true;
  }
  mem.search = null;
  mem.activeHint = -1;
  mem.target = null;
  mem.mode = "idle";
  return applyWheels(0, 0, obs, mem, dt, false);
}

function startToHint(mem, obs, now, idx) {
  const h = mem.hints[idx];
  mem.activeHint = idx;
  mem.target = {
    x: h.x, y: h.y, type: "hint", hintIdx: idx,
    start: now, lastProgress: now,
    bestDist: dist(mem.x, mem.y, h.x, h.y)
  };
  mem.mode = "toHint";
  mem.siteInfo = null;
  mem.drillStart = null;
}

function chooseHint(mem, obs, now, timeLeft, battery) {
  let best = -1;
  let bestScore = 1e100;

  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (!h || h.state !== 0) continue;

    const d = dist(mem.x, mem.y, h.x, h.y);
    const db = dist(h.x, h.y, mem.baseX, mem.baseY);
    const vr = clamp(h.val / Math.max(0.000001, mem.maxHintVal), 0, 1);

    let R = 18;
    if (timeLeft < 250) R = 14;
    if (timeLeft < 140) R = 10;
    const pathLen = (2 * R) * (2 * R) / 9.5 * 1.15 + 20;
    const need = (d + db + pathLen * 0.5 + 30) / 0.65 + 25;

    let score;
    if (mem.deliveredSamples === 0 && mem.samplesCollected === 0) {
      score = d + 0.35 * db - 18 * vr;
    } else {
      score = (d + 0.45 * db + 0.35 * pathLen) / (0.3 + 1.8 * vr);
    }
    if (timeLeft < 300) score += db * (0.5 + 0.2 * (300 - timeLeft) / 300);
    if (timeLeft < need) score += 40 + (need - timeLeft) * 2;
    if (battery < 0.20) score += 30;

    if (score < bestScore) {
      bestScore = score;
      best = i;
    }
  }
  return best;
}

function chooseExplore(mem, obs, now, timeLeft, battery) {
  if (!mem.explore || mem.explore.length === 0) return null;

  for (let i = 0; i < mem.explore.length; i++) {
    const p = mem.explore[i];
    if (!p.visited && dist(mem.x, mem.y, p.x, p.y) < 15) p.visited = true;
  }

  let best = null;
  let bestScore = 1e100;
  for (let i = 0; i < mem.explore.length; i++) {
    const p = mem.explore[i];
    if (p.visited) continue;
    const d = dist(mem.x, mem.y, p.x, p.y);
    const db = dist(p.x, p.y, mem.baseX, mem.baseY);
    if (timeLeft < (d + db) / 0.6 + 45) continue;
    if (battery < 0.15) continue;
    const score = d + 0.3 * db;
    if (score < bestScore) {
      bestScore = score;
      best = p;
    }
  }
  return best;
}

function isAtBase(mem, obs) {
  if (obs.docked) return true;
  const b = obs.beacon;
  if (b && isFinite(Number(b.distance)) && Number(b.distance) <= 3.0) return true;
  if (dist(mem.x, mem.y, mem.baseX, mem.baseY) <= 2.8) return true;
  return false;
}

function chargeTarget(timeLeft) {
  if (timeLeft > 500) return 1.0;
  if (timeLeft > 300) return 0.70;
  if (timeLeft > 150) return 0.55;
  return 0.40;
}

function handleCalib(obs, mem, now, timeLeft, battery, dt) {
  if (now < mem.calStart) mem.calStart = now;
  mem.calSin += Math.sin(mem.rawH);
  mem.calCos += Math.cos(mem.rawH);
  mem.calCount++;

  const d = dist(mem.x, mem.y, mem.calX, mem.calY);
  const elapsed = now - mem.calStart;

  if (elapsed >= 2.2 || d >= 1.0) {
    if (d > 0.35 && mem.calCount > 5) {
      const course = Math.atan2(mem.y - mem.calY, mem.x - mem.calX);
      const avg = Math.atan2(mem.calSin, mem.calCos);
      mem.bias = wrap(course - avg);
      mem.biasValid = true;
    }
    mem.mode = "idle";
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  if (obs.bumped || frontClearance(obs.rays) < 0.9) {
    mem.mode = "idle";
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  return applyWheels(0.45, 0.45, obs, mem, dt, false);
}

function handleSite(obs, mem, now, timeLeft, battery, dt) {
  const s = mem.siteInfo;
  if (!s) {
    mem.mode = "idle";
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  const since = now - s.lastSeen;
  let d, b;

  if (since < 0.6) {
    d = s.d;
    b = s.b;
  } else if (since < 4.0) {
    const dd = dist(mem.x, mem.y, s.x, s.y);
    if (dd > 1.35) {
      return navigateToPoint(s.x, s.y, 0.45, 1.0, obs, mem, dt);
    }
    const maxW = Math.max(Math.abs(Number(obs.wheelLeft) || 0), Math.abs(Number(obs.wheelRight) || 0));
    if (maxW < 0.10) {
      mem.mode = "drill";
      mem.drillStart = now;
      mem.drillSite = { x: s.x, y: s.y };
      mem.siteAttempts = (mem.siteAttempts || 0) + 1;
      return applyWheels(0, 0, obs, mem, dt, true);
    }
    return applyWheels(0, 0, obs, mem, dt, false);
  } else {
    addIgnore(mem, s.x, s.y, now, 120, 3);
    mem.siteInfo = null;
    mem.mode = "idle";
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  const maxW = Math.max(Math.abs(Number(obs.wheelLeft) || 0), Math.abs(Number(obs.wheelRight) || 0));

  if (d <= 1.42 && maxW < 0.11 && battery > 0.010) {
    mem.mode = "drill";
    mem.drillStart = now;
    mem.drillSite = { x: s.x, y: s.y };
    mem.siteAttempts = (mem.siteAttempts || 0) + 1;
    return applyWheels(0, 0, obs, mem, dt, true);
  }

  if (d <= 1.55 && maxW >= 0.08) {
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  if (d < 3.0) {
    const err = wrap(b);
    let v = 0.18;
    if (d < 1.7) v = 0.06;
    if (d < 1.45) v = 0.0;
    if (Math.abs(err) > 0.60) v = 0;

    const omega = clamp(1.8 * err, -1.0, 1.0);
    let vL, vR;
    if (v < 0.025) {
      vL = -0.3 * omega;
      vR = 0.3 * omega;
    } else {
      vL = v - 0.3 * omega;
      vR = v + 0.3 * omega;
    }
    if (frontClearance(obs.rays) < 0.65) {
      vL = 0;
      vR = 0;
    }
    return applyWheels(vL, vR, obs, mem, dt, false);
  }

  let v = Math.min(0.60, Math.max(0.10, (d - 1.20) * 0.55));
  if (timeLeft < 90) v = Math.min(0.70, v * 1.10);
  if (battery < 0.20) v = Math.min(v, 0.35);
  return driveRelative(b, v, obs, mem, dt);
}

function handleDrill(obs, mem, now, timeLeft, battery, dt) {
  const carried = Number(obs.carried) || 0;

  if (!mem.drillStart) {
    mem.mode = "site";
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  const elapsed = now - mem.drillStart;
  const maxW = Math.max(Math.abs(Number(obs.wheelLeft) || 0), Math.abs(Number(obs.wheelRight) || 0));

  if (timeLeft < 2.0 || battery < 0.005 || elapsed > 7.8 || (maxW > 0.30 && elapsed > 2.0)) {
    const failX = mem.drillSite ? mem.drillSite.x : (mem.siteInfo ? mem.siteInfo.x : mem.x);
    const failY = mem.drillSite ? mem.drillSite.y : (mem.siteInfo ? mem.siteInfo.y : mem.y);
    mem.drillStart = null;

    if ((mem.siteAttempts || 1) < 2) {
      mem.mode = "site";
      mem.siteModeStart = now;
    } else {
      addIgnore(mem, failX, failY, now, 180, 3);
      mem.siteInfo = null;
      mem.activeHint = -1;
      mem.search = null;
      mem.target = null;
      mem.mode = "idle";
    }
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  return applyWheels(0, 0, obs, mem, dt, true);
}

function handleReturn(obs, mem, now, timeLeft, battery, carried, dt) {
  const b = obs.beacon;
  const bd = b && isFinite(Number(b.distance)) ? Number(b.distance) : null;
  const at = isAtBase(mem, obs);

  if (at) {
    if (carried > 0) {
      if (mem.atBaseSince == null) mem.atBaseSince = now;
      if (!obs.docked && b && bd != null && bd > 0.7 &&
          now - mem.atBaseSince > 1.0 && timeLeft > 5) {
        return driveRelative((Number(b.bearing) || 0) * D2R, 0.18, obs, mem, dt);
      }
      return applyWheels(0, 0, obs, mem, dt, false);
    }
    mem.mode = "idle";
    return applyWheels(0, 0, obs, mem, dt, false);
  }
  mem.atBaseSince = null;

  if (b && bd != null && isFinite(bd) && bd < 25) {
    if (bd <= 1.0) return applyWheels(0, 0, obs, mem, dt, false);
    let sp;
    if (bd > 10) sp = 0.75;
    else if (bd > 4) sp = 0.50;
    else sp = 0.30;
    if (timeLeft < 80) sp = Math.min(0.90, sp + 0.15);
    if (battery < 0.20) sp = Math.min(sp, 0.55);
    return driveRelative((Number(b.bearing) || 0) * D2R, sp, obs, mem, dt);
  }

  let sp = 0.80;
  if (timeLeft < 100) sp = 0.90;
  if (battery < 0.20) sp = 0.60;
  return navigateToPoint(mem.baseX, mem.baseY, sp, 1.2, obs, mem, dt);
}

function handleCharge(obs, mem, now, timeLeft, battery, dt) {
  if (!isAtBase(mem, obs)) {
    mem.mode = "return";
    return handleReturn(obs, mem, now, timeLeft, battery, 0, dt);
  }

  if (battery >= (mem.chargeTarget || 0.8) || timeLeft < 60 ||
      (mem.chargeStart >= 0 && now - mem.chargeStart > 120)) {
    mem.mode = "idle";
    mem.chargeStart = -1;
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  const b = obs.beacon;
  if (!obs.docked && b && isFinite(Number(b.distance)) &&
      Number(b.distance) > 0.8 && timeLeft > 10) {
    return driveRelative((Number(b.bearing) || 0) * D2R, 0.20, obs, mem, dt);
  }

  return applyWheels(0, 0, obs, mem, dt, false);
}

function handleToHint(obs, mem, now, timeLeft, battery, dt) {
  const t = mem.target;
  if (!t || mem.activeHint < 0 || !mem.hints[mem.activeHint] ||
      mem.hints[mem.activeHint].state !== 0) {
    mem.mode = "idle";
    mem.activeHint = -1;
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  const h = mem.hints[mem.activeHint];
  const d = dist(mem.x, mem.y, h.x, h.y);

  if (d < 5.0 || (now - t.start > 15 && d < 10)) {
    startSearch(mem, now, timeLeft, h.x, h.y, mem.activeHint, null, null);
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  if (d < t.bestDist - 0.45) {
    t.bestDist = d;
    t.lastProgress = now;
  }

  const maxTravel = Math.max(70, 25 + 2.2 * Math.max(1, t.bestDist));
  if (now - t.lastProgress > 45 || now - t.start > maxTravel) {
    if (d < 20) {
      startSearch(mem, now, timeLeft, h.x, h.y, mem.activeHint, null, null);
      return applyWheels(0, 0, obs, mem, dt, false);
    }
    h.state = 2;
    mem.activeHint = -1;
    mem.target = null;
    mem.mode = "idle";
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  let sp = 0.75;
  if (timeLeft < 160) sp = 0.85;
  if (battery < 0.20) sp = 0.55;
  return navigateToPoint(h.x, h.y, sp, 2.0, obs, mem, dt);
}

function handleSearch(obs, mem, now, timeLeft, battery, dt) {
  const s = mem.search;
  if (!s) {
    mem.mode = "idle";
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  if (timeLeft < 20 || now > s.deadline || s.idx >= s.pts.length) {
    return finishSearch(mem, obs, now, dt);
  }

  let p = s.pts[s.idx];
  let d = dist(mem.x, mem.y, p.x, p.y);

  if (d < 1.20) {
    s.idx++;
    s.lastProgress = now;
    s.bestDist = 1e9;
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  if (d < s.bestDist - 0.45) {
    s.bestDist = d;
    s.lastProgress = now;
  }

  if (now - s.lastProgress > 10) {
    s.idx++;
    s.lastProgress = now;
    s.bestDist = 1e9;
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  let sp = 0.70;
  if (timeLeft < 150) sp = 0.80;
  if (battery < 0.20) sp = 0.55;
  return navigateToPoint(p.x, p.y, sp, 0.9, obs, mem, dt);
}

function handleToExplore(obs, mem, now, timeLeft, battery, dt) {
  const t = mem.target;
  if (!t) {
    mem.mode = "idle";
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  const d = dist(mem.x, mem.y, t.x, t.y);
  if (d < 5.0) {
    startSearch(mem, now, timeLeft, t.x, t.y, -1, 16, t.id);
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  if (d < t.bestDist - 0.45) {
    t.bestDist = d;
    t.lastProgress = now;
  }

  if (now - t.start > 200 || now - t.lastProgress > 60) {
    if (t.id != null && mem.explore[t.id]) mem.explore[t.id].visited = true;
    mem.target = null;
    mem.mode = "idle";
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  let sp = 0.75;
  if (timeLeft < 180) sp = 0.85;
  if (battery < 0.20) sp = 0.55;
  return navigateToPoint(t.x, t.y, sp, 1.5, obs, mem, dt);
}

function handleIdle(obs, mem, now, timeLeft, battery, dt) {
  const atBase = isAtBase(mem, obs);
  const carry = Number(obs.carried) || 0;

  if (carry > 0) {
    mem.mode = "return";
    return handleReturn(obs, mem, now, timeLeft, battery, carry, dt);
  }

  if (atBase) {
    const ct = chargeTarget(timeLeft);
    if (battery < ct - 0.02 && timeLeft > 80) {
      mem.mode = "charge";
      mem.chargeStart = now;
      mem.chargeTarget = ct;
      return applyWheels(0, 0, obs, mem, dt, false);
    }
  }

  if (!atBase && battery < 0.10 && timeLeft > 30) {
    mem.mode = "return";
    return handleReturn(obs, mem, now, timeLeft, battery, 0, dt);
  }

  if (timeLeft < 50 && atBase) {
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  const idx = chooseHint(mem, obs, now, timeLeft, battery);
  if (idx >= 0) {
    startToHint(mem, obs, now, idx);
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  const ep = chooseExplore(mem, obs, now, timeLeft, battery);
  if (ep) {
    ep.visited = true;
    mem.exploreTarget = ep;
    mem.target = {
      x: ep.x, y: ep.y, type: "explore", id: ep.id,
      start: now, lastProgress: now,
      bestDist: dist(mem.x, mem.y, ep.x, ep.y)
    };
    mem.mode = "toExplore";
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  if (!atBase && Number(obs.science) > 0.03 && timeLeft > 80 &&
      now - (mem.lastScienceSearch || -9999) > 120) {
    mem.lastScienceSearch = now;
    startSearch(mem, now, timeLeft, mem.x, mem.y, -1, 12, null);
    return applyWheels(0, 0, obs, mem, dt, false);
  }

  if (!atBase && timeLeft > 20) {
    mem.mode = "return";
    return handleReturn(obs, mem, now, timeLeft, battery, 0, dt);
  }

  return applyWheels(0, 0, obs, mem, dt, false);
}

function startRecovery(mem, obs, now) {
  if (now < (mem.recoverUntil || -1)) return;
  mem.recoverUntil = now + 1.2;
  mem.recoverStart = now;

  const rays = obs.rays || [];
  let left = 0, right = 0;
  for (let i = 0; i < 9; i++) {
    let d = Number(rays[i]);
    if (!isFinite(d) || d < 0 || d > 15) d = 9;
    if (i <= 3) right += d;
    else if (i >= 5) left += d;
  }
  mem.recoverSide = left >= right ? 1 : -1;

  if (now - (mem.lastBumpT || -9999) > 15) mem.bumpCount = 0;
  mem.bumpCount = (mem.bumpCount || 0) + 1;
  mem.lastBumpT = now;

  if (mem.bumpCount >= 5) {
    if (mem.target && mem.target.type === "hint" && mem.target.hintIdx >= 0 &&
        mem.hints[mem.target.hintIdx]) {
      mem.hints[mem.target.hintIdx].state = 2;
    }
    if (mem.search && mem.search.hintIdx >= 0 && mem.hints[mem.search.hintIdx]) {
      mem.hints[mem.search.hintIdx].state = 2;
    }
    if (mem.siteInfo) addIgnore(mem, mem.siteInfo.x, mem.siteInfo.y, now, 120, 3);
    mem.siteInfo = null;
    mem.search = null;
    mem.target = null;
    mem.activeHint = -1;
    mem.mode = "idle";
    mem.bumpCount = 0;
  }
}

function doRecovery(obs, mem, now, dt) {
  const elapsed = now - mem.recoverStart;
  if (elapsed < 0.45) {
    return applyWheels(-0.32, -0.32, obs, mem, dt, false);
  }
  const side = mem.recoverSide || 1;
  const omega = 0.85 * side;
  return applyWheels(-0.3 * omega, 0.3 * omega, obs, mem, dt, false);
}

function checkStuck(obs, mem, now, dt) {
  if (mem.mode === "drill" || mem.mode === "calib" || now < (mem.recoverUntil || -1)) {
    mem.stuckCount = 0;
    return;
  }
  if (mem.mode === "site" && mem.siteInfo && mem.siteInfo.d < 2.2) return;

  if (now - (mem.stuckCheckT || 0) >= 1.0) {
    const cmd = Math.abs(mem.lastCmdL || 0) + Math.abs(mem.lastCmdR || 0);
    const moved = dist(mem.x, mem.y, mem.stuckX || mem.x, mem.stuckY || mem.y);
    const movingMode = (mem.mode === "toHint" || mem.mode === "search" ||
                        mem.mode === "site" || mem.mode === "return" ||
                        mem.mode === "toExplore");

    if (movingMode && cmd > 0.35 && moved < 0.10) {
      mem.stuckCount = (mem.stuckCount || 0) + 1;
    } else if (moved > 0.30) {
      mem.stuckCount = 0;
    } else {
      mem.stuckCount = Math.max(0, (mem.stuckCount || 0) - 1);
    }

    mem.stuckX = mem.x;
    mem.stuckY = mem.y;
    mem.stuckCheckT = now;

    if (mem.stuckCount >= 3) {
      startRecovery(mem, obs, now);
      mem.stuckCount = 0;
    }
  }
}

function markSampleSuccess(mem, now) {
  let sx = mem.x, sy = mem.y;
  if (mem.siteInfo) {
    sx = mem.siteInfo.x;
    sy = mem.siteInfo.y;
  }

  let best = -1, bd = 35;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.state !== 0) continue;
    const d = dist(h.x, h.y, sx, sy);
    if (d < bd) {
      bd = d;
      best = i;
    }
  }
  if (best >= 0) mem.hints[best].state = 1;
  if (mem.activeHint >= 0 && mem.hints[mem.activeHint]) {
    mem.hints[mem.activeHint].state = 1;
  }
  if (mem.search && mem.search.hintIdx >= 0 && mem.hints[mem.search.hintIdx]) {
    mem.hints[mem.search.hintIdx].state = 1;
  }

  mem.siteInfo = null;
  mem.search = null;
  mem.target = null;
  mem.activeHint = -1;
  mem.drillStart = null;
  mem.mode = "return";
  mem.atBaseSince = null;
}

function act(obs, mem) {
  try {
    if (!mem.init) initMem(obs, mem);

    const now = (obs.t != null && isFinite(Number(obs.t))) ? Number(obs.t) : ((mem.tick || 0) * 0.1);
    let dt = 0.1;
    if (mem.lastT != null && now > mem.lastT) {
      dt = clamp(now - mem.lastT, 0.02, 0.5);
    }
    mem.lastT = now;
    mem.dt = dt;
    mem.tick = (mem.tick || 0) + 1;

    updatePose(obs, mem, now, dt);
    updateRays(obs, mem);

    const carried = clamp(Number(obs.carried) || 0, 0, 99);
    const battery = (obs.battery != null && isFinite(Number(obs.battery))) ?
      Number(obs.battery) : 1;
    const timeLeft = (obs.timeLeft != null && isFinite(Number(obs.timeLeft))) ?
      Number(obs.timeLeft) : Math.max(0, mem.seconds - now);

    let vis = null;
    if (carried === 0) {
      vis = observeSite(obs, mem, now, carried);
    }

    if (carried > mem.prevCarried) {
      mem.samplesCollected = (mem.samplesCollected || 0) + (carried - mem.prevCarried);
      markSampleSuccess(mem, now);
    } else if (carried < mem.prevCarried) {
      mem.deliveredSamples = (mem.deliveredSamples || 0) + (mem.prevCarried - carried);
      mem.lastDeliveryT = now;
      mem.mode = "idle";
      mem.siteInfo = null;
      mem.search = null;
      mem.target = null;
      mem.drillStart = null;
      mem.activeHint = -1;
      mem.chargeStart = now;
      mem.atBaseSince = null;
    }
    mem.prevCarried = carried;

    if (obs.bumped && !mem.prevBumped && mem.mode !== "drill") {
      startRecovery(mem, obs, now);
    }
    mem.prevBumped = !!obs.bumped;

    checkStuck(obs, mem, now, dt);

    if (now < (mem.recoverUntil || -1) && mem.mode !== "drill") {
      return doRecovery(obs, mem, now, dt);
    }

    if (timeLeft < 0.25) {
      return applyWheels(0, 0, obs, mem, dt, false);
    }

    if (mem.mode === "drill") {
      return handleDrill(obs, mem, now, timeLeft, battery, dt);
    }

    if (carried > 0) {
      if (mem.mode !== "return") {
        mem.mode = "return";
        mem.atBaseSince = null;
      }
      return handleReturn(obs, mem, now, timeLeft, battery, carried, dt);
    }

    if (mem.mode === "return") {
      mem.mode = "idle";
    }

    if (vis && !isIgnored(mem, vis.x, vis.y, now)) {
      if (mem.mode !== "site") {
        mem.mode = "site";
        mem.siteModeStart = now;
        mem.siteAttempts = 0;
        mem.search = null;
        mem.target = null;
      }
      return handleSite(obs, mem, now, timeLeft, battery, dt);
    }

    if (mem.mode === "site") {
      return handleSite(obs, mem, now, timeLeft, battery, dt);
    }

    if (mem.mode === "calib") {
      return handleCalib(obs, mem, now, timeLeft, battery, dt);
    }
    if (mem.mode === "toHint") {
      return handleToHint(obs, mem, now, timeLeft, battery, dt);
    }
    if (mem.mode === "search") {
      return handleSearch(obs, mem, now, timeLeft, battery, dt);
    }
    if (mem.mode === "charge") {
      return handleCharge(obs, mem, now, timeLeft, battery, dt);
    }
    if (mem.mode === "toExplore") {
      return handleToExplore(obs, mem, now, timeLeft, battery, dt);
    }

    return handleIdle(obs, mem, now, timeLeft, battery, dt);
  } catch (e) {
    return { left: 0, right: 0, drill: false };
  }
}

const D2R = Math.PI / 180;

function clamp(v, a, b) {
  v = Number(v);
  if (!isFinite(v)) v = a;
  return v < a ? a : (v > b ? b : v);
}
function wrap(a) {
  a = Number(a);
  if (!isFinite(a)) return 0;
  a = a % (Math.PI * 2);
  if (a > Math.PI) a -= Math.PI * 2;
  if (a < -Math.PI) a += Math.PI * 2;
  return a;
}
function dist(ax, ay, bx, by) {
  const dx = ax - bx, dy = ay - by;
  return Math.sqrt(dx * dx + dy * dy);
}
function edgeClear(x, y, ang, margin, size) {
  const ca = Math.cos(ang), sa = Math.sin(ang);
  let e = 1e9;
  if (ca > 1e-6) e = Math.min(e, (size - margin - x) / ca);
  else if (ca < -1e-6) e = Math.min(e, (margin - x) / ca);
  if (sa > 1e-6) e = Math.min(e, (size - margin - y) / sa);
  else if (sa < -1e-6) e = Math.min(e, (margin - y) / sa);
  return Math.max(0, e);
}
function clearanceInDir(rel, rays) {
  if (!rays) return 15;
  let best = 15;
  for (let i = 0; i < 9; i++) {
    let d = Number(rays[i]);
    if (!isFinite(d) || d < 0) continue;
    if (d > 15) d = 15;
    const a = (-80 + i * 20) * D2R;
    const diff = Math.abs(wrap(a - rel));
    if (diff < 0.90) {
      const proj = d * Math.cos(diff);
      if (proj < best) best = proj;
    }
  }
  return best;
}
function isAtBase(obs, mem) {
  if (obs.docked) return true;
  const b = obs.beacon;
  if (b && isFinite(Number(b.distance)) && Number(b.distance) <= 2.9) return true;
  if (dist(mem.x, mem.y, mem.baseX, mem.baseY) <= 2.7) return true;
  return false;
}
function addIgnore(mem, x, y, now, dur, rad) {
  if (!isFinite(x) || !isFinite(y)) return;
  mem.ignore.push({ x: x, y: y, until: now + (dur || 35), rad: rad || 3.5 });
  while (mem.ignore.length > 25) mem.ignore.shift();
}
function isIgnored(mem, x, y, now) {
  for (let i = mem.ignore.length - 1; i >= 0; i--) {
    const q = mem.ignore[i];
    if (now < q.until && dist(x, y, q.x, q.y) < q.rad) return true;
  }
  return false;
}

function updateRays(obs, mem) {
  const rays = obs.rays || [];
  let valid = 0, mn = 15, mx = 0;
  for (let i = 0; i < 9; i++) {
    let d = Number(rays[i]);
    if (isFinite(d) && d >= 0) {
      valid++;
      if (d < mn) mn = d;
      if (d > mx) mx = d;
    }
  }
  mem.raysBad = (valid >= 7 && mx - mn < 0.05 && mn < 12);
}

function updatePose(obs, mem, now, dt) {
  const hr = Number(obs.heading);
  if (isFinite(hr)) {
    const raw = hr * D2R;
    let prev = (mem.rawH === undefined) ? raw : mem.rawH;
    let diff = wrap(raw - prev);
    const turnCmd = Math.abs((Number(obs.wheelRight) || 0) - (Number(obs.wheelLeft) || 0));
    if (Math.abs(diff) > 1.60 && turnCmd < 0.8 && (mem.tick || 0) > 5) {
      // likely a compass jump; keep the filter state
    } else {
      mem.rawH = wrap(prev + diff * 0.65);
    }
  }
  if (mem.rawH === undefined) mem.rawH = 0;
  if (!isFinite(mem.bias)) mem.bias = 0;
  mem.trueH = wrap(mem.rawH + mem.bias);

  const wl = Number(obs.wheelLeft) || 0;
  const wr = Number(obs.wheelRight) || 0;
  const v = (wl + wr) * 0.5;
  const gx = Number(obs.x), gy = Number(obs.y);

  if (isFinite(gx) && isFinite(gy)) {
    const stepG = dist(gx, gy, mem.lastGpsX, mem.lastGpsY);
    if (Math.abs(v) > 0.08 && stepG < 0.008) mem.gpsFreezeT += dt;
    else mem.gpsFreezeT = Math.max(0, mem.gpsFreezeT - dt * 2.0);

    if (mem.gpsFreezeT > 1.5) mem.gpsFrozen = true;
    if (mem.gpsFrozen && stepG > 0.15) {
      mem.gpsFrozen = false;
      mem.gpsFreezeT = 0;
    }

    if (!mem.gpsFrozen) {
      const jump = dist(gx, gy, mem.x, mem.y);
      if (jump > 5.0) {
        mem.x = gx;
        mem.y = gy;
      } else {
        mem.x += (gx - mem.x) * 0.50;
        mem.y += (gy - mem.y) * 0.50;
      }
      mem.lastGpsX = gx;
      mem.lastGpsY = gy;
    } else {
      mem.x += Math.cos(mem.trueH) * v * dt;
      mem.y += Math.sin(mem.trueH) * v * dt;
    }
  } else {
    mem.x += Math.cos(mem.trueH) * v * dt;
    mem.y += Math.sin(mem.trueH) * v * dt;
  }

  mem.x = clamp(mem.x, 0.5, mem.size - 0.5);
  mem.y = clamp(mem.y, 0.5, mem.size - 0.5);

  const b = obs.beacon;
  if (b && isFinite(Number(b.distance)) && isFinite(Number(b.bearing))) {
    const bd = Number(b.distance);
    const br = Number(b.bearing) * D2R;
    if (bd > 1.2 && bd < 19.0) {
      const angToBase = Math.atan2(mem.baseY - mem.y, mem.baseX - mem.x);
      const trueHead = wrap(angToBase - br);
      const biasEst = wrap(trueHead - mem.rawH);
      if (!mem.biasValid) {
        mem.bias = biasEst;
        mem.biasValid = true;
      } else {
        const de = wrap(biasEst - mem.bias);
        if (Math.abs(de) < 0.8) mem.bias = wrap(mem.bias + de * 0.08);
      }
      mem.trueH = wrap(mem.rawH + mem.bias);
    }
  }

  mem.calSin += Math.sin(mem.rawH);
  mem.calCos += Math.cos(mem.rawH);
  mem.calCount++;
  mem.calVSum += Math.abs(v);
  mem.calDiffSum += Math.abs(wr - wl);
  if (wl + wr > 0.08) mem.calFwdCount++;

  if (now - mem.calT > 1.0) {
    if (mem.calCount > 3) {
      const dx = mem.x - mem.calX;
      const dy = mem.y - mem.calY;
      const dd = Math.sqrt(dx * dx + dy * dy);
      const avgV = mem.calVSum / mem.calCount;
      const avgDiff = mem.calDiffSum / mem.calCount;
      if (dd > 0.30 && avgV > 0.08 && avgDiff < 0.28 &&
          dd < avgV * 1.8 + 1.0 && mem.calFwdCount > mem.calCount * 0.60) {
        const avgRaw = Math.atan2(mem.calSin, mem.calCos);
        const course = Math.atan2(dy, dx);
        const biasEst = wrap(course - avgRaw);
        if (!mem.biasValid) {
          mem.bias = biasEst;
          mem.biasValid = true;
        } else {
          const de = wrap(biasEst - mem.bias);
          if (Math.abs(de) < 0.9) mem.bias = wrap(mem.bias + de * 0.05);
        }
        mem.trueH = wrap(mem.rawH + mem.bias);
      }
    }
    mem.calX = mem.x;
    mem.calY = mem.y;
    mem.calT = now;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.calCount = 0;
    mem.calVSum = 0;
    mem.calDiffSum = 0;
    mem.calFwdCount = 0;
  }
}

function wheelControl(st, target, actual, pitch, dt) {
  if (!st) return 0;
  if (st.gain === undefined) st.gain = 1.5;
  if (st.i === undefined) st.i = 0;
  if (st.lastCmd === undefined) st.lastCmd = 0;

  let av = Number(actual) || 0;
  let tg = clamp(Number(target) || 0, -0.85, 0.85);

  if (Math.abs(av) > 1.25) {
    const u = -Math.sign(av) * 1.0;
    st.lastCmd = u;
    return clamp(u, -1, 1);
  }

  if (Math.abs(st.lastCmd) > 0.08 && Math.abs(av) > 0.08 && st.lastCmd * av > 0) {
    const g = Math.abs(av / st.lastCmd);
    if (g > 0.25 && g < 8.0) {
      st.gain = st.gain * 0.98 + g * 0.02;
    }
  }
  st.gain = clamp(st.gain, 0.4, 6.0);

  const err = tg - av;
  let u = tg / Math.max(0.6, st.gain) + 0.9 * err;

  st.i += err * dt * 0.45;
  st.i = clamp(st.i, -0.35, 0.35);
  u += st.i;

  if (Math.abs(tg) < 0.02) {
    u += clamp((Number(pitch) || 0) * 0.015, -0.25, 0.25);
    if (Math.abs(av) < 0.025 && Math.abs(u) < 0.06) u = 0;
  }

  const prev = st.lastCmd || 0;
  const maxD = 5.0 * dt;
  if (u > prev + maxD) u = prev + maxD;
  else if (u < prev - maxD) u = prev - maxD;

  if (u > 0.015 && u < 0.06) u = 0.06;
  else if (u < -0.015 && u > -0.06) u = -0.06;

  u = clamp(u, -1, 1);

  if (u > 0.98 && err > 0) st.i = Math.min(st.i, 0.25);
  if (u < -0.98 && err < 0) st.i = Math.max(st.i, -0.25);

  st.lastCmd = u;
  return u;
}

function applyWheels(vL, vR, obs, mem, dt, drill) {
  vL = clamp(Number(vL) || 0, -0.85, 0.85);
  vR = clamp(Number(vR) || 0, -0.85, 0.85);

  const wl = Number(obs.wheelLeft) || 0;
  const wr = Number(obs.wheelRight) || 0;
  const pitch = Number(obs.pitch) || 0;

  const uL = wheelControl(mem.wheelL, vL, wl, pitch, dt);
  const uR = wheelControl(mem.wheelR, vR, wr, pitch, dt);

  return { left: clamp(uL, -1, 1), right: clamp(uR, -1, 1), drill: !!drill };
}

function hold(obs, mem, dt, drill) {
  return applyWheels(0, 0, obs, mem, dt, !!drill);
}

function chooseAvoid(desired, obs, mem) {
  desired = wrap(desired);
  const rays = obs.rays || [];
  if (mem.raysBad) return desired;

  let blocked = false;
  for (let i = 0; i < 9; i++) {
    let d = Number(rays[i]);
    if (!isFinite(d) || d < 0) continue;
    if (d > 15) d = 15;
    const a = (-80 + i * 20) * D2R;
    const diff = Math.abs(wrap(a - desired));
    if (d < 2.8 && diff < 0.65) {
      blocked = true;
      break;
    }
  }
  if (!blocked) {
    mem.avoidPrev = desired;
    return desired;
  }

  let best = desired;
  let bestCost = 1e100;

  for (let deg = -160; deg <= 160; deg += 10) {
    const cand = wrap(desired + deg * D2R);
    let cost = Math.abs(deg) * 0.015 + deg * deg * 0.00012;

    for (let i = 0; i < 9; i++) {
      let d = Number(rays[i]);
      if (!isFinite(d) || d < 0) continue;
      if (d > 15) d = 15;
      const a = (-80 + i * 20) * D2R;
      const diff = Math.abs(wrap(a - cand));
      if (diff < 0.80) {
        const proj = d * Math.cos(diff);
        if (proj < 0.60) cost += 500;
        else if (proj < 2.0) cost += (2.0 - proj) * (2.0 - proj) * 12 * (1 - diff / 0.80);
      }
    }

    const world = wrap(mem.trueH + cand);
    const ed = edgeClear(mem.x, mem.y, world, 2.0, mem.size);
    if (ed < 2.8) cost += (2.8 - ed) * (2.8 - ed) * 8;
    if (ed < 0.8) cost += 500;

    if (mem.avoidPrev !== undefined && mem.avoidPrev !== null) {
      cost += (1 - Math.cos(wrap(cand - mem.avoidPrev))) * 0.05;
    }

    if (cost < bestCost) {
      bestCost = cost;
      best = cand;
    }
  }

  mem.avoidPrev = best;
  return best;
}

function driveRelative(rel, speed, obs, mem, dt, avoid) {
  rel = wrap(rel);
  let chosen = avoid ? chooseAvoid(rel, obs, mem) : rel;
  const err = wrap(chosen);

  let v = clamp(Number(speed) || 0, 0, 0.75);

  const clear = clearanceInDir(chosen, obs.rays);
  if (!mem.raysBad) {
    if (clear < 0.65) v = 0;
    else if (clear < 1.8) v = Math.min(v, Math.max(0.04, (clear - 0.50) * 0.55));
  }

  const world = wrap(mem.trueH + chosen);
  const ed = edgeClear(mem.x, mem.y, world, 2.0, mem.size);
  if (ed < 2.5) v = Math.min(v, Math.max(0.04, (ed - 0.70) * 0.50));
  if (ed < 0.8) v = 0;

  if (Math.abs(err) > 1.20) v = 0;
  else if (Math.abs(err) > 0.55) v *= 0.35;
  else v *= Math.max(0.25, Math.cos(err));

  const omega = clamp(1.7 * err, -1.35, 1.35);
  let vL, vR;

  if (v < 0.025 && Math.abs(err) > 0.06) {
    vL = -0.30 * omega;
    vR = 0.30 * omega;
  } else if (v < 0.02) {
    vL = 0;
    vR = 0;
  } else {
    vL = v - 0.30 * omega;
    vR = v + 0.30 * omega;
  }

  return applyWheels(vL, vR, obs, mem, dt, false);
}

function navigateToPoint(tx, ty, speed, stopDist, obs, mem, dt) {
  const dx = tx - mem.x;
  const dy = ty - mem.y;
  const d = Math.sqrt(dx * dx + dy * dy);
  if (!isFinite(d)) return hold(obs, mem, dt, false);
  if (d <= stopDist) return hold(obs, mem, dt, false);

  const world = Math.atan2(dy, dx);
  const rel = wrap(world - mem.trueH);

  let sp = speed;
  if (d < stopDist + 2.5) {
    sp = Math.min(sp, Math.max(0.06, (d - stopDist) * 0.45));
  }
  return driveRelative(rel, sp, obs, mem, dt, true);
}

function makeSpiral(cx, cy, size, step, maxR) {
  const pts = [];
  let x = 0, y = 0;
  let len = step;
  let dir = 0;
  let guard = 0;
  const dirs = [[1, 0], [0, 1], [-1, 0], [0, -1]];

  while (guard++ < 400) {
    for (let rep = 0; rep < 2; rep++) {
      x += dirs[dir][0] * len;
      y += dirs[dir][1] * len;
      dir = (dir + 1) % 4;

      const px = clamp(cx + x, 4, size - 4);
      const py = clamp(cy + y, 4, size - 4);
      let last = pts.length ? pts[pts.length - 1] : null;
      if (!last || dist(px, py, last.x, last.y) > 2.0) {
        pts.push({ x: px, y: py });
      }

      if (Math.max(Math.abs(x), Math.abs(y)) > maxR + step) break;
    }
    if (Math.max(Math.abs(x), Math.abs(y)) > maxR + step) break;
    len += step;
  }

  return pts;
}

function buildInitialPath(mem) {
  const spiral = makeSpiral(mem.baseX, mem.baseY, mem.size, 7.5, 70);

  const near = [];
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    const db = dist(h.x, h.y, mem.baseX, mem.baseY);
    if (db < 20) near.push({ h: h, db: db });
  }
  near.sort(function (a, b) { return a.db - b.db; });

  const hp = [];
  let usedCount = 0;
  for (let i = 0; i < near.length && usedCount < 2; i++) {
    const h = near[i].h;
    hp.push({ x: clamp(h.x, 4, mem.size - 4), y: clamp(h.y, 4, mem.size - 4) });
    hp.push({ x: clamp(h.x + 6, 4, mem.size - 4), y: clamp(h.y, 4, mem.size - 4) });
    hp.push({ x: clamp(h.x - 6, 4, mem.size - 4), y: clamp(h.y, 4, mem.size - 4) });
    hp.push({ x: clamp(h.x, 4, mem.size - 4), y: clamp(h.y + 6, 4, mem.size - 4) });
    hp.push({ x: clamp(h.x, 4, mem.size - 4), y: clamp(h.y - 6, 4, mem.size - 4) });
    h.used = true;
    usedCount++;
  }

  const out = [{ x: mem.baseX, y: mem.baseY }];
  for (let i = 0; i < Math.min(4, spiral.length); i++) out.push(spiral[i]);
  for (let i = 0; i < hp.length; i++) out.push(hp[i]);
  for (let i = 4; i < spiral.length; i++) out.push(spiral[i]);

  const cleaned = [];
  for (let i = 0; i < out.length; i++) {
    const q = out[i];
    if (!isFinite(q.x) || !isFinite(q.y)) continue;
    const px = clamp(q.x, 4, mem.size - 4);
    const py = clamp(q.y, 4, mem.size - 4);
    const last = cleaned.length ? cleaned[cleaned.length - 1] : null;
    if (!last || dist(px, py, last.x, last.y) > 2.0) {
      cleaned.push({ x: px, y: py });
    }
  }
  return cleaned;
}

function initMem(obs, mem) {
  mem.init = true;
  const m = obs.mission || {};
  mem.size = Number(m.size) || 400;
  mem.seconds = Number(m.seconds) || 1200;
  mem.cap = Number(m.capacity) || 5;

  let bx = (m.base && isFinite(Number(m.base.x))) ? Number(m.base.x) : Number(obs.x);
  let by = (m.base && isFinite(Number(m.base.y))) ? Number(m.base.y) : Number(obs.y);
  if (!isFinite(bx)) bx = mem.size * 0.5;
  if (!isFinite(by)) by = mem.size * 0.5;
  mem.baseX = bx;
  mem.baseY = by;

  mem.x = isFinite(Number(obs.x)) ? Number(obs.x) : mem.baseX;
  mem.y = isFinite(Number(obs.y)) ? Number(obs.y) : mem.baseY;
  mem.lastGpsX = mem.x;
  mem.lastGpsY = mem.y;
  mem.gpsFreezeT = 0;
  mem.gpsFrozen = false;

  mem.rawH = isFinite(Number(obs.heading)) ? Number(obs.heading) * D2R : 0;
  mem.trueH = mem.rawH;
  mem.bias = 0;
  mem.biasValid = false;
  mem.lastT = (obs.t != null && isFinite(Number(obs.t))) ? Number(obs.t) : 0;
  mem.tick = 0;
  mem.dt = 0.1;

  mem.state = "search";
  mem.prevCarried = Number(obs.carried) || 0;
  mem.prevBumped = !!obs.bumped;
  mem.samplesCollected = 0;
  mem.deliveries = 0;
  mem.drillStart = null;
  mem.drillSite = null;
  mem.activeSite = null;
  mem.siteLastProgress = mem.lastT;
  mem.approachStart = mem.lastT;
  mem.bestSiteD = 1e9;

  mem.wheelL = { gain: 1.5, i: 0, lastCmd: 0 };
  mem.wheelR = { gain: 1.5, i: 0, lastCmd: 0 };

  mem.recoverUntil = -1;
  mem.recoverStart = -1;
  mem.recoverTurn = 1;
  mem.bumpCount = 0;

  mem.ignore = [];
  mem.avoidPrev = null;
  mem.raysBad = false;

  mem.path = [];
  mem.pathIdx = 0;
  mem.pathTargetActive = -1;
  mem.targetStart = mem.lastT;
  mem.targetProgressT = mem.lastT;
  mem.targetBestD = 1e9;
  mem.stuckPathCount = 0;

  mem.calX = mem.x;
  mem.calY = mem.y;
  mem.calT = mem.lastT;
  mem.calSin = 0;
  mem.calCos = 0;
  mem.calCount = 0;
  mem.calVSum = 0;
  mem.calDiffSum = 0;
  mem.calFwdCount = 0;

  mem.chargeUntil = -1;
  mem.atBaseStart = null;

  mem.hints = [];
  mem.maxHintVal = 0.000001;
  const hl = (m.hints && m.hints.length) ? m.hints : [];
  for (let i = 0; i < hl.length; i++) {
    const q = hl[i];
    let x = Number(q.x), y = Number(q.y), v = Number(q.estimate);
    if (!isFinite(x) || !isFinite(y)) continue;
    x = clamp(x, 4, mem.size - 4);
    y = clamp(y, 4, mem.size - 4);
    if (!isFinite(v) || v <= 0) v = 0.000001;
    mem.hints.push({ x: x, y: y, val: v, used: false });
    if (v > mem.maxHintVal) mem.maxHintVal = v;
  }

  mem.path = buildInitialPath(mem);
  if (!mem.path.length) mem.path.push({ x: mem.baseX, y: mem.baseY });
}

function startRecovery(mem, obs, now) {
  if (now < (mem.recoverUntil || -1) + 0.20) return;
  mem.recoverUntil = now + 1.25;
  mem.recoverStart = now;

  const rays = obs.rays || [];
  let left = 0, right = 0;
  for (let i = 0; i < 9; i++) {
    let d = Number(rays[i]);
    if (!isFinite(d) || d < 0 || d > 15) d = 9;
    if (i < 4) right += d;
    else if (i > 4) left += d;
  }
  mem.recoverTurn = (left >= right) ? 1 : -1;
  mem.bumpCount = (mem.bumpCount || 0) + 1;

  if (mem.bumpCount >= 5) {
    if (mem.activeSite) {
      addIgnore(mem, mem.activeSite.x, mem.activeSite.y, now, 45, 4);
    }
    mem.activeSite = null;
    mem.drillStart = null;
    mem.state = "search";
    mem.pathTargetActive = -1;
    mem.bumpCount = 0;
  }
}

function doRecovery(obs, mem, now, dt) {
  const el = now - (mem.recoverStart || now);
  if (el < 0.45) {
    return applyWheels(-0.35, -0.35, obs, mem, dt, false);
  }
  const side = mem.recoverTurn || 1;
  if (side > 0) {
    return applyWheels(-0.30, 0.30, obs, mem, dt, false);
  }
  return applyWheels(0.30, -0.30, obs, mem, dt, false);
}

function handleApproach(obs, mem, now, dt, timeLeft, battery) {
  const s = obs.site;
  if (!s) {
    mem.state = "search";
    return hold(obs, mem, dt, false);
  }

  const d = Number(s.distance);
  const b = Number(s.bearing) * D2R;
  const maxW = Math.max(Math.abs(Number(obs.wheelLeft) || 0), Math.abs(Number(obs.wheelRight) || 0));

  if (!isFinite(d) || !isFinite(b)) {
    mem.state = "search";
    return hold(obs, mem, dt, false);
  }

  if (d <= 1.55) {
    if (maxW < 0.12) {
      mem.state = "drill";
      mem.drillStart = now;
      mem.drillSite = mem.activeSite ? { x: mem.activeSite.x, y: mem.activeSite.y } : { x: mem.x, y: mem.y };
      return hold(obs, mem, dt, true);
    }
    return hold(obs, mem, dt, false);
  }

  let sp;
  if (d > 6.0) sp = 0.62;
  else if (d > 3.0) sp = 0.45;
  else if (d > 2.0) sp = 0.28;
  else sp = 0.12;

  if (timeLeft < 60) sp = Math.min(0.70, sp + 0.08);
  if (battery < 0.20) sp = Math.min(sp, 0.32);

  return driveRelative(b, sp, obs, mem, dt, true);
}

function handleApproachLost(obs, mem, now, dt, timeLeft, battery) {
  const s = mem.activeSite;
  if (!s) {
    mem.state = "search";
    return hold(obs, mem, dt, false);
  }

  const d = dist(mem.x, mem.y, s.x, s.y);
  const maxW = Math.max(Math.abs(Number(obs.wheelLeft) || 0), Math.abs(Number(obs.wheelRight) || 0));

  if (d < 1.8) {
    if (now - s.lastSeen > 4.0) {
      addIgnore(mem, s.x, s.y, now, 45, 4);
      mem.activeSite = null;
      mem.state = "search";
      return hold(obs, mem, dt, false);
    }
    return hold(obs, mem, dt, false);
  }

  if (now - s.lastSeen > 5.0) {
    addIgnore(mem, s.x, s.y, now, 45, 4);
    mem.activeSite = null;
    mem.state = "search";
    return hold(obs, mem, dt, false);
  }

  let sp = (d > 3.0) ? 0.48 : 0.30;
  if (battery < 0.20) sp = Math.min(sp, 0.30);
  return navigateToPoint(s.x, s.y, sp, 1.2, obs, mem, dt);
}

function handleDrill(obs, mem, now, dt, timeLeft, battery) {
  if (mem.drillStart == null) mem.drillStart = now;
  const elapsed = now - mem.drillStart;
  const maxW = Math.max(Math.abs(Number(obs.wheelLeft) || 0), Math.abs(Number(obs.wheelRight) || 0));

  if (elapsed > 9.5 || timeLeft < 3.0 || battery < 0.010) {
    if (mem.drillSite) addIgnore(mem, mem.drillSite.x, mem.drillSite.y, now, 55, 4);
    mem.drillStart = null;
    mem.drillSite = null;
    mem.activeSite = null;
    mem.state = "search";
    return hold(obs, mem, dt, false);
  }

  if (obs.site && isFinite(Number(obs.site.distance)) &&
      Number(obs.site.distance) > 1.9 && elapsed > 0.8) {
    mem.drillStart = null;
    mem.state = "approach";
    return hold(obs, mem, dt, false);
  }

  return hold(obs, mem, dt, true);
}

function handleReturn(obs, mem, now, dt, timeLeft, battery, carried) {
  let d = 1e9;
  let rel = 0;
  let haveBeacon = false;
  const b = obs.beacon;

  if (b && isFinite(Number(b.distance)) && isFinite(Number(b.bearing))) {
    d = Number(b.distance);
    rel = Number(b.bearing) * D2R;
    haveBeacon = true;
  } else {
    d = dist(mem.x, mem.y, mem.baseX, mem.baseY);
    const world = Math.atan2(mem.baseY - mem.y, mem.baseX - mem.x);
    rel = wrap(world - mem.trueH);
  }

  const maxW = Math.max(Math.abs(Number(obs.wheelLeft) || 0), Math.abs(Number(obs.wheelRight) || 0));

  if (d <= 2.1) {
    if (maxW < 0.15) {
      if (mem.atBaseStart == null) mem.atBaseStart = now;

      if (carried === 0) {
        mem.state = "search";
        mem.atBaseStart = null;
        return hold(obs, mem, dt, false);
      }

      if (now - mem.atBaseStart > 2.0 && haveBeacon && d > 0.7) {
        return driveRelative(rel, 0.12, obs, mem, dt, false);
      }
      return hold(obs, mem, dt, false);
    }
    return hold(obs, mem, dt, false);
  }

  if (d <= 3.0 && maxW > 0.20) return hold(obs, mem, dt, false);

  let sp;
  if (d > 8.0) sp = 0.70;
  else if (d > 4.0) sp = 0.45;
  else if (d > 2.5) sp = 0.28;
  else sp = 0.12;

  if (timeLeft < 30) sp = Math.min(0.80, sp + 0.10);
  if (battery < 0.20) sp = Math.min(sp, 0.35);
  if (carried > 0 && d < 1.8) sp = 0.08;

  return driveRelative(rel, sp, obs, mem, dt, true);
}

function chooseNextHint(mem, obs, now, timeLeft) {
  let best = null;
  let bestScore = 1e100;

  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.used) continue;

    const dc = dist(mem.x, mem.y, h.x, h.y);
    const db = dist(h.x, h.y, mem.baseX, mem.baseY);

    const need = (dc + db) / 0.35 + 40;
    if (timeLeft < need) continue;
    if (db > 130) continue;

    let score = dc + 0.5 * db;
    const relVal = clamp(h.val / Math.max(0.000001, mem.maxHintVal), 0, 1);
    score -= relVal * 12;

    if (score < bestScore) {
      bestScore = score;
      best = h;
    }
  }

  if (best) {
    best.used = true;
    return best;
  }
  return null;
}

function handleSearch(obs, mem, now, dt, timeLeft, battery) {
  if (!mem.path || !mem.path.length) {
    mem.path = [{ x: mem.baseX, y: mem.baseY }];
  }

  let idx = mem.pathIdx || 0;

  while (idx < mem.path.length) {
    const p = mem.path[idx];
    if (!p) {
      idx++;
      continue;
    }
    const d0 = dist(mem.x, mem.y, p.x, p.y);
    if (d0 < 1.6) {
      idx++;
      mem.pathTargetActive = -1;
      mem.stuckPathCount = 0;
      continue;
    }
    break;
  }

  if (idx >= mem.path.length) {
    const h = chooseNextHint(mem, obs, now, timeLeft);
    if (h) {
      mem.path.push({ x: h.x, y: h.y });
      idx = mem.path.length - 1;
    } else {
      mem.pathIdx = idx;
      return hold(obs, mem, dt, false);
    }
  }

  mem.pathIdx = idx;
  const p = mem.path[idx];
  const d = dist(mem.x, mem.y, p.x, p.y);

  if (mem.pathTargetActive !== idx) {
    mem.pathTargetActive = idx;
    mem.targetStart = now;
    mem.targetProgressT = now;
    mem.targetBestD = d;
    mem.stuckPathCount = 0;
    mem.bumpCount = 0;
  }

  if (d < mem.targetBestD - 0.4) {
    mem.targetBestD = d;
    mem.targetProgressT = now;
  }

  if (now - mem.targetProgressT > 18.0) {
    mem.stuckPathCount = (mem.stuckPathCount || 0) + 1;
