          for (var oy = -rr; oy <= rr && !got; oy++) {
            if (Math.abs(ox) !== rr && Math.abs(oy) !== rr) continue;
            if (!blk(gcx + ox, gcy + oy)) { fx = gcx + ox; fy = gcy + oy; got = true; }
          }
        }
      }
      if (!got) return null;
    }
    var hk = [], hv = [];
    function hpush(kk, val) {
      hk.push(kk); hv.push(val);
      var i2 = hk.length - 1;
      while (i2 > 0) {
        var p = (i2 - 1) >> 1;
        if (hk[p] <= hk[i2]) break;
        var tk = hk[p]; hk[p] = hk[i2]; hk[i2] = tk;
        var tv = hv[p]; hv[p] = hv[i2]; hv[i2] = tv;
        i2 = p;
      }
    }
    function hpop() {
      var top = hv[0];
      var lk = hk.pop(), lv = hv.pop();
      if (hk.length > 0) {
        hk[0] = lk; hv[0] = lv;
        var i3 = 0, nn = hk.length;
        while (true) {
          var l = 2 * i3 + 1, r = l + 1, mi = i3;
          if (l < nn && hk[l] < hk[mi]) mi = l;
          if (r < nn && hk[r] < hk[mi]) mi = r;
          if (mi === i3) break;
          var tk2 = hk[mi]; hk[mi] = hk[i3]; hk[i3] = tk2;
          var tv2 = hv[mi]; hv[mi] = hv[i3]; hv[i3] = tv2;
          i3 = mi;
        }
      }
      return top;
    }
    var sl = (scy - y0) * W + (scx - x0);
    var gl = (fy - y0) * W + (fx - x0);
    var gS = new Float32Array(NB).fill(1e9);
    var par = new Int32Array(NB).fill(-1);
    var closed = new Uint8Array(NB);
    gS[sl] = 0;
    hpush(0, sl);
    var DX = [1, -1, 0, 0, 1, 1, -1, -1], DY = [0, 0, 1, -1, 1, -1, 1, -1];
    var DC = [1, 1, 1, 1, 1.414, 1.414, 1.414, 1.414];
    var it = 0, found = false;
    while (hk.length > 0 && it < 30000) {
      var cur = hpop(); it++;
      if (closed[cur]) continue;
      closed[cur] = 1;
      if (cur === gl) { found = true; break; }
      var ccx = x0 + cur % W, ccy = y0 + Math.floor(cur / W);
      for (var d = 0; d < 8; d++) {
        var nx = ccx + DX[d], ny = ccy + DY[d];
        if (blk(nx, ny)) continue;
        if (d >= 4 && (blk(ccx + DX[d], ccy) || blk(ccx, ccy + DY[d]))) continue;
        var nl = (ny - y0) * W + (nx - x0);
        if (closed[nl]) continue;
        var ng = gS[cur] + DC[d] + (nearB(nx, ny) ? 1.5 : 0);
        if (ng < gS[nl]) {
          gS[nl] = ng; par[nl] = cur;
          var ax = Math.abs(nx - fx), ay = Math.abs(ny - fy);
          hpush(ng + 1.5 * (Math.max(ax, ay) + 0.414 * Math.min(ax, ay)), nl);
        }
      }
    }
    if (!found) return null;
    var rl = [];
    var c = gl;
    while (c !== sl && c !== -1) { rl.push(c); c = par[c]; }
    var out = [];
    for (var pi = rl.length - 1; pi >= 0; pi--) {
      var cc = rl[pi];
      out.push({ x: (x0 + cc % W) * CS + 1, y: (y0 + Math.floor(cc / W)) * CS + 1 });
    }
    if (out.length > 0) out[out.length - 1] = { x: gx, y: gy };
    return out;
  }

  function navTo(gx, gy, goalR, vmax) {
    var dG = hyp(mem.px, mem.py, gx, gy);
    if (dG < goalR) return null;
    mem.replanT++;
    if (mem.planWait > 0) mem.planWait--;
    var need = false;
    if (!mem.path || !mem.pathGoal || hyp(mem.pathGoal.x, mem.pathGoal.y, gx, gy) > 3) need = true;
    else if (mem.replanT > 40) need = true;
    else if (mem.replanT > 6 && blockedAhead()) need = true;
    if (need && mem.planWait === 0) {
      var P = plan(mem.px, mem.py, gx, gy);
      mem.replanT = 0;
      mem.pathGoal = { x: gx, y: gy };
      if (P && P.length > 0) { mem.path = P; mem.pathIdx = 0; }
      else { mem.path = null; mem.planWait = 25; }
    }
    if (!mem.path) return steerTo(gx, gy, vmax * 0.7);
    var Pa = mem.path, i4 = mem.pathIdx;
    while (i4 < Pa.length - 1 && hyp(mem.px, mem.py, Pa[i4].x, Pa[i4].y) < 1.5) i4++;
    mem.pathIdx = i4;
    var j = i4;
    while (j < Pa.length - 1 && hyp(mem.px, mem.py, Pa[j].x, Pa[j].y) < 2.5) j++;
    var sp = dG < 4 ? vmax * 0.6 : vmax;
    return steerTo(Pa[j].x, Pa[j].y, sp);
  }

  function isSkipped(x, y) {
    for (var i5 = 0; i5 < mem.skip.length; i5++) if (hyp(x, y, mem.skip[i5].x, mem.skip[i5].y) < 3) return true;
    return false;
  }
  function isDone(x, y, r) {
    for (var i6 = 0; i6 < mem.done.length; i6++) if (hyp(x, y, mem.done[i6].x, mem.done[i6].y) < r) return true;
    return false;
  }
  function markNearestHint(x, y) {
    var bi = -1, bd = 1e9;
    for (var i7 = 0; i7 < mem.hints.length; i7++) {
      var d7 = hyp(x, y, mem.hints[i7].x, mem.hints[i7].y);
      if (d7 < bd) { bd = d7; bi = i7; }
    }
    if (bi >= 0 && bd < 25) mem.hints[bi].st = 1;
  }
  function makeSearch(cx, cy, kind, R) {
    var ring = [];
    for (var k8 = 0; k8 < 8; k8++) {
      var a = k8 * Math.PI / 4;
      ring.push({ x: clamp(cx + R * Math.cos(a), 3, 397), y: clamp(cy + R * Math.sin(a), 3, 397) });
    }
    var best = 0, bd2 = 1e9;
    for (var k9 = 0; k9 < 8; k9++) {
      var dd = hyp(mem.px, mem.py, ring[k9].x, ring[k9].y);
      if (dd < bd2) { bd2 = dd; best = k9; }
    }
    var wps = [];
    for (var k10 = 0; k10 < 8; k10++) wps.push(ring[(best + k10) % 8]);
    wps.push({ x: clamp(cx, 3, 397), y: clamp(cy, 3, 397) });
    return { kind: kind, wps: wps, idx: 0, t: 0, bestSci: -1, bx: cx, by: cy };
  }
  function anyLeft() {
    for (var i = 0; i < mem.hints.length; i++) if (mem.hints[i].st === 0 && mem.hints[i].tries < 2) return true;
    for (var j = 0; j < mem.scouts.length; j++) if (!mem.scouts[j].vis) return true;
    return false;
  }
  function pickTarget() {
    var best = null, bs = -1, bi = -1;
    for (var i11 = 0; i11 < mem.hints.length; i11++) {
      var H2 = mem.hints[i11];
      if (H2.st !== 0 || H2.tries >= 2) continue;
      if (isDone(H2.x, H2.y, 4)) { H2.st = 1; continue; }
      var d1 = hyp(px, py, H2.x, H2.y), d2 = hyp(H2.x, H2.y, base.x, base.y);
      if (tl < 2.0 * (d1 + d2) + 120) continue;
      var sc = H2.est / (d1 + 0.6 * d2 + 40);
      if (sc > bs) { bs = sc; best = H2; bi = i11; }
    }
    if (best) return { kind: 'hint', i: bi };
    var bestS = -1, bsd = 1e9;
    for (var j12 = 0; j12 < mem.scouts.length; j12++) {
      var S3 = mem.scouts[j12];
      if (S3.vis) continue;
      var dS = hyp(px, py, S3.x, S3.y), dSB = hyp(S3.x, S3.y, base.x, base.y);
      if (tl < 2.0 * (dS + dSB) + 120) continue;
      if (dS < bsd) { bsd = dS; bestS = j12; }
    }
    if (bestS >= 0) return { kind: 'scout', i: bestS };
    return null;
  }
  function wantDeliver() {
    if (carried <= 0) return false;
    if (carried >= cap) return true;
    if (tl < 2.0 * db + 100) return true;
    if (battery < 0.25) return true;
    if (carried >= 1 && db < 10) return true;
    if (carried >= 2 && db < 30) return true;
    if (carried >= 3 && db < 60) return true;
    if (!anyLeft()) return true;
    return false;
  }
  function startDock(why) {
    mem.mode = 'dock'; mem.dockWhy = why; mem.dockWait = 0;
    mem.search = null; mem.tgt = null; mem.path = null;
  }
  function dropTarget() {
    if (mem.tgt) {
      if (mem.tgt.kind === 'hint') mem.hints[mem.tgt.i].st = 2;
      else mem.scouts[mem.tgt.i].vis = true;
    }
    mem.tgt = null; mem.search = null; mem.path = null; mem.tgtStuck = 0;
  }
  function noteTgtFail() {
    if (!mem.tgt) return;
    mem.tgtStuck = (mem.tgtStuck || 0) + 1;
    if (mem.tgtStuck >= 3) dropTarget();
  }
  function dockStep() {
    var bd = bc ? num(bc.distance, 99) : 99;
    var arrived = db < 2.2 || bd < 2.2;
    if (!arrived) {
      mem.dockWait = 0;
      if (bc && bd < 12) return steer(num(bc.bearing, 0) * D2R, clamp(bd * 0.1, 0.08, 0.2));
      var cD = navTo(base.x, base.y, 2.0, 0.3);
      return cD || brake();
    }
    mem.dockWait++;
    var leave;
    if (mem.dockWhy === 'charge') leave = battery > 0.6 || mem.dockWait > 800;
    else leave = (carried <= 0 && mem.dockWait > 5);
    if (!leave && mem.dockWait > 400) leave = true;
    if (leave) { mem.mode = 'nav'; mem.dockWait = 0; mem.path = null; mem.tgt = null; mem.search = null; }
    return brake();
  }

  // ---------- drilling ----------
  if (mem.mode === 'drill') {
    if (num(obs.drilling, 0) >= 6.05) {
      mem.done.push({ x: mem.sx, y: mem.sy });
      markNearestHint(mem.sx, mem.sy);
      mem.mode = 'nav'; mem.search = null; mem.tgt = null; mem.path = null;
      return brake();
    }
    if (!s || sd > 2.6) mem.drillMiss++; else mem.drillMiss = 0;
    mem.drillT++;
    if (mem.drillMiss > 8 || mem.drillT > 200) {
      mem.skip.push({ x: mem.sx, y: mem.sy });
      mem.mode = 'nav'; mem.path = null; mem.tgt = null;
      return brake();
    }
    return holdDrill();
  }

  // ---------- map update from rays ----------
  for (var ri = 0; ri < 9; ri++) {
    var r = rays[ri];
    var ang = (h + ANG[ri]) * D2R, ca = Math.cos(ang), sa = Math.sin(ang);
    var lim = (r >= 14.9) ? 15 : r;
    for (var st = 1.0; st < lim - 0.7; st += 1.0) {
      var fc = cellOf(px + st * ca, py + st * sa);
      if (mem.occ[fc] > -3) mem.occ[fc] -= 0.5;
    }
    if (r < 14.9 && r > 0.3) {
      var oc = cellOf(px + r * ca, py + r * sa);
      if (mem.occ[oc] < 3) mem.occ[oc] += 1.0;
    }
  }

  // ---------- bump / stuck / front-blocked ----------
  if (bumpNow0 && !mem.wasBumped) {
    markAhead(1.5); markAhead(2.5);
    mem.rev = 12; mem.revTurn = -mem.revTurn; mem.path = null; mem.stkBuf = [];
    noteTgtFail();
  }
  mem.wasBumped = bumpNow0;

  mem.stkBuf.push({ x: px, y: py });
  if (mem.stkBuf.length > 30) mem.stkBuf.shift();
  if (mem.rev === 0 && mem.stkBuf.length >= 30 && Math.abs(mem.lastFwd) > 0.08 &&
      hyp(px, py, mem.stkBuf[0].x, mem.stkBuf[0].y) < 0.25) {
    markAhead(1.5);
    mem.rev = 12; mem.revTurn = -mem.revTurn; mem.path = null; mem.stkBuf = [];
    noteTgtFail();
  }
  if (mem.rev === 0 && Math.min(rays[3], rays[4], rays[5]) < 0.7) {
    markAhead(1.0);
    mem.rev = 10; mem.revTurn = -mem.revTurn; mem.path = null;
  }
  if (mem.rev > 0) {
    mem.rev--;
    return finish({ left: -0.25 - 0.12 * mem.revTurn, right: -0.25 + 0.12 * mem.revTurn, drill: false });
  }

  // ---------- initial compass/GPS calibration: short straight drive ----------
  if (mem.calN < 1 && mem.tick < 250 && !s && rays[4] > 3 && rays[3] > 2.5 && rays[5] > 2.5) {
    return finish({ left: 0.3, right: 0.3, drill: false });
  }

  // ---------- progress watchdog: drop targets we cannot reach in ~10 s ----------
  if (!mem.wdInit) { mem.wdInit = true; mem.wdX = px; mem.wdY = py; mem.wdTick = mem.tick; }
  if (mem.tick - mem.wdTick >= 100) {
    var movedW = hyp(px, py, mem.wdX, mem.wdY);
    if (movedW < 3 && mem.mode === 'nav' && (mem.tgt || mem.search)) {
      mem.wdCount++;
      if (mem.tgt && mem.tgt.kind === 'hint') {
        mem.hints[mem.tgt.i].tries++;
        if (mem.hints[mem.tgt.i].tries >= 2) mem.hints[mem.tgt.i].st = 2;
      }
      if (mem.search && mem.search.kind === 'hint' && mem.tgt && mem.tgt.kind === 'hint') mem.hints[mem.tgt.i].st = 2;
      mem.tgt = null; mem.search = null; mem.path = null; mem.pathGoal = null;
      mem.rev = 8; mem.revTurn = -mem.revTurn;
      mem.stkBuf = [];
    }
    mem.wdX = px; mem.wdY = py; mem.wdTick = mem.tick;
  }

  // ---------- visible site ----------
  if (!s) mem.siteT = 0;
  if (s && sd < 8.5 && carried < cap && mem.mode !== 'dock' && tl > 30) {
    var sr = (h + sb) * D2R;
    var spx = px + sd * Math.cos(sr), spy = py + sd * Math.sin(sr);
    if (!isDone(spx, spy, 4) && !isSkipped(spx, spy)) {
      mem.siteT++;
      if (mem.siteT > 500) {
        mem.skip.push({ x: spx, y: spy }); mem.siteT = 0; mem.path = null;
      } else {
        if (sd <= 1.4) {
          mem.mode = 'drill'; mem.sx = spx; mem.sy = spy; mem.drillT = 0; mem.drillMiss = 0;
          return holdDrill();
        }
        if (sd < 2.6) return steer(sb * D2R, clamp((sd - 1.0) * 0.2, 0.05, 0.15));
        return navTo(spx, spy, 1.0, 0.25) || steer(sb * D2R, 0.1);
      }
    }
  }

  // ---------- docking / delivery ----------
  if (mem.mode === 'dock') return dockStep();
  if (carried > 0 && wantDeliver()) { startDock('deliver'); return dockStep(); }
  if (carried <= 0 && battery < 0.12 && tl > 150) { startDock('charge'); return dockStep(); }

  // ---------- science-triggered search (strong signal only) ----------
  if (sci > SCI_T && !mem.search && carried < cap && tl > 150 && mem.tick - mem.sciT > 60) {
    var nearSci = false;
    for (var z = 0; z < mem.sciPts.length; z++) {
      if (hyp(px, py, mem.sciPts[z].x, mem.sciPts[z].y) < 25) { nearSci = true; break; }
    }
    if (!nearSci) {
      mem.sciPts.push({ x: px, y: py });
      mem.sciT = mem.tick;
      mem.search = makeSearch(px, py, 'sci', 12);
      mem.path = null;
    }
  }

  // ---------- ring search around a hint or science spot ----------
  if (mem.search) {
    var S = mem.search;
    S.t++;
    if (S.kind !== 'hint' && sci > S.bestSci) { S.bestSci = sci; S.bx = px; S.by = py; }
    if (S.t > 600) {
      if (S.kind === 'hint' && mem.tgt && mem.tgt.kind === 'hint') { mem.hints[mem.tgt.i].st = 2; mem.tgt = null; }
      mem.search = null; mem.path = null;
      return brake();
    }
    while (S.idx < S.wps.length && hyp(px, py, S.wps[S.idx].x, S.wps[S.idx].y) < 1.6) { S.idx++; mem.path = null; }
    if (S.idx >= S.wps.length) {
      if (S.kind === 'hint' && mem.tgt && mem.tgt.kind === 'hint') { mem.hints[mem.tgt.i].st = 2; mem.tgt = null; }
      if (S.kind === 'sci' && S.bestSci >= 1.0 && hyp(S.bx, S.by, px, py) > 2) {
        mem.search = makeSearch(S.bx, S.by, 'sci2', 6);
        mem.path = null;
        return brake();
      }
      mem.search = null; mem.path = null; mem.tgtStuck = 0;
      return brake();
    }
    var wp = S.wps[S.idx];
    return navTo(wp.x, wp.y, 1.5, CRUISE) || brake();
  }

  // ---------- target selection and navigation ----------
  if (!mem.tgt) {
    mem.tgt = pickTarget();
    mem.tgtStuck = 0; mem.tgtT = 0; mem.path = null;
    if (!mem.tgt) {
      if (carried > 0) { startDock('deliver'); return dockStep(); }
      return brake();
    }
  }
  mem.tgtT++;
  if (mem.tgtT > 1500) { dropTarget(); return brake(); }
  var T = mem.tgt;
  if (T.kind === 'hint') {
    var H = mem.hints[T.i];
    if (H.st !== 0) { mem.tgt = null; return brake(); }
    var dH = hyp(px, py, H.x, H.y);
    if (dH < 4) {
      mem.search = makeSearch(H.x, H.y, 'hint', 10);
      H.tries++;
      mem.path = null;
      return brake();
    }
    return navTo(H.x, H.y, 3.5, CRUISE) || brake();
  }
  var SC = mem.scouts[T.i];
  if (SC.vis) { mem.tgt = null; return brake(); }
  if (hyp(px, py, SC.x, SC.y) < 5) { SC.vis = true; mem.tgt = null; mem.path = null; return brake(); }
  return navTo(SC.x, SC.y, 4.5, CRUISE) || brake();
}
